# ── 순수 파이썬 Keccak-256 (1D 평탄화 무할당 고속 치환, Ethereum 0x01 패딩) ──
_KECCAK_RC: Tuple[int, ...] = (
    0x0000000000000001, 0x0000000000008082, 0x800000000000808A,
    0x8000000080008000, 0x000000000000808B, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008A,
    0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
    0x000000008000808B, 0x800000000000008B, 0x8000000000008089,
    0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
    0x000000000000800A, 0x800000008000000A, 0x8000000080008081,
    0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
)
_KECCAK_RHO_PI: Tuple[Tuple[int, int, int], ...] = tuple(
    (
        x + 5 * y,
        y + 5 * ((2 * x + 3 * y) % 5),
        (
            (0, 36, 3, 41, 18),
            (1, 44, 10, 45, 2),
            (62, 6, 43, 15, 61),
            (28, 55, 25, 21, 56),
            (27, 20, 39, 8, 14),
        )[x][y],
    )
    for x in range(5)
    for y in range(5)
)
_MASK64: int = (1 << 64) - 1
_UINT256_MAX: int = (1 << 256) - 1
_TWO256: int = 1 << 256


def _keccak_f1600_flat(st: List[int]) -> None:
    m64 = _MASK64
    b = [0] * 25
    rho_pi = _KECCAK_RHO_PI
    for rc in _KECCAK_RC:
        c0 = st[0] ^ st[5] ^ st[10] ^ st[15] ^ st[20]
        c1 = st[1] ^ st[6] ^ st[11] ^ st[16] ^ st[21]
        c2 = st[2] ^ st[7] ^ st[12] ^ st[17] ^ st[22]
        c3 = st[3] ^ st[8] ^ st[13] ^ st[18] ^ st[23]
        c4 = st[4] ^ st[9] ^ st[14] ^ st[19] ^ st[24]
        d0 = c4 ^ (((c1 << 1) | (c1 >> 63)) & m64)
        d1 = c0 ^ (((c2 << 1) | (c2 >> 63)) & m64)
        d2 = c1 ^ (((c3 << 1) | (c3 >> 63)) & m64)
        d3 = c2 ^ (((c4 << 1) | (c4 >> 63)) & m64)
        d4 = c3 ^ (((c0 << 1) | (c0 >> 63)) & m64)
        st[0] ^= d0; st[5] ^= d0; st[10] ^= d0; st[15] ^= d0; st[20] ^= d0
        st[1] ^= d1; st[6] ^= d1; st[11] ^= d1; st[16] ^= d1; st[21] ^= d1
        st[2] ^= d2; st[7] ^= d2; st[12] ^= d2; st[17] ^= d2; st[22] ^= d2
        st[3] ^= d3; st[8] ^= d3; st[13] ^= d3; st[18] ^= d3; st[23] ^= d3
        st[4] ^= d4; st[9] ^= d4; st[14] ^= d4; st[19] ^= d4; st[24] ^= d4
        for src_i, dst_i, r in rho_pi:
            v = st[src_i]
            b[dst_i] = (((v << r) | (v >> (64 - r))) & m64) if r else (v & m64)
        for y5 in (0, 5, 10, 15, 20):
            b0, b1, b2, b3, b4 = b[y5], b[y5 + 1], b[y5 + 2], b[y5 + 3], b[y5 + 4]
            st[y5] = (b0 ^ ((~b1) & b2)) & m64
            st[y5 + 1] = (b1 ^ ((~b2) & b3)) & m64
            st[y5 + 2] = (b2 ^ ((~b3) & b4)) & m64
            st[y5 + 3] = (b3 ^ ((~b4) & b0)) & m64
            st[y5 + 4] = (b4 ^ ((~b0) & b1)) & m64
        st[0] ^= rc


def _keccak256(data: bytes) -> bytes:
    rate = 136
    st = [0] * 25
    off = 0
    mv = memoryview(data)
    n = len(mv)
    from_bytes = int.from_bytes
    while n - off >= rate:
        blk = mv[off:off + rate]
        off += rate
        for i in range(17):
            st[i] ^= from_bytes(blk[i * 8:(i + 1) * 8], "little")
        _keccak_f1600_flat(st)
    last = bytearray(rate)
    rem = mv[off:]
    rlen = len(rem)
    last[:rlen] = rem
    last[rlen] ^= 0x01
    last[rate - 1] ^= 0x80
    for i in range(17):
        st[i] ^= from_bytes(last[i * 8:(i + 1) * 8], "little")
    _keccak_f1600_flat(st)
    return st[0].to_bytes(8, "little") + st[1].to_bytes(8, "little") + st[2].to_bytes(8, "little") + st[3].to_bytes(8, "little")


def _keccak256_hex(data: bytes) -> str:
    return "0x" + _keccak256(data).hex()


@functools.lru_cache(maxsize=16384)
def _selector(sig: str) -> str:
    return "0x" + _keccak256(sig.encode("utf-8"))[:4].hex()


@functools.lru_cache(maxsize=32768)
def _norm_addr_cached(s: str) -> str:
    s_clean = s.strip()
    if len(s_clean) == 42 and _ADDR_RE.match(s_clean):
        return "0x" + s_clean[2:].lower()
    return ""


def _norm_addr(addr: Any) -> str:
    if not addr:
        return ""
    if isinstance(addr, str):
        return _norm_addr_cached(addr)
    return _norm_addr_cached(str(addr))


@functools.lru_cache(maxsize=32768)
def _checksum_cached(norm_a: str) -> str:
    raw = norm_a[2:]
    h = _keccak256(raw.encode("ascii")).hex()
    return "0x" + "".join(
        ch.upper() if ch in "abcdef" and int(h[i], 16) >= 8 else ch
        for i, ch in enumerate(raw)
    )


def _checksum(addr: str) -> str:
    a = _norm_addr(addr)
    if not a:
        raise ValueError(f"Invalid EVM address: {addr!r}")
    return _checksum_cached(a)


def _is_non_precompile_addr(addr: Any) -> bool:
    """
    0x000..000 및 표준/L2 프리컴파일 대역(0x01~0x1ff, 0x400~0x4ff, 0x800~0x8ff)은 제외하되,
    선행 제로 바이트(CREATE2/vanity 등, 예: 0x0000...0250)를 포함한 정상 배포 컨트랙트 주소는 온전히 보존한다.
    """
    na = _norm_addr(addr)
    if not na:
        return False
    val = int(na, 16)
    if val <= 0x1FF or (0x400 <= val <= 0x4FF) or (0x800 <= val <= 0x8FF):
        return False
    return True


