@functools.lru_cache(maxsize=4096)
def _norm_chain_cached(s: str) -> str:
    raw = _SLUG_CLEAN_RE.sub("", s.lower())
    if not raw:
        return ""
    if raw.isdigit():
        cid = int(raw)
        if cid in CHAIN_BY_ID:
            return CHAIN_BY_ID[cid]
    mapped = CHAIN_ALIASES.get(raw, raw)
    if mapped in CHAIN_IDS:
        return mapped
    for extra_k, extra_v in (
        ("eth", "ethereum"),
        ("ethereummainnet", "ethereum"),
        ("mainnet", "ethereum"),
        ("arb", "arbitrum"),
        ("arbitrumone", "arbitrum"),
        ("op", "optimism"),
        ("bnb", "bsc"),
        ("binance", "bsc"),
        ("binancesmartchain", "bsc"),
        ("matic", "polygon"),
        ("ftm", "fantom"),
        ("era", "zksync"),
    ):
        if raw == extra_k:
            return extra_v
    return mapped


def _norm_chain(name: Any) -> str:
    if not name:
        return ""
    if isinstance(name, str):
        return _norm_chain_cached(name)
    return _norm_chain_cached(str(name))


def _usable_chain(name: Any) -> bool:
    c = _norm_chain(name)
    if not c or any(kw in c for kw in TESTNET_KWS):
        return False
    if c in NON_EVM_CHAINS:
        return False
    return c in CHAIN_IDS


def _default_batch_cap_for_url(url: str) -> int:
    try:
        host = (urllib.parse.urlparse(url).hostname or "").lower()
    except Exception:
        host = ""
    for suffix, cap in _BATCH_CAP_BY_HOST:
        if host.endswith(suffix):
            return cap
    return 25


def _read_body_deadlined(resp: Any, timeout_sec: float, max_bytes: int = 16 * 1024 * 1024) -> bytes:
    deadline = time.monotonic() + max(1.0, float(timeout_sec))
    chunks: List[bytes] = []
    total = 0
    while True:
        if time.monotonic() > deadline:
            raise TimeoutError("HTTP response body read exceeded wall-clock deadline")
        chunk = resp.read(65536)
        if not chunk:
            break
        chunks.append(chunk)
        total += len(chunk)
        if total > max_bytes:
            raise OverflowError(f"HTTP response exceeded {max_bytes} bytes")
    return b"".join(chunks)


def _classify_rpc_error(exc_or_err: Any) -> str:
    txt = str(exc_or_err or "").lower()
    if ("reorg" in txt or "block reverted" in txt) and "execution reverted" not in txt:
        return "gap"
    if any(m in txt for m in _REVERT_ERR_MARKERS):
        return "revert"
    if "wrong_chain" in txt or "chainid mismatch" in txt:
        return "wrong_chain"
    if any(m in txt for m in _SHRINK_ERR_MARKERS):
        return "shrink"
    if any(m in txt for m in _QUOTA_ERR_MARKERS):
        return "quota"
    return "gap"


class _DeterministicHTTPClientError(RuntimeError):
    def __init__(self, status: int, body_preview: str = "") -> None:
        super().__init__(f"HTTP {status}: {body_preview}".rstrip(": "))
        self.status = status


class RPCRouter:
    """스레드 로컬 Keep-Alive 커넥션 풀 + 적응형 배치 + 체인 ID 검증 + TTL 격리 복구 + 다중 엔드포인트 쿼럼 헤드."""

    _QUARANTINE_TTL_SEC: float = 3600.0

    def __init__(self, store: Optional[SQLiteStore] = None, session_id: str = "") -> None:
        self.store = store
        self.session_id: str = str(session_id or "").strip().lower()
        self._session_salt: int = (
            (int(hashlib.sha256(self.session_id.encode("utf-8")).hexdigest()[:8], 16) | 1)
            if self.session_id
            else 0
        )
        self._tls = threading.local()
        self._lock = threading.Lock()
        self._batch_caps: Dict[str, int] = {}
        self._rtt_ms: Dict[str, float] = {}
        self._cool_until: Dict[str, float] = {}
        self._demote_until: Dict[str, float] = {}
        self._quarantine_until: Dict[Tuple[int, str], float] = {}
        self._last_persisted_at: Dict[str, float] = {}
        self._last_shared_sync_at: float = 0.0
        self._verified_chain_urls: Set[Tuple[int, str]] = set()
        self._no_multicall_chains: Set[str] = set()
        self._bm_cursor: int = 0
        self._ssl_ctx = ssl.create_default_context()
        self._sync_shared_endpoints_if_due(force=True)

    def _sync_shared_endpoints_if_due(self, force: bool = False) -> None:
        if self.store is None:
            return
        mono_now = time.monotonic()
        with self._lock:
            if not force and (mono_now - self._last_shared_sync_at) < 2.0:
                return
            self._last_shared_sync_at = mono_now
        try:
            now = time.time()
            rows = self.store.load_rpc_endpoints()
            with self._lock:
                for row in rows:
                    u = str(row.get("url") or "")
                    rcid = int(row.get("chain_id") or 0)
                    if not u:
                        continue
                    du = float(row.get("demote_until") or 0.0)
                    if int(row.get("quarantined") or 0) == 1:
                        if du > now and rcid > 0:
                            self._quarantine_until[(rcid, u)] = max(self._quarantine_until.get((rcid, u), 0.0), du)
                    elif du > now:
                        self._demote_until[u] = max(self._demote_until.get(u, 0.0), du)
                    bcap = int(row.get("batch_cap") or 0)
                    if bcap > 0 and u not in self._batch_caps:
                        self._batch_caps[u] = bcap
                    rtt = float(row.get("rtt_ms") or 0.0)
                    if 0.0 < rtt < 60000.0 and u not in self._rtt_ms:
                        self._rtt_ms[u] = rtt
                    cu = float(row.get("cool_until") or 0.0)
                    if cu > now:
                        self._cool_until[u] = max(self._cool_until.get(u, 0.0), cu)
        except Exception:
            pass

    def _get_conn_pool(self) -> Dict[Tuple[str, str, int], http.client.HTTPConnection]:
        pool = getattr(self._tls, "conn_pool", None)
        if pool is None:
            pool = {}
            self._tls.conn_pool = pool
        return pool

    @staticmethod
    def _parse_http_endpoint(url: str) -> Tuple[str, str, int, str]:
        parsed = urllib.parse.urlparse(url)
        scheme = (parsed.scheme or "https").lower()
        host = parsed.hostname or ""
        port = parsed.port or (443 if scheme == "https" else 80)
        path = parsed.path or "/"
        if parsed.query:
            path = f"{path}?{parsed.query}"
        return scheme, host, port, path

    def _pooled_http_exchange(
        self,
        scheme: str,
        host: str,
        port: int,
        method: str,
        path: str,
        headers: Dict[str, str],
        timeout: float,
        body: Optional[bytes] = None,
    ) -> Tuple[int, bytes]:
        key = (scheme, host, port)
        pool = self._get_conn_pool()
        for attempt in range(2):
            conn = pool.get(key)
            try:
                if conn is None:
                    conn = (
                        http.client.HTTPSConnection(host, port, timeout=timeout, context=self._ssl_ctx)
                        if scheme == "https"
                        else http.client.HTTPConnection(host, port, timeout=timeout)
                    )
                    pool[key] = conn
                conn.timeout = timeout
                conn.request(method, path, body=body, headers=headers)
                resp = conn.getresponse()
                raw = _read_body_deadlined(resp, timeout)
                return int(resp.status), raw
            except Exception:
                pool.pop(key, None)
                try:
                    if conn is not None:
                        conn.close()
                except Exception:
                    pass
                if attempt == 1:
                    raise
        raise RuntimeError("Unreachable HTTP pool exit")

    def _pooled_post(self, url: str, body: bytes, timeout: float) -> bytes:
        scheme, host, port, path = self._parse_http_endpoint(url)
        if not host:
            raise ValueError(f"Invalid RPC URL: {url}")
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "Connection": "keep-alive",
            "User-Agent": "defi-audit-engine/1.0",
        }
        if host.endswith("blockmachine.io") and BLOCKMACHINE_API_KEYS:
            with self._lock:
                bm_key = BLOCKMACHINE_API_KEYS[self._bm_cursor % len(BLOCKMACHINE_API_KEYS)]
                self._bm_cursor += 1
            if bm_key:
                headers["x-api-key"] = bm_key
        status, raw = self._pooled_http_exchange(scheme, host, port, "POST", path, headers, timeout, body=body)
        if status >= 400:
            raise RuntimeError(f"HTTP {status}: {raw[:200].decode('utf-8', errors='replace')}")
        return raw

    def http_get_json(self, url: str, timeout: float = 15.0, extra_headers: Optional[Dict[str, str]] = None) -> Any:
        hdrs = {
            "Accept": "application/json",
            "Connection": "keep-alive",
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) DefiAudit/1.0",
        }
        if extra_headers:
            hdrs.update(extra_headers)
        scheme, host, port, path = self._parse_http_endpoint(url)
        if host and scheme in ("http", "https"):
            try:
                status, raw = self._pooled_http_exchange(scheme, host, port, "GET", path, hdrs, timeout)
                if not (300 <= status < 400):
                    if status in (400, 404, 410):
                        raise _DeterministicHTTPClientError(status)
                    if status >= 400:
                        raise RuntimeError(f"HTTP {status}")
                    return json.loads(raw.decode("utf-8", errors="replace"))
            except _DeterministicHTTPClientError:
                raise
            except Exception:
                pass
        req = urllib.request.Request(url, headers={k: v for k, v in hdrs.items() if k != "Connection"})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = _read_body_deadlined(resp, timeout)
            return json.loads(raw.decode("utf-8", errors="replace"))

    def candidate_urls(self, chain: str, need_archive: bool = False, for_forge: bool = False) -> List[str]:
        c = _norm_chain(chain)
        if c not in CHAIN_IDS:
            return []
        cid = CHAIN_IDS[c]
        base_urls = list(CHAIN_RPCS.get(c, []))
        arch_urls = list(KEYLESS_ARCHIVE_RPCS.get(c, []))
        bslug = _BM_SLUGS.get(c)
        if bslug and not for_forge:
            bm_url = f"https://rpc-{bslug}.blockmachine.io"
            if bm_url not in base_urls:
                base_urls.append(bm_url)
        keyed_urls: List[str] = []
        c_hash = int(hashlib.sha256(c.encode("utf-8")).hexdigest(), 16)
        aslug = _ANKR_SLUGS.get(c)
        if aslug and ANKR_API_KEYS:
            start = c_hash % len(ANKR_API_KEYS)
            for idx in range(len(ANKR_API_KEYS)):
                k = ANKR_API_KEYS[(start + idx) % len(ANKR_API_KEYS)]
                if k:
                    keyed_urls.append(f"https://rpc.ankr.com/{aslug}/{k}")
        nrslug = _NODEREAL_SLUGS.get(c)
        if nrslug and NODEREAL_API_KEYS:
            nr_start = c_hash % len(NODEREAL_API_KEYS)
            for idx in range(len(NODEREAL_API_KEYS)):
                nk = NODEREAL_API_KEYS[(nr_start + idx) % len(NODEREAL_API_KEYS)]
                if nk:
                    keyed_urls.append(f"https://{nrslug}.nodereal.io/v1/{nk}")
        for u in list(base_urls):
            if u.endswith("/v1/rpc/public") and "blockreq.com" in u:
                stem = u[:-len("/v1/rpc/public")]
                for bk in BLOCKREQ_API_KEYS:
                    if bk:
                        keyed_urls.append(f"{stem}/v1/rpc/{bk}")
        arch_set = set(arch_urls) | set(keyed_urls)
        if need_archive:
            ordered = list(dict.fromkeys(arch_urls + keyed_urls + base_urls))
        else:
            ordered = list(dict.fromkeys(base_urls + keyed_urls))
        if not ordered:
            return []
        self._sync_shared_endpoints_if_due(force=False)
        now = time.time()
        with self._lock:
            active: List[str] = []
            demoted: List[str] = []
            cooled: List[str] = []
            quarantined_pool: List[str] = []
            for u in ordered:
                qu = self._quarantine_until.get((cid, u), 0.0)
                if qu > now:
                    quarantined_pool.append(u)
                    continue
                if qu > 0.0:
                    self._quarantine_until.pop((cid, u), None)
                if self._cool_until.get(u, 0.0) > now:
                    cooled.append(u)
                    continue
                if self._demote_until.get(u, 0.0) > now:
                    demoted.append(u)
                else:
                    active.append(u)
            sort_fn = (
                (lambda u: (0 if u in arch_set else 1, self._rtt_ms.get(u, 500.0)))
                if need_archive
                else (lambda u: self._rtt_ms.get(u, 500.0))
            )
            active.sort(key=sort_fn)
            if self._session_salt and len(active) > 1:
                lead_arch = active[0] in arch_set if need_archive else True
                lead_rtt = self._rtt_ms.get(active[0], 500.0)
                top_k = 0
                for u_cand in active[:5]:
                    if need_archive and (u_cand in arch_set) != lead_arch:
                        break
                    if self._rtt_ms.get(u_cand, 500.0) > lead_rtt + 600.0:
                        break
                    top_k += 1
                if top_k > 1:
                    rot_off = (self._session_salt + cid) % top_k
                    if rot_off:
                        active[:top_k] = active[rot_off:top_k] + active[:rot_off]
            demoted.sort(key=sort_fn)
            primary = active + demoted
            if primary:
                return primary
            if cooled:
                cooled.sort(key=lambda u: self._cool_until.get(u, 0.0))
                return cooled
            return quarantined_pool

    def _verify_endpoint_chain_id(self, url: str, expected_cid: int, timeout: float = 6.0) -> bool:
        if expected_cid <= 0:
            return True
        with self._lock:
            if (expected_cid, url) in self._verified_chain_urls:
                return True
        try:
            t0 = time.perf_counter()
            raw = self._pooled_post(
                url,
                b'{"jsonrpc":"2.0","id":1,"method":"eth_chainId","params":[]}',
                timeout=min(5.0, timeout),
            )
            doc = json.loads(raw.decode("utf-8", errors="replace"))
            res = doc.get("result") if isinstance(doc, dict) else None
            if isinstance(res, str) and res.startswith("0x"):
                got_cid = int(res, 16)
                if got_cid != expected_cid:
                    self._record_failure(url, "wrong_chain", cid=expected_cid)
                    return False
                with self._lock:
                    self._verified_chain_urls.add((expected_cid, url))
                self._record_success(url, (time.perf_counter() - t0) * 1000.0, cid=expected_cid)
                return True
            self._record_failure(url, "gap", cid=expected_cid)
            return False
        except Exception as exc:
            self._record_failure(url, _classify_rpc_error(exc), cid=expected_cid)
            return False

    def batch_cap_for(self, url: str) -> int:
        with self._lock:
            if url not in self._batch_caps:
                self._batch_caps[url] = _default_batch_cap_for_url(url)
            return self._batch_caps[url]

    def _persist_endpoint_if_due(self, url: str, cid: int, force: bool = False) -> None:
        if self.store is None or cid <= 0:
            return
        now = time.time()
        with self._lock:
            if not force and (now - self._last_persisted_at.get(url, 0.0)) < 60.0:
                return
            self._last_persisted_at[url] = now
            bcap = self._batch_caps.get(url, _default_batch_cap_for_url(url))
            rtt = self._rtt_ms.get(url, 500.0)
            cu = self._cool_until.get(url, 0.0)
            qu = self._quarantine_until.get((cid, url), 0.0)
            quar = qu > now
            du = qu if quar else self._demote_until.get(url, 0.0)
        try:
            self.store.save_rpc_endpoint(cid, url, batch_cap=bcap, rtt_ms=rtt, cool_until=cu, demote_until=du, quarantined=quar, last_ok_at=now if not quar else 0.0)
        except Exception:
            pass

    def _record_success(self, url: str, elapsed_ms: float, cid: int = 0) -> None:
        with self._lock:
            prev = self._rtt_ms.get(url)
            self._rtt_ms[url] = elapsed_ms if prev is None else (0.7 * prev + 0.3 * elapsed_ms)
            if cid > 0:
                self._quarantine_until.pop((cid, url), None)
        if cid > 0:
            self._persist_endpoint_if_due(url, cid, force=False)

    def _record_failure(self, url: str, kind: str, cid: int = 0) -> None:
        now = time.time()
        force_save = False
        with self._lock:
            if kind == "wrong_chain" and cid > 0:
                self._quarantine_until[(cid, url)] = now + self._QUARANTINE_TTL_SEC
                force_save = True
            elif kind == "quota":
                self._demote_until[url] = now + 1800.0
                self._cool_until[url] = now + 60.0
                force_save = True
            elif kind == "shrink":
                cur = self._batch_caps.get(url, _default_batch_cap_for_url(url))
                self._batch_caps[url] = max(1, cur // 2)
                force_save = True
            elif kind == "gap":
                self._cool_until[url] = now + 20.0
                force_save = True
        if cid > 0:
            self._persist_endpoint_if_due(url, cid, force=force_save)

    def get_quorum_head_block(self, chain: str, timeout: float = 8.0) -> Tuple[int, int]:
        """
        최소 2개 이상의 독립 호스트 RPC 엔드포인트 병렬 `eth_getBlockByNumber("latest", false)` / `eth_blockNumber` 쿼럼 조회:
        - 호스트(`netloc`) 기준 중복 제거로 동일 사업자 복수 URL의 단일 장애점 위장 방지.
        - 아카이브 노드 지연과 분리해 실제 체인 최신 팁(`b_tip = max`) 및 아카이브 합의 헤드(`b_head`) 산출.
        - 반환 `(b_tip, b_head)`는 이상치(median ± max(2048, median // 500)) 배제 후 교차 검증.
        """
        c = _norm_chain(chain)
        if type(self).call is not RPCRouter.call or "call" in self.__dict__:
            raw_bn = self.call(c, "eth_blockNumber", [], timeout=timeout)
            bn = int(str(raw_bn), 16) if isinstance(raw_bn, str) and str(raw_bn).startswith("0x") else int(raw_bn or 0)
            if bn <= 0:
                raise RuntimeError(f"Invalid blockNumber on {c}: {raw_bn!r}")
            return bn, bn
        cid = CHAIN_IDS.get(c, 0)
        arch_urls = self.candidate_urls(c, need_archive=True)
        live_urls = self.candidate_urls(c, need_archive=False)
        arch_url_set = set(arch_urls)
        urls: List[str] = []
        seen_hosts: Set[str] = set()
        for u in [*arch_urls, *live_urls]:
            host_k = urllib.parse.urlparse(u).netloc.lower() or u.lower()
            if host_k in seen_hosts:
                continue
            seen_hosts.add(host_k)
            urls.append(u)
            if len(urls) >= 5:
                break
        if not urls:
            raise RuntimeError(f"No RPC endpoints for chain {c}")

        def _probe_one(u: str) -> Tuple[int, int, bool]:
            is_arch = u in arch_url_set
            if not self._verify_endpoint_chain_id(u, cid, timeout=min(5.0, timeout)):
                return 0, 0, is_arch
            t0 = time.perf_counter()
            try:
                raw_blk = self._pooled_post(
                    u,
                    b'{"jsonrpc":"2.0","id":1,"method":"eth_getBlockByNumber","params":["latest",false]}',
                    timeout=min(6.0, timeout),
                )
                doc_blk = json.loads(raw_blk.decode("utf-8", errors="replace"))
                res_blk = doc_blk.get("result") if isinstance(doc_blk, dict) else None
                if isinstance(res_blk, dict):
                    num_s = str(res_blk.get("number") or "")
                    ts_s = str(res_blk.get("timestamp") or "")
                    bn_v = int(num_s, 16) if num_s.startswith("0x") else int(num_s or 0)
                    ts_v = int(ts_s, 16) if ts_s.startswith("0x") else int(ts_s or 0)
                    if bn_v > 0:
                        self._record_success(u, (time.perf_counter() - t0) * 1000.0, cid=cid)
                        return bn_v, max(0, ts_v), is_arch
            except Exception:
                pass
            t1 = time.perf_counter()
            raw = self._pooled_post(
                u,
                b'{"jsonrpc":"2.0","id":1,"method":"eth_blockNumber","params":[]}',
                timeout=min(6.0, timeout),
            )
            doc = json.loads(raw.decode("utf-8", errors="replace"))
            res = doc.get("result") if isinstance(doc, dict) else None
            if isinstance(res, str) and res.startswith("0x"):
                bn_val = int(res, 16)
                if bn_val > 0:
                    self._record_success(u, (time.perf_counter() - t1) * 1000.0, cid=cid)
                    return bn_val, 0, is_arch
            return 0, 0, is_arch

        samples: List[Tuple[int, int, bool]] = []
        if len(urls) == 1:
            try:
                s0 = _probe_one(urls[0])
                if s0[0] > 0:
                    samples.append(s0)
            except Exception:
                pass
        else:
            with concurrent.futures.ThreadPoolExecutor(max_workers=len(urls)) as ex:
                futs = [ex.submit(_probe_one, u) for u in urls]
                for fut in futs:
                    try:
                        sv = fut.result(timeout=timeout + 1.0)
                        if sv[0] > 0:
                            samples.append(sv)
                    except Exception:
                        pass
        if not samples:
            raw_fb = self.call(c, "eth_blockNumber", [], timeout=timeout)
            fb_bn = int(str(raw_fb), 16) if isinstance(raw_fb, str) and str(raw_fb).startswith("0x") else int(raw_fb or 0)
            if fb_bn <= 0 or len(urls) >= 2:
                raise RuntimeError(f"eth_blockNumber quorum failed on {c} (distinct hosts={len(urls)}, samples=0)")
            return fb_bn, fb_bn
        if len(urls) >= 2 and len(samples) < 2:
            raise RuntimeError(f"Insufficient RPC quorum agreement on {c}: only {len(samples)}/{len(urls)} hosts responded")
        if len(samples) >= 2:
            sorted_samples = sorted(samples, key=lambda x: x[0])
            med_bn = sorted_samples[(len(sorted_samples) - 1) // 2][0]
            band = max(2048, med_bn // 500)
            filtered = [s for s in samples if abs(s[0] - med_bn) <= band]
            if len(urls) >= 2 and len(filtered) < 2:
                raise RuntimeError(f"Insufficient RPC quorum agreement on {c}: only {len(filtered)}/{len(urls)} hosts within quorum band (median={med_bn}, band={band})")
            if filtered:
                samples = filtered
        tip_bn, tip_ts, _ = max(samples, key=lambda x: x[0])
        fresh: List[int] = []
        arch_fresh: List[int] = []
        for h_bn, h_ts, is_arch in samples:
            is_f = (tip_bn - h_bn) <= MAX_AUDIT_BLOCK_LAG or (
                tip_ts > 0 and h_ts > 0 and 0 <= (tip_ts - h_ts) <= 12
            )
            if is_f:
                fresh.append(h_bn)
                if is_arch:
                    arch_fresh.append(h_bn)
        b_head = max(arch_fresh) if arch_fresh else (min(fresh) if fresh else tip_bn)
        return tip_bn, b_head

    def call(
        self,
        chain: str,
        method: str,
        params: List[Any],
        block_pin: Optional[int] = None,
        need_archive: bool = False,
        timeout: float = 12.0,
    ) -> Any:
        c = _norm_chain(chain)
        cid = CHAIN_IDS.get(c, 0)
        params_sha = ""
        if self.store is not None and block_pin is not None and block_pin > 0:
            params_sha = hashlib.sha256(
                json.dumps(params, sort_keys=True, ensure_ascii=True).encode("utf-8")
            ).hexdigest()
            hit, cached_val = self.store.get_pinned_rpc(cid, int(block_pin), method, params_sha)
            if hit:
                return cached_val
        urls = self.candidate_urls(c, need_archive=need_archive or (block_pin is not None and block_pin > 0))
        payload = json.dumps({"jsonrpc": "2.0", "id": 1, "method": method, "params": params}).encode("utf-8")
        last_err = "no_candidate_rpc"
        for url in urls:
            if method != "eth_chainId" and not self._verify_endpoint_chain_id(url, cid, timeout=timeout):
                last_err = f"endpoint_unverified on {url}"
                continue
            t0 = time.perf_counter()
            try:
                raw = self._pooled_post(url, payload, timeout=timeout)
                doc = json.loads(raw.decode("utf-8", errors="replace"))
            except Exception as exc:
                kind = _classify_rpc_error(exc)
                self._record_failure(url, kind, cid=cid)
                last_err = str(exc)
                continue
            if not isinstance(doc, dict):
                self._record_failure(url, "gap", cid=cid)
                continue
            err = doc.get("error")
            if err is not None and doc.get("result") is None:
                kind = _classify_rpc_error(err)
                if kind == "revert":
                    return None
                self._record_failure(url, kind, cid=cid)
                last_err = str(err)
                continue
            res = doc.get("result")
            self._record_success(url, (time.perf_counter() - t0) * 1000.0, cid=cid)
            if self.store is not None and block_pin is not None and block_pin > 0 and res is not None:
                self.store.put_pinned_rpc(cid, int(block_pin), method, params_sha, res)
            return res
        raise RuntimeError(f"RPC call failed on {c}.{method}: {last_err}")

    def last_batch_transport_failures(self) -> int:
        tls = getattr(self, "_tls", None)
        return int(getattr(tls, "last_batch_transport_failures", 0) or 0)

    def last_multicall_transport_failed(self) -> bool:
        tls = getattr(self, "_tls", None)
        return bool(getattr(tls, "last_multicall_transport_failed", False))

    def _set_tls_batch_failures(self, failed_indices: Set[int]) -> None:
        tls = getattr(self, "_tls", None)
        if tls is not None:
            tls.last_batch_transport_failures = len(failed_indices)
            tls.last_batch_failed_indices = frozenset(failed_indices)

    def batch_call(
        self,
        chain: str,
        calls: Sequence[Tuple[str, List[Any]]],
        block_pin: Optional[int] = None,
        need_archive: bool = False,
        timeout: float = 15.0,
        raise_on_all_failed: bool = False,
    ) -> List[Any]:
        if not calls:
            self._set_tls_batch_failures(set())
            return []
        c = _norm_chain(chain)
        cid = CHAIN_IDS.get(c, 0)
        results: List[Any] = [None] * len(calls)
        missing_indices: List[int] = []
        param_hashes: Dict[int, str] = {}
        if self.store is not None and block_pin is not None and block_pin > 0:
            lookup_keys: List[Tuple[str, str]] = []
            for idx, (m, p) in enumerate(calls):
                psha = hashlib.sha256(
                    json.dumps(p, sort_keys=True, ensure_ascii=True).encode("utf-8")
                ).hexdigest()
                param_hashes[idx] = psha
                lookup_keys.append((m, psha))
            cached_map = self.store.get_pinned_rpc_batch(cid, int(block_pin), lookup_keys)
            for idx, (m, _) in enumerate(calls):
                k = (m, param_hashes[idx])
                if k in cached_map:
                    results[idx] = cached_map[k]
                else:
                    missing_indices.append(idx)
        else:
            missing_indices = list(range(len(calls)))
        if not missing_indices:
            self._set_tls_batch_failures(set())
            return results
        failed_indices: Set[int] = set()
        if type(self).call is not RPCRouter.call or "call" in self.__dict__:
            ok_any = False
            last_exc: Optional[Exception] = None
            for idx in missing_indices:
                m_i, p_i = calls[idx]
                try:
                    results[idx] = self.call(c, m_i, p_i, block_pin=block_pin, need_archive=need_archive, timeout=timeout)
                    ok_any = True
                except Exception as exc:
                    last_exc = exc
                    results[idx] = None
                    if _classify_rpc_error(exc) != "revert":
                        failed_indices.add(idx)
            self._set_tls_batch_failures(failed_indices)
            if raise_on_all_failed and not ok_any and last_exc is not None:
                raise RuntimeError(f"All RPC calls failed on {c}: {last_exc}") from last_exc
            return results
        urls = self.candidate_urls(c, need_archive=need_archive or (block_pin is not None and block_pin > 0))
        if not urls:
            failed_indices.update(missing_indices)
            self._set_tls_batch_failures(failed_indices)
            if raise_on_all_failed:
                raise RuntimeError(f"No candidate RPC URLs for {c}")
            return results
        pending: List[int] = list(missing_indices)
        url_idx = 0
        ok_rpc_count = 0
        last_transport_err = "batch_call_exhausted"
        while pending:
            url = urls[url_idx % len(urls)]
            if not self._verify_endpoint_chain_id(url, cid, timeout=timeout):
                url_idx += 1
                if url_idx >= len(urls) * 2:
                    failed_indices.update(pending)
                    break
                continue
            cap = max(1, self.batch_cap_for(url))
            chunk_idxs = pending[:cap]
            if cap == 1:
                i0 = chunk_idxs[0]
                m0, p0 = calls[i0]
                try:
                    results[i0] = self.call(c, m0, p0, block_pin=block_pin, need_archive=need_archive, timeout=timeout)
                    ok_rpc_count += 1
                except Exception as exc:
                    last_transport_err = str(exc)
                    results[i0] = None
                    if _classify_rpc_error(exc) != "revert":
                        failed_indices.add(i0)
                del pending[:1]
                continue
            req_list = [
                {"jsonrpc": "2.0", "id": k, "method": calls[i][0], "params": calls[i][1]}
                for k, i in enumerate(chunk_idxs)
            ]
            t0 = time.perf_counter()
            cur_unresolved = list(chunk_idxs)
            try:
                raw = self._pooled_post(url, json.dumps(req_list).encode("utf-8"), timeout=timeout)
                decoded = json.loads(raw.decode("utf-8", errors="replace"))
                if not isinstance(decoded, list):
                    raise RuntimeError("Batch response not a JSON list")
                by_id = {int(item.get("id", -1)): item for item in decoded if isinstance(item, dict)}
                non_revert_err: Optional[Any] = None
                unresolved_in_chunk: List[int] = []
                to_cache_batch: List[Tuple[str, str, Any]] = []
                for k, orig_i in enumerate(chunk_idxs):
                    item = by_id.get(k)
                    if item is None:
                        if non_revert_err is None:
                            non_revert_err = "missing_batch_item"
                        unresolved_in_chunk.append(orig_i)
                    elif "error" in item and item.get("result") is None:
                        kind = _classify_rpc_error(item.get("error"))
                        if kind != "revert":
                            if non_revert_err is None:
                                non_revert_err = item.get("error")
                            unresolved_in_chunk.append(orig_i)
                        else:
                            results[orig_i] = None
                    else:
                        val = item.get("result")
                        results[orig_i] = val
                        if (
                            self.store is not None
                            and block_pin is not None
                            and block_pin > 0
                            and val is not None
                            and orig_i in param_hashes
                        ):
                            to_cache_batch.append((calls[orig_i][0], param_hashes[orig_i], val))
                if to_cache_batch and self.store is not None and block_pin is not None and block_pin > 0:
                    self.store.put_pinned_rpc_batch(cid, int(block_pin), to_cache_batch)
                cur_unresolved = unresolved_in_chunk
                if non_revert_err is not None:
                    ok_rpc_count += len(chunk_idxs) - len(unresolved_in_chunk)
                    raise RuntimeError(str(non_revert_err))
                self._record_success(url, (time.perf_counter() - t0) * 1000.0, cid=cid)
                ok_rpc_count += len(chunk_idxs)
                del pending[:len(chunk_idxs)]
            except Exception as exc:
                last_transport_err = str(exc)
                kind = _classify_rpc_error(exc)
                self._record_failure(url, kind, cid=cid)
                if len(cur_unresolved) < len(chunk_idxs):
                    pending = cur_unresolved + pending[len(chunk_idxs):]
                url_idx += 1
                if url_idx >= len(urls) * 2:
                    for orig_i in cur_unresolved:
                        m_i, p_i = calls[orig_i]
                        try:
                            results[orig_i] = self.call(c, m_i, p_i, block_pin=block_pin, need_archive=need_archive, timeout=timeout)
                            ok_rpc_count += 1
                        except Exception as sub_exc:
                            last_transport_err = str(sub_exc)
                            results[orig_i] = None
                            if _classify_rpc_error(sub_exc) != "revert":
                                failed_indices.add(orig_i)
                    del pending[:len(cur_unresolved)]
        self._set_tls_batch_failures(failed_indices)
        if raise_on_all_failed and ok_rpc_count == 0:
            raise RuntimeError(f"All batch RPC calls failed on {c}: {last_transport_err}")
        return results

    def _batch_eth_call_fallback(self, c: str, sub_calls: Sequence[Tuple[str, bytes]], btag: str, block_pin: int) -> List[Tuple[bool, bytes]]:
        rpc_batch = [
            ("eth_call", [{"to": _checksum(target), "data": "0x" + bytes(cdata).hex()}, btag])
            for target, cdata in sub_calls
        ]
        tls = getattr(self, "_tls", None)
        if tls is not None:
            tls.last_fallback_transport_failed = False
        try:
            raw_res = self.batch_call(c, rpc_batch, block_pin=block_pin, need_archive=True)
        except Exception:
            if tls is not None:
                tls.last_fallback_transport_failed = True
            return [(False, b"") for _ in sub_calls]
        if tls is not None:
            if int(getattr(tls, "last_batch_transport_failures", 0) or 0) > 0 or len(raw_res) < len(sub_calls):
                tls.last_fallback_transport_failed = True
        fb_out: List[Tuple[bool, bytes]] = []
        for r in raw_res:
            if isinstance(r, str) and r.startswith("0x") and len(r) > 2:
                try:
                    fb_out.append((True, _hex_to_bytes(r)))
                    continue
                except Exception:
                    pass
            fb_out.append((False, b""))
        return fb_out

    def multicall3(
        self,
        chain: str,
        calls: Sequence[Tuple[str, bytes]],
        block_pin: int,
        chunk_size: int = 120,
    ) -> List[Tuple[bool, bytes]]:
        """Multicall3.aggregate3 패스 호출 (불량 노드의 빈 '0x' 응답 감지 및 성공 청크 보존형 청크별 폴백)."""
        tls = getattr(self, "_tls", None)
        if tls is not None:
            tls.last_multicall_transport_failed = False
        if not calls:
            return []
        c = _norm_chain(chain)
        btag = hex(int(block_pin)) if block_pin > 0 else "latest"
        if c in self._no_multicall_chains:
            fb_res = self._batch_eth_call_fallback(c, calls, btag, block_pin)
            if tls is not None:
                tls.last_multicall_transport_failed = bool(getattr(tls, "last_fallback_transport_failed", False))
            return fb_res
        out: List[Tuple[bool, bytes]] = []
        any_transport_failed = False
        for i in range(0, len(calls), chunk_size):
            sub = calls[i:i + chunk_size]
            if c in self._no_multicall_chains:
                out.extend(self._batch_eth_call_fallback(c, sub, btag, block_pin))
                if tls is not None and bool(getattr(tls, "last_fallback_transport_failed", False)):
                    any_transport_failed = True
                continue
            tuples = [(_checksum(target), True, bytes(cdata)) for target, cdata in sub]
            calldata_hex = encode_calldata(AGG3_SEL, ["(address,bool,bytes)[]"], [tuples])
            try:
                raw_hex = self.call(
                    c,
                    "eth_call",
                    [{"to": MULTICALL3_ADDR, "data": calldata_hex}, btag],
                    block_pin=block_pin,
                    need_archive=True,
                )
            except Exception:
                raw_hex = None
            if not raw_hex or str(raw_hex) in ("0x", "0X"):
                try:
                    mc_code = self.call(c, "eth_getCode", [MULTICALL3_ADDR, btag], block_pin=block_pin)
                except Exception:
                    mc_code = "0x"
                if not mc_code or str(mc_code) in ("0x", "0X"):
                    with self._lock:
                        self._no_multicall_chains.add(c)
                out.extend(self._batch_eth_call_fallback(c, sub, btag, block_pin))
                if tls is not None and bool(getattr(tls, "last_fallback_transport_failed", False)):
                    any_transport_failed = True
                continue
            try:
                decoded = abi_decode(["(bool,bytes)[]"], raw_hex)[0]
                if len(decoded) != len(sub):
                    out.extend(self._batch_eth_call_fallback(c, sub, btag, block_pin))
                    if tls is not None and bool(getattr(tls, "last_fallback_transport_failed", False)):
                        any_transport_failed = True
                    continue
                for ok_flag, ret_bytes in decoded:
                    out.append((bool(ok_flag), bytes(ret_bytes)))
            except Exception:
                out.extend(self._batch_eth_call_fallback(c, sub, btag, block_pin))
                if tls is not None and bool(getattr(tls, "last_fallback_transport_failed", False)):
                    any_transport_failed = True
        if tls is not None:
            tls.last_multicall_transport_failed = any_transport_failed
        return out


# ═════════════════════════════════════════════════════════════════════════════
# §3. Sourcify v2 138GB 전체 Parquet + DuckDB 2.0 로컬 엔진 & 3단 소스/Mode B 탐색기
# ═════════════════════════════════════════════════════════════════════════════

SOURCIFY_PARQUET_DIR: Path = CACHE_DIR / "sourcify_v2"
SOURCIFY_MANIFEST_PATH: Path = CACHE_DIR / "sourcify_v2_manifest.json"

SOURCIFY_V2_TABLES: Tuple[str, ...] = (
    "sourcify_matches",
    "verified_contracts",
    "compiled_contracts_signatures",
    "signatures",
    "compiled_contracts_sources",
    "compiled_contracts_metadata",
    "contract_deployments",
    "contracts",
    "sources",
    "compiled_contracts",
    "code",
    "transactions",
)

NGRAM_SIZES: Tuple[int, ...] = (4, 8, 16, 32)
CONTAINMENT_MIN: float = 0.2
MIN_SIZE_RATIO: float = 0.3

def _sql_quote_str(val: str) -> str:
    return "'" + str(val).replace("'", "''") + "'"


_SOURCIFY_META_LOCK = threading.Lock()
_SOURCIFY_META_CACHE: Dict[Tuple[Any, ...], Dict[str, Any]] = {}

_COMMON_BOILERPLATE_SELECTORS: FrozenSet[str] = frozenset({
    "06fdde03", "95d89b41", "313ce567", "18160ddd", "70a08231",
    "a9059cbb", "23b872dd", "095ea7b3", "dd62ed3e", "8da5cb5b",
    "715018a6", "f2fde38b", "5c975abb", "01ffc9a7", "d505accf",
    "3644e515", "7ecebe00",
})


_SOURCIFY_V2_TABLE_RES: Dict[str, re.Pattern[str]] = {
    tbl: re.compile(rf"\b{re.escape(tbl)}\b", re.IGNORECASE) for tbl in SOURCIFY_V2_TABLES
}


def _run_duckdb_cli_json(
    sql: str,
    parquet_root: Optional[Path] = None,
    timeout_sec: float = 30.0,
    scratch_root: Optional[Path] = None,
    table_files: Optional[Dict[str, Sequence[Path]]] = None,
) -> Optional[List[Dict[str, Any]]]:
    """
    `tools/duckdb/duckdb.exe :memory: -json` 비데몬 서브프로세스 Zero-Copy 실행기:
    - SQL 본문에서 실제 참조하는 테이블만 선택적으로 VIEW 바인딩하여 2,210개 Parquet 푸터 불필요 스캔 원천 제거
    - `table_files` 지정 시 해당 테이블 VIEW를 지정된 소수 파일 슬라이스로만 바인딩하여 초고속 파티션 커서 전진 보장
    - `.duckdb` 파일 배타 락 경합 0건 (다중 병렬 프로세스 동시 읽기 100% 무충돌)
    - `home_directory` 및 `temp_directory`를 격리 루트 내부로 제한하여 외부 파일시스템 및 기존 `_cache/` 불변 보장
    """
    if not DUCKDB_BIN.is_file():
        return None
    if scratch_root is not None:
        eff_scratch = scratch_root
    elif parquet_root is not None and parquet_root.resolve() != SOURCIFY_PARQUET_DIR.resolve():
        eff_scratch = parquet_root / "_ddb_scratch"
    else:
        _curr_art = globals().get("ARTIFACT_ROOT", AUDIT_ROOT)
        eff_scratch = (_curr_art / "_cache") if _curr_art.resolve() != AUDIT_ROOT.resolve() else CACHE_DIR
    pid_tag = f"p_{os.getpid()}_{threading.get_ident()}"
    home_dir = eff_scratch / "duckdb_home" / pid_tag
    tmp_dir = eff_scratch / "duckdb_tmp" / pid_tag
    home_dir.mkdir(parents=True, exist_ok=True)
    tmp_dir.mkdir(parents=True, exist_ok=True)
    stmts: List[str] = [
        "SET memory_limit = '1536MB';",
        "SET threads = 2;",
        "SET preserve_insertion_order = false;",
        f"SET home_directory = {_sql_quote_str(home_dir.resolve().as_posix())};",
        f"SET temp_directory = {_sql_quote_str(tmp_dir.resolve().as_posix())};",
    ]
    if parquet_root is not None and parquet_root.is_dir():
        for tbl, tbl_re in _SOURCIFY_V2_TABLE_RES.items():
            if not tbl_re.search(sql):
                continue
            files_override = [Path(fp) for fp in ((table_files or {}).get(tbl) or ()) if Path(fp).is_file()]
            if files_override:
                f_arr = ", ".join(_sql_quote_str(fp.resolve().as_posix()) for fp in files_override)
                stmts.append(
                    f"CREATE OR REPLACE VIEW {tbl} AS SELECT * FROM read_parquet([{f_arr}], union_by_name=true);"
                )
                continue
            tdir = parquet_root / tbl
            if tdir.is_dir():
                pfiles = list(tdir.glob("*.parquet"))
                if pfiles:
                    glob_pat = (tdir.resolve() / "*.parquet").as_posix()
                    stmts.append(
                        f"CREATE OR REPLACE VIEW {tbl} AS SELECT * FROM read_parquet({_sql_quote_str(glob_pat)}, union_by_name=true);"
                    )
    stmts.append(sql.strip().rstrip(";") + ";")
    full_sql = "\n".join(stmts) + "\n"
    try:
        eff_scratch.mkdir(parents=True, exist_ok=True)
        cp = subprocess.run(
            [str(DUCKDB_BIN), ":memory:", "-json", "-c", full_sql],
            stdin=subprocess.DEVNULL,
            capture_output=True,
            timeout=max(5.0, float(timeout_sec)),
            check=False,
            cwd=str(eff_scratch.resolve()),
            env=_isolated_subproc_env(eff_scratch),
        )
        if cp.returncode != 0:
            return None
        out_txt = cp.stdout.decode("utf-8", errors="replace").strip()
        if not out_txt:
            return []
        parsed = json.loads(out_txt)
        if isinstance(parsed, list):
            return [r for r in parsed if isinstance(r, dict)]
        return []
    except Exception:
        return None
    finally:
        shutil.rmtree(home_dir, ignore_errors=True)
        shutil.rmtree(tmp_dir, ignore_errors=True)
        for _pdir in (home_dir.parent, tmp_dir.parent):
            try:
                if _pdir.is_dir() and not any(_pdir.iterdir()):
                    _pdir.rmdir()
            except OSError:
                pass


def _get_sourcify_v2_meta(parquet_root: Path) -> Dict[str, Any]:
    """Parquet 루트별 테이블 파일 수 및 컬럼 타입 스키마를 1회 단일 프로세스로 프로빙 후 메모리 캐싱."""
    if not parquet_root.is_dir():
        return {"file_counts": {}, "col_types": {}}
    file_counts: Dict[str, int] = {}
    first_files: Dict[str, str] = {}
    for tbl in SOURCIFY_V2_TABLES:
        tdir = parquet_root / tbl
        if tdir.is_dir():
            pfiles = sorted(tdir.glob("*.parquet"))
            if pfiles:
                file_counts[tbl] = len(pfiles)
                first_files[tbl] = pfiles[0].resolve().as_posix()
    cache_key = (str(parquet_root.resolve()), tuple(sorted(file_counts.items())))
    with _SOURCIFY_META_LOCK:
        cached = _SOURCIFY_META_CACHE.get(cache_key)
        if cached is not None:
            return cached
    col_types: Dict[str, Dict[str, str]] = {}
    if first_files and DUCKDB_BIN.is_file():
        union_parts: List[str] = []
        for tbl, fpath in sorted(first_files.items()):
            union_parts.append(
                f"SELECT {_sql_quote_str(tbl)} AS tbl_name, column_name, column_type "
                f"FROM (DESCRIBE SELECT * FROM read_parquet({_sql_quote_str(fpath)}))"
            )
        scratch = (parquet_root / "_ddb_scratch") if parquet_root.resolve() != SOURCIFY_PARQUET_DIR.resolve() else None
        rows = _run_duckdb_cli_json(" UNION ALL ".join(union_parts), parquet_root=None, timeout_sec=15.0, scratch_root=scratch)
        for r in rows or []:
            tn = str(r.get("tbl_name") or "")
            cn = str(r.get("column_name") or "").lower()
            ct = str(r.get("column_type") or "").upper()
            if tn and cn:
                col_types.setdefault(tn, {})[cn] = ct
    meta_doc = {"file_counts": file_counts, "col_types": col_types}
    with _SOURCIFY_META_LOCK:
        _SOURCIFY_META_CACHE[cache_key] = meta_doc
    return meta_doc


_S3_CONTENTS_RE: re.Pattern[str] = re.compile(r"<Contents>(.*?)</Contents>", re.DOTALL)
_S3_KEY_RE: re.Pattern[str] = re.compile(r"<Key>(v2/([^/]+)/[^<]+\.parquet)</Key>")
_S3_SIZE_RE: re.Pattern[str] = re.compile(r"<Size>\s*(\d+)\s*</Size>")
_HEX64_RE: re.Pattern[str] = re.compile(r"[0-9a-f]{64}")


def _parse_sourcify_s3_xml_contents(xml: str, wanted: Set[str]) -> List[Tuple[str, str, int]]:
    """S3 ListObjects XML의 각 <Contents> 블록에서 태그 순서(<ETag> 개입 등)와 무관하게 <Key> 및 <Size>를 독립 추출."""
    out: List[Tuple[str, str, int]] = []
    for bm in _S3_CONTENTS_RE.finditer(xml):
        blk = bm.group(1)
        km = _S3_KEY_RE.search(blk)
        if not km:
            continue
        rel_key, tbl = km.group(1).strip(), km.group(2).strip()
        if tbl not in wanted:
            continue
        sm = _S3_SIZE_RE.search(blk)
        sz_val = int(sm.group(1)) if sm else 0
        out.append((tbl, rel_key, sz_val))
    return out


def _sourcify_deployment_sql_parts(d_cols: Dict[str, str], chain_id: Optional[int]) -> Tuple[str, str]:
    chain_filter = (
        f"AND d.chain_id = {int(chain_id)}"
        if (chain_id is not None and "INT" in d_cols.get("chain_id", ""))
        else (f"AND CAST(d.chain_id AS BIGINT) = {int(chain_id)}" if chain_id is not None else "")
    )
    addr_proj = (
        "'0x' || lower(hex(d.address))"
        if "BLOB" in d_cols.get("address", "")
        else "CASE WHEN typeof(d.address) = 'BLOB' THEN '0x' || lower(hex(d.address)) ELSE lower(CAST(d.address AS VARCHAR)) END"
    )
    return chain_filter, addr_proj


def _sf_col(cols_map: Dict[str, str], primary: str, *fallbacks: str) -> str:
    """Sourcify v2 및 Verifier Alliance Parquet 스키마 별칭(compilation_id / compiled_contract_id, deployment_id / contract_deployment_id) 자동 해석."""
    if not cols_map or primary in cols_map:
        return primary
    for fb in fallbacks:
        if fb in cols_map:
            return fb
    return primary


def _unpack_sourcify_v2_meta(p_root: Path) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    sf_meta = _get_sourcify_v2_meta(p_root)
    return (sf_meta.get("file_counts") or {}), (sf_meta.get("col_types") or {})


def _iter_sourcify_sidecar_items(
    p_root: Path, chain_id: Optional[int] = None
) -> Iterator[Tuple[int, Dict[str, Any]]]:
    sidecar = p_root / "_local_index.jsonl"
    if not sidecar.is_file():
        return
    try:
        with sidecar.open("r", encoding="utf-8", errors="replace") as fh:
            for line in fh:
                if not line.strip():
                    continue
                item = json.loads(line)
                cid = int(item.get("chain_id") or 0)
                if chain_id is not None and cid != int(chain_id):
                    continue
                yield cid, item
    except Exception:
        return


def _query_local_sourcify_verified(
    chain_id: int,
    address: str,
    parquet_root: Optional[Path] = None,
) -> Optional[Dict[str, Any]]:
    """로컬 Sourcify v2 Parquet(DUCKDB_BIN `:memory:` Zero-Copy) 또는 로컬 인덱스에서 ABI 및 Solidity 소스를 조회."""
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR
    addr = _norm_addr(address)
    if chain_id <= 0 or not addr or not p_root.is_dir():
        return None
    f_counts, c_types = _unpack_sourcify_v2_meta(p_root)
    req_dirs = ("contract_deployments", "verified_contracts", "compiled_contracts")
    has_parquet = all(int(f_counts.get(d, 0)) > 0 for d in req_dirs)
    if has_parquet and DUCKDB_BIN.is_file():
        cc_cols_map = c_types.get("compiled_contracts") or {}
        d_cols_map = c_types.get("contract_deployments") or {}
        vc_cols_map = c_types.get("verified_contracts") or {}
        if cc_cols_map:
            cc_pk = _sf_col(cc_cols_map, "id", "compilation_id", "compiled_contract_id")
            vc_comp_col = _sf_col(vc_cols_map, "compilation_id", "compiled_contract_id")
            vc_dep_col = _sf_col(vc_cols_map, "deployment_id", "contract_deployment_id")
            d_addr_type = d_cols_map.get("address", "")
            abi_expr = "CAST(cc.abi AS VARCHAR)" if "abi" in cc_cols_map else "''"
            comp_art_expr = "CAST(cc.compilation_artifacts AS VARCHAR)" if "compilation_artifacts" in cc_cols_map else "''"
            cc_src_expr = "CAST(cc.sources AS VARCHAR)" if "sources" in cc_cols_map else "''"
            fqn_expr = "CAST(cc.fully_qualified_name AS VARCHAR)" if "fully_qualified_name" in cc_cols_map else "''"
            addr_hex = addr[2:].lower()
            addr_pred = (
                f"d.address = unhex({_sql_quote_str(addr_hex)})"
                if "BLOB" in d_addr_type
                else f"lower(CASE WHEN typeof(d.address) = 'BLOB' THEN hex(d.address) ELSE replace(CAST(d.address AS VARCHAR), '0x', '') END) = {_sql_quote_str(addr_hex)}"
            )
            d_cid_type = d_cols_map.get("chain_id", "")
            cid_pred = f"d.chain_id = {int(chain_id)}" if "INT" in d_cid_type else f"CAST(d.chain_id AS BIGINT) = {int(chain_id)}"
            vc_order = "ORDER BY vc.id DESC" if (not vc_cols_map or "id" in vc_cols_map) else ""
            vc_rows = _run_duckdb_cli_json(
                f"""
                SELECT CAST(vc.{vc_comp_col} AS VARCHAR) AS comp_id
                FROM contract_deployments d
                JOIN verified_contracts vc ON vc.{vc_dep_col} = d.id
                WHERE {cid_pred}
                  AND {addr_pred}
                {vc_order}
                LIMIT 1
                """,
                parquet_root=p_root,
                timeout_sec=20.0,
            )
            comp_id = str((vc_rows[0] if vc_rows else {}).get("comp_id") or "")
            q_rows = None
            if comp_id:
                cc_pk_type = cc_cols_map.get(cc_pk, "")
                cc_pred = (
                    f"cc.{cc_pk} = {_sql_quote_str(comp_id)}"
                    if "VARCHAR" in cc_pk_type
                    else (
                        f"cc.{cc_pk} = {int(comp_id)}"
                        if ("INT" in cc_pk_type and comp_id.isdigit())
                        else f"CAST(cc.{cc_pk} AS VARCHAR) = {_sql_quote_str(comp_id)}"
                    )
                )
                q_rows = _run_duckdb_cli_json(
                    f"""
                    SELECT
                        CAST(cc.name AS VARCHAR) AS contract_name,
                        {fqn_expr} AS fqn_str,
                        {abi_expr} AS abi_str,
                        {comp_art_expr} AS comp_art_str,
                        {cc_src_expr} AS cc_sources_str
                    FROM compiled_contracts cc
                    WHERE {cc_pred}
                    LIMIT 1
                    """,
                    parquet_root=p_root,
                    timeout_sec=20.0,
                )
            if q_rows:
                r0 = q_rows[0]
                cname = str(r0.get("contract_name") or "Contract")
                fqn_path = str(r0.get("fqn_str") or "").split(":", 1)[0].strip()
                abi_str = str(r0.get("abi_str") or "")
                comp_art_str = str(r0.get("comp_art_str") or "")
                cc_sources_str = str(r0.get("cc_sources_str") or "")
                abi_list: List[Any] = []
                if abi_str.startswith("["):
                    try:
                        abi_list = json.loads(abi_str)
                    except Exception:
                        abi_list = []
                if not abi_list and comp_art_str.startswith("{"):
                    try:
                        art_obj = json.loads(comp_art_str)
                        if isinstance(art_obj, dict) and isinstance(art_obj.get("abi"), list):
                            abi_list = art_obj["abi"]
                    except Exception:
                        pass
                if not abi_list and comp_id and int(f_counts.get("compiled_contracts_metadata", 0)) > 0:
                    ccm_cols = c_types.get("compiled_contracts_metadata") or {}
                    ccm_col = _sf_col(ccm_cols, "compilation_id", "compiled_contract_id")
                    ccm_type = ccm_cols.get(ccm_col, "")
                    ccm_cid_pred = (
                        f"ccm.{ccm_col} = {_sql_quote_str(comp_id)}"
                        if "VARCHAR" in ccm_type
                        else (
                            f"ccm.{ccm_col} = {int(comp_id)}"
                            if ("INT" in ccm_type and comp_id.isdigit())
                            else f"CAST(ccm.{ccm_col} AS VARCHAR) = {_sql_quote_str(comp_id)}"
                        )
                    )
                    mrows = _run_duckdb_cli_json(
                        f"""
                        SELECT CAST(ccm.metadata AS VARCHAR) AS meta_str
                        FROM compiled_contracts_metadata ccm
                        WHERE {ccm_cid_pred}
                        LIMIT 1
                        """,
                        parquet_root=p_root,
                        timeout_sec=20.0,
                    )
                    for mr in mrows or []:
                        m_str = str(mr.get("meta_str") or "")
                        if m_str.startswith("{"):
                            try:
                                m_obj = json.loads(m_str)
                                out_abi = (m_obj.get("output") or {}).get("abi") if isinstance(m_obj, dict) else None
                                if isinstance(out_abi, list):
                                    abi_list = out_abi
                                    break
                                if isinstance(m_obj, dict) and isinstance(m_obj.get("abi"), list):
                                    abi_list = m_obj["abi"]
                                    break
                            except Exception:
                                pass
                sources_map: Dict[str, str] = {}
                if cc_sources_str.startswith("{"):
                    try:
                        parsed_s = json.loads(cc_sources_str)
                        if isinstance(parsed_s, dict):
                            for fn, fobj in parsed_s.items():
                                if isinstance(fobj, dict) and fobj.get("content"):
                                    sources_map[str(fn)] = str(fobj["content"])
                                elif isinstance(fobj, str):
                                    sources_map[str(fn)] = fobj
                    except Exception:
                        pass
                if (
                    not sources_map
                    and comp_id
                    and int(f_counts.get("compiled_contracts_sources", 0)) > 0
                    and int(f_counts.get("sources", 0)) > 0
                ):
                    ccs_cols = c_types.get("compiled_contracts_sources") or {}
                    s_cols = c_types.get("sources") or {}
                    ccs_col = _sf_col(ccs_cols, "compilation_id", "compiled_contract_id")
                    ccs_type = ccs_cols.get(ccs_col, "")
                    ccs_cid_pred = (
                        f"ccs.{ccs_col} = {_sql_quote_str(comp_id)}"
                        if "VARCHAR" in ccs_type
                        else (
                            f"ccs.{ccs_col} = {int(comp_id)}"
                            if ("INT" in ccs_type and comp_id.isdigit())
                            else f"CAST(ccs.{ccs_col} AS VARCHAR) = {_sql_quote_str(comp_id)}"
                        )
                    )
                    sh_proj = (
                        "lower(hex(ccs.source_hash))"
                        if "BLOB" in ccs_cols.get("source_hash", "")
                        else "lower(CASE WHEN typeof(ccs.source_hash) = 'BLOB' THEN hex(ccs.source_hash) ELSE replace(CAST(ccs.source_hash AS VARCHAR), '0x', '') END)"
                    )
                    ccs_rows = _run_duckdb_cli_json(
                        f"""
                        SELECT CAST(ccs.path AS VARCHAR) AS path, {sh_proj} AS sh_hex
                        FROM compiled_contracts_sources ccs
                        WHERE {ccs_cid_pred}
                        """,
                        parquet_root=p_root,
                        timeout_sec=15.0,
                    )
                    if ccs_rows:
                        ordered_ccs = sorted(
                            ccs_rows,
                            key=lambda r: (
                                0 if (fqn_path and str(r.get("path") or "") == fqn_path) else (
                                    1 if not str(r.get("path") or "").startswith(("@", "lib/", "node_modules/")) else 2
                                ),
                                str(r.get("path") or ""),
                            ),
                        )
                        path_by_sh: Dict[str, List[str]] = {}
                        for cr_item in ordered_ccs:
                            p_str = str(cr_item.get("path") or "")
                            sh_str = str(cr_item.get("sh_hex") or "").strip().lower()
                            if p_str and sh_str and _HEX64_RE.fullmatch(sh_str):
                                path_by_sh.setdefault(sh_str, []).append(p_str)
                        if path_by_sh:
                            s_sh_blob = "BLOB" in s_cols.get("source_hash", "")
                            sh_keys_sorted = sorted(path_by_sh.keys())
                            for sh_off in range(0, len(sh_keys_sorted), 64):
                                sh_chunk = sh_keys_sorted[sh_off : sh_off + 64]
                                union_src_queries = [
                                    (
                                        f"SELECT {_sql_quote_str(sh_k)} AS sh_hex, CAST(s.content AS VARCHAR) AS content "
                                        f"FROM sources s WHERE s.source_hash = unhex({_sql_quote_str(sh_k)})"
                                    )
                                    if s_sh_blob
                                    else (
                                        f"SELECT {_sql_quote_str(sh_k)} AS sh_hex, CAST(s.content AS VARCHAR) AS content "
                                        f"FROM sources s WHERE lower(replace(CAST(s.source_hash AS VARCHAR), '0x', '')) = {_sql_quote_str(sh_k)}"
                                    )
                                    for sh_k in sh_chunk
                                ]
                                srows = _run_duckdb_cli_json(
                                    " UNION ALL ".join(union_src_queries),
                                    parquet_root=p_root,
                                    timeout_sec=20.0,
                                )
                                for sr in srows or []:
                                    sh_got = str(sr.get("sh_hex") or "").lower()
                                    sc = str(sr.get("content") or "")
                                    if sh_got and sc:
                                        for sp in path_by_sh.get(sh_got, []):
                                            sources_map[sp] = sc
                if abi_list or sources_map:
                    return {
                        "verified": True,
                        "provider": "sourcify_v2_local_parquet",
                        "contract_name": cname,
                        "abi": abi_list,
                        "sources": sources_map,
                    }
    for _, item in _iter_sourcify_sidecar_items(p_root, chain_id):
        if _norm_addr(item.get("address")) == addr:
            abi_l = item.get("abi") if isinstance(item.get("abi"), list) else []
            src_m = item.get("sources") if isinstance(item.get("sources"), dict) else {}
            if abi_l or src_m:
                return {
                    "verified": True,
                    "provider": "sourcify_v2_local_parquet",
                    "contract_name": str(item.get("contract_name") or "Contract"),
                    "abi": abi_l,
                    "sources": src_m,
                }
    return None


def _strip_cbor_bytes(raw: bytes) -> bytes:
    """CBOR 메타데이터 트레일러(끝 2바이트 길이 + 0xa1/0xa2/0xa3 맵 헤더) 제거."""
    if len(raw) > 4:
        tail_len = int.from_bytes(raw[-2:], "big")
        if 0 < tail_len < len(raw) - 2 and (raw[-2 - tail_len] & 0xE0) == 0xA0:
            return raw[:-2 - tail_len]
    for marker in (b"\xa2dipfsX\"", b"\xa2ebzzr1X ", b"\xa2ebzzr0X ", b"\xa1dsolcC"):
        idx = raw.rfind(marker)
        if idx > 0 and (len(raw) - idx) <= 96:
            return raw[:idx]
    return raw


def _extract_grams_clean(clean: bytes, sizes: Sequence[int] = NGRAM_SIZES) -> Set[bytes]:
    """CBOR 이미 제거 완료된 바이트열에서 4/8/16/32 바이트 멀티그램 집합 추출."""
    grams: Set[bytes] = set()
    n_len = len(clean)
    for sz in sizes:
        if n_len >= sz:
            step = 1 if n_len <= 16384 else max(1, sz // 2)
            for i in range(0, n_len - sz + 1, step):
                grams.add(clean[i : i + sz])
    return grams


def _normalize_bytecode_immediates(clean: bytes) -> bytes:
    """
    CBOR 제거 바이트코드에서 함수 셀렉터·소형 오프셋(PUSH1..PUSH4)은 보존하고
    PUSH5..PUSH32(0x64..0x7f) 불변 주소·상수·솔트 피연산자만 0x00*k로 정규화 마스킹한다.
    """
    if not clean:
        return b""
    out = bytearray()
    pc = 0
    n = len(clean)
    while pc < n:
        op = clean[pc]
        out.append(op)
        spec = _effective_opcode_spec(clean, pc)
        imm_w = spec[3] if spec is not None else 0
        if imm_w > 0:
            avail = min(imm_w, n - (pc + 1))
            if 0x64 <= op <= 0x7F:
                out.extend(b"\x00" * avail)
            else:
                out.extend(clean[pc + 1 : pc + 1 + avail])
            pc += 1 + avail
        else:
            pc += 1
    return bytes(out)


def _containment_from_clean(s_clean: bytes, c_clean: bytes) -> float:
    s_grams = _extract_grams_clean(s_clean)
    c_grams = _extract_grams_clean(c_clean)
    if not s_grams or not c_grams:
        return 0.0
    return float(len(s_grams & c_grams)) / float(len(s_grams))


def compute_multigram_containment(seed_raw: bytes, cand_raw: bytes) -> float:
    """
    Exact CBOR-stripped 일치 시 1.0, 불변 주소·상수 마스킹 후 완전 일치 시 0.995,
    크기 비율 >= MIN_SIZE_RATIO(0.3) 하 원본 및 불변-마스킹 멀티그램 Containment 최댓값 산출.
    """
    s_clean = _strip_cbor_bytes(seed_raw)
    c_clean = _strip_cbor_bytes(cand_raw)
    if not s_clean or not c_clean:
        return 0.0
    if s_clean == c_clean:
        return 1.0
    ratio = float(min(len(s_clean), len(c_clean))) / float(max(len(s_clean), len(c_clean)))
    if ratio < MIN_SIZE_RATIO:
        return 0.0
    raw_score = _containment_from_clean(s_clean, c_clean)
    s_masked = _normalize_bytecode_immediates(s_clean)
    c_masked = _normalize_bytecode_immediates(c_clean)
    if s_masked and c_masked and s_masked == c_masked:
        return max(raw_score, 0.995)
    masked_score = _containment_from_clean(s_masked, c_masked) if (s_masked and c_masked) else 0.0
    return max(raw_score, masked_score)


def _parse_usable_sourcify_row(
    row: Mapping[str, Any], addr_key: str = "addr_hex"
) -> Optional[Tuple[int, str, str]]:
    cid_v = int(row.get("cid") or 0)
    c_slug = CHAIN_BY_ID.get(cid_v, "")
    if not c_slug or not _usable_chain(c_slug):
        return None
    s_raw = str(row.get(addr_key) or "")
    addr_n = _norm_addr(s_raw if s_raw.startswith("0x") else ("0x" + s_raw)) if s_raw else ""
    return (cid_v, c_slug, addr_n) if addr_n else None


def _unpack_sourcify_base_schema(
    p_root: Path, chain_id: Optional[int] = None
) -> Tuple[Dict[str, int], Dict[str, Dict[str, str]], Dict[str, str], Dict[str, str], str, str]:
    f_counts, c_types = _unpack_sourcify_v2_meta(p_root)
    d_cols = c_types.get("contract_deployments") or {}
    ct_cols = c_types.get("contracts") or {}
    chain_filter, addr_proj = _sourcify_deployment_sql_parts(d_cols, chain_id)
    return f_counts, c_types, d_cols, ct_cols, chain_filter, addr_proj


def _make_sourcify_proxy_accumulator() -> Tuple[
    List[Dict[str, Any]],
    Set[Tuple[int, str]],
    Callable[..., bool],
]:
    out: List[Dict[str, Any]] = []
    seen: Set[Tuple[int, str]] = set()

    def _try_record_proxy(
        cid: int, raw_addr: Any, *, impl_addr: str = "", proxy_source: str = ""
    ) -> bool:
        parsed = _parse_usable_sourcify_row({"cid": cid, "addr_hex": raw_addr})
        if parsed is None:
            return False
        cid_v, c_slug, addr = parsed
        if (cid_v, addr) in seen:
            return False
        seen.add((cid_v, addr))
        rec: Dict[str, Any] = {
            "chain_id": cid_v,
            "chain": c_slug,
            "address": addr,
            "proxy_address": addr,
        }
        if impl_addr:
            rec["impl_address"] = _norm_addr(impl_addr)
        if proxy_source:
            rec["proxy_source"] = proxy_source
        out.append(rec)
        return True

    return out, seen, _try_record_proxy


def search_sourcify_v2_similar_contracts(
    seed_bytecodes: Union[bytes, Sequence[bytes]],
    parquet_root: Optional[Path] = None,
    min_containment: float = CONTAINMENT_MIN,
    limit_per_seed: Optional[int] = None,
    chain_id: Optional[int] = None,
    limit: Optional[int] = None,
    allow_bulk_parquet_scan: bool = True,
) -> List[Dict[str, Any]]:
    """
    Sourcify v2 / Verifier Alliance 로컬 Parquet DB(DUCKDB_BIN Zero-Copy) 또는 로컬 인덱스에서:
    1) BLOB 통계 푸시다운 기반 Exact runtime_code_hash 매칭(1.0) 초고속 전수 조회
    2) Selector-Set 프리필터 및 Multi-gram(4,8,16,32) 정밀 스코어링 전수 수행 후 결정론적 정렬 반환
    """
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR
    raw_list: List[bytes] = [bytes(seed_bytecodes)] if isinstance(seed_bytecodes, (bytes, bytearray)) else [bytes(b) for b in seed_bytecodes if b]
    valid_seeds = [_strip_cbor_bytes(b) for b in raw_list if len(_strip_cbor_bytes(b)) >= 16]
    if not valid_seeds or not p_root.is_dir():
        return []
    max_total = (
        int(limit)
        if (limit is not None and int(limit) > 0)
        else (
            max(1, int(limit_per_seed) * max(1, len(valid_seeds)))
            if (limit_per_seed is not None and int(limit_per_seed) > 0)
            else 0
        )
    )
    results_by_key: Dict[Tuple[int, str], Dict[str, Any]] = {}

    def _record_result(cid_val: int, chain_slug: str, addr: str, score_val: float, match_type: str) -> None:
        key_ca = (cid_val, addr)
        prev = results_by_key.get(key_ca)
        if prev is None or score_val > float(prev.get("score", 0.0)):
            results_by_key[key_ca] = {
                "chain_id": cid_val,
                "chain": chain_slug,
                "address": addr,
                "score": round(score_val, 4),
                "containment": round(score_val, 4),
                "match_type": match_type,
            }

    def _ingest_candidate_row(cid_val: int, addr_raw: Any, code_hex_raw: Any) -> None:
        chain_slug = CHAIN_BY_ID.get(cid_val, "")
        if not chain_slug or not _usable_chain(chain_slug):
            return
        addr_s = str(addr_raw or "")
        addr = _norm_addr(addr_s if addr_s.startswith("0x") else ("0x" + addr_s))
        if not addr:
            return
        existing = results_by_key.get((cid_val, addr))
        if existing is not None and float(existing.get("score", 0.0)) >= 1.0:
            return
        chex = str(code_hex_raw or "").replace("0x", "").strip()
        if not chex:
            return
        try:
            cand_bytes = bytes.fromhex(chex)
        except Exception:
            return
        best_score = 0.0
        for sb in valid_seeds:
            sc = compute_multigram_containment(sb, cand_bytes)
            if sc > best_score:
                best_score = sc
            if best_score >= 1.0:
                break
        if best_score >= min_containment:
            _record_result(
                cid_val,
                chain_slug,
                addr,
                best_score,
                "exact" if best_score >= 0.9999 else "ngram",
            )

    f_counts, c_types, _d_cols, ct_cols, chain_filter, addr_proj = _unpack_sourcify_base_schema(p_root, chain_id)
    has_base_parquet = int(f_counts.get("contract_deployments", 0)) > 0 and int(f_counts.get("contracts", 0)) > 0
    code_file_cnt = int(f_counts.get("code", 0))

    if has_base_parquet and DUCKDB_BIN.is_file():
        vc_cols = c_types.get("verified_contracts") or {}
        ccs_sig_cols = c_types.get("compiled_contracts_signatures") or {}
        vc_comp_col = _sf_col(vc_cols, "compilation_id", "compiled_contract_id")
        vc_dep_col = _sf_col(vc_cols, "deployment_id", "contract_deployment_id")
        ccs_sig_comp_col = _sf_col(ccs_sig_cols, "compilation_id", "compiled_contract_id")
        cand_hashes: Set[str] = set()
        for rb in raw_list + valid_seeds:
            cand_hashes.add(hashlib.sha256(rb).hexdigest().lower())
            cand_hashes.add(_keccak256(rb).hex().lower())

        rch_type = ct_cols.get("runtime_code_hash", "")
        if "BLOB" in rch_type:
            rch_pred = f"ct.runtime_code_hash IN ({', '.join(f'unhex({_sql_quote_str(h)})' for h in sorted(cand_hashes))})"
        else:
            rch_pred = (
                "lower(CASE WHEN typeof(ct.runtime_code_hash) = 'BLOB' THEN hex(ct.runtime_code_hash) "
                f"ELSE replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', '') END) IN ({', '.join(_sql_quote_str(h) for h in sorted(cand_hashes))})"
            )

        exact_rows = _run_duckdb_cli_json(
            f"""
            SELECT
                CAST(d.chain_id AS BIGINT) AS cid,
                {addr_proj} AS addr_hex
            FROM contracts ct
            JOIN contract_deployments d ON d.contract_id = ct.id
            WHERE {rch_pred}
              {chain_filter}
            """,
            parquet_root=p_root,
            timeout_sec=25.0,
        )
        for er in exact_rows or []:
            parsed_er = _parse_usable_sourcify_row(er)
            if parsed_er is not None:
                _record_result(parsed_er[0], parsed_er[1], parsed_er[2], 1.0, "exact")

        has_sig_tables = all(
            int(f_counts.get(d, 0)) > 0
            for d in ("signatures", "compiled_contracts_signatures", "verified_contracts")
        )
        if has_sig_tables and (allow_bulk_parquet_scan or code_file_cnt <= 32):
            disp_seed_sels: Set[str] = set()
            all_seed_sels: Set[str] = set()
            for sb in valid_seeds:
                dis_sb = _disassemble(sb)
                for idx_d, (_, nm, imm) in enumerate(dis_sb):
                    if nm == "PUSH4" and len(imm) == 4 and imm not in (b"\x00\x00\x00\x00", b"\xff\xff\xff\xff"):
                        sh_l = imm.hex().lower()
                        all_seed_sels.add(sh_l)
                        if any(dis_sb[j][1] in ("EQ", "SUB", "GT", "LT") for j in range(idx_d + 1, min(len(dis_sb), idx_d + 4))):
                            disp_seed_sels.add(sh_l)
            base_sels = disp_seed_sels if disp_seed_sels else all_seed_sels
            distinctive_sels = sorted(base_sels - _COMMON_BOILERPLATE_SELECTORS)
            chosen_sels = distinctive_sels if distinctive_sels else sorted(base_sels)
            if len(chosen_sels) >= 1:
                sel_blob_in = ", ".join(f"unhex({_sql_quote_str(sh)})" for sh in chosen_sels)
                ratio_req = 0.4 if code_file_cnt > 16 else max(min_containment, 0.5)
                min_match_cnt = 1 if len(chosen_sels) == 1 else max(2, int(len(chosen_sels) * ratio_req))
                rch_hex_proj = (
                    "lower(hex(ct.runtime_code_hash))"
                    if "BLOB" in rch_type
                    else "lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', ''))"
                )
                sel_rows = _run_duckdb_cli_json(
                    f"""
                    WITH matched_comps AS (
                        SELECT
                            ccs.{ccs_sig_comp_col} AS comp_id_val,
                            COUNT(DISTINCT s.signature_hash_4) AS matched_cnt
                        FROM signatures s
                        JOIN compiled_contracts_signatures ccs ON ccs.signature_hash_32 = s.signature_hash_32
                        WHERE s.signature_hash_4 IN ({sel_blob_in})
                          AND ccs.signature_type = 'function'
                        GROUP BY ccs.{ccs_sig_comp_col}
                        HAVING COUNT(DISTINCT s.signature_hash_4) >= {int(min_match_cnt)}
                    )
                    SELECT
                        CAST(d.chain_id AS BIGINT) AS cid,
                        {addr_proj} AS addr_hex,
                        {rch_hex_proj} AS rch_hex,
                        CAST(mc.matched_cnt AS BIGINT) AS m_cnt
                    FROM matched_comps mc
                    JOIN verified_contracts vc ON vc.{vc_comp_col} = mc.comp_id_val
                    JOIN contract_deployments d ON vc.{vc_dep_col} = d.id
                    JOIN contracts ct ON d.contract_id = ct.id
                    WHERE 1=1 {chain_filter}
                    ORDER BY mc.matched_cnt DESC, d.chain_id ASC, addr_hex ASC
                    """,
                    parquet_root=p_root,
                    timeout_sec=25.0,
                )
                code_by_hash: Dict[str, str] = {}
                if sel_rows and code_file_cnt > 0:
                    cand_rchs = sorted({str(r.get("rch_hex") or "") for r in sel_rows if _HEX64_RE.fullmatch(str(r.get("rch_hex") or ""))})
                    if cand_rchs:
                        cd_cols = c_types.get("code") or {}
                        cd_ch_blob = "BLOB" in cd_cols.get("code_hash", "")
                        for rch_off in range(0, len(cand_rchs), 64):
                            rch_chunk = cand_rchs[rch_off : rch_off + 64]
                            union_code_q = [
                                (
                                    f"SELECT {_sql_quote_str(h)} AS ch_hex, lower(hex(cd.code)) AS c_hex "
                                    f"FROM code cd WHERE cd.code_hash = unhex({_sql_quote_str(h)}) AND cd.code IS NOT NULL"
                                )
                                if cd_ch_blob
                                else (
                                    f"SELECT {_sql_quote_str(h)} AS ch_hex, lower(hex(cd.code)) AS c_hex "
                                    f"FROM code cd WHERE lower(CASE WHEN typeof(cd.code_hash) = 'BLOB' THEN hex(cd.code_hash) ELSE replace(CAST(cd.code_hash AS VARCHAR), '0x', '') END) = {_sql_quote_str(h)} AND cd.code IS NOT NULL"
                                )
                                for h in rch_chunk
                            ]
                            c_rows = _run_duckdb_cli_json(
                                " UNION ALL ".join(union_code_q),
                                parquet_root=p_root,
                                timeout_sec=15.0,
                            )
                            for cr in c_rows or []:
                                ch_k = str(cr.get("ch_hex") or "")
                                c_v = str(cr.get("c_hex") or "")
                                if ch_k and c_v:
                                    code_by_hash[ch_k] = c_v
                for sr in sel_rows or []:
                    rch_k = str(sr.get("rch_hex") or "")
                    if rch_k and rch_k in code_by_hash:
                        _ingest_candidate_row(int(sr.get("cid") or 0), sr.get("addr_hex"), code_by_hash[rch_k])
                        continue
                    parsed_sr = _parse_usable_sourcify_row(sr)
                    m_cnt = int(sr.get("m_cnt") or 0)
                    sc = min(0.99, float(m_cnt) / float(max(1, len(chosen_sels))))
                    if parsed_sr is not None and sc >= min_containment:
                        _record_result(parsed_sr[0], parsed_sr[1], parsed_sr[2], sc, "selector_containment")

        if 0 < code_file_cnt <= 32:
            min_len = min(len(s) for s in valid_seeds)
            max_len = max(len(s) for s in valid_seeds)
            len_lo = max(16, int(min_len * MIN_SIZE_RATIO))
            len_hi = int(max_len / max(0.05, MIN_SIZE_RATIO)) + 256
            mid_len = max(16, int((min_len + max_len) // 2))
            scan_rows = _run_duckdb_cli_json(
                f"""
                SELECT
                    CAST(d.chain_id AS BIGINT) AS cid,
                    {addr_proj} AS addr_hex,
                    CASE WHEN typeof(cd.code) = 'BLOB' THEN lower(hex(cd.code))
                         ELSE replace(lower(CAST(cd.code AS VARCHAR)), '0x', '') END AS code_hex
                FROM contract_deployments d
                JOIN contracts ct ON d.contract_id = ct.id
                JOIN code cd ON ct.runtime_code_hash = cd.code_hash
                WHERE cd.code IS NOT NULL
                  AND octet_length(cd.code) BETWEEN {int(len_lo)} AND {int(len_hi)}
                  {chain_filter}
                ORDER BY abs(CAST(octet_length(cd.code) AS BIGINT) - {int(mid_len)}) ASC, d.chain_id ASC, addr_hex ASC
                """,
                parquet_root=p_root,
                timeout_sec=25.0,
            )
            for sr in scan_rows or []:
                _ingest_candidate_row(int(sr.get("cid") or 0), sr.get("addr_hex"), sr.get("code_hex"))
    else:
        for cid, item in _iter_sourcify_sidecar_items(p_root, chain_id):
            _ingest_candidate_row(cid, item.get("address"), item.get("runtime_code_hex") or item.get("code_hex"))
    results = sorted(
        results_by_key.values(),
        key=lambda x: (-float(x.get("score", 0.0)), int(x.get("chain_id", 0)), str(x.get("address", ""))),
    )
    return results[:max_total] if max_total > 0 else results


def _compute_clone_hash_to_impl_map(impl_hex_list: Sequence[str]) -> Tuple[Set[str], Dict[str, str]]:
    """구현체 40-hex 목록에 대응하는 EIP-7702 및 표준 EIP-1167 최소 프록시 바이트코드 해시 -> 구현체 주소 매핑 생성."""
    hashes: Set[str] = set()
    hash_to_impl: Dict[str, str] = {}
    for ih_raw in impl_hex_list:
        ih = str(ih_raw or "").lower().removeprefix("0x")
        if len(ih) != 40:
            continue
        impl_addr = "0x" + ih
        for clone_hex in (
            f"ef0100{ih}",
            f"363d3d373d3d3d363d73{ih}5af43d82803e903d91602b57fd5bf3",
            f"3d3d3d3d363d3d37363d73{ih}5af43d3d93803e602a57fd5bf3",
            f"363d3d373d3d3d363d73{ih}5af43d82803e903d91602b57fd5bf300",
            f"366000600037611000600036600073{ih}5af4602c57600080fd5b6110006000f3",
        ):
            cb = bytes.fromhex(clone_hex)
            for h_hex in (hashlib.sha256(cb).hexdigest().lower(), _keccak256(cb).hex().lower()):
                hashes.add(h_hex)
                hash_to_impl.setdefault(h_hex, impl_addr)
    return hashes, hash_to_impl


def _find_fast_clone_proxies_by_impl(
    impl_addrs: Sequence[str],
    parquet_root: Optional[Path] = None,
    chain_id: Optional[int] = None,
    limit: int = 64,
) -> List[Dict[str, Any]]:
    """
    Verified_contracts 전체 문자열 스캔 없이 `contracts.runtime_code_hash` 정확 해시 및 사이드카만 조회해
    EIP-1167 / EIP-7702 클론 프록시와 매핑된 구현체 주소를 초고속 역추적한다.
    """
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR
    norm_impls = list(dict.fromkeys(na[2:] for a in impl_addrs if (na := _norm_addr(a))))
    if not norm_impls or not p_root.is_dir():
        return []
    f_counts, _c_types, _d_cols, ct_cols, chain_filter, addr_proj = _unpack_sourcify_base_schema(p_root, chain_id)
    out, _seen, _try_record_fast = _make_sourcify_proxy_accumulator()
    cap = max(1, int(limit or 64))

    def _record_fast(cid: int, raw_addr: Any, impl_addr: str) -> None:
        if len(out) < cap:
            _try_record_fast(cid, raw_addr, impl_addr=impl_addr, proxy_source="clone_hash")

    if int(f_counts.get("contracts", 0)) > 0 and int(f_counts.get("contract_deployments", 0)) > 0 and DUCKDB_BIN.is_file():
        rch_type = ct_cols.get("runtime_code_hash", "")
        rch_hex_proj = (
            "lower(hex(ct.runtime_code_hash))"
            if "BLOB" in rch_type
            else "lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', ''))"
        )
        for chunk_im in (norm_impls[i : i + 64] for i in range(0, len(norm_impls), 64)):
            if len(out) >= cap:
                break
            clone_hashes, h2i = _compute_clone_hash_to_impl_map(chunk_im)
            if not clone_hashes:
                continue
            rch_pred = (
                f"ct.runtime_code_hash IN ({', '.join(f'unhex({_sql_quote_str(h)})' for h in sorted(clone_hashes))})"
                if "BLOB" in rch_type
                else f"lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', '')) IN ({', '.join(_sql_quote_str(h) for h in sorted(clone_hashes))})"
            )
            rows = _run_duckdb_cli_json(
                f"""
                SELECT CAST(d.chain_id AS BIGINT) AS cid, {addr_proj} AS addr_hex, {rch_hex_proj} AS rch_hex
                FROM contracts ct
                JOIN contract_deployments d ON d.contract_id = ct.id
                WHERE {rch_pred}
                  {chain_filter}
                LIMIT {max(1, cap - len(out))}
                """,
                parquet_root=p_root,
                timeout_sec=6.0,
            )
            for r in rows or ():
                rh = str(r.get("rch_hex") or "").lower().removeprefix("0x")
                _record_fast(int(r.get("cid") or 0), r.get("addr_hex"), h2i.get(rh, ""))

    if len(out) < cap:
        for cid, item in _iter_sourcify_sidecar_items(p_root, chain_id):
            chex = str(item.get("runtime_code_hex") or item.get("code_hex") or "").lower().replace("0x", "")
            if 46 <= len(chex) <= 8192:
                matched_ih = next((ih for ih in norm_impls if ih in chex), "")
                if matched_ih:
                    _record_fast(cid, item.get("address"), "0x" + matched_ih)
                    if len(out) >= cap:
                        break
    return out


def _sql_first_matching_impl_case(haystack_sql: str, hex_addrs: Sequence[str]) -> str:
    whens = " ".join(
        f"WHEN strpos({haystack_sql}, {_sql_quote_str(ih_c)}) > 0 THEN {_sql_quote_str('0x' + ih_c)}"
        for ih in hex_addrs
        if (ih_c := str(ih).lower().removeprefix("0x"))
    )
    return f"CASE {whens} ELSE '' END" if whens else "''"


def search_sourcify_v2_proxies_for_impls(
    impl_addrs: Sequence[str],
    parquet_root: Optional[Path] = None,
    chain_id: Optional[int] = None,
    limit: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """구현체 주소를 바이트코드(결정론적 클론·EIP-7702 위임 지정자 runtime_code_hash 포함) 또는 verified_contracts(runtime_values/creation_values)에 내장한 프록시/클론 배포본을 로컬 Sourcify Parquet·인덱스에서 역추적."""
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR
    norm_impls = list(dict.fromkeys(na[2:] for a in impl_addrs if (na := _norm_addr(a))))
    if not norm_impls or not p_root.is_dir():
        return []
    eff_cap = int(limit) if (limit is not None and int(limit) > 0) else 0
    f_counts, c_types, d_cols, ct_cols, chain_filter, addr_proj = _unpack_sourcify_base_schema(p_root, chain_id)
    code_file_cnt = int(f_counts.get("code", 0))
    out, _seen, _try_record_proxy = _make_sourcify_proxy_accumulator()

    def _reached_cap() -> bool:
        return bool(eff_cap > 0 and len(out) >= eff_cap)

    def _sql_limit_clause() -> str:
        return f"LIMIT {max(1, eff_cap - len(out))}" if eff_cap > 0 else ""

    def _collect_proxy_rows(rows_in: Optional[List[Dict[str, Any]]], *, h2i: Optional[Dict[str, str]] = None, default_src: str = "") -> None:
        for r in rows_in or []:
            if _reached_cap():
                return
            rh = str(r.get("rch_hex") or "").lower().removeprefix("0x")
            imp_a = (h2i.get(rh, "") if h2i and rh else "") or str(r.get("matched_impl") or "")
            p_src = str(r.get("p_src") or default_src or "")
            _try_record_proxy(int(r.get("cid") or 0), r.get("addr_hex"), impl_addr=imp_a, proxy_source=p_src)

    impl_chunks = [norm_impls[i : i + 64] for i in range(0, len(norm_impls), 64)]

    if int(f_counts.get("contracts", 0)) > 0 and int(f_counts.get("contract_deployments", 0)) > 0 and DUCKDB_BIN.is_file():
        rch_type = ct_cols.get("runtime_code_hash", "")
        rch_hex_proj = (
            "lower(hex(ct.runtime_code_hash))"
            if "BLOB" in rch_type
            else "lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', ''))"
        )
        for chunk_im in impl_chunks:
            if _reached_cap():
                return out
            clone_hashes, h2i = _compute_clone_hash_to_impl_map(chunk_im)
            if clone_hashes:
                rch_pred = (
                    f"ct.runtime_code_hash IN ({', '.join(f'unhex({_sql_quote_str(h)})' for h in sorted(clone_hashes))})"
                    if "BLOB" in rch_type
                    else f"lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', '')) IN ({', '.join(_sql_quote_str(h) for h in sorted(clone_hashes))})"
                )
                cl_rows = _run_duckdb_cli_json(
                    f"""
                    SELECT CAST(d.chain_id AS BIGINT) AS cid, {addr_proj} AS addr_hex, {rch_hex_proj} AS rch_hex
                    FROM contracts ct
                    JOIN contract_deployments d ON d.contract_id = ct.id
                    WHERE {rch_pred}
                      {chain_filter}
                    {_sql_limit_clause()}
                    """,
                    parquet_root=p_root,
                    timeout_sec=20.0,
                )
                _collect_proxy_rows(cl_rows, h2i=h2i, default_src="clone_hash")

    if 0 < code_file_cnt <= 32 and int(f_counts.get("contracts", 0)) > 0 and int(f_counts.get("contract_deployments", 0)) > 0 and DUCKDB_BIN.is_file() and not _reached_cap():
        for chunk_im in impl_chunks:
            if _reached_cap():
                return out
            code_haystack = "lower(CASE WHEN typeof(cd.code) = 'BLOB' THEN hex(cd.code) ELSE CAST(cd.code AS VARCHAR) END)"
            substr_cond = " OR ".join(
                f"strpos({code_haystack}, {_sql_quote_str(ih)}) > 0"
                for ih in chunk_im
            )
            matched_impl_proj = _sql_first_matching_impl_case(code_haystack, chunk_im)
            rows = _run_duckdb_cli_json(
                f"""
                SELECT CAST(d.chain_id AS BIGINT) AS cid, {addr_proj} AS addr_hex, {matched_impl_proj} AS matched_impl
                FROM contract_deployments d
                JOIN contracts ct ON d.contract_id = ct.id
                JOIN code cd ON ct.runtime_code_hash = cd.code_hash
                WHERE cd.code IS NOT NULL
                  AND octet_length(cd.code) BETWEEN 23 AND 4096
                  AND ({substr_cond})
                  {chain_filter}
                {_sql_limit_clause()}
                """,
                parquet_root=p_root,
                timeout_sec=20.0,
            )
            _collect_proxy_rows(rows, default_src="code_embed")

    if int(f_counts.get("contract_deployments", 0)) > 0 and int(f_counts.get("verified_contracts", 0)) > 0 and DUCKDB_BIN.is_file() and not _reached_cap():
        vc_cols = c_types.get("verified_contracts") or {}
        vc_dep_col = _sf_col(vc_cols, "deployment_id", "contract_deployment_id")
        if "runtime_values" in vc_cols or "creation_values" in vc_cols:
            for chunk_im in impl_chunks:
                if _reached_cap():
                    break
                rt_conds: List[str] = []
                cr_conds: List[str] = []
                for ih in chunk_im:
                    if "runtime_values" in vc_cols:
                        rt_conds.append(f"strpos(lower(CAST(vc.runtime_values AS VARCHAR)), {_sql_quote_str(ih)}) > 0")
                    if "creation_values" in vc_cols:
                        cr_conds.append(f"strpos(lower(CAST(vc.creation_values AS VARCHAR)), {_sql_quote_str(ih)}) > 0")
                val_conds = rt_conds + cr_conds
                rt_expr = f"({' OR '.join(rt_conds)})" if rt_conds else "FALSE"
                p_src_proj = f"CASE WHEN vc.runtime_values IS NOT NULL AND {rt_expr} THEN 'runtime_values' ELSE 'creation_values' END"
                if "runtime_values" in vc_cols and "creation_values" in vc_cols:
                    vc_haystack = "lower(coalesce(CAST(vc.runtime_values AS VARCHAR), '') || ' ' || coalesce(CAST(vc.creation_values AS VARCHAR), ''))"
                elif "runtime_values" in vc_cols:
                    vc_haystack = "lower(coalesce(CAST(vc.runtime_values AS VARCHAR), ''))"
                else:
                    vc_haystack = "lower(coalesce(CAST(vc.creation_values AS VARCHAR), ''))"
                vc_impl_proj = _sql_first_matching_impl_case(vc_haystack, chunk_im)
                vc_rows = _run_duckdb_cli_json(
                    f"""
                    SELECT CAST(d.chain_id AS BIGINT) AS cid, {addr_proj} AS addr_hex, {p_src_proj} AS p_src, {vc_impl_proj} AS matched_impl
                    FROM verified_contracts vc
                    JOIN contract_deployments d ON vc.{vc_dep_col} = d.id
                    WHERE (vc.runtime_values IS NOT NULL OR vc.creation_values IS NOT NULL)
                      AND ({' OR '.join(val_conds)})
                      {chain_filter}
                    ORDER BY CASE WHEN vc.runtime_values IS NOT NULL AND {rt_expr} THEN 0 ELSE 1 END
                    {_sql_limit_clause()}
                    """,
                    parquet_root=p_root,
                    timeout_sec=25.0,
                )
                _collect_proxy_rows(vc_rows)
        if out and _reached_cap():
            return out

    if not _reached_cap():
        for cid, item in _iter_sourcify_sidecar_items(p_root, chain_id):
            chex = str(item.get("runtime_code_hex") or item.get("code_hex") or "").lower().replace("0x", "")
            if 46 <= len(chex) <= 8192:
                matched_ih = next((ih for ih in norm_impls if ih in chex), "")
                if matched_ih and _try_record_proxy(cid, item.get("address"), impl_addr="0x" + matched_ih, proxy_source="sidecar") and _reached_cap():
                    break
    return out


_PADDED32_ADDR_RE: re.Pattern[str] = re.compile(r"(?:00){12}([0-9a-fA-F]{40})")


def _abi_zero_arg_addr_getters(abi_list: Sequence[Any]) -> List[bytes]:
    """검증 ABI에서 입력 인자 0개이며 address/address[]/address-튜플을 반환하는 view/pure 게터 4바이트 셀렉터 목록 추출."""
    out: List[bytes] = []
    seen: Set[bytes] = set()
    for item in abi_list or ():
        if not isinstance(item, dict) or item.get("type") != "function":
            continue
        if item.get("inputs") or item.get("stateMutability") not in ("view", "pure"):
            continue
        outs = item.get("outputs")
        if not isinstance(outs, list) or not outs:
            continue
        if not any(
            isinstance(o, dict) and str(o.get("type") or "") in ("address", "address[]", "tuple", "tuple[]")
            for o in outs
        ):
            continue
        fname = str(item.get("name") or "").strip()
        if not fname:
            continue
        sel_b = bytes.fromhex(_selector(f"{fname}()")[2:])
        if sel_b not in seen:
            seen.add(sel_b)
            out.append(sel_b)
    return out


def _extract_hex_addrs_from_sourcify_values(raw_text: str) -> List[str]:
    """Sourcify verified_contracts runtime_values/creation_values JSON에서 0x... 및 32바이트 패딩 주소를 추출."""
    if not raw_text:
        return []
    found: Set[str] = set()
    for addr in _extract_addresses_from_text(raw_text):
        if _is_non_precompile_addr(addr):
            found.add(addr)
    for m_hex in _PADDED32_ADDR_RE.findall(raw_text):
        cand = _norm_addr("0x" + m_hex)
        if cand and _is_non_precompile_addr(cand):
            found.add(cand)
    return sorted(found)


def _query_local_sourcify_deployment_hints(
    chain_id: int,
    addresses: Sequence[str],
    parquet_root: Optional[Path] = None,
) -> Dict[str, Any]:
    """
    로컬 Sourcify v2 Parquet/사이드카 배치 힌트 추출:
    - original_bytecodes: contracts/code 기준 원천 배포 런타임/크리에이션 바이트코드 (업그레이드·자기소멸 복원용)
    - embedded_addresses: verified_contracts creation_values/runtime_values 내 불변·생성자 주입 연결 금고 주소
    - abi_zero_arg_getters: 검증 ABI에서 추출한 0-인자 주소 게터 4바이트 hex 문자열 목록
    - sibling_contracts: 동일 chain_id·동일 deployer(배포수<=40, 블록 차이 +-5000 이내) 형제 컨트랙트 주소
    """
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR
    clean_addrs = list(dict.fromkeys(na for a in addresses if (na := _norm_addr(a)) and _is_non_precompile_addr(na)))[:24]
    out: Dict[str, Any] = {
        "original_bytecodes": {},
        "embedded_addresses": {},
        "abi_zero_arg_getters": {},
        "sibling_contracts": [],
    }
    if chain_id <= 0 or not clean_addrs or not p_root.is_dir():
        return out

    f_counts, c_types = _unpack_sourcify_v2_meta(p_root)
    has_dep = int(f_counts.get("contract_deployments", 0)) > 0
    if has_dep and DUCKDB_BIN.is_file():
        d_cols = c_types.get("contract_deployments") or {}
        ct_cols = c_types.get("contracts") or {}
        vc_cols = c_types.get("verified_contracts") or {}
        d_addr_type = d_cols.get("address", "")
        addr_hex_list = [a[2:].lower() for a in clean_addrs]
        addr_in_pred = (
            f"d.address IN ({', '.join(f'unhex({_sql_quote_str(h)})' for h in addr_hex_list)})"
            if "BLOB" in d_addr_type
            else f"lower(CASE WHEN typeof(d.address) = 'BLOB' THEN hex(d.address) ELSE replace(CAST(d.address AS VARCHAR), '0x', '') END) IN ({', '.join(_sql_quote_str(h) for h in addr_hex_list)})"
        )
        cid_pred = (
            f"d.chain_id = {int(chain_id)}"
            if "INT" in d_cols.get("chain_id", "")
            else f"CAST(d.chain_id AS BIGINT) = {int(chain_id)}"
        )
        _, addr_proj = _sourcify_deployment_sql_parts(d_cols, chain_id)
        if int(f_counts.get("contracts", 0)) > 0 and int(f_counts.get("code", 0)) > 0:
            code_rows = _run_duckdb_cli_json(
                f"""
                SELECT
                    {addr_proj} AS addr_hex,
                    CASE WHEN typeof(cd.code) = 'BLOB' THEN lower(hex(cd.code))
                         ELSE replace(lower(CAST(cd.code AS VARCHAR)), '0x', '') END AS code_hex
                FROM contract_deployments d
                JOIN contracts ct ON d.contract_id = ct.id
                JOIN code cd ON ct.runtime_code_hash = cd.code_hash
                WHERE {cid_pred} AND {addr_in_pred} AND cd.code IS NOT NULL
                """,
                parquet_root=p_root,
                timeout_sec=15.0,
            )
            for cr in code_rows or []:
                na = _norm_addr(str(cr.get("addr_hex") or ""))
                chex = str(cr.get("code_hex") or "").replace("0x", "").strip()
                if na and chex:
                    try:
                        rb = bytes.fromhex(chex)
                    except ValueError:
                        continue
                    if len(rb) >= 4 and na not in out["original_bytecodes"]:
                        out["original_bytecodes"][na] = rb

        if int(f_counts.get("verified_contracts", 0)) > 0 and ("runtime_values" in vc_cols or "creation_values" in vc_cols):
            vc_dep_col = _sf_col(vc_cols, "deployment_id", "contract_deployment_id")
            rv_expr = "CAST(vc.runtime_values AS VARCHAR)" if "runtime_values" in vc_cols else "''"
            cv_expr = "CAST(vc.creation_values AS VARCHAR)" if "creation_values" in vc_cols else "''"
            v_rows = _run_duckdb_cli_json(
                f"""
                SELECT {addr_proj} AS addr_hex, {rv_expr} AS rv_str, {cv_expr} AS cv_str
                FROM contract_deployments d
                JOIN verified_contracts vc ON vc.{vc_dep_col} = d.id
                WHERE {cid_pred} AND {addr_in_pred}
                """,
                parquet_root=p_root,
                timeout_sec=15.0,
            )
            for vr in v_rows or []:
                na = _norm_addr(str(vr.get("addr_hex") or ""))
                if not na:
                    continue
                embs = _extract_hex_addrs_from_sourcify_values(
                    f"{vr.get('rv_str') or ''} {vr.get('cv_str') or ''}"
                )
                if embs:
                    prev_e = list(out["embedded_addresses"].get(na, []))
                    out["embedded_addresses"][na] = list(dict.fromkeys([*prev_e, *embs]))

        if "deployer" in d_cols:
            dep_blob = "BLOB" in d_cols.get("deployer", "")
            has_blk = "block_number" in d_cols
            blk_proj = "CAST(d.block_number AS BIGINT) AS blk_num" if has_blk else "0::BIGINT AS blk_num"
            dep_proj = (
                "lower(hex(d.deployer))"
                if dep_blob
                else "lower(CASE WHEN typeof(d.deployer) = 'BLOB' THEN hex(d.deployer) ELSE replace(CAST(d.deployer AS VARCHAR), '0x', '') END)"
            )
            src_deps = _run_duckdb_cli_json(
                f"""
                SELECT DISTINCT {dep_proj} AS dep_hex, {blk_proj}
                FROM contract_deployments d
                WHERE {cid_pred} AND {addr_in_pred} AND d.deployer IS NOT NULL
                LIMIT 16
                """,
                parquet_root=p_root,
                timeout_sec=12.0,
            )
            dep_blk_bounds: Dict[str, List[int]] = {}
            for dr in src_deps or []:
                dh = str(dr.get("dep_hex") or "").replace("0x", "").strip().lower()
                if len(dh) == 40 and int(dh, 16) > 0:
                    dep_blk_bounds.setdefault(dh, []).append(int(dr.get("blk_num") or 0))
            if dep_blk_bounds:
                dep_in = (
                    ", ".join(f"unhex({_sql_quote_str(dh)})" for dh in sorted(dep_blk_bounds.keys()))
                    if dep_blob
                    else ", ".join(_sql_quote_str(dh) for dh in sorted(dep_blk_bounds.keys()))
                )
                dep_pred = (
                    f"d.deployer IN ({dep_in})"
                    if dep_blob
                    else f"lower(CASE WHEN typeof(d.deployer) = 'BLOB' THEN hex(d.deployer) ELSE replace(CAST(d.deployer AS VARCHAR), '0x', '') END) IN ({dep_in})"
                )
                sib_rows = _run_duckdb_cli_json(
                    f"""
                    SELECT {addr_proj} AS addr_hex, {dep_proj} AS dep_hex, {blk_proj}
                    FROM contract_deployments d
                    WHERE {cid_pred} AND {dep_pred}
                    LIMIT 256
                    """,
                    parquet_root=p_root,
                    timeout_sec=15.0,
                )
                by_dep: Dict[str, List[Tuple[str, int]]] = {}
                for sr in sib_rows or []:
                    sa = _norm_addr(str(sr.get("addr_hex") or ""))
                    dh = str(sr.get("dep_hex") or "").replace("0x", "").strip().lower()
                    sb = int(sr.get("blk_num") or 0)
                    if sa and _is_non_precompile_addr(sa) and dh:
                        by_dep.setdefault(dh, []).append((sa, sb))
                sibs_out: List[str] = []
                seen_sibs: Set[str] = set(clean_addrs)
                for dh, entries in by_dep.items():
                    if len(entries) > 40:
                        continue
                    seed_blks = [b for b in dep_blk_bounds.get(dh, []) if b > 0]
                    for sa, sb in entries:
                        if seed_blks and sb > 0 and all(abs(sb - b0) > 5000 for b0 in seed_blks):
                            continue
                        _append_unique(sibs_out, seen_sibs, sa)
                out["sibling_contracts"] = sibs_out[:24]

    for ca in clean_addrs[:6]:
        sf_v = _query_local_sourcify_verified(chain_id, ca, parquet_root=p_root)
        if sf_v and isinstance(sf_v.get("abi"), list):
            gsels = _abi_zero_arg_addr_getters(sf_v["abi"])
            if gsels:
                out["abi_zero_arg_getters"][ca] = ["0x" + g.hex() for g in gsels]

    clean_set = set(clean_addrs)
    for sc_cid, sc_item in _iter_sourcify_sidecar_items(p_root, chain_id):
        if int(sc_cid) != int(chain_id):
            continue
        sa = _norm_addr(sc_item.get("address"))
        if sa in clean_set:
            chex = str(sc_item.get("runtime_code_hex") or sc_item.get("code_hex") or "").replace("0x", "").strip()
            if chex and sa not in out["original_bytecodes"]:
                try:
                    out["original_bytecodes"][sa] = bytes.fromhex(chex)
                except ValueError:
                    pass
            emb_raw = json.dumps(
                {"rv": sc_item.get("runtime_values") or {}, "cv": sc_item.get("creation_values") or {}},
                ensure_ascii=True,
            )
            embs = _extract_hex_addrs_from_sourcify_values(emb_raw)
            if embs:
                prev_e = list(out["embedded_addresses"].get(sa, []))
                out["embedded_addresses"][sa] = list(dict.fromkeys([*prev_e, *embs]))
            if isinstance(sc_item.get("abi"), list):
                gsels = _abi_zero_arg_addr_getters(sc_item["abi"])
                if gsels:
                    out["abi_zero_arg_getters"][sa] = ["0x" + g.hex() for g in gsels]
    return out


