def fetch_verified_contract(router: RPCRouter, chain: str, address: str) -> Dict[str, Any]:
    """4단 소스 폴백: SQLite 캐시 -> 0순위 로컬 Sourcify v2 Parquet(DUCKDB_BIN) -> 1순위 Etherscan V2 -> 2순위 Blockscout v2 -> 3순위 Sourcify V2 API."""
    c = _norm_chain(chain)
    cid = CHAIN_IDS.get(c, 0)
    addr = _norm_addr(address)
    if not cid or not addr:
        return {"verified": False, "provider": "none", "contract_name": "", "abi": [], "sources": {}}
    if router.store is not None:
        cached = router.store.get_verified_source(cid, addr)
        if cached is not None:
            return cached

    # 0순위: 로컬 Sourcify v2 Parquet (API 레이트리밋 0, 오프라인 조회)
    local_sf = _query_local_sourcify_verified(cid, addr)
    if local_sf is not None and local_sf.get("verified"):
        if router.store is not None:
            router.store.put_verified_source(
                cid,
                addr,
                str(local_sf.get("provider") or "sourcify_v2_local"),
                True,
                str(local_sf.get("contract_name") or "Contract"),
                local_sf.get("abi") or [],
                local_sf.get("sources") or {},
            )
        return local_sf

    # 1순위: Etherscan API V2 Unified Endpoint (전 체인 단일 엔드포인트 https://api.etherscan.io/v2/api?chainid={cid})
    es_keys = [k for k in ETHERSCAN_API_KEYS if k] or [""]
    tmpls: List[str] = [
        "https://api.etherscan.io/v2/api?chainid={cid}&module=contract&action=getsourcecode&address={addr}&apikey={key}",
    ]
    start_idx = int(hashlib.sha256(addr.encode("ascii")).hexdigest(), 16) % len(es_keys)
    for attempt in range(len(es_keys) * len(tmpls)):
        tmpl = tmpls[(attempt // len(es_keys)) % len(tmpls)]
        key = es_keys[(start_idx + attempt) % len(es_keys)]
        url = tmpl.format(cid=cid, addr=addr, key=key)
        try:
            doc = router.http_get_json(url, timeout=10.0)
        except Exception:
            continue
        res = doc.get("result") if isinstance(doc, dict) else None
        if isinstance(res, list) and res and isinstance(res[0], dict):
            item = res[0]
            src_raw = str(item.get("SourceCode") or "").strip()
            abi_raw = str(item.get("ABI") or "").strip()
            if src_raw and "not verified" not in abi_raw.lower():
                try:
                    abi_list = json.loads(abi_raw) if abi_raw.startswith("[") else []
                except Exception:
                    abi_list = []
                sources_map: Dict[str, str] = {}
                if (src_raw.startswith("{{") and src_raw.endswith("}}")) or (src_raw.startswith("{") and src_raw.endswith("}")):
                    inner_json = src_raw[1:-1] if (src_raw.startswith("{{") and src_raw.endswith("}}")) else src_raw
                    try:
                        parsed_src = json.loads(inner_json)
                        src_dict = parsed_src.get("sources") if isinstance(parsed_src, dict) and isinstance(parsed_src.get("sources"), dict) else parsed_src
                        if isinstance(src_dict, dict):
                            for fn, fobj in src_dict.items():
                                if isinstance(fobj, dict) and "content" in fobj:
                                    sources_map[str(fn)] = str(fobj["content"])
                                elif isinstance(fobj, str):
                                    sources_map[str(fn)] = fobj
                    except Exception:
                        sources_map["Contract.sol"] = src_raw
                if not sources_map:
                    sources_map[str(item.get("ContractName") or "Contract") + ".sol"] = src_raw
                cname = str(item.get("ContractName") or "Contract")
                if router.store is not None:
                    router.store.put_verified_source(cid, addr, "etherscan_v2", True, cname, abi_list, sources_map)
                return {"verified": True, "provider": "etherscan_v2", "contract_name": cname, "abi": abi_list, "sources": sources_map}

    # 2순위: Blockscout REST v2
    bs_host = _BLOCKSCOUT_HOSTS.get(cid)
    if bs_host:
        try:
            bs_doc = router.http_get_json(f"{bs_host.rstrip('/')}/api/v2/smart-contracts/{addr}", timeout=8.0)
            if isinstance(bs_doc, dict) and bs_doc.get("source_code"):
                cname = str(bs_doc.get("name") or "Contract")
                abi_list = bs_doc.get("abi") if isinstance(bs_doc.get("abi"), list) else []
                sources_map = {f"{cname}.sol": str(bs_doc.get("source_code") or "")}
                for extra in bs_doc.get("additional_sources") or []:
                    if isinstance(extra, dict) and extra.get("file_path") and extra.get("source_code"):
                        sources_map[str(extra["file_path"])] = str(extra["source_code"])
                if router.store is not None:
                    router.store.put_verified_source(cid, addr, "blockscout_v2", True, cname, abi_list, sources_map)
                return {"verified": True, "provider": "blockscout_v2", "contract_name": cname, "abi": abi_list, "sources": sources_map}
        except Exception:
            pass

    # 3순위: Sourcify V2 REST API
    try:
        sf_url = f"https://sourcify.dev/server/v2/contract/{cid}/{_checksum(addr)}?fields=abi,sources"
        sf_doc = router.http_get_json(sf_url, timeout=8.0)
        if isinstance(sf_doc, dict) and (sf_doc.get("abi") or sf_doc.get("sources")):
            abi_list = sf_doc.get("abi") if isinstance(sf_doc.get("abi"), list) else []
            sources_map = {}
            for fn, fobj in (sf_doc.get("sources") or {}).items():
                if isinstance(fobj, dict) and fobj.get("content"):
                    sources_map[str(fn)] = str(fobj["content"])
            cname = next(iter(sources_map.keys()), "Contract").rsplit("/", 1)[-1].replace(".sol", "")
            if router.store is not None:
                router.store.put_verified_source(cid, addr, "sourcify_v2", True, cname, abi_list, sources_map)
            return {"verified": True, "provider": "sourcify_v2", "contract_name": cname, "abi": abi_list, "sources": sources_map}
    except Exception:
        pass

    if router.store is not None:
        router.store.put_verified_source(cid, addr, "unverified", False, "", [], {})
    return {"verified": False, "provider": "unverified", "contract_name": "", "abi": [], "sources": {}}


# ── Mode B: 컨트랙트.md 전수 파서 (무누락 파티션: EVM 시드 + 0-시드 EVM 위임 + 순수 Non-EVM 분리) ──
