def _with_decimal_prec_100(fn: Callable[..., Any]) -> Callable[..., Any]:
    @functools.wraps(fn)
    def _wrapped(*args: Any, **kwargs: Any) -> Any:
        with localcontext() as _dec_ctx:
            _dec_ctx.prec = 100
            return fn(*args, **kwargs)

    return _wrapped


@functools.lru_cache(maxsize=512)
def _norm_addr_tuple_cached(raw_items: Tuple[str, ...]) -> Tuple[str, ...]:
    return tuple(dict.fromkeys(na for x in raw_items if (na := _norm_addr(x))))


@functools.lru_cache(maxsize=512)
def _norm_addr_frozenset_cached(raw_items: Tuple[str, ...]) -> FrozenSet[str]:
    return frozenset(_norm_addr_tuple_cached(raw_items))


def _norm_chain_stables(chain: str) -> Tuple[str, ...]:
    return _norm_addr_tuple_cached(tuple(CHAIN_STABLES.get(_norm_chain(chain), ())))


def _norm_chain_stables_set(chain: str) -> FrozenSet[str]:
    return _norm_addr_frozenset_cached(tuple(CHAIN_STABLES.get(_norm_chain(chain), ())))


def _norm_chain_bluechips_set(chain: str) -> FrozenSet[str]:
    return _norm_addr_frozenset_cached(tuple(CHAIN_BLUECHIPS.get(_norm_chain(chain), ())))


def _decode_clamped_dec(r_entry: Tuple[bool, bytes], default_dec: int = 18) -> int:
    raw_d = int.from_bytes(r_entry[1][:32], "big") if (r_entry[0] and len(r_entry[1]) >= 32) else default_dec
    return max(0, min(77, raw_d))


@_with_decimal_prec_100
def probe_dex_exit_liquidity(
    router: RPCRouter,
    chain: str,
    token_addr: str,
    raw_amount: int,
    decimals: int,
    unit_price_usd: float,
    native_usd: float,
    block_pin: int,
    quote_prices_usd: Optional[Dict[str, float]] = None,
    unbacked_supply_mint: bool = False,
    _redeem_depth: int = 0,
) -> Dict[str, Any]:
    """
    DEX 환금성 및 AMM 슬리피지·스왑 수수료 단일 배치 실측:
    - 네이티브 및 체인 표준 Wrapped Native는 1:1 무손실 환금
    - 상위 스테이블코인은 온체인 WNATIVE 풀 스팟 가격 교차검증(>15% 괴리 시 Fail-Open) 및 5~30bps 스왑 수수료·슬리피지 반영
    - LP 토큰은 getReserves/totalSupply/token0/token1 및 실측 decimals·단가로 환금 한도 산출
    - 일반 ERC-20 및 무담보 발행량 증가분(unbacked_supply_mint)은 온체인 V2/V3 풀 리저브로만 환금 한도를 산출(가공 심도 부여 금지)
    """
    c = _norm_chain(chain)
    tok = _norm_addr(token_addr)
    dec = max(0, min(77, int(decimals or 18)))
    eff_unit_price_dec = max(_DEC_ZERO, _to_dec(unit_price_usd))
    eff_unit_price = float(eff_unit_price_dec)
    nat_usd_dec = max(_DEC_ZERO, _to_dec(native_usd))
    nominal_units_dec = (Decimal(int(raw_amount)) / (Decimal(10) ** dec)) if raw_amount > 0 else _DEC_ZERO
    nominal_usd_dec = nominal_units_dec * eff_unit_price_dec
    nominal_usd = float(nominal_usd_dec)
    wnative = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
    stables = list(_norm_chain_stables(c))
    stables_set = _norm_chain_stables_set(c)
    tier1_stables = set(stables[:4])
    q_price_cache: Dict[str, Decimal] = {}
    for k_qp, v_qp in (quote_prices_usd or {}).items():
        nk_qp = _norm_addr(k_qp)
        dv_qp = _to_dec(v_qp)
        if nk_qp and dv_qp > _DEC_ZERO:
            q_price_cache[nk_qp] = dv_qp

    def _quote_usd_dec(qt_addr: str) -> Decimal:
        q_norm = _norm_addr(qt_addr)
        if not q_norm:
            return _DEC_ZERO
        if wnative and q_norm == wnative:
            return nat_usd_dec
        if q_norm in q_price_cache:
            return q_price_cache[q_norm]
        if block_pin > 0:
            st_ref = getattr(router, "store", None)
            p_live, _ = _fetch_token_price_usd(
                st_ref, c, q_norm, router=router, block_pin=block_pin, allow_offline_fixture=False
            )
            val_dec = max(_DEC_ZERO, _to_dec(p_live))
            q_price_cache[q_norm] = val_dec
            return val_dec
        return Decimal("1") if q_norm in stables_set else _DEC_ZERO

    def _v3_tok_in_quote_dec(r_s0: Tuple[bool, bytes], r_t0: Tuple[bool, bytes], qt_a: str, qt_dec: int) -> Decimal:
        if not (r_s0[0] and len(r_s0[1]) >= 32 and r_t0[0] and len(r_t0[1]) >= 32):
            return _DEC_ZERO
        sqrt_p_x96 = int.from_bytes(r_s0[1][:32], "big")
        t0_addr = _norm_addr("0x" + r_t0[1][12:32].hex())
        if sqrt_p_x96 <= 0 or t0_addr not in (tok, qt_a):
            return _DEC_ZERO
        ratio_dec = (Decimal(sqrt_p_x96) / Decimal(1 << 96)) ** 2
        if ratio_dec <= _DEC_ZERO:
            return _DEC_ZERO
        scale_dec = Decimal(10) ** (dec - qt_dec)
        return (ratio_dec if t0_addr == tok else (Decimal("1") / ratio_dec)) * scale_dec

    def _zero_slip_liq_out(exit_ok: bool, depth_dec: Decimal) -> Dict[str, Any]:
        return {
            "exit_liquid": exit_ok,
            "realizable_usd": nominal_usd,
            "realizable_usd_dec": format(nominal_usd_dec, "f"),
            "nominal_usd": nominal_usd,
            "nominal_usd_dec": format(nominal_usd_dec, "f"),
            "effective_unit_price": eff_unit_price,
            "effective_unit_price_dec": format(eff_unit_price_dec, "f"),
            "swap_fee_bps": 0,
            "slippage_bps": 0,
            "dex_depth_usd": float(depth_dec),
            "dex_depth_usd_dec": format(depth_dec, "f"),
        }

    def _illiquid_dex_out(*, price_diverged: bool = False, paused: bool = False) -> Dict[str, Any]:
        out_il: Dict[str, Any] = {
            "exit_liquid": False,
            "realizable_usd": 0.0,
            "swap_fee_bps": 30,
            "slippage_bps": 10000,
            "dex_depth_usd": 0.0,
        }
        if price_diverged:
            out_il["price_diverged"] = True
        if paused:
            out_il["paused"] = True
        return out_il

    if not tok or token_addr == "native" or (wnative and tok == wnative and not unbacked_supply_mint):
        return _zero_slip_liq_out(
            nominal_usd_dec > _DEC_ZERO or raw_amount > 0,
            max(nominal_usd_dec, Decimal("10000000")),
        )

    peg_confirmed = False
    if tok in stables and not unbacked_supply_mint:
        if eff_unit_price_dec <= _DEC_ZERO:
            return _illiquid_dex_out()
        if block_pin > 0 and nat_usd_dec > _DEC_ZERO and wnative:
            v2_facs = _UNIV2_FACTORIES.get(c, [])[:2]
            v3_facs = _UNIV3_FACTORIES.get(c, [])[:1]
            peg_queries: List[Tuple[str, bytes]] = []
            peg_is_v3: List[bool] = []
            get_pair_s = _selector("getPair(address,address)")
            for fac in v2_facs:
                cd_h = encode_calldata(get_pair_s, ["address", "address"], [tok, wnative])
                peg_queries.append((fac, bytes.fromhex(cd_h[2:])))
                peg_is_v3.append(False)
            for fac3 in v3_facs:
                for v3_f, _ in _V3_FEE_TIERS:
                    cd3_h = encode_calldata(V3_GET_POOL_SEL, ["address", "address", "uint24"], [tok, wnative, v3_f])
                    peg_queries.append((fac3, bytes.fromhex(cd3_h[2:])))
                    peg_is_v3.append(True)
            if peg_queries:
                peg_res = router.multicall3(c, peg_queries, block_pin=block_pin)
                peg_pools: List[Tuple[str, bool]] = []
                seen_peg_pa: Set[str] = set()
                for idx_pq, (ok_pp, ret_pp) in enumerate(peg_res):
                    if ok_pp and len(ret_pp) >= 32:
                        pa = _norm_addr("0x" + ret_pp[12:32].hex())
                        if pa and int(pa, 16) > 0 and pa not in seen_peg_pa:
                            seen_peg_pa.add(pa)
                            peg_pools.append((pa, peg_is_v3[idx_pq]))
                if peg_pools:
                    p_rcalls: List[Tuple[str, bytes]] = [(wnative, bytes.fromhex(DECIMALS_SEL[2:]))]
                    for pa, _ in peg_pools:
                        bcd = encode_calldata(BALANCE_OF_SEL, ["address"], [pa])
                        p_rcalls.append((wnative, bytes.fromhex(bcd[2:])))
                        p_rcalls.append((tok, bytes.fromhex(bcd[2:])))
                    v3_peg_idxs: List[Tuple[int, str]] = [
                        (idx_pp, pa) for idx_pp, (pa, is_v3_p) in enumerate(peg_pools) if is_v3_p
                    ]
                    for _, pa in v3_peg_idxs:
                        p_rcalls.append((pa, bytes.fromhex(V3_SLOT0_SEL[2:])))
                        p_rcalls.append((pa, bytes.fromhex(V2_TOKEN0_SEL[2:])))
                    pr_out = router.multicall3(c, p_rcalls, block_pin=block_pin)
                    w_dec_p = _decode_clamped_dec(pr_out[0] if pr_out else (False, b""))
                    v3_peg_spot_usd: Dict[int, Decimal] = {}
                    v3_peg_off = 1 + len(peg_pools) * 2
                    for k_vp, (idx_pp, _) in enumerate(v3_peg_idxs):
                        si_p = v3_peg_off + k_vp * 2
                        if si_p + 1 >= len(pr_out):
                            break
                        tok_in_w_dec = _v3_tok_in_quote_dec(pr_out[si_p], pr_out[si_p + 1], wnative, w_dec_p)
                        if tok_in_w_dec > _DEC_ZERO:
                            v3_peg_spot_usd[idx_pp] = tok_in_w_dec * nat_usd_dec
                    best_peg_depth_dec = _DEC_ZERO
                    best_peg_spot_dec = _DEC_ZERO
                    peg_depth_floor = Decimal("10000")
                    for idx_pp, (_, is_v3_p) in enumerate(peg_pools):
                        bi = 1 + idx_pp * 2
                        if bi + 1 >= len(pr_out):
                            break
                        rw_b, rt_b = pr_out[bi], pr_out[bi + 1]
                        if not (rw_b[0] and len(rw_b[1]) >= 32 and rt_b[0] and len(rt_b[1]) >= 32):
                            continue
                        w_raw = int.from_bytes(rw_b[1][:32], "big")
                        t_raw = int.from_bytes(rt_b[1][:32], "big")
                        w_usd_dec = (Decimal(w_raw) / (Decimal(10) ** w_dec_p)) * nat_usd_dec
                        t_units_pool_dec = Decimal(t_raw) / (Decimal(10) ** dec)
                        if is_v3_p:
                            s_v3_dec = v3_peg_spot_usd.get(idx_pp, _DEC_ZERO)
                            cand_depth_dec = w_usd_dec + t_units_pool_dec * (s_v3_dec if s_v3_dec > _DEC_ZERO else eff_unit_price_dec)
                            if (w_usd_dec > _DEC_ZERO or t_raw > 0) and cand_depth_dec >= peg_depth_floor and s_v3_dec > _DEC_ZERO and cand_depth_dec > best_peg_depth_dec:
                                best_peg_depth_dec = cand_depth_dec
                                best_peg_spot_dec = s_v3_dec
                        else:
                            cand_depth_dec = w_usd_dec * Decimal("2")
                            if w_usd_dec >= peg_depth_floor and t_units_pool_dec > _DEC_ZERO and cand_depth_dec > best_peg_depth_dec:
                                best_peg_depth_dec = cand_depth_dec
                                best_peg_spot_dec = w_usd_dec / t_units_pool_dec
                    if best_peg_depth_dec >= peg_depth_floor and best_peg_spot_dec > _DEC_ZERO:
                        p_hi_dec = max(eff_unit_price_dec, best_peg_spot_dec)
                        p_lo_dec = min(eff_unit_price_dec, best_peg_spot_dec)
                        if p_hi_dec > _DEC_ZERO and ((p_hi_dec - p_lo_dec) / p_hi_dec) > Decimal("0.15"):
                            return _illiquid_dex_out(price_diverged=True)
                        peg_confirmed = True
                        eff_unit_price_dec = p_lo_dec
                        eff_unit_price = float(eff_unit_price_dec)
                        nominal_usd_dec = nominal_units_dec * eff_unit_price_dec
                        nominal_usd = float(nominal_usd_dec)

    calls: List[Tuple[str, bytes]] = [
        (tok, bytes.fromhex(TOTAL_SUPPLY_SEL[2:])),
        (tok, bytes.fromhex(V2_RESERVES_SEL[2:])),
        (tok, bytes.fromhex(V2_TOKEN0_SEL[2:])),
        (tok, bytes.fromhex(V2_TOKEN1_SEL[2:])),
        (tok, bytes.fromhex(PAUSED_SEL[2:])),
    ]
    res = router.multicall3(c, calls, block_pin=block_pin) if block_pin > 0 else []
    if len(res) >= 5 and res[4][0] and len(res[4][1]) >= 32 and int.from_bytes(res[4][1][:32], "big") != 0:
        return _illiquid_dex_out(paused=True)

    live_router_chk = _is_live_real_router(router) and block_pin > 0
    if (not live_router_chk or peg_confirmed) and not unbacked_supply_mint and tok in tier1_stables and eff_unit_price_dec > _DEC_ZERO:
        depth_dec = Decimal("5000000") if c in ("ethereum", "arbitrum", "base", "bsc", "optimism", "polygon") else Decimal("500000")
        if nominal_usd_dec <= depth_dec:
            return _zero_slip_liq_out(
                nominal_usd_dec > _DEC_ZERO,
                depth_dec,
            )

    if not live_router_chk and not unbacked_supply_mint and tok in stables[:6] and eff_unit_price_dec > _DEC_ZERO:
        depth_dec = Decimal("5000000") if c in ("ethereum", "arbitrum", "base", "bsc", "optimism", "polygon") else Decimal("500000")
        eff_nom_dec = min(nominal_usd_dec, depth_dec)
        slip_bps = min(2500, max(5, int((nominal_usd_dec / max(Decimal("1"), depth_dec)) * Decimal("500"))))
        fee_bps = 5 if nominal_usd_dec < depth_dec else 30
        realizable_dec = eff_nom_dec * (Decimal(max(0, 10000 - (fee_bps + slip_bps))) / Decimal("10000"))
        return {
            "exit_liquid": realizable_dec > _DEC_ZERO,
            "realizable_usd": float(realizable_dec),
            "realizable_usd_dec": format(realizable_dec, "f"),
            "nominal_usd": nominal_usd,
            "nominal_usd_dec": format(nominal_usd_dec, "f"),
            "swap_fee_bps": fee_bps,
            "slippage_bps": slip_bps,
            "dex_depth_usd": float(depth_dec),
            "dex_depth_usd_dec": format(depth_dec, "f"),
        }
    total_supply = 0
    if len(res) >= 1 and res[0][0] and len(res[0][1]) >= 32:
        total_supply = int.from_bytes(res[0][1][:32], "big")
    if not unbacked_supply_mint and len(res) >= 4 and res[1][0] and len(res[1][1]) >= 64 and res[2][0] and res[3][0]:
        try:
            r0 = int.from_bytes(res[1][1][0:32], "big")
            r1 = int.from_bytes(res[1][1][32:64], "big")
            t0 = _norm_addr("0x" + res[2][1][12:32].hex())
            t1 = _norm_addr("0x" + res[3][1][12:32].hex())
            liq_usd_dec = _DEC_ZERO
            lp_qt = ""
            lp_other = ""
            if wnative and (t0 == wnative or t1 == wnative):
                w_res_amt = r0 if t0 == wnative else r1
                lp_qt = wnative
                lp_other = t1 if t0 == wnative else t0
                dw_res = router.multicall3(c, [(wnative, bytes.fromhex(DECIMALS_SEL[2:]))], block_pin=block_pin) if block_pin > 0 else []
                w_dec_lp = _decode_clamped_dec(dw_res[0] if dw_res else (False, b""))
                liq_usd_dec = (Decimal(w_res_amt) / (Decimal(10) ** w_dec_lp)) * nat_usd_dec * Decimal("2")
            elif t0 in stables_set or t1 in stables_set:
                st_tok = t0 if t0 in stables_set else t1
                st_res_amt = r0 if t0 in stables_set else r1
                st_q_dec = _quote_usd_dec(st_tok)
                lp_qt = st_tok
                lp_other = t1 if st_tok == t0 else t0
                if st_q_dec > _DEC_ZERO:
                    d_res = router.multicall3(c, [(st_tok, bytes.fromhex(DECIMALS_SEL[2:]))], block_pin=block_pin) if block_pin > 0 else []
                    s_dec = _decode_clamped_dec(d_res[0] if d_res else (False, b""), 6 if st_res_amt < 10 ** 15 else 18)
                    liq_usd_dec = (Decimal(st_res_amt) / (Decimal(10) ** s_dec)) * st_q_dec * Decimal("2")
            elif t0 in _norm_chain_bluechips_set(c) or t1 in _norm_chain_bluechips_set(c):
                bc_set_lp = _norm_chain_bluechips_set(c)
                bc_tok = t0 if t0 in bc_set_lp else t1
                bc_res_amt = r0 if bc_tok == t0 else r1
                bc_q_dec = _quote_usd_dec(bc_tok)
                if bc_q_dec > _DEC_ZERO:
                    lp_qt = bc_tok
                    lp_other = t1 if bc_tok == t0 else t0
                    d_res = router.multicall3(c, [(bc_tok, bytes.fromhex(DECIMALS_SEL[2:]))], block_pin=block_pin) if block_pin > 0 else []
                    b_dec = _decode_clamped_dec(d_res[0] if d_res else (False, b""), 18)
                    liq_usd_dec = (Decimal(bc_res_amt) / (Decimal(10) ** b_dec)) * bc_q_dec * Decimal("2")
            if lp_qt and lp_other and liq_usd_dec > _DEC_ZERO:
                oth_q_dec = _quote_usd_dec(lp_other)
                if oth_q_dec > _DEC_ZERO:
                    oth_res_amt = r0 if lp_other == t0 else r1
                    d_oth = router.multicall3(c, [(lp_other, bytes.fromhex(DECIMALS_SEL[2:]))], block_pin=block_pin) if block_pin > 0 else []
                    o_dec = _decode_clamped_dec(d_oth[0] if d_oth else (False, b""), 18)
                    oth_usd_total = (Decimal(oth_res_amt) / (Decimal(10) ** o_dec)) * oth_q_dec
                    liq_usd_dec = min(liq_usd_dec, (liq_usd_dec / Decimal("2")) + oth_usd_total)
            if total_supply > 0 and liq_usd_dec >= PROFIT_FLOOR_DEC and lp_qt:
                share_dec = min(Decimal("1"), Decimal(raw_amount) / Decimal(total_supply))
                lp_usd_dec = liq_usd_dec * share_dec
                realizable_lp_dec = lp_usd_dec * Decimal("0.994")
                lp_out: Dict[str, Any] = {
                    "exit_liquid": realizable_lp_dec > _DEC_ZERO,
                    "realizable_usd": float(realizable_lp_dec),
                    "realizable_usd_dec": format(realizable_lp_dec, "f"),
                    "nominal_usd": float(lp_usd_dec),
                    "nominal_usd_dec": format(lp_usd_dec, "f"),
                    "swap_fee_bps": 30,
                    "slippage_bps": 30,
                    "dex_depth_usd": float(liq_usd_dec),
                    "dex_depth_usd_dec": format(liq_usd_dec, "f"),
                    "best_pool_address": _checksum(tok),
                    "best_quote_token": _checksum(lp_qt),
                    "best_dex_kind": "lp_token",
                }
                if lp_other and lp_other not in (tok, lp_qt):
                    lp_out["best_other_token"] = _checksum(lp_other)
                return lp_out
        except Exception:
            pass

    if block_pin <= 0 and not unbacked_supply_mint and tok in stables_set and eff_unit_price_dec > _DEC_ZERO:
        depth_dec = Decimal("250000")
        slip_bps = min(3000, max(15, int((nominal_usd_dec / depth_dec) * Decimal("1000"))))
        capped_nom_dec = min(nominal_usd_dec, depth_dec)
        realizable_st_dec = capped_nom_dec * (Decimal(max(0, 10000 - (30 + slip_bps))) / Decimal("10000"))
        return {
            "exit_liquid": realizable_st_dec > _DEC_ZERO,
            "realizable_usd": float(realizable_st_dec),
            "realizable_usd_dec": format(realizable_st_dec, "f"),
            "nominal_usd": float(capped_nom_dec),
            "nominal_usd_dec": format(capped_nom_dec, "f"),
            "swap_fee_bps": 30,
            "slippage_bps": slip_bps,
            "dex_depth_usd": float(depth_dec),
            "dex_depth_usd_dec": format(depth_dec, "f"),
        }

    # 일반 ERC-20: V2 Factory + Solidly/Aerodrome + V3 Factory(100/500/2500/3000/10000 + QuoterV2) + Algebra(globalState) 온체인 실측
    bluechips = sorted(_norm_chain_bluechips_set(c))
    quote_tokens = list(dict.fromkeys(q for q in ([wnative] + list(stables) + bluechips) if q and q != tok))
    v2_factories = _UNIV2_FACTORIES.get(c, [])
    solidly_factories = _SOLIDLY_FACTORIES.get(c, [])
    v3_factories = _UNIV3_FACTORIES.get(c, [])
    alg_factories = _ALGEBRA_FACTORIES.get(c, [])
    if block_pin > 0 and (v2_factories or solidly_factories or v3_factories or alg_factories) and quote_tokens:
        get_pair_sel = _selector("getPair(address,address)")
        pool_queries: List[Tuple[str, bytes]] = []
        pool_meta: List[Tuple[str, int, str, int, str]] = []  # (qt_addr, fee_bps, dex_kind, v3_fee_raw, quoter_addr)
        for fac in v2_factories[:2]:
            for qt in quote_tokens:
                cd_hex = encode_calldata(get_pair_sel, ["address", "address"], [tok, qt])
                pool_queries.append((fac, bytes.fromhex(cd_hex[2:])))
                pool_meta.append((qt, 30, "v2", 0, ""))
        for fac_s in solidly_factories[:2]:
            for qt in quote_tokens:
                for is_stable, s_fee, s_kind in ((False, 30, "solidly_v"), (True, 5, "solidly_s")):
                    for s_sel in (SOLIDLY_GET_POOL_SEL, SOLIDLY_GET_PAIR_SEL):
                        cds_hex = encode_calldata(s_sel, ["address", "address", "bool"], [tok, qt, is_stable])
                        pool_queries.append((fac_s, bytes.fromhex(cds_hex[2:])))
                        pool_meta.append((qt, s_fee, s_kind, 0, ""))
        for fac3 in v3_factories[:2]:
            q2_addr = _UNIV3_QUOTERS_V2.get((c, _norm_addr(fac3)), "")
            for qt in quote_tokens:
                for v3_fee, fee_b in _V3_FEE_TIERS:
                    cd3_hex = encode_calldata(V3_GET_POOL_SEL, ["address", "address", "uint24"], [tok, qt, v3_fee])
                    pool_queries.append((fac3, bytes.fromhex(cd3_hex[2:])))
                    pool_meta.append((qt, fee_b, "v3", v3_fee, q2_addr))
        for fac_alg in alg_factories[:2]:
            for qt in quote_tokens:
                cda_hex = encode_calldata(ALGEBRA_POOL_SEL, ["address", "address"], [tok, qt])
                pool_queries.append((fac_alg, bytes.fromhex(cda_hex[2:])))
                pool_meta.append((qt, 30, "algebra", 0, ""))
        p_res = router.multicall3(c, pool_queries, block_pin=block_pin)
        discovered_pools: List[Tuple[str, str, int, str, int, str]] = []
        seen_pools: Set[str] = set()
        for idx_p, (ok_p, ret_p) in enumerate(p_res):
            if not ok_p or len(ret_p) < 32:
                continue
            pool_addr = _norm_addr("0x" + ret_p[12:32].hex())
            if not pool_addr or int(pool_addr, 16) == 0 or pool_addr in seen_pools:
                continue
            seen_pools.add(pool_addr)
            qt_addr, fee_b, dex_kind, v3_fee_raw, q2_addr = pool_meta[idx_p]
            discovered_pools.append((pool_addr, qt_addr, fee_b, dex_kind, v3_fee_raw, q2_addr))

        best_realizable_dec = _DEC_ZERO
        best_pq_dec = _DEC_ZERO
        best_out_nom_dec = nominal_usd_dec
        best_fee_bps = 30
        best_pool_addr = ""
        best_quote_addr = ""
        best_dex_kind = ""
        best_v3_fee = 0
        best_curve_i = 0
        best_curve_j = 0
        best_curve_underlying = False
        best_solidly_stable = False

        if discovered_pools:
            reserve_calls: List[Tuple[str, bytes]] = []
            for pool_addr, qt_addr, _, _, _, _ in discovered_pools:
                bal_cd = encode_calldata(BALANCE_OF_SEL, ["address"], [pool_addr])
                reserve_calls.append((qt_addr, bytes.fromhex(bal_cd[2:])))
                reserve_calls.append((qt_addr, bytes.fromhex(DECIMALS_SEL[2:])))
                reserve_calls.append((tok, bytes.fromhex(bal_cd[2:])))
            v3_indices: List[Tuple[int, str, str, str]] = [
                (idx_d, pool_addr, qt_addr, dk)
                for idx_d, (pool_addr, qt_addr, _, dk, _, _) in enumerate(discovered_pools)
                if dk in ("v3", "algebra")
            ]
            for _, pool_addr, _, dk in v3_indices:
                state_sel = ALGEBRA_GLOBAL_STATE_SEL if dk == "algebra" else V3_SLOT0_SEL
                reserve_calls.append((pool_addr, bytes.fromhex(state_sel[2:])))
                reserve_calls.append((pool_addr, bytes.fromhex(V2_TOKEN0_SEL[2:])))
                reserve_calls.append((pool_addr, bytes.fromhex(V3_LIQUIDITY_SEL[2:])))
            solidly_indices: List[Tuple[int, str, str]] = (
                [
                    (idx_d, pool_addr, qt_addr)
                    for idx_d, (pool_addr, qt_addr, _, dk, _, _) in enumerate(discovered_pools)
                    if dk.startswith("solidly")
                ]
                if raw_amount > 0
                else []
            )
            amt_out_cd = (
                bytes.fromhex(encode_calldata(SOLIDLY_AMOUNT_OUT_SEL, ["uint256", "address"], [raw_amount, tok])[2:])
                if solidly_indices
                else b""
            )
            for _, pool_addr, _ in solidly_indices:
                reserve_calls.append((pool_addr, amt_out_cd))
            r_batch = router.multicall3(c, reserve_calls, block_pin=block_pin)
            q_dec_by_idx: List[int] = [
                _decode_clamped_dec(r_batch[i_dp * 3 + 1] if (i_dp * 3 + 1) < len(r_batch) else (False, b""))
                for i_dp in range(len(discovered_pools))
            ]
            v3_spot_by_idx: Dict[int, Decimal] = {}
            v3_active_q_units_by_idx: Dict[int, Decimal] = {}
            v3_zero_liq: Set[int] = set()
            alg_fee_by_idx: Dict[int, int] = {}
            v3_offset = len(discovered_pools) * 3
            for k_v3, (idx_d, _, qt_addr, dk) in enumerate(v3_indices):
                si = v3_offset + k_v3 * 3
                if si + 2 >= len(r_batch):
                    break
                if r_batch[si + 2][0] and len(r_batch[si + 2][1]) >= 32:
                    liq_val = int.from_bytes(r_batch[si + 2][1][:32], "big")
                    if liq_val == 0:
                        v3_zero_liq.add(idx_d)
                        continue
                else:
                    liq_val = 0
                if dk == "algebra" and r_batch[si][0] and len(r_batch[si][1]) >= 96:
                    raw_alg_fee = int.from_bytes(r_batch[si][1][64:96], "big")
                    if 0 < raw_alg_fee <= 100_000:
                        alg_fee_by_idx[idx_d] = max(1, raw_alg_fee // 100)
                tok_in_qt_dec = _v3_tok_in_quote_dec(r_batch[si], r_batch[si + 1], qt_addr, q_dec_by_idx[idx_d])
                if tok_in_qt_dec > _DEC_ZERO:
                    v3_spot_by_idx[idx_d] = tok_in_qt_dec
                    if liq_val > 0 and r_batch[si][0] and len(r_batch[si][1]) >= 32 and r_batch[si + 1][0] and len(r_batch[si + 1][1]) >= 32:
                        sqrt_p_x96 = int.from_bytes(r_batch[si][1][:32], "big")
                        t0_addr = _norm_addr("0x" + r_batch[si + 1][1][12:32].hex())
                        if sqrt_p_x96 > 0 and t0_addr in (tok, qt_addr):
                            sp_dec = Decimal(sqrt_p_x96) / Decimal(1 << 96)
                            if sp_dec > _DEC_ZERO:
                                active_q_raw_dec = (
                                    (Decimal(liq_val) / sp_dec) if qt_addr == t0_addr else (Decimal(liq_val) * sp_dec)
                                )
                                v3_active_q_units_by_idx[idx_d] = active_q_raw_dec / (Decimal(10) ** q_dec_by_idx[idx_d])
            solidly_out_by_idx: Dict[int, int] = {}
            sol_offset = v3_offset + len(v3_indices) * 3
            for k_sl, (idx_d, _, _) in enumerate(solidly_indices):
                oi = sol_offset + k_sl
                if oi < len(r_batch) and r_batch[oi][0] and len(r_batch[oi][1]) >= 32:
                    solidly_out_by_idx[idx_d] = int.from_bytes(r_batch[oi][1][:32], "big")

            # QuoterV2 시뮬레이션 가스/리버트 격리: 잔액/spot0/active-tick liquidity 프리필터를 통과한 V3 풀만 별도 소형 배치로 실행
            v3_quoted_out_by_idx: Dict[int, int] = {}
            if raw_amount > 0:
                v3_quoter_jobs: List[Tuple[int, Tuple[str, bytes]]] = []
                for idx_d, (_, qt_addr, _, dk, v3_fee_raw, q2_addr) in enumerate(discovered_pools):
                    if dk != "v3" or v3_fee_raw <= 0 or not q2_addr:
                        continue
                    if idx_d in v3_zero_liq or v3_spot_by_idx.get(idx_d, _DEC_ZERO) <= _DEC_ZERO:
                        continue
                    base_i = idx_d * 3
                    if base_i >= len(r_batch) or not (r_batch[base_i][0] and len(r_batch[base_i][1]) >= 32):
                        continue
                    q_price_pre = _quote_usd_dec(qt_addr)
                    if q_price_pre <= _DEC_ZERO:
                        continue
                    q_bal_pre = int.from_bytes(r_batch[base_i][1][:32], "big")
                    pq_pre_dec = (Decimal(q_bal_pre) / (Decimal(10) ** q_dec_by_idx[idx_d])) * q_price_pre
                    if idx_d in v3_active_q_units_by_idx:
                        pq_pre_dec = min(pq_pre_dec, v3_active_q_units_by_idx[idx_d] * q_price_pre)
                    if (pq_pre_dec * Decimal("2")) < PROFIT_FLOOR_DEC:
                        continue
                    cd_qv2 = encode_calldata(
                        QUOTER_V2_EXACT_IN_SINGLE_SEL,
                        ["address", "address", "uint256", "uint24", "uint160"],
                        [tok, qt_addr, raw_amount, v3_fee_raw, 0],
                    )
                    v3_quoter_jobs.append((idx_d, (q2_addr, bytes.fromhex(cd_qv2[2:]))))
                for k_c in range(0, len(v3_quoter_jobs), 2):
                    chunk_jobs = v3_quoter_jobs[k_c : k_c + 2]
                    try:
                        q_res = router.multicall3(c, [job_call for _, job_call in chunk_jobs], block_pin=block_pin)
                        for (idx_d, _), (ok_q, ret_q) in zip(chunk_jobs, q_res):
                            if ok_q and len(ret_q) >= 32:
                                v3_quoted_out_by_idx[idx_d] = int.from_bytes(ret_q[:32], "big")
                    except Exception:
                        pass

            for idx_d, (pool_addr, qt_addr, fee_b, dex_k, v3_fee_raw, _) in enumerate(discovered_pools):
                if idx_d in v3_zero_liq or (dex_k in ("v3", "algebra") and v3_spot_by_idx.get(idx_d, _DEC_ZERO) <= _DEC_ZERO):
                    continue
                eff_fee_b = alg_fee_by_idx.get(idx_d, fee_b)
                base_i = idx_d * 3
                if base_i + 2 >= len(r_batch):
                    break
                r_qb, r_tb = r_batch[base_i], r_batch[base_i + 2]
                if not (r_qb[0] and len(r_qb[1]) >= 32):
                    continue
                q_bal = int.from_bytes(r_qb[1][:32], "big")
                q_dec = q_dec_by_idx[idx_d]
                t_bal = int.from_bytes(r_tb[1][:32], "big") if (r_tb[0] and len(r_tb[1]) >= 32) else 0
                q_price_dec = _quote_usd_dec(qt_addr)
                if q_price_dec <= _DEC_ZERO:
                    continue
                pool_quote_dec = (Decimal(q_bal) / (Decimal(10) ** q_dec)) * q_price_dec
                if idx_d in v3_active_q_units_by_idx and idx_d not in v3_quoted_out_by_idx:
                    pool_quote_dec = min(pool_quote_dec, v3_active_q_units_by_idx[idx_d] * q_price_dec)
                if (pool_quote_dec * Decimal("2")) < PROFIT_FLOOR_DEC:
                    continue
                fee_mult_dec = Decimal(max(0, 10000 - int(eff_fee_b))) / Decimal("10000")
                eff_nom_dec = nominal_usd_dec
                v3_unit_dec = v3_spot_by_idx.get(idx_d, _DEC_ZERO) * q_price_dec
                if v3_unit_dec > _DEC_ZERO and nominal_units_dec > _DEC_ZERO:
                    v3_nom_dec = nominal_units_dec * v3_unit_dec
                    eff_nom_dec = min(eff_nom_dec, v3_nom_dec) if eff_nom_dec > _DEC_ZERO else v3_nom_dec
                elif eff_nom_dec <= _DEC_ZERO and t_bal > 0 and raw_amount > 0:
                    eff_nom_dec = (Decimal(raw_amount) / Decimal(t_bal)) * pool_quote_dec
                if idx_d in solidly_out_by_idx:
                    q_out_dec = (Decimal(solidly_out_by_idx[idx_d]) / (Decimal(10) ** q_dec)) * q_price_dec
                    cand_real_dec = min(pool_quote_dec, q_out_dec)
                    if eff_nom_dec > _DEC_ZERO:
                        cand_real_dec = min(cand_real_dec, eff_nom_dec * fee_mult_dec)
                elif idx_d in v3_quoted_out_by_idx:
                    q_out_v3_dec = (Decimal(v3_quoted_out_by_idx[idx_d]) / (Decimal(10) ** q_dec)) * q_price_dec
                    cand_real_dec = min(pool_quote_dec, q_out_v3_dec)
                    if eff_nom_dec > _DEC_ZERO:
                        cand_real_dec = min(cand_real_dec, eff_nom_dec * fee_mult_dec)
                elif v3_unit_dec > _DEC_ZERO and nominal_units_dec > _DEC_ZERO:
                    num_v3 = pool_quote_dec * eff_nom_dec * fee_mult_dec
                    den_v3 = pool_quote_dec + max(Decimal("1e-18"), eff_nom_dec * fee_mult_dec)
                    cand_real_dec = min(pool_quote_dec, num_v3 / den_v3)
                elif t_bal > 0 and raw_amount > 0:
                    rm_dec = Decimal(raw_amount) * fee_mult_dec
                    cand_real_dec = (pool_quote_dec * rm_dec) / (Decimal(t_bal) + rm_dec)
                elif not unbacked_supply_mint:
                    cand_real_dec = ((pool_quote_dec * eff_nom_dec) / (pool_quote_dec + max(Decimal("1e-18"), eff_nom_dec))) * fee_mult_dec
                else:
                    cand_real_dec = _DEC_ZERO
                cand_score_key = (cand_real_dec, pool_quote_dec)
                if cand_score_key > (best_realizable_dec, best_pq_dec):
                    best_realizable_dec = cand_real_dec
                    best_pq_dec = pool_quote_dec
                    best_out_nom_dec = max(eff_nom_dec, cand_real_dec)
                    best_fee_bps = eff_fee_b
                    best_pool_addr = pool_addr
                    best_quote_addr = qt_addr
                    best_dex_kind = dex_k
                    best_v3_fee = int(v3_fee_raw) if dex_k == "v3" else 0
                    best_curve_i = 0
                    best_curve_j = 0
                    best_curve_underlying = False
                    best_solidly_stable = dex_k == "solidly_s"

        # Ethereum Curve MetaRegistry 온체인 get_dy / 잔고 실측
        if c == "ethereum" and block_pin > 0 and raw_amount > 0 and quote_tokens:
            try:
                crv_find_calls: List[Tuple[str, bytes]] = []
                crv_find_qts: List[str] = []
                for qt in quote_tokens:
                    for p_idx in (0, 1):
                        cd_fp = encode_calldata(CURVE_FIND_POOL_SEL, ["address", "address", "uint256"], [tok, qt, p_idx])
                        crv_find_calls.append((CURVE_ETH_METAREGISTRY, bytes.fromhex(cd_fp[2:])))
                        crv_find_qts.append(qt)
                crv_fp_res = router.multicall3(c, crv_find_calls, block_pin=block_pin)
                crv_pools: List[Tuple[str, str]] = []
                crv_seen: Set[str] = set()
                for qt, (ok_fp, ret_fp) in zip(crv_find_qts, crv_fp_res):
                    if not ok_fp or len(ret_fp) < 32:
                        continue
                    c_pool = _norm_addr("0x" + ret_fp[12:32].hex())
                    if c_pool and int(c_pool, 16) != 0 and c_pool not in crv_seen:
                        crv_seen.add(c_pool)
                        crv_pools.append((c_pool, qt))
                if crv_pools:
                    crv_info_calls: List[Tuple[str, bytes]] = []
                    for c_pool, qt in crv_pools:
                        cd_idx = encode_calldata(CURVE_GET_COIN_INDICES_SEL, ["address", "address", "address"], [c_pool, tok, qt])
                        cd_bal = encode_calldata(CURVE_GET_BALANCES_SEL, ["address"], [c_pool])
                        cd_ubal = encode_calldata(CURVE_GET_UNDERLYING_BALANCES_SEL, ["address"], [c_pool])
                        crv_info_calls.append((CURVE_ETH_METAREGISTRY, bytes.fromhex(cd_idx[2:])))
                        crv_info_calls.append((qt, bytes.fromhex(DECIMALS_SEL[2:])))
                        crv_info_calls.append((CURVE_ETH_METAREGISTRY, bytes.fromhex(cd_bal[2:])))
                        crv_info_calls.append((CURVE_ETH_METAREGISTRY, bytes.fromhex(cd_ubal[2:])))
                    crv_info_res = router.multicall3(c, crv_info_calls, block_pin=block_pin)
                    crv_dy_jobs: List[Tuple[str, str, Decimal, int, int, int, bool, Tuple[str, bytes]]] = []
                    for k_cp, (c_pool, qt) in enumerate(crv_pools):
                        bi = k_cp * 4
                        if bi + 3 >= len(crv_info_res):
                            break
                        ok_ci, ret_ci = crv_info_res[bi]
                        if not ok_ci or len(ret_ci) < 96:
                            continue
                        ci = int.from_bytes(ret_ci[:32], "big", signed=True)
                        cj = int.from_bytes(ret_ci[32:64], "big", signed=True)
                        is_und = int.from_bytes(ret_ci[64:96], "big") != 0
                        if not (0 <= ci < 8 and 0 <= cj < 8 and ci != cj):
                            continue
                        q_dec_c = _decode_clamped_dec(crv_info_res[bi + 1])
                        q_price_c = _quote_usd_dec(qt)
                        if q_price_c <= _DEC_ZERO:
                            continue
                        bal_row = crv_info_res[bi + (3 if is_und else 2)]
                        if not bal_row[0] or len(bal_row[1]) < 256:
                            continue
                        q_bal_c = int.from_bytes(bal_row[1][cj * 32 : (cj + 1) * 32], "big")
                        if q_bal_c <= 0:
                            continue
                        pq_crv_dec = (Decimal(q_bal_c) / (Decimal(10) ** q_dec_c)) * q_price_c
                        if (pq_crv_dec * Decimal("2")) < PROFIT_FLOOR_DEC:
                            continue
                        dy_sel = CURVE_GET_DY_UNDERLYING_SEL if is_und else CURVE_GET_DY_SEL
                        cd_dy = encode_calldata(dy_sel, ["int128", "int128", "uint256"], [ci, cj, raw_amount])
                        crv_dy_jobs.append((c_pool, qt, pq_crv_dec, q_dec_c, ci, cj, is_und, (c_pool, bytes.fromhex(cd_dy[2:]))))
                    if crv_dy_jobs:
                        crv_dy_res = router.multicall3(c, [j_call for *_, j_call in crv_dy_jobs], block_pin=block_pin)
                        for (c_pool, qt, pq_crv_dec, q_dec_c, ci_c, cj_c, is_und_c, _), (ok_dy, ret_dy) in zip(crv_dy_jobs, crv_dy_res):
                            if not ok_dy or len(ret_dy) < 32:
                                continue
                            dy_raw = int.from_bytes(ret_dy[:32], "big")
                            if dy_raw <= 0:
                                continue
                            q_price_c = _quote_usd_dec(qt)
                            cand_crv_dec = min(pq_crv_dec, (Decimal(dy_raw) / (Decimal(10) ** q_dec_c)) * q_price_c)
                            if nominal_usd_dec > _DEC_ZERO:
                                cand_crv_dec = min(cand_crv_dec, nominal_usd_dec)
                            if (cand_crv_dec, pq_crv_dec) > (best_realizable_dec, best_pq_dec):
                                best_realizable_dec = cand_crv_dec
                                best_pq_dec = pq_crv_dec
                                best_out_nom_dec = max(nominal_usd_dec, cand_crv_dec)
                                best_fee_bps = 4
                                best_pool_addr = c_pool
                                best_quote_addr = qt
                                best_dex_kind = "curve"
                                best_v3_fee = 0
                                best_curve_i = int(ci_c)
                                best_curve_j = int(cj_c)
                                best_curve_underlying = bool(is_und_c)
                                best_solidly_stable = False
            except Exception:
                pass

        if (best_pq_dec * Decimal("2")) >= PROFIT_FLOOR_DEC and best_pool_addr:
                realizable_dec = best_realizable_dec
                slip_bps = min(
                    9900,
                    max(
                        best_fee_bps,
                        int((Decimal("1") - (realizable_dec / max(Decimal("1e-18"), best_out_nom_dec))) * Decimal("10000")),
                    ),
                )
                depth_pool_dec = best_pq_dec * Decimal("2")
                return {
                    "exit_liquid": realizable_dec > _DEC_ZERO,
                    "realizable_usd": float(realizable_dec),
                    "realizable_usd_dec": format(realizable_dec, "f"),
                    "nominal_usd": float(best_out_nom_dec),
                    "nominal_usd_dec": format(best_out_nom_dec, "f"),
                    "swap_fee_bps": best_fee_bps,
                    "slippage_bps": slip_bps,
                    "dex_depth_usd": float(depth_pool_dec),
                    "dex_depth_usd_dec": format(depth_pool_dec, "f"),
                    "best_pool_address": _checksum(best_pool_addr),
                    "best_quote_token": _checksum(best_quote_addr),
                    "best_dex_kind": best_dex_kind,
                    "v3_fee": best_v3_fee,
                    "curve_i": best_curve_i,
                    "curve_j": best_curve_j,
                    "curve_underlying": best_curve_underlying,
                    "solidly_stable": best_solidly_stable,
                }

    # 직접 DEX 풀이 부재하거나 심도 미달인 영수증·파생 예치 토큰(ERC-4626 / Aave aToken / Compound cToken)의 온체인 즉시 상환 준비금 실측
    if block_pin > 0 and not unbacked_supply_mint and raw_amount > 0 and _redeem_depth < 1:
        try:
            clamped_in = min(int(raw_amount), (1 << 256) - 1)
            wrap_probe_calls: List[Tuple[str, bytes]] = [
                (tok, bytes.fromhex(ERC4626_ASSET_SEL[2:])),
                (tok, bytes.fromhex(ERC4626_CONVERT_TO_ASSETS_SEL[2:]) + clamped_in.to_bytes(32, "big")),
                (tok, bytes.fromhex(AAVE_UNDERLYING_SEL[2:])),
                (tok, bytes.fromhex(AAVE_POOL_SEL[2:])),
                (tok, bytes.fromhex(COMPOUND_UNDERLYING_SEL[2:])),
                (tok, bytes.fromhex(COMPOUND_EXCHANGE_RATE_STORED_SEL[2:])),
                (tok, bytes.fromhex(COMPOUND_GET_CASH_SEL[2:])),
            ]
            w_res = router.multicall3(c, wrap_probe_calls, block_pin=block_pin)
            if len(w_res) >= 7:
                def _res_addr(idx_w: int) -> str:
                    ok_w, b_w = w_res[idx_w]
                    if not ok_w or len(b_w) < 32 or any(b_w[:12]):
                        return ""
                    ca_w = _norm_addr("0x" + b_w[12:32].hex())
                    return ca_w if (_is_non_precompile_addr(ca_w) and ca_w != tok) else ""

                def _res_uint(idx_w: int) -> int:
                    ok_w, b_w = w_res[idx_w]
                    return int.from_bytes(b_w[:32], "big") if (ok_w and len(b_w) >= 32) else 0

                w_kind = ""
                u_addr = ""
                u_converted_raw = 0
                aave_pool_addr = ""
                comp_cash_raw = 0
                u_4626 = _res_addr(0)
                conv_4626 = _res_uint(1)
                u_aave = _res_addr(2)
                u_comp = _res_addr(4)
                ex_comp = _res_uint(5)
                cash_comp = _res_uint(6)
                if u_4626 and conv_4626 > 0:
                    w_kind = "erc4626"
                    u_addr = u_4626
                    u_converted_raw = conv_4626
                elif u_aave:
                    w_kind = "atoken"
                    u_addr = u_aave
                    u_converted_raw = int(raw_amount)
                    aave_pool_addr = _res_addr(3)
                elif u_comp and ex_comp > 0 and cash_comp > 0:
                    w_kind = "ctoken"
                    u_addr = u_comp
                    u_converted_raw = (int(raw_amount) * ex_comp) // (10 ** 18)
                    comp_cash_raw = cash_comp

                if w_kind and u_addr and u_converted_raw > 0:
                    tok_pad32 = abi_encode(["address"], [tok])
                    u_v_calls: List[Tuple[str, bytes]] = [
                        (u_addr, bytes.fromhex(PAUSED_SEL[2:])),
                        (u_addr, bytes.fromhex(DECIMALS_SEL[2:])),
                        (u_addr, bytes.fromhex(BALANCE_OF_SEL[2:]) + tok_pad32),
                    ]
                    if w_kind == "atoken" and aave_pool_addr and aave_pool_addr not in (tok, u_addr):
                        u_v_calls.append((u_addr, bytes.fromhex(BALANCE_OF_SEL[2:]) + abi_encode(["address"], [aave_pool_addr])))
                    u_v_res = router.multicall3(c, u_v_calls, block_pin=block_pin)
                    u_paused = len(u_v_res) >= 1 and u_v_res[0][0] and len(u_v_res[0][1]) >= 32 and int.from_bytes(u_v_res[0][1][:32], "big") != 0
                    if not u_paused and len(u_v_res) >= 3:
                        u_dec = _decode_clamped_dec(u_v_res[1], 18)
                        u_bal_tok = int.from_bytes(u_v_res[2][1][:32], "big") if (u_v_res[2][0] and len(u_v_res[2][1]) >= 32) else 0
                        u_bal_pool = (
                            int.from_bytes(u_v_res[3][1][:32], "big")
                            if (len(u_v_res) >= 4 and u_v_res[3][0] and len(u_v_res[3][1]) >= 32)
                            else 0
                        )
                        if w_kind == "erc4626":
                            avail_u_raw = u_bal_tok
                        elif w_kind == "atoken":
                            avail_u_raw = u_bal_tok if u_bal_tok > 0 else u_bal_pool
                        else:
                            avail_u_raw = min(comp_cash_raw, u_bal_tok) if u_bal_tok > 0 else 0
                        redeem_raw = min(u_converted_raw, avail_u_raw)
                        if redeem_raw > 0 and avail_u_raw > 0:
                            u_p_dec = _quote_usd_dec(u_addr)
                            u_liq = probe_dex_exit_liquidity(
                                router,
                                c,
                                u_addr,
                                redeem_raw,
                                u_dec,
                                float(u_p_dec),
                                native_usd,
                                block_pin,
                                quote_prices_usd=quote_prices_usd,
                                unbacked_supply_mint=False,
                                _redeem_depth=_redeem_depth + 1,
                            )
                            u_real_dec = _to_dec(u_liq.get("realizable_usd_dec") or u_liq.get("realizable_usd") or 0.0)
                            u_depth_dec = _to_dec(u_liq.get("dex_depth_usd_dec") or u_liq.get("dex_depth_usd") or 0.0)
                            redeem_units_dec = Decimal(redeem_raw) / (Decimal(10) ** u_dec)
                            avail_units_dec = Decimal(avail_u_raw) / (Decimal(10) ** u_dec)
                            eff_u_unit_dec = u_p_dec if u_p_dec > _DEC_ZERO else (
                                (u_real_dec / redeem_units_dec) if redeem_units_dec > _DEC_ZERO else _DEC_ZERO
                            )
                            reserve_depth_dec = avail_units_dec * eff_u_unit_dec
                            eff_depth_dec = min(u_depth_dec, reserve_depth_dec) if u_depth_dec > _DEC_ZERO else reserve_depth_dec
                            if u_liq.get("exit_liquid") and u_real_dec > _DEC_ZERO and eff_depth_dec >= PROFIT_FLOOR_DEC:
                                out_redeem = dict(u_liq)
                                out_redeem["dex_depth_usd"] = float(eff_depth_dec)
                                out_redeem["dex_depth_usd_dec"] = format(eff_depth_dec, "f")
                                out_redeem["best_pool_address"] = _checksum(tok)
                                out_redeem["best_quote_token"] = _checksum(u_addr)
                                out_redeem["best_dex_kind"] = f"redeem_{w_kind}"
                                out_redeem["redeem_target"] = (
                                    _checksum(aave_pool_addr)
                                    if (w_kind == "atoken" and aave_pool_addr)
                                    else ("" if w_kind == "atoken" else _checksum(tok))
                                )
                                if u_liq.get("best_pool_address") and u_liq.get("best_quote_token"):
                                    out_redeem["underlying_exit"] = {
                                        "pool": str(u_liq.get("best_pool_address") or ""),
                                        "quote_token": str(u_liq.get("best_quote_token") or ""),
                                        "dex_kind": str(u_liq.get("best_dex_kind") or ""),
                                        "v3_fee": int(u_liq.get("v3_fee") or 0),
                                        "curve_i": int(u_liq.get("curve_i") or 0),
                                        "curve_j": int(u_liq.get("curve_j") or 0),
                                        "curve_underlying": bool(u_liq.get("curve_underlying")),
                                        "solidly_stable": bool(u_liq.get("solidly_stable")),
                                    }
                                out_redeem["v3_fee"] = 0
                                out_redeem["curve_i"] = 0
                                out_redeem["curve_j"] = 0
                                out_redeem["curve_underlying"] = False
                                out_redeem["solidly_stable"] = False
                                return out_redeem
        except Exception:
            pass

    # 온체인 블록이 고정된 상태(block_pin > 0) 또는 무담보 공급 증가분에서 DEX 풀이 전무한 토큰에 가공 유동성을 부여하지 않음
    if block_pin > 0 or unbacked_supply_mint or total_supply <= 0 or eff_unit_price_dec <= _DEC_ZERO or nominal_usd_dec < PROFIT_FLOOR_DEC:
        return _illiquid_dex_out()
    supply_share_dec = min(Decimal("1"), Decimal(raw_amount) / Decimal(max(1, total_supply)))
    if supply_share_dec > Decimal("0.25"):
        return _illiquid_dex_out()
    slip_bps = min(5000, max(50, int(supply_share_dec * Decimal("10000"))))
    realizable_fb_dec = nominal_usd_dec * (Decimal(max(0, 10000 - (30 + slip_bps))) / Decimal("10000"))
    return {
        "exit_liquid": realizable_fb_dec >= PROFIT_FLOOR_DEC,
        "realizable_usd": float(realizable_fb_dec),
        "realizable_usd_dec": format(realizable_fb_dec, "f"),
        "nominal_usd": nominal_usd,
        "nominal_usd_dec": format(nominal_usd_dec, "f"),
        "swap_fee_bps": 30,
        "slippage_bps": slip_bps,
        "dex_depth_usd": nominal_usd,
        "dex_depth_usd_dec": format(nominal_usd_dec, "f"),
    }

# ═════════════════════════════════════════════════════════════════════════════
# §4. 현행 EVM 오프코드 스펙 · 6단 프록시/Diamond/EIP-7702 해석기 · E1 보존 표면 폐포
# ═════════════════════════════════════════════════════════════════════════════

# (opcode -> (mnemonic, pop_count, push_count, imm_bytes))
OPCODE_SPEC: Dict[int, Tuple[str, int, int, int]] = {
    0x00: ("STOP", 0, 0, 0),
    0x01: ("ADD", 2, 1, 0),
    0x02: ("MUL", 2, 1, 0),
    0x03: ("SUB", 2, 1, 0),
    0x04: ("DIV", 2, 1, 0),
    0x05: ("SDIV", 2, 1, 0),
    0x06: ("MOD", 2, 1, 0),
    0x07: ("SMOD", 2, 1, 0),
    0x08: ("ADDMOD", 3, 1, 0),
    0x09: ("MULMOD", 3, 1, 0),
    0x0A: ("EXP", 2, 1, 0),
    0x0B: ("SIGNEXTEND", 2, 1, 0),
    0x10: ("LT", 2, 1, 0),
    0x11: ("GT", 2, 1, 0),
    0x12: ("SLT", 2, 1, 0),
    0x13: ("SGT", 2, 1, 0),
    0x14: ("EQ", 2, 1, 0),
    0x15: ("ISZERO", 1, 1, 0),
    0x16: ("AND", 2, 1, 0),
    0x17: ("OR", 2, 1, 0),
    0x18: ("XOR", 2, 1, 0),
    0x19: ("NOT", 1, 1, 0),
    0x1A: ("BYTE", 2, 1, 0),
    0x1B: ("SHL", 2, 1, 0),
    0x1C: ("SHR", 2, 1, 0),
    0x1D: ("SAR", 2, 1, 0),
    0x1E: ("CLZ", 1, 1, 0),          # Fusaka EIP-7939 Count Leading Zeros
    0x20: ("KECCAK256", 2, 1, 0),
    0x30: ("ADDRESS", 0, 1, 0),
    0x31: ("BALANCE", 1, 1, 0),
    0x32: ("ORIGIN", 0, 1, 0),
    0x33: ("CALLER", 0, 1, 0),
    0x34: ("CALLVALUE", 0, 1, 0),
    0x35: ("CALLDATALOAD", 1, 1, 0),
    0x36: ("CALLDATASIZE", 0, 1, 0),
    0x37: ("CALLDATACOPY", 3, 0, 0),
    0x38: ("CODESIZE", 0, 1, 0),
    0x39: ("CODECOPY", 3, 0, 0),
    0x3A: ("GASPRICE", 0, 1, 0),
    0x3B: ("EXTCODESIZE", 1, 1, 0),
    0x3C: ("EXTCODECOPY", 4, 0, 0),
    0x3D: ("RETURNDATASIZE", 0, 1, 0),
    0x3E: ("RETURNDATACOPY", 3, 0, 0),
    0x3F: ("EXTCODEHASH", 1, 1, 0),
    0x40: ("BLOCKHASH", 1, 1, 0),
    0x41: ("COINBASE", 0, 1, 0),
    0x42: ("TIMESTAMP", 0, 1, 0),
    0x43: ("NUMBER", 0, 1, 0),
    0x44: ("PREVRANDAO", 0, 1, 0),
    0x45: ("GASLIMIT", 0, 1, 0),
    0x46: ("CHAINID", 0, 1, 0),
    0x47: ("SELFBALANCE", 0, 1, 0),
    0x48: ("BASEFEE", 0, 1, 0),
    0x49: ("BLOBHASH", 1, 1, 0),     # Cancun EIP-4844
    0x4A: ("BLOBBASEFEE", 0, 1, 0),  # Cancun EIP-7516
    0x4B: ("SLOTNUM", 0, 1, 0),      # Glamsterdam EIP-7843 reserve
    0x50: ("POP", 1, 0, 0),
    0x51: ("MLOAD", 1, 1, 0),
    0x52: ("MSTORE", 2, 0, 0),
    0x53: ("MSTORE8", 2, 0, 0),
    0x54: ("SLOAD", 1, 1, 0),
    0x55: ("SSTORE", 2, 0, 0),
    0x56: ("JUMP", 1, 0, 0),
    0x57: ("JUMPI", 2, 0, 0),
    0x58: ("PC", 0, 1, 0),
    0x59: ("MSIZE", 0, 1, 0),
    0x5A: ("GAS", 0, 1, 0),
    0x5B: ("JUMPDEST", 0, 0, 0),
    0x5C: ("TLOAD", 1, 1, 0),        # Cancun EIP-1153 Transient Load
    0x5D: ("TSTORE", 2, 0, 0),       # Cancun EIP-1153 Transient Store
    0x5E: ("MCOPY", 3, 0, 0),        # Cancun EIP-5656 Memory Copy
    0x5F: ("PUSH0", 0, 1, 0),        # Shanghai EIP-3855
    0xE6: ("DUPN", 0, 1, 1),         # Glamsterdam EIP-8024
    0xE7: ("SWAPN", 0, 0, 1),        # Glamsterdam EIP-8024
    0xE8: ("EXCHANGE", 0, 0, 1),     # Glamsterdam EIP-8024
    0xF0: ("CREATE", 3, 1, 0),
    0xF1: ("CALL", 7, 1, 0),
    0xF2: ("CALLCODE", 7, 1, 0),
    0xF3: ("RETURN", 2, 0, 0),
    0xF4: ("DELEGATECALL", 6, 1, 0),
    0xF5: ("CREATE2", 4, 1, 0),
    0xFA: ("STATICCALL", 6, 1, 0),
    0xFD: ("REVERT", 2, 0, 0),
    0xFE: ("INVALID", 0, 0, 0),
    0xFF: ("SELFDESTRUCT", 1, 0, 0),
}

for _w in range(1, 33):
    OPCODE_SPEC[0x5F + _w] = (f"PUSH{_w}", 0, 1, _w)
for _d in range(1, 17):
    OPCODE_SPEC[0x7F + _d] = (f"DUP{_d}", _d, _d + 1, 0)
    OPCODE_SPEC[0x8F + _d] = (f"SWAP{_d}", _d + 1, _d + 1, 0)
for _lg in range(0, 5):
    OPCODE_SPEC[0xA0 + _lg] = (f"LOG{_lg}", 2 + _lg, 0, 0)


def _strip_cbor_metadata(code: bytes) -> bytes:
    return _strip_cbor_bytes(code)


def _effective_opcode_spec(clean_code: bytes, pc: int) -> Optional[Tuple[str, int, int, int]]:
    op = clean_code[pc]
    spec = OPCODE_SPEC.get(op)
    if spec is None:
        return None
    if op in (0xE6, 0xE7, 0xE8):
        if pc + 1 >= len(clean_code):
            return None
        nxt = clean_code[pc + 1]
        if op in (0xE6, 0xE7):
            if 0x5B <= nxt <= 0x7F:
                return None
        elif 0x52 <= nxt <= 0x7F:
            return None
    return spec


@functools.lru_cache(maxsize=512)
def _disassemble_cached(code: bytes) -> Tuple[Tuple[int, str, bytes], ...]:
    clean_code = _strip_cbor_metadata(code)
    out: List[Tuple[int, str, bytes]] = []
    pc = 0
    n = len(clean_code)
    while pc < n:
        op = clean_code[pc]
        spec = _effective_opcode_spec(clean_code, pc)
        if spec is None:
            out.append((pc, f"OP_{op:02x}", b""))
            pc += 1
        else:
            name, _pop, _push, imm_w = spec
            imm = clean_code[pc + 1:pc + 1 + imm_w] if imm_w > 0 else b""
            out.append((pc, name, imm))
            pc += 1 + imm_w
    return tuple(out)


def _disassemble(code: Any) -> List[Tuple[int, str, bytes]]:
    raw = _hex_to_bytes(code) if not isinstance(code, (bytes, bytearray)) else bytes(code)
    return list(_disassemble_cached(raw))


def _skeleton_hash(code: Any) -> str:
    raw = _strip_cbor_metadata(_hex_to_bytes(code) if not isinstance(code, (bytes, bytearray)) else bytes(code))
    if not raw:
        return ""
    sk = bytearray()
    pc = 0
    n = len(raw)
    while pc < n:
        op = raw[pc]
        sk.append(op)
        spec = _effective_opcode_spec(raw, pc)
        imm_w = spec[3] if spec is not None else 0
        pc += 1 + imm_w
    return _keccak256_hex(bytes(sk))


def _opcode_4grams(code: Any, cap: int = 512) -> Set[str]:
    raw = _strip_cbor_metadata(_hex_to_bytes(code) if not isinstance(code, (bytes, bytearray)) else bytes(code))
    if not raw:
        return set()
    ops: List[int] = []
    pc = 0
    n = len(raw)
    while pc < n:
        op = raw[pc]
        ops.append(op)
        spec = _effective_opcode_spec(raw, pc)
        pc += 1 + (spec[3] if spec is not None else 0)
    if len(ops) < 4:
        return {bytes(ops).hex()} if ops else set()
    grams = {bytes(ops[i:i + 4]).hex() for i in range(len(ops) - 3)}
    if len(grams) > cap:
        return set(sorted(grams)[:cap])
    return grams


# ── 6단 프록시 · EIP-7702 · EIP-1167(불변인자 포함) · Slot-0 Safe(2KB 가드) · Diamond 해석기 ──
_EIP1167_STD_PREFIX: bytes = bytes.fromhex("363d3d373d3d3d363d73")
_EIP1167_ALT_PREFIX: bytes = bytes.fromhex("3d3d3d3d363d3d37363d73")


def _eip1167_impl(code: Any) -> str:
    raw = _hex_to_bytes(code)
    for pref in (_EIP1167_STD_PREFIX, _EIP1167_ALT_PREFIX):
        if len(raw) >= len(pref) + 20 + 11 and raw.startswith(pref):
            tail_window = raw[len(pref) + 20:len(pref) + 35]
            if b"\x5a\xf4" in tail_window:  # GAS DELEGATECALL (표준 45B 및 >45B 불변인자 클론 모두 포착)
                addr = _norm_addr("0x" + raw[len(pref):len(pref) + 20].hex())
                if addr and int(addr, 16) > 0:
                    return addr
    # Vyper create_minimal_proxy_to 및 wighawag/Solady ClonesWithImmutableArgs(CWIA) 무상태 DELEGATECALL 스텁 해석
    if 32 <= len(raw) <= 4096:
        stub_limit = min(len(raw), 128)
        pc = 0
        stub_insns: List[Tuple[str, bytes]] = []
        dcall_idx = -1
        ret_after_dcall = False
        forbidden_stub_ops = {
            "SLOAD", "SSTORE", "TLOAD", "TSTORE",
            "CALL", "STATICCALL", "CALLCODE",
            "CREATE", "CREATE2", "SELFDESTRUCT", "EQ",
        }
        valid_stub = True
        while pc < stub_limit:
            spec = _effective_opcode_spec(raw, pc)
            if spec is None:
                valid_stub = False
                break
            nm, _pop, _push, imm_w = spec
            if pc + 1 + imm_w > len(raw):
                valid_stub = False
                break
            if nm in forbidden_stub_ops:
                valid_stub = False
                break
            imm = raw[pc + 1:pc + 1 + imm_w] if imm_w > 0 else b""
            stub_insns.append((nm, imm))
            pc += 1 + imm_w
            if nm == "DELEGATECALL" and dcall_idx < 0:
                dcall_idx = len(stub_insns) - 1
            elif nm == "RETURN" and dcall_idx >= 0:
                ret_after_dcall = True
                break
        if valid_stub and dcall_idx > 0 and ret_after_dcall:
            p20_hits = [
                (i, imm)
                for i, (nm, imm) in enumerate(stub_insns[:dcall_idx])
                if nm == "PUSH20" and len(imm) == 20 and _is_non_precompile_addr("0x" + imm.hex())
            ]
            if len(p20_hits) == 1 and 0 < (dcall_idx - p20_hits[0][0]) <= 6:
                addr = _norm_addr("0x" + p20_hits[0][1].hex())
                if addr:
                    return addr
    return ""


def _eip7702_delegate(code: Any) -> str:
    raw = _hex_to_bytes(code)
    if len(raw) == 23 and raw[:3] == b"\xef\x01\x00":
        addr = _norm_addr("0x" + raw[3:23].hex())
        if addr and int(addr, 16) > 0:
            return addr
    return ""


def _slot0_safe_proxy_shape(code: Any, dis: Optional[Sequence[Tuple[int, str, bytes]]] = None) -> bool:
    raw = _hex_to_bytes(code)
    # 2,048B 대형 컨트랙트 오염 가드 + Safe 프록시 상한(<=512B)
    if len(raw) == 0 or len(raw) > 512:
        return False
    insns = list(dis) if dis is not None else _disassemble(raw)
    if not any(name == "DELEGATECALL" for _, name, _ in insns):
        return False
    for i in range(len(insns) - 1):
        _, n0, imm0 = insns[i]
        _, n1, _ = insns[i + 1]
        if n1 == "SLOAD" and (n0 == "PUSH0" or (n0.startswith("PUSH") and int.from_bytes(imm0 or b"\x00", "big") == 0)):
            return True
    return False


LOUPE_FACET_ADDRS_SEL: str = _selector("facetAddresses()")


def _decode_checked_facet_entries(raw_ret: Any, abi_type: str, tuple_head: bool) -> Tuple[List[str], bool]:
    b = _hex_to_bytes(raw_ret)
    if len(b) < 64:
        return [], bool(len(b) > 0)
    try:
        decoded = abi_decode([abi_type], b)[0]
        addrs: List[str] = []
        seen_addrs: Set[str] = set()
        had_invalid = False
        for item in decoded:
            na = _norm_addr(item[0] if tuple_head else item)
            if _is_non_precompile_addr(na):
                _append_unique(addrs, seen_addrs, na)
            else:
                had_invalid = True
        return addrs, had_invalid
    except Exception:
        return [], True


def _decode_diamond_facets_checked(raw_ret: Any) -> Tuple[List[str], bool]:
    return _decode_checked_facet_entries(raw_ret, "(address,bytes4[])[]", tuple_head=True)


def _decode_diamond_facet_addresses_checked(raw_ret: Any) -> Tuple[List[str], bool]:
    return _decode_checked_facet_entries(raw_ret, "address[]", tuple_head=False)


def _decode_diamond_facets(raw_ret: Any) -> List[str]:
    return _decode_diamond_facets_checked(raw_ret)[0]


def _extract_constant_storage_slots(dis: Sequence[Tuple[int, str, bytes]]) -> Tuple[Set[int], Set[int]]:
    reads: Set[int] = set()
    writes: Set[int] = set()
    for i in range(len(dis) - 1):
        _, n0, imm0 = dis[i]
        _, n1, _ = dis[i + 1]
        if n1 in ("SLOAD", "SSTORE"):
            if n0 == "PUSH0":
                slot_val = 0
            elif n0.startswith("PUSH"):
                slot_val = int.from_bytes(imm0, "big")
            else:
                continue
            if n1 == "SLOAD":
                reads.add(slot_val)
            else:
                writes.add(slot_val)
    return reads, writes


def _detect_storage_slot_collision(proxy_dis: Sequence[Tuple[int, str, bytes]], impl_dis: Sequence[Tuple[int, str, bytes]]) -> Set[int]:
    pr_r, pr_w = _extract_constant_storage_slots(proxy_dis)
    im_r, im_w = _extract_constant_storage_slots(impl_dis)
    proxy_all = (pr_r | pr_w) - STANDARD_PROXY_SLOTS - {0}
    impl_all = (im_r | im_w) - STANDARD_PROXY_SLOTS
    return proxy_all & impl_all


def _push20_constants(dis: Sequence[Tuple[int, str, bytes]]) -> List[str]:
    out: Set[str] = set()
    for _, name, imm in dis:
        if name == "PUSH20" and len(imm) == 20:
            v = int.from_bytes(imm, "big")
            cand_a = "0x" + imm.hex().lower()
            if _is_non_precompile_addr(cand_a) and v < ((1 << 160) - 0x1000):
                out.add(cand_a)
    return sorted(out)


@dataclasses.dataclass
class ProxyResolution:
    address: str
    proxy_kind: str
    impl_addresses: List[str]
    admin_address: str
    raw_code_hex: str
    effective_code_hex: str
    skeleton_hash: str
    slot_collisions: List[int]
    impl_codes_hex: Dict[str, str] = dataclasses.field(default_factory=dict)
    unresolved_delegation: bool = False


def _res_facet_codes_hex(res: ProxyResolution) -> List[str]:
    if res.impl_codes_hex:
        return list(res.impl_codes_hex.values())
    return [res.effective_code_hex] if res.effective_code_hex else []


def _collect_hint_probe_blocks(
    hint_blocks: Optional[Sequence[int]],
    hi_block: int,
    *,
    pre_first: bool = False,
) -> Tuple[List[int], List[int]]:
    probe_blocks: List[int] = []
    seen_pb: Set[int] = set()
    valid_hints: List[int] = []
    for raw_hb in (hint_blocks or ()):
        try:
            hb = int(raw_hb)
        except (TypeError, ValueError):
            continue
        if 1 <= hb <= hi_block:
            valid_hints.append(hb)
            pair = (max(1, hb - 1), hb) if pre_first else (hb, max(1, hb - 1))
            for cand_h in pair:
                _append_unique(probe_blocks, seen_pb, cand_h)
    return probe_blocks, valid_hints


def _extract_mode_b_hint_blocks(
    router: Optional[RPCRouter],
    chain: str,
    meta_doc: Optional[Dict[str, Any]],
    hi_block: int = 0,
) -> List[int]:
    """메타데이터의 block_numbers 및 tx_hashes 영수증에서 과거 시점 탐색용 블록 단서(hi_block 이하)를 수집."""
    out: List[int] = []
    seen: Set[int] = set()
    if not isinstance(meta_doc, dict):
        return out
    for raw_bn in (meta_doc.get("block_numbers") or [])[:8]:
        try:
            bn_i = int(raw_bn)
        except (TypeError, ValueError):
            bn_i = 0
        if bn_i >= 1 and (hi_block <= 0 or bn_i <= hi_block):
            for cand_hb in (bn_i, max(1, bn_i - 1)):
                _append_unique(out, seen, cand_hb)
    if router is None:
        return out
    for txh in (meta_doc.get("tx_hashes") or [])[:4]:
        if not isinstance(txh, str) or not txh.startswith("0x") or len(txh) != 66:
            continue
        try:
            rcpt = router.call(chain, "eth_getTransactionReceipt", [txh], timeout=5.0)
            if isinstance(rcpt, dict) and isinstance(rcpt.get("blockNumber"), str):
                r_bn = _hex_to_int(rcpt.get("blockNumber"))
                if r_bn >= 1 and (hi_block <= 0 or r_bn <= hi_block):
                    for cand_hb in (max(1, r_bn - 1), r_bn):
                        _append_unique(out, seen, cand_hb)
        except Exception:
            pass
    return out


def _is_delegatecall_or_thin_proxy(code_b: bytes) -> bool:
    """로컬 바이트코드가 얇은 프록시 셸(<768B)이거나 DELEGATECALL 옵코드를 포함하는지 판별."""
    if not code_b:
        return False
    clean_b = _strip_cbor_bytes(code_b)
    if len(clean_b) < 768:
        return True
    return any(nm == "DELEGATECALL" for _, nm, _ in _disassemble(clean_b))


def _recover_historical_bytecode_bisect(
    router: RPCRouter,
    chain: str,
    address: str,
    hi_block: int,
    hint_blocks: Optional[Sequence[int]] = None,
) -> bytes:
    """
    Mode B 전용 과거 바이트코드 역추적기:
    - 현재 블록(hi_block)에서 SELFDESTRUCT 또는 빈 코드로 초기화된 과거 사건 시드 주소에 대해
      사건 블록 단서(hint_blocks) 우선 프로브 + 지수 백오프 프로브(최대 12회 아카이브 eth_getCode)로 파괴 직전 런타임 바이트코드를 복원한다.
    """
    addr = _norm_addr(address)
    if not addr or hi_block <= 1:
        return b""
    c = _norm_chain(chain)
    probe_blocks, _ = _collect_hint_probe_blocks(hint_blocks, hi_block)
    seen_pb: Set[int] = set(probe_blocks)
    for fine_step in (250, 1_500):
        if fine_step < hi_block:
            _append_unique(probe_blocks, seen_pb, max(1, hi_block - fine_step))
    step = 10_000
    while step < hi_block:
        _append_unique(probe_blocks, seen_pb, max(1, hi_block - step))
        step *= 8
    for frac in (hi_block * 3 // 4, hi_block // 2, hi_block // 4):
        if 1 <= frac < hi_block:
            _append_unique(probe_blocks, seen_pb, frac)
    for pb in probe_blocks:
        try:
            rhex = router.call(c, "eth_getCode", [_checksum(addr), hex(int(pb))], block_pin=pb, need_archive=True, timeout=6.0)
            cb = _hex_to_bytes(rhex) if isinstance(rhex, str) else b""
            if len(cb) > 0:
                return cb
        except Exception:
            continue
    return b""


def _recover_historical_proxy_impl_bytecodes(
    router: RPCRouter,
    chain: str,
    address: str,
    hi_block: int,
    hint_blocks: Optional[Sequence[int]] = None,
) -> List[bytes]:
    """
    Mode B 전용 프록시 과거 구현체(Implementation) 바이트코드 역추적기:
    - 사후 업그레이드(패치)된 프록시 시드에 대해 사건 블록 단서(hint_blocks) 및 과거 블록 스냅샷의
      EIP-1967(impl/beacon/Upgraded 로그) / EIP-1822 / ZeppelinOS / Safe slot0 슬롯 및
      EIP-7702 위임 코드를 아카이브 배치 프로빙하여 패치 이전 구현체 바이트코드까지 함께 복원한다.
    """
    addr = _norm_addr(address)
    if not addr or hi_block <= 1:
        return []
    c = _norm_chain(chain)
    probe_blocks, valid_hints = _collect_hint_probe_blocks(hint_blocks, hi_block, pre_first=True)
    seen_pb: Set[int] = set(probe_blocks)
    for step in (5_000, 40_000, 320_000, hi_block // 2):
        if 1 <= hi_block - step < hi_block:
            _append_unique(probe_blocks, seen_pb, max(1, hi_block - step))
    seen_impls: Set[str] = set()
    out_codes: List[bytes] = []
    direct_slots = (EIP1967_SLOTS["impl"], EIP1822_SLOT, ZOS_SLOTS["impl"])
    beacon_slot = EIP1967_SLOTS["beacon"]
    zero_slot = "0x" + ("00" * 32)
    chk_addr = _checksum(addr)

    def _word_to_valid_addr(raw_hex: Any) -> str:
        if not isinstance(raw_hex, str):
            return ""
        wb = _hex_to_word32(raw_hex)
        if wb[:12] != b"\x00" * 12:
            return ""
        cand = _norm_addr("0x" + wb[12:32].hex())
        return cand if _is_non_precompile_addr(cand) else ""

    upgrade_t0s = [
        _keccak256_hex(b"Upgraded(address)"),
        _keccak256_hex(b"BeaconUpgraded(address)"),
        _keccak256_hex(b"DiamondCut((address,uint8,bytes4[])[],address,bytes)"),
    ]
    log_windows: List[Tuple[int, int]] = [
        (max(1, hb_log - 2_000), min(hi_block, hb_log + 200)) for hb_log in valid_hints
    ]
    if not log_windows:
        log_windows.append((max(1, hi_block - 50_000), hi_block))

    for w_from, w_to in log_windows:
        try:
            logs = router.call(
                c,
                "eth_getLogs",
                [
                    {
                        "address": chk_addr,
                        "fromBlock": hex(w_from),
                        "toBlock": hex(w_to),
                        "topics": [upgrade_t0s],
                    }
                ],
                block_pin=w_to,
                need_archive=True,
                timeout=5.0,
            )
            if isinstance(logs, list):
                diamond_t0 = upgrade_t0s[2].lower()
                for lg in logs:
                    if not isinstance(lg, dict):
                        continue
                    log_b = _hex_to_int(lg.get("blockNumber"))
                    if 1 < log_b <= hi_block:
                        pre_b = log_b - 1
                        if pre_b not in seen_pb:
                            seen_pb.add(pre_b)
                            probe_blocks.insert(0, pre_b)
                    tops = lg.get("topics") or []
                    log_cands: List[str] = []
                    if tops and str(tops[0]).lower() == diamond_t0:
                        try:
                            d_cuts, d_init, _ = abi_decode(
                                ["(address,uint8,bytes4[])[]", "address", "bytes"],
                                _hex_to_bytes(lg.get("data")),
                            )
                            for f_item in d_cuts or []:
                                if isinstance(f_item, (list, tuple)) and f_item:
                                    fa = _norm_addr(f_item[0])
                                    if _is_non_precompile_addr(fa):
                                        log_cands.append(fa)
                            init_a = _norm_addr(d_init)
                            if _is_non_precompile_addr(init_a):
                                log_cands.append(init_a)
                        except Exception:
                            pass
                    cand_u = _word_to_valid_addr(tops[1]) if len(tops) >= 2 else _word_to_valid_addr(lg.get("data"))
                    if cand_u:
                        log_cands.append(cand_u)
                    for cu_item in dict.fromkeys(log_cands):
                        if cu_item and cu_item not in seen_impls:
                            seen_impls.add(cu_item)
                            q_blk = log_b if (1 <= log_b <= hi_block) else w_to
                            rhex_u = router.call(
                                c, "eth_getCode", [_checksum(cu_item), hex(q_blk)], block_pin=q_blk, need_archive=True, timeout=5.0
                            )
                            cb_u = _hex_to_bytes(rhex_u) if isinstance(rhex_u, str) else b""
                            if len(cb_u) >= 16:
                                out_codes.append(cb_u)
        except Exception:
            pass

    for pb in probe_blocks:
        btag = hex(int(pb))
        try:
            batch_reqs: List[Tuple[str, Any]] = [
                ("eth_getStorageAt", [chk_addr, sl, btag]) for sl in (*direct_slots, beacon_slot, zero_slot)
            ]
            batch_reqs.append(("eth_getCode", [chk_addr, btag]))
            res_list = router.batch_call(c, batch_reqs, block_pin=pb, need_archive=True)
            if not isinstance(res_list, list) or len(res_list) < 6:
                continue
            proxy_hist_code = _hex_to_bytes(res_list[5]) if isinstance(res_list[5], str) else b""
            cand_impls: List[str] = []
            for raw_s in res_list[:3]:
                ia = _word_to_valid_addr(raw_s)
                if ia:
                    cand_impls.append(ia)
            beacon_a = _word_to_valid_addr(res_list[3])
            if beacon_a:
                try:
                    b_ret = router.call(
                        c,
                        "eth_call",
                        [{"to": _checksum(beacon_a), "data": "0x5c60da1b"}, btag],
                        block_pin=pb,
                        need_archive=True,
                        timeout=5.0,
                    )
                    b_ia = _word_to_valid_addr(b_ret)
                    if b_ia:
                        cand_impls.append(b_ia)
                except Exception:
                    pass
            if _slot0_safe_proxy_shape(proxy_hist_code):
                s0_a = _word_to_valid_addr(res_list[4])
                if s0_a:
                    cand_impls.append(s0_a)
            d1167 = _eip1167_impl(proxy_hist_code)
            if _is_non_precompile_addr(d1167):
                cand_impls.append(d1167)
            d7702 = _eip7702_delegate(proxy_hist_code)
            if _is_non_precompile_addr(d7702):
                cand_impls.append(d7702)
            if proxy_hist_code and any(nm == "DELEGATECALL" for _, nm, _ in _disassemble(proxy_hist_code)):
                for d_sel, d_dec_fn in (
                    (LOUPE_FACETS_SEL, _decode_diamond_facets),
                    (LOUPE_FACET_ADDRS_SEL, lambda r: _decode_diamond_facet_addresses_checked(r)[0]),
                ):
                    try:
                        f_ret = router.call(
                            c,
                            "eth_call",
                            [{"to": chk_addr, "data": d_sel}, btag],
                            block_pin=pb,
                            need_archive=True,
                            timeout=5.0,
                        )
                        for fa_h in d_dec_fn(f_ret):
                            cand_impls.append(fa_h)
                    except Exception:
                        pass

            new_impls = [ia for ia in dict.fromkeys(cand_impls) if ia not in seen_impls]
            if not new_impls:
                continue
            for ia in new_impls:
                seen_impls.add(ia)
            code_reqs = [("eth_getCode", [_checksum(ia), btag]) for ia in new_impls]
            code_res = router.batch_call(c, code_reqs, block_pin=pb, need_archive=True)
            for rhex in code_res:
                cb = _hex_to_bytes(rhex) if isinstance(rhex, str) else b""
                if len(cb) >= 16:
                    out_codes.append(cb)
        except Exception:
            continue
    return out_codes


def _extract_word32_address(raw_val: Any) -> str:
    if isinstance(raw_val, str):
        try:
            word_b = _hex_to_word32(raw_val)
        except Exception:
            return ""
    elif isinstance(raw_val, (bytes, bytearray)) and len(raw_val) == 32:
        word_b = bytes(raw_val)
    else:
        return ""
    if word_b[:12] != b"\x00" * 12:
        return ""
    cand = _norm_addr("0x" + word_b[12:32].hex())
    return cand if _is_non_precompile_addr(cand) else ""


def _extract_addr_candidates_from_word_or_array(rdata: bytes) -> List[str]:
    """ABI 32바이트 단일 address, 동적 address[], 또는 소형 정적 튜플에서 유효 EVM 주소를 중복 없이 추출."""
    if not rdata or len(rdata) < 32:
        return []
    if len(rdata) == 32:
        cand = _extract_word32_address(rdata)
        return [cand] if cand else []
    out: List[str] = []
    seen: Set[str] = set()
    if len(rdata) >= 96 and int.from_bytes(rdata[0:32], "big") == 32:
        cnt = int.from_bytes(rdata[32:64], "big")
        if 1 <= cnt <= 32 and 64 + cnt * 32 <= len(rdata):
            for idx_el in range(cnt):
                cand = _extract_word32_address(rdata[64 + idx_el * 32 : 96 + idx_el * 32])
                if cand and cand not in seen:
                    seen.add(cand)
                    out.append(cand)
            if out:
                return out
    if len(rdata) <= 160 and len(rdata) % 32 == 0:
        for off_w in range(0, len(rdata), 32):
            cand = _extract_word32_address(rdata[off_w : off_w + 32])
            if cand and cand not in seen:
                seen.add(cand)
                out.append(cand)
    return out


def _resolve_proxy_and_delegates(
    router: RPCRouter,
    chain: str,
    addrs: Union[str, Sequence[str]],
    block_pin: int,
    raise_on_rpc_failure: bool = False,
) -> Dict[str, ProxyResolution]:
    addr_iter: Sequence[str] = [addrs] if isinstance(addrs, str) else addrs
    norm_list = sorted({na for a in addr_iter if (na := _norm_addr(a))})
    if not norm_list:
        return {}
    btag = hex(int(block_pin)) if block_pin > 0 else "latest"
    code_calls = [("eth_getCode", [_checksum(a), btag]) for a in norm_list]
    code_res = router.batch_call(
        chain,
        code_calls,
        block_pin=block_pin,
        need_archive=True,
        raise_on_all_failed=raise_on_rpc_failure,
    )
    code_map: Dict[str, bytes] = {}
    code_rpc_failed: Set[str] = set()
    if len(code_res) < len(norm_list):
        for a_miss in norm_list[len(code_res) :]:
            code_rpc_failed.add(a_miss)
            code_map[a_miss] = b""
    for a, raw_hex in zip(norm_list, code_res):
        if raise_on_rpc_failure and not isinstance(raw_hex, str):
            raise RuntimeError(f"RPC eth_getCode failed for {a} on {chain}")
        if isinstance(raw_hex, str):
            code_map[a] = _hex_to_bytes(raw_hex)
        else:
            code_rpc_failed.add(a)
            code_map[a] = b""

    # 슬롯 배치 조회 (EIP-1967 impl/beacon/admin, EIP-1822, ZOS impl/admin, Slot-0)
    slot_keys = [
        ("impl_1967", EIP1967_SLOTS["impl"]),
        ("beacon_1967", EIP1967_SLOTS["beacon"]),
        ("admin_1967", EIP1967_SLOTS["admin"]),
        ("impl_1822", EIP1822_SLOT),
        ("impl_zos", ZOS_SLOTS["impl"]),
        ("admin_zos", ZOS_SLOTS["admin"]),
        ("slot0", "0x0"),
    ]
    storage_calls: List[Tuple[str, List[Any]]] = []
    storage_index: List[Tuple[str, str]] = []
    for a in norm_list:
        if not code_map.get(a):
            continue
        for sk_name, sk_hex in slot_keys:
            storage_calls.append(("eth_getStorageAt", [_checksum(a), sk_hex, btag]))
            storage_index.append((a, sk_name))
    storage_res = router.batch_call(chain, storage_calls, block_pin=block_pin, need_archive=True) if storage_calls else []
    slot_vals: Dict[str, Dict[str, str]] = {a: {} for a in norm_list}
    slot_rpc_failed: Set[str] = set()
    if len(storage_res) < len(storage_index):
        for a, _ in storage_index[len(storage_res) :]:
            slot_rpc_failed.add(a)
    for (a, sk_name), sval in zip(storage_index, storage_res):
        if sval is None:
            slot_rpc_failed.add(a)
            continue
        cand = _extract_word32_address(sval)
        if cand and cand != a:
            slot_vals[a][sk_name] = cand

    out: Dict[str, ProxyResolution] = {}
    extra_impl_to_fetch: Set[str] = set()
    prelim: Dict[str, Tuple[str, List[str], str]] = {}
    dis_cache: Dict[str, List[Tuple[int, str, bytes]]] = {}

    # 1차 슬롯/바이트코드 기반 판정 + Beacon/Diamond/커스텀 게터 프록시 단일 배치 프로브 수집
    probe_mc_calls: List[Tuple[str, bytes]] = []
    probe_mc_meta: List[Tuple[str, str]] = []
    pending_beacon: Set[str] = set()
    has_unresolved_hop_or_beacon: Set[str] = set()

    for a in norm_list:
        raw_code = code_map.get(a, b"")
        dis = _disassemble(raw_code) if raw_code else []
        dis_cache[a] = dis
        p_kind = "none"
        impls: List[str] = []
        sv = slot_vals.get(a, {})
        admin = sv.get("admin_1967") or sv.get("admin_zos") or ""

        d7702 = _eip7702_delegate(raw_code)
        if d7702:
            p_kind = "eip7702"
            impls = [d7702]
        elif _eip1167_impl(raw_code):
            p_kind = "eip1167"
            impls = [_eip1167_impl(raw_code)]
        else:
            for k in ("impl_1967", "impl_1822", "impl_zos"):
                if sv.get(k):
                    p_kind = k
                    impls = [sv[k]]
                    break
            if not impls and sv.get("beacon_1967"):
                pending_beacon.add(a)
                probe_mc_calls.append((sv["beacon_1967"], bytes.fromhex(IMPL_GETTER_SEL[2:])))
                probe_mc_meta.append((a, "beacon_1967"))
            if not impls and sv.get("slot0") and _slot0_safe_proxy_shape(raw_code, dis):
                p_kind = "slot0_safe"
                impls = [sv["slot0"]]
            if not impls and any(nm == "DELEGATECALL" for _, nm, _ in dis):
                probe_mc_calls.append((a, bytes.fromhex(LOUPE_FACETS_SEL[2:])))
                probe_mc_meta.append((a, "diamond_2535"))
                probe_mc_calls.append((a, bytes.fromhex(LOUPE_FACET_ADDRS_SEL[2:])))
                probe_mc_meta.append((a, "diamond_2535_addrs"))
                for g_kind, g_sel in (
                    ("getter_impl", IMPL_GETTER_SEL),
                    ("getter_master_copy", MASTER_COPY_SEL),
                    ("getter_comptroller", COMPTROLLER_IMPL_SEL),
                ):
                    probe_mc_calls.append((a, bytes.fromhex(g_sel[2:])))
                    probe_mc_meta.append((a, g_kind))

        prelim[a] = (p_kind, impls, admin)

    if probe_mc_calls:
        probe_res = router.multicall3(chain, probe_mc_calls, block_pin=block_pin)
        for (a, probe_kind), (ok_p, ret_p) in zip(probe_mc_meta, probe_res):
            if not ok_p or not ret_p:
                continue
            cur_kind, cur_impls, cur_admin = prelim[a]
            if probe_kind in ("diamond_2535", "diamond_2535_addrs"):
                if cur_impls and cur_kind != "diamond_2535":
                    continue
                if probe_kind == "diamond_2535":
                    facets, bad_fac = _decode_diamond_facets_checked(ret_p)
                else:
                    facets, bad_fac = _decode_diamond_facet_addresses_checked(ret_p)
                if bad_fac:
                    has_unresolved_hop_or_beacon.add(a)
                if facets:
                    merged_f = list(dict.fromkeys([*cur_impls, *facets]))
                    prelim[a] = ("diamond_2535", merged_f, cur_admin)
                continue
            if cur_impls:
                continue
            if len(ret_p) >= 32 and ret_p[:12] == b"\x00" * 12:
                g_impl = _norm_addr("0x" + ret_p[12:32].hex())
                if _is_non_precompile_addr(g_impl) and g_impl != a:
                    prelim[a] = (probe_kind, [g_impl], cur_admin)

    for b_addr in pending_beacon:
        if not prelim[b_addr][1]:
            has_unresolved_hop_or_beacon.add(b_addr)

    for a, (_pk, im_list, _adm) in prelim.items():
        for im in im_list:
            if im not in code_map:
                extra_impl_to_fetch.add(im)

    # 최대 8홉 위임 체인(EIP-7702 -> EIP-1167 등) 바이트코드 일괄 수집
    for _hop in range(8):
        if not extra_impl_to_fetch:
            break
        extra_list = sorted(extra_impl_to_fetch)
        extra_impl_to_fetch = set()
        extra_res = router.batch_call(
            chain,
            [("eth_getCode", [_checksum(x), btag]) for x in extra_list],
            block_pin=block_pin,
            need_archive=True,
        )
        if len(extra_res) < len(extra_list):
            for x_miss in extra_list[len(extra_res) :]:
                code_rpc_failed.add(x_miss)
                code_map[x_miss] = b""
        for x, rhex in zip(extra_list, extra_res):
            if not isinstance(rhex, str):
                code_rpc_failed.add(x)
            cbytes = _hex_to_bytes(rhex) if isinstance(rhex, str) else b""
            code_map[x] = cbytes
            next_hop = _eip7702_delegate(cbytes) or _eip1167_impl(cbytes)
            if next_hop and next_hop not in code_map:
                extra_impl_to_fetch.add(next_hop)

    cid = CHAIN_IDS.get(_norm_chain(chain), 0)
    eip6780 = _probe_cancun_eip6780(router, chain, block_pin)
    code_rows_to_put: List[Tuple[int, str, int, str, str, str, str, str, List[str], bool]] = []

    for a in norm_list:
        raw_code = code_map.get(a, b"")
        p_kind, impls, admin = prelim[a]
        resolved_impls: List[str] = []
        seen_res_impls: Set[str] = set()
        for im in impls:
            cur = im
            seen_hops: Set[str] = {a}
            hop_broken = False
            for _ in range(8):
                if cur in seen_hops:
                    hop_broken = True
                    break
                seen_hops.add(cur)
                cb = code_map.get(cur, b"")
                if len(cb) == 0:
                    hop_broken = True
                    break
                nh = _eip7702_delegate(cb) or _eip1167_impl(cb)
                if nh:
                    if nh in seen_hops:
                        hop_broken = True
                        break
                    if len(code_map.get(nh, b"")) > 0 or p_kind == "eip7702":
                        cur = nh
                    else:
                        hop_broken = True
                        break
                else:
                    break
            else:
                cb_tail = code_map.get(cur, b"")
                if _eip7702_delegate(cb_tail) or _eip1167_impl(cb_tail):
                    hop_broken = True
            if hop_broken:
                has_unresolved_hop_or_beacon.add(a)
            if len(code_map.get(cur, b"")) > 0 or p_kind == "eip7702":
                _append_unique(resolved_impls, seen_res_impls, cur)

        proxy_dis = dis_cache.get(a) or []
        unresolved_deleg = bool(
            a in has_unresolved_hop_or_beacon
            or a in code_rpc_failed
            or a in slot_rpc_failed
            or any(im in code_rpc_failed for im in [*impls, *resolved_impls])
            or (
                bool(impls)
                and (not resolved_impls or any(len(code_map.get(im, b"")) == 0 for im in impls))
            )
        )
        if p_kind != "none" and not resolved_impls:
            p_kind = "none"

        impl_codes_hex: Dict[str, str] = {}
        collisions_set: Set[int] = set()
        raw_hex = "0x" + raw_code.hex() if raw_code else "0x"
        # 비최소 프록시(Transparent/UUPS/Unitroller/Custom)의 자체 디스패처·관리자 함수도 누락 없이 감사 대상에 포함
        if resolved_impls and p_kind not in ("none", "eip1167", "eip7702") and len(raw_code) > 64:
            impl_codes_hex[a] = raw_hex
        for im in resolved_impls:
            ibytes = code_map.get(im, b"")
            if ibytes:
                ihex = "0x" + ibytes.hex()
                impl_codes_hex[im] = ihex
                if proxy_dis:
                    collisions_set |= _detect_storage_slot_collision(proxy_dis, _disassemble(ibytes))
                if router.store is not None and im != a:
                    code_rows_to_put.append((
                        cid,
                        im,
                        block_pin,
                        _keccak256_hex(ibytes),
                        _skeleton_hash(ibytes),
                        ",".join(sorted(_opcode_4grams(ibytes, cap=128))),
                        ihex,
                        "implementation",
                        [],
                        eip6780,
                    ))

        if p_kind == "eip7702":
            eff_bytes = code_map.get(resolved_impls[0], b"") if resolved_impls else b""
        else:
            eff_bytes = code_map[resolved_impls[0]] if resolved_impls else raw_code
        eff_hex = "0x" + eff_bytes.hex() if eff_bytes else "0x"
        if not impl_codes_hex and eff_bytes:
            impl_codes_hex[a] = eff_hex
        skel = _skeleton_hash(eff_bytes)
        grams = ",".join(sorted(_opcode_4grams(eff_bytes, cap=128)))
        if router.store is not None:
            code_rows_to_put.append((
                cid,
                a,
                block_pin,
                _keccak256_hex(eff_bytes),
                skel,
                grams,
                eff_hex,
                p_kind,
                resolved_impls,
                eip6780,
            ))
        out[a] = ProxyResolution(
            address=a,
            proxy_kind=p_kind,
            impl_addresses=resolved_impls,
            admin_address=admin,
            raw_code_hex=raw_hex,
            effective_code_hex=eff_hex,
            skeleton_hash=skel,
            slot_collisions=sorted(collisions_set),
            impl_codes_hex=impl_codes_hex,
            unresolved_delegation=unresolved_deleg,
        )

    if router.store is not None and code_rows_to_put:
        router.store.put_contract_code_batch(code_rows_to_put)
    return out


def _probe_cancun_eip6780(router: RPCRouter, chain: str, block_pin: int) -> bool:
    """Cancun EIP-6780 활성화 여부 확인: 표준 Cancun 체인은 즉시 True, 기타 체인은 블록 헤더 Cancun 필드 프로브."""
    c = _norm_chain(chain)
    if c in (
        "ethereum", "arbitrum", "base", "optimism", "polygon", "bsc", "avalanche",
        "gnosis", "sonic", "unichain", "berachain", "monad", "megaeth", "hyperevm",
        "worldchain", "ink", "scroll", "linea", "zksync", "mantle", "blast", "mode",
    ):
        return True
    if block_pin <= 0:
        return True
    try:
        blk = router.call(c, "eth_getBlockByNumber", [hex(int(block_pin)), False], block_pin=block_pin, timeout=5.0)
        if isinstance(blk, dict):
            return any(k in blk for k in ("excessBlobGas", "blobGasUsed", "parentBeaconBlockRoot", "withdrawalsRoot"))
    except Exception:
        pass
    return False

