def _extract_push_selectors_and_addrs(dis: List[Tuple[int, str, bytes]]) -> Tuple[List[str], List[str]]:
    """디스어셈블리에서 PUSH1..PUSH4 셀렉터 및 PUSH20 상수 주소 추출."""
    sels: Set[str] = set()
    n = len(dis)
    has_shr_e0 = any(
        nm in ("SHR", "DIV") and idx > 0 and dis[idx - 1][1].startswith("PUSH") and int.from_bytes(dis[idx - 1][2] or b"\x00", "big") in (0xE0, 1 << 224)
        for idx, (_, nm, _) in enumerate(dis)
    )
    for idx, (_, nm, imm) in enumerate(dis):
        if nm == "PUSH4" and len(imm) == 4:
            sh = "0x" + imm.hex()
            if sh not in ("0x00000000", "0xffffffff"):
                if any(dis[j][1] in ("EQ", "SUB", "XOR", "GT", "LT", "SLT", "SGT") for j in range(idx + 1, min(n, idx + 8))):
                    sels.add(sh)
        elif has_shr_e0 and nm in ("PUSH1", "PUSH2", "PUSH3") and 1 <= len(imm) <= 3:
            if any(dis[j][1] == "EQ" for j in range(idx + 1, min(n, idx + 6))) and any(
                dis[j][1] == "JUMPI" for j in range(idx + 1, min(n, idx + 10))
            ):
                sh = "0x" + imm.rjust(4, b"\x00").hex()
                if sh != "0x00000000":
                    sels.add(sh)
    addrs = [a for a in _push20_constants(dis) if a != "0xffffffffffffffffffffffffffffffffffffffff"]
    return sorted(sels), addrs


def _has_dynamic_or_external_call_capability(dis: Sequence[Tuple[int, str, bytes]]) -> bool:
    """컨트랙트가 외부 CALL / DELEGATECALL / CREATE / SSTORE / TSTORE를 통해 연결된 금고나 상태를 조작할 수 있는지 판별."""
    for _, nm, _ in dis:
        if nm in ("CALL", "DELEGATECALL", "CALLCODE", "CREATE", "CREATE2", "SELFDESTRUCT", "SSTORE", "TSTORE"):
            return True
    return False


def _expand_address_graph_conceptually(
    router: RPCRouter,
    chain: str,
    seeds: List[str],
    resolutions: Dict[str, ProxyResolution],
    block_pin: int,
    max_nodes: int = 48,
    max_hops: int = 2,
) -> List[str]:
    """
    다중 홉(2~3홉) 연결 가치 그래프 확장:
    - 잔고 없는 라우터/헬퍼/컨트롤러에서 출발하더라도 PUSH20 상수, OZ Upgradeable __gap 포함 스토리지 슬롯,
      표준/인덱싱 연결 게터 + 바이트코드/Sourcify 검증 ABI 0-인자 주소 게터 + 동일 배포자 형제 컨트랙트,
      최근 이벤트 로그를 최대 max_hops 단계까지 재귀 확장하여 실제 잔고가 담긴 연결 금고/풀을 폐포에 편입한다.
    - 단, 시드에 명시되지 않은 체인 공용 인프라 싱글톤/DEX 라우터/Permit2는 금고 폐포 확장 대상에서 제외하여
      공용 인프라 잔고로 인한 E1 임계치 오염 및 이중 계상을 원천 차단한다.
    """
    c = _norm_chain(chain)
    btag = hex(block_pin) if block_pin > 0 else "latest"
    seed_set: Set[str] = {ns for s in seeds if (ns := _norm_addr(s))}
    excluded_infra: Set[str] = _infra_addresses_for_chain(c) - seed_set
    known: Set[str] = set(seed_set)
    frontier: Set[str] = set(known)
    is_live_rpc = bool(type(router).call is RPCRouter.call and "call" not in router.__dict__)

    for hop in range(max(1, int(max_hops))):
        if not frontier or len(known) >= max_nodes:
            break
        discovered: Set[str] = set()
        slot_calls: List[Tuple[str, List[Any]]] = []
        mc_calls: List[Tuple[str, bytes]] = []
        sourcify_getters_by_addr: Dict[str, List[str]] = {}
        sorted_frontier = sorted(frontier)
        frontier_has_ext_call = False

        if hop == 0 and SOURCIFY_PARQUET_DIR.is_dir():
            cid = CHAIN_IDS.get(c, 0)
            if cid > 0:
                try:
                    s_hints = _query_local_sourcify_deployment_hints(cid, sorted_frontier)
                    for ea_list in (s_hints.get("embedded_addresses") or {}).values():
                        for ea in ea_list:
                            if ea and ea not in known and ea not in excluded_infra and len(discovered) < max_nodes * 2:
                                discovered.add(ea)
                    for sa in s_hints.get("sibling_contracts") or ():
                        if sa and sa not in known and sa not in excluded_infra and len(discovered) < max_nodes * 2:
                            discovered.add(sa)
                    sourcify_getters_by_addr = dict(s_hints.get("abi_zero_arg_getters") or {})
                except Exception:
                    sourcify_getters_by_addr = {}

        for addr in sorted_frontier:
            res = resolutions.get(addr)
            if not res:
                continue
            code_hex_list = _res_facet_codes_hex(res)
            seen_calls_for_addr: Set[bytes] = set()
            if res.proxy_kind == "eip7702":
                frontier_has_ext_call = True
            for chx in code_hex_list:
                eff_bytes = _hex_to_bytes(chx)
                if not eff_bytes:
                    continue
                dis = _disassemble(eff_bytes)
                if _has_dynamic_or_external_call_capability(dis):
                    frontier_has_ext_call = True
                sels, push_addrs = _extract_push_selectors_and_addrs(dis)
                for pa in push_addrs:
                    if pa not in known and pa not in excluded_infra and len(discovered) < max_nodes * 2:
                        discovered.add(pa)
                for sel in sels:
                    sb = _hex_to_bytes(sel)
                    if sb and sb not in seen_calls_for_addr:
                        seen_calls_for_addr.add(sb)
                        mc_calls.append((addr, sb))
            for g_hex in sourcify_getters_by_addr.get(addr, ()):
                gb = _hex_to_bytes(g_hex)
                if gb and gb not in seen_calls_for_addr:
                    seen_calls_for_addr.add(gb)
                    mc_calls.append((addr, gb))
            for gs in _COMMON_CONNECTED_GETTER_SELS:
                if gs not in seen_calls_for_addr:
                    seen_calls_for_addr.add(gs)
                    mc_calls.append((addr, gs))
            if hop == 0:
                for igs in _INDEXED_CONNECTED_GETTER_CALLS:
                    if igs not in seen_calls_for_addr:
                        seen_calls_for_addr.add(igs)
                        mc_calls.append((addr, igs))
            slot_indices: Sequence[int] = _CONNECTED_STORAGE_PROBE_SLOTS if hop == 0 else range(16)
            for slot_idx in slot_indices:
                slot_calls.append(("eth_getStorageAt", [_checksum(addr), hex(slot_idx), btag]))

        if slot_calls:
            for idx_sc in range(0, len(slot_calls), 96):
                s_res = router.batch_call(c, slot_calls[idx_sc : idx_sc + 96], block_pin=block_pin, need_archive=True)
                for sval in s_res:
                    cand = _extract_word32_address(sval)
                    if cand and cand not in known and cand not in excluded_infra and len(discovered) < max_nodes * 2:
                        discovered.add(cand)

        if mc_calls:
            mc_res: List[Tuple[bool, bytes]] = []
            for idx_mc in range(0, len(mc_calls), 96):
                mc_res.extend(router.multicall3(c, mc_calls[idx_mc : idx_mc + 96], block_pin=block_pin))
            for ok, rdata in mc_res:
                if not ok or len(rdata) < 32:
                    continue
                for cand in _extract_addr_candidates_from_word_or_array(rdata):
                    if cand not in known and cand not in excluded_infra and len(discovered) < max_nodes * 2:
                        discovered.add(cand)

        if hop == 0 and block_pin > 100:
            try:
                log_lookback = 50_000 if is_live_rpc else 2_000
                log_depth = 3 if is_live_rpc else 2
                log_addrs = _harvest_logs_bisect(
                    router, c, sorted_frontier, max(1, block_pin - log_lookback), block_pin, max_depth=log_depth
                )
                for la in sorted(log_addrs):
                    if la not in known and la not in excluded_infra and len(discovered) < max_nodes * 2:
                        discovered.add(la)
            except Exception:
                pass
            if frontier_has_ext_call:
                try:
                    inb_vaults, inb_grantors, _ = _harvest_inbound_trust_and_approvals(
                        router, c, sorted_frontier, block_pin, is_live_rpc=is_live_rpc
                    )
                    for iv in sorted(inb_vaults | inb_grantors):
                        if iv not in known and iv not in excluded_infra and len(discovered) < max_nodes * 2:
                            discovered.add(iv)
                except Exception:
                    pass

        new_cands = sorted(discovered - known - excluded_infra)[: max(1, max_nodes - len(known))]
        if not new_cands:
            break
        new_res = _resolve_proxy_and_delegates(router, c, new_cands, block_pin)
        resolutions.update(new_res)
        next_frontier: Set[str] = set()
        for x, pr in new_res.items():
            if x not in excluded_infra and (len(_hex_to_bytes(pr.effective_code_hex)) > 0 or pr.proxy_kind == "eip7702"):
                known.add(x)
                next_frontier.add(x)
        frontier = next_frontier

    return sorted(known)[:max_nodes]


