@_with_decimal_prec_100
def _probe_chainlink_usd_price(
    router: RPCRouter,
    chain: str,
    feed_addr: str,
    block_pin: int,
    block_timestamp: int = 0,
) -> Decimal:
    """기준 블록(block_pin)에서 Chainlink AggregatorV3 latestRoundData() 5-워드 무결성(updatedAt > 0, answeredInRound >= roundId, heartbeat 신선도) 및 decimals()를 온체인 실측."""
    if block_pin <= 0 or not feed_addr:
        return _DEC_ZERO
    c = _norm_chain(chain)
    try:
        res = router.multicall3(
            c,
            [
                (feed_addr, bytes.fromhex("feaf968c")),
                (feed_addr, bytes.fromhex(DECIMALS_SEL[2:])),
            ],
            block_pin=block_pin,
        )
        if len(res) == 2 and res[0][0] and len(res[0][1]) >= 64:
            raw_r = res[0][1]
            if len(raw_r) >= 160:
                round_id = int.from_bytes(raw_r[0:32], "big")
                updated_at = int.from_bytes(raw_r[96:128], "big")
                answered_in_round = int.from_bytes(raw_r[128:160], "big")
                if updated_at == 0 or (round_id > 0 and answered_in_round < round_id):
                    return _DEC_ZERO
                if block_timestamp > 0 and updated_at > 0:
                    if (block_timestamp - updated_at) > 86400 * 2 or updated_at > block_timestamp + 3600:
                        return _DEC_ZERO
            answer = int.from_bytes(raw_r[32:64], "big", signed=True)
            dec = int.from_bytes(res[1][1][:32], "big") if (res[1][0] and len(res[1][1]) >= 32) else 8
            if answer > 0 and 0 <= dec <= 18:
                return Decimal(answer) / (Decimal(10) ** dec)
    except Exception:
        pass
    return _DEC_ZERO


def _fetch_block_timestamp(
    router: Optional[Any],
    chain: str,
    block_num: int,
    *,
    need_archive: bool = True,
    timeout: Optional[float] = None,
) -> int:
    if router is None or block_num <= 0:
        return 0
    c = _norm_chain(chain)
    call_kw: Dict[str, Any] = {"block_pin": int(block_num), "need_archive": need_archive}
    if timeout is not None:
        call_kw["timeout"] = timeout
    try:
        try:
            blk_obj = router.call(c, "eth_getBlockByNumber", [hex(int(block_num)), False], **call_kw)
        except TypeError:
            blk_obj = router.call(c, "eth_getBlockByNumber", [hex(int(block_num)), False])
        if isinstance(blk_obj, dict):
            return max(0, _hex_to_int(blk_obj.get("timestamp")))
    except Exception:
        pass
    return 0


def _is_live_real_router(router: Optional[Any]) -> bool:
    """모의(mock) 테스트 라우터가 아닌 실제 라이브 `RPCRouter` 인스턴스인지 판별."""
    return bool(
        router is not None
        and isinstance(router, RPCRouter)
        and type(router).call is RPCRouter.call
        and type(router).http_get_json is RPCRouter.http_get_json
        and type(router).multicall3 is RPCRouter.multicall3
        and "call" not in getattr(router, "__dict__", {})
        and "http_get_json" not in getattr(router, "__dict__", {})
        and "multicall3" not in getattr(router, "__dict__", {})
    )


@_with_decimal_prec_100
def _estimate_native_price_interval_dec(
    chain: str,
    router: Optional[RPCRouter] = None,
    block_pin: int = 0,
    allow_offline_fixture: bool = False,
) -> Tuple[Decimal, Decimal]:
    """체인 네이티브 토큰 기준 블록(block_pin) 온체인 오라클 + coins.llama.fi(historical/current) 고정밀 Decimal 교차 시세 구간 [P_min, P_max] 조회 (>15% 괴리 시 (0, 0) Fail-Open)."""
    c = _norm_chain(chain)
    live_real_ctx = bool(_is_live_real_router(router) and block_pin > 0 and not allow_offline_fixture)
    cache_key = f"native_usd:{c}:{int(block_pin)}" if block_pin > 0 else f"native_usd:{c}"
    cache_max_key = f"native_usd_max:{c}:{int(block_pin)}" if block_pin > 0 else f"native_usd_max:{c}"
    if router is not None and router.store is not None:
        cached = router.store.get_price(cache_key, max_age_sec=1800.0)
        if cached is not None and _to_dec(cached[0]) > _DEC_ZERO:
            src_lo = str(cached[1] or "")
            if (not live_real_ctx) or (not src_lo.startswith("fixture:") and "xcheck" in src_lo):
                cached_hi = router.store.get_price(cache_max_key, max_age_sec=1800.0)
                p_lo_d = _to_dec(cached[0])
                hi_valid = (
                    cached_hi is not None
                    and _to_dec(cached_hi[0]) >= p_lo_d
                    and (
                        (not live_real_ctx)
                        or (not str(cached_hi[1] or "").startswith("fixture:") and "xcheck" in str(cached_hi[1] or ""))
                    )
                )
                p_hi_d = _to_dec(cached_hi[0]) if hi_valid else p_lo_d
                return p_lo_d, p_hi_d
    blk_ts = _fetch_block_timestamp(router, c, block_pin)
    cl_d = _DEC_ZERO
    if router is not None and block_pin > 0 and c in _CHAINLINK_NATIVE_USD_FEEDS:
        cl_d = _probe_chainlink_usd_price(
            router, c, _CHAINLINK_NATIVE_USD_FEEDS[c], block_pin, block_timestamp=blk_ts
        )
    llama_d = _DEC_ZERO
    cg_key = _COINGECKO_NATIVE_IDS.get(c) or ("coingecko:ethereum" if c in NATIVE_ETH_CHAINS else "")
    if router is not None and cg_key:
        try:
            if blk_ts > 1_500_000_000:
                doc = router.http_get_json(f"https://coins.llama.fi/prices/historical/{blk_ts}/{cg_key}", timeout=5.0)
                llama_d = _to_dec(((doc.get("coins") or {}).get(cg_key) or {}).get("price") or 0)
            if llama_d <= _DEC_ZERO:
                doc = router.http_get_json(f"https://coins.llama.fi/prices/current/{cg_key}", timeout=5.0)
                llama_d = _to_dec(((doc.get("coins") or {}).get(cg_key) or {}).get("price") or 0)
        except Exception:
            llama_d = _DEC_ZERO
    if cl_d > _DEC_ZERO and llama_d > _DEC_ZERO:
        p_min_d = min(cl_d, llama_d)
        p_max_d = max(cl_d, llama_d)
        if p_max_d > _DEC_ZERO and (p_max_d - p_min_d) / p_max_d > Decimal("0.15"):
            return _DEC_ZERO, _DEC_ZERO
        if router is not None and router.store is not None:
            router.store.put_price(cache_key, float(p_min_d), "onchain:chainlink_llama_xcheck")
            router.store.put_price(cache_max_key, float(p_max_d), "onchain:chainlink_llama_xcheck_max")
        return p_min_d, p_max_d
    if live_real_ctx:
        if cl_d > _DEC_ZERO or llama_d > _DEC_ZERO:
            wnative_c = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
            stables_list = list(_norm_chain_stables(c))[:4]
            dex_nat_p_d = _DEC_ZERO
            if wnative_c and stables_list:
                try:
                    wn_dec = 18
                    dec_res = router.multicall3(
                        c, [(wnative_c, bytes.fromhex(DECIMALS_SEL[2:]))], block_pin=block_pin
                    )
                    if dec_res:
                        wn_dec = _decode_clamped_dec(dec_res[0], default_dec=18)
                    stable_quote_prices: Dict[str, float] = {}
                    for st_a in stables_list:
                        st_p_d, st_src = _fetch_token_price_usd_dec(
                            getattr(router, "store", None),
                            c,
                            st_a,
                            router=router,
                            block_pin=block_pin,
                            allow_offline_fixture=False,
                            _allow_live_xcheck=False,
                        )
                        if (
                            not str(st_src or "").startswith("fixture:")
                            and Decimal("0.85") <= st_p_d <= Decimal("1.15")
                        ):
                            stable_quote_prices[st_a] = float(st_p_d)
                    if stable_quote_prices:
                        dq_nat = probe_dex_exit_liquidity(
                            router,
                            c,
                            wnative_c,
                            10 ** wn_dec,
                            wn_dec,
                            0.0,
                            0.0,
                            block_pin,
                            quote_prices_usd=stable_quote_prices,
                            unbacked_supply_mint=True,
                        )
                        if dq_nat.get("exit_liquid") and not bool(dq_nat.get("price_diverged")):
                            dex_nat_p_d = _to_dec(
                                dq_nat.get("effective_unit_price_dec")
                                or dq_nat.get("effective_unit_price")
                                or dq_nat.get("realizable_usd_dec")
                                or dq_nat.get("realizable_usd")
                                or 0
                            )
                except Exception:
                    dex_nat_p_d = _DEC_ZERO
            if dex_nat_p_d > _DEC_ZERO:
                ref_p_d = cl_d if cl_d > _DEC_ZERO else llama_d
                p_min_d = min(ref_p_d, dex_nat_p_d)
                p_max_d = max(ref_p_d, dex_nat_p_d)
                if p_max_d > _DEC_ZERO and (p_max_d - p_min_d) / p_max_d <= Decimal("0.15"):
                    if router is not None and router.store is not None:
                        router.store.put_price(cache_key, float(p_min_d), "onchain:native_dex_xcheck")
                        router.store.put_price(cache_max_key, float(p_max_d), "onchain:native_dex_xcheck_max")
                    return p_min_d, p_max_d
        return _DEC_ZERO, _DEC_ZERO
    if cl_d > _DEC_ZERO:
        if router is not None and router.store is not None:
            router.store.put_price(cache_key, float(cl_d), "onchain:chainlink_feed")
            router.store.put_price(cache_max_key, float(cl_d), "onchain:chainlink_feed")
        return cl_d, cl_d
    if llama_d > _DEC_ZERO:
        if router is not None and router.store is not None:
            router.store.put_price(cache_key, float(llama_d), "llama_native")
            router.store.put_price(cache_max_key, float(llama_d), "llama_native")
        return llama_d, llama_d
    if allow_offline_fixture or router is None or block_pin <= 0:
        fb_val_d = Decimal("1")
        if c in _BTC_NATIVE_CHAINS:
            fb_val_d = Decimal("85000")
        elif c in NATIVE_ETH_CHAINS or c in (
            "ethereum", "arbitrum", "optimism", "base", "linea", "scroll", "zksync",
            "blast", "mode", "taiko", "unichain", "ink", "worldchain", "megaeth", "bob",
        ):
            fb_val_d = Decimal("3000")
        elif c in ("bsc", "opbnb"):
            fb_val_d = Decimal("600")
        elif c == "avalanche":
            fb_val_d = Decimal("30")
        elif c in ("polygon",):
            fb_val_d = Decimal("0.5")
        elif c in ("gnosis", "xdai"):
            fb_val_d = Decimal("1")
        return fb_val_d, fb_val_d
    return _DEC_ZERO, _DEC_ZERO


def _estimate_native_price_interval_usd(
    chain: str,
    router: Optional[RPCRouter] = None,
    block_pin: int = 0,
    allow_offline_fixture: bool = False,
) -> Tuple[float, float]:
    """체인 네이티브 토큰 기준 블록(block_pin) 온체인 오라클 + coins.llama.fi(historical/current) 교차 시세 구간 [P_min, P_max] 조회 (>15% 괴리 시 (0.0, 0.0) Fail-Open)."""
    p_lo_d, p_hi_d = _estimate_native_price_interval_dec(
        chain, router=router, block_pin=block_pin, allow_offline_fixture=allow_offline_fixture
    )
    return float(p_lo_d), float(p_hi_d)


def _estimate_native_price_dec(
    chain: str,
    router: Optional[RPCRouter] = None,
    block_pin: int = 0,
    allow_offline_fixture: bool = False,
) -> Decimal:
    """체인 네이티브 토큰 기준 블록(block_pin) 온체인 오라클 + coins.llama.fi 교차 시세 하한(P_min) 조회."""
    p_min_d, _ = _estimate_native_price_interval_dec(
        chain, router=router, block_pin=block_pin, allow_offline_fixture=allow_offline_fixture
    )
    return p_min_d


@_with_decimal_prec_100
def _resolve_token_metadata_batch(
    router: RPCRouter,
    chain: str,
    tokens: Sequence[str],
    block_pin: int,
    native_price_usd: Union[float, Decimal],
    upper_prices_out: Optional[Dict[str, float]] = None,
    native_price_max_usd: Optional[Union[float, Decimal]] = None,
    *,
    prices_dec_out: Optional[Dict[str, Decimal]] = None,
    upper_prices_dec_out: Optional[Dict[str, Decimal]] = None,
) -> Tuple[Dict[str, int], Dict[str, float]]:
    """
    토큰별 decimals(), symbol() 단일 Multicall3 배치 조회 + coins.llama.fi 배치 시세 조회 + 온체인 DEX 호가 교차 검증:
    - 0-decimal ~ 77-decimal ERC-20 (`0 <= val <= 77`) 전 범위 정밀 수용 (`10 ** dec` 단위 실측).
    - 라이브 블록(`block_pin > 0`)에서 하드코딩 상수 단가($1, $3,000, $85,000) 부여를 금지하고 미확정 시 0.0으로 유지하여 Fail-Open 보장.
    - 온체인 DEX 현물과 외부 시세 간 괴리율 `> 15%` 발생 시 0.0(Fail-Open)으로 강등하며, 이익 계산용 하한(`min`)과 E1 노출 상한(`max`)을 이원화 기록.
    """
    c = _norm_chain(chain)
    cid = CHAIN_IDS.get(c, 0)
    wnative = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
    alias_set = NATIVE_ALIAS_TOKENS_BY_CHAIN.get(c, frozenset())
    stables = _norm_chain_stables_set(c)
    bluechips = _norm_chain_bluechips_set(c)
    nat_lo_d = _to_dec(native_price_usd)
    eff_native_hi_d = (
        _to_dec(native_price_max_usd)
        if (native_price_max_usd is not None and _to_dec(native_price_max_usd) >= nat_lo_d)
        else nat_lo_d
    )
    decimals_map: Dict[str, int] = {}
    price_map: Dict[str, float] = {}
    to_query: List[str] = []

    for t in tokens:
        tn = _norm_addr(t)
        if not tn or tn in decimals_map or tn in alias_set:
            continue
        if router.store is not None and block_pin > 0:
            cached = router.store.get_token_meta(cid, tn, block_pin)
            if cached is not None and int(cached.get("is_valid_erc20", 0)) == 1:
                decimals_map[tn] = int(cached["decimals"])
                c_p_d = _to_dec(cached["price_usd"])
                price_map[tn] = float(c_p_d)
                if prices_dec_out is not None:
                    prices_dec_out[tn] = c_p_d
                if upper_prices_out is not None or upper_prices_dec_out is not None:
                    cached_max = router.store.get_price(f"TOKEN_MAX:{cid}:{tn}:{block_pin}", max_age_sec=86400)
                    c_p_hi_d = _to_dec(cached_max[0]) if (cached_max is not None and _to_dec(cached_max[0]) > _DEC_ZERO) else c_p_d
                    hi_d = eff_native_hi_d if (tn == wnative and eff_native_hi_d > _DEC_ZERO and c_p_d > _DEC_ZERO) else max(c_p_d, c_p_hi_d)
                    if upper_prices_out is not None:
                        upper_prices_out[tn] = float(hi_d)
                    if upper_prices_dec_out is not None:
                        upper_prices_dec_out[tn] = hi_d
                continue
        to_query.append(tn)

    if to_query:
        dec_bytes = bytes.fromhex(DECIMALS_SEL[2:])
        sym_bytes = bytes.fromhex(SYMBOL_SEL[2:])
        calls: List[Tuple[str, bytes]] = []
        for tn in to_query:
            calls.append((tn, dec_bytes))
            calls.append((tn, sym_bytes))
        res = router.multicall3(c, calls, block_pin=block_pin) if block_pin > 0 else []

        parsed_tokens: List[Tuple[str, int, str, bool]] = []
        llama_batch_addrs: List[str] = []
        for idx, tn in enumerate(to_query):
            d_ok, d_raw = res[2 * idx] if (2 * idx) < len(res) else (False, b"")
            s_ok, s_raw = res[2 * idx + 1] if (2 * idx + 1) < len(res) else (False, b"")
            dec = 18
            is_erc20 = False
            if d_ok and len(d_raw) >= 32:
                val = int.from_bytes(d_raw[:32], "big")
                if 0 <= val <= 77:
                    dec = val
                    is_erc20 = True
            sym = ""
            if s_ok and len(s_raw) >= 32:
                try:
                    sym = str(abi_decode(["string"], s_raw)[0]).strip()
                except Exception:
                    sym = s_raw[:32].rstrip(b"\x00").decode("utf-8", errors="ignore").strip()
            parsed_tokens.append((tn, dec, sym, is_erc20))
            if tn != wnative and (is_erc20 or tn in stables or tn in bluechips):
                llama_batch_addrs.append(tn)

        llama_prices_dec: Dict[str, Decimal] = {}
        if llama_batch_addrs and block_pin > 0:
            l_pref = _llama_chain_prefix(c)
            blk_ts_meta = _fetch_block_timestamp(router, c, block_pin)
            for lb_off in range(0, len(llama_batch_addrs), 24):
                lb_chunk = llama_batch_addrs[lb_off : lb_off + 24]
                joined_keys = ",".join(f"{l_pref}:{tn}" for tn in lb_chunk)
                batch_urls = (
                    (
                        f"https://coins.llama.fi/prices/historical/{blk_ts_meta}/{joined_keys}",
                        f"https://coins.llama.fi/prices/current/{joined_keys}",
                    )
                    if blk_ts_meta > 1_500_000_000
                    else (f"https://coins.llama.fi/prices/current/{joined_keys}",)
                )
                for b_url in batch_urls:
                    missing_tn = [tn for tn in lb_chunk if tn not in llama_prices_dec]
                    if not missing_tn:
                        break
                    try:
                        doc = router.http_get_json(b_url, timeout=5.0)
                        coins_obj = doc.get("coins") if isinstance(doc, dict) else {}
                        if isinstance(coins_obj, dict):
                            for tn in missing_tn:
                                p_val_d = _to_dec((coins_obj.get(f"{l_pref}:{tn}") or coins_obj.get(f"{c}:{tn}") or {}).get("price") or 0)
                                if p_val_d > _DEC_ZERO:
                                    llama_prices_dec[tn] = p_val_d
                    except Exception:
                        pass

        llama_prices_f: Dict[str, float] = {k: float(v) for k, v in llama_prices_dec.items()}
        meta_rows: List[Tuple[int, str, int, str, int, bool, float, float, str]] = []
        for tn, dec, sym, is_erc20 in parsed_tokens:
            u_price_d = _DEC_ZERO
            u_price_hi_d = _DEC_ZERO
            if tn == wnative:
                u_price_d = nat_lo_d if nat_lo_d > _DEC_ZERO else _DEC_ZERO
                u_price_hi_d = eff_native_hi_d if eff_native_hi_d > _DEC_ZERO else u_price_d
            elif block_pin > 0 and (tn in llama_prices_dec or (eff_native_hi_d > _DEC_ZERO and (is_erc20 or tn in stables or tn in bluechips))):
                ext_p_d = llama_prices_dec.get(tn, _DEC_ZERO)
                dex_p_d = _DEC_ZERO
                dex_p_hi_d = _DEC_ZERO
                dex_div = False
                probe_nat_d = nat_lo_d if nat_lo_d > _DEC_ZERO else eff_native_hi_d
                if probe_nat_d > _DEC_ZERO and (is_erc20 or tn in stables or tn in bluechips):
                    try:
                        if ext_p_d > _DEC_ZERO:
                            target_raw = int((Decimal("1") / ext_p_d) * (Decimal(10) ** dec))
                            probe_amt = max(1, min(10 ** min(dec + 12, 36), target_raw))
                        else:
                            probe_amt = max(1, (10 ** dec) // 100 if dec >= 2 else (10 ** dec))
                        dex_q = probe_dex_exit_liquidity(
                            router,
                            c,
                            tn,
                            probe_amt,
                            dec,
                            float(ext_p_d),
                            float(probe_nat_d),
                            block_pin,
                            quote_prices_usd=llama_prices_f,
                        )
                        if bool(dex_q.get("price_diverged")):
                            dex_div = True
                        elif dex_q.get("exit_liquid"):
                            dex_real_d = _to_dec(
                                dex_q["realizable_usd_dec"]
                                if "realizable_usd_dec" in dex_q
                                else dex_q.get("realizable_usd")
                            )
                            if dex_real_d > _DEC_ZERO:
                                dex_unit_d = dex_real_d * (Decimal(10 ** dec) / Decimal(probe_amt))
                                dex_p_d = dex_unit_d
                                dex_p_hi_d = (
                                    dex_unit_d * (eff_native_hi_d / probe_nat_d)
                                    if eff_native_hi_d > probe_nat_d > _DEC_ZERO
                                    else dex_p_d
                                )
                    except Exception:
                        dex_p_d = _DEC_ZERO
                        dex_p_hi_d = _DEC_ZERO
                if dex_div:
                    u_price_d = _DEC_ZERO
                    u_price_hi_d = _DEC_ZERO
                elif ext_p_d > _DEC_ZERO and dex_p_d > _DEC_ZERO:
                    p_hi_d = max(ext_p_d, dex_p_d)
                    p_lo_d = min(ext_p_d, dex_p_d)
                    if p_hi_d > _DEC_ZERO and (p_hi_d - p_lo_d) / p_hi_d > Decimal("0.15"):
                        u_price_d = _DEC_ZERO
                        u_price_hi_d = _DEC_ZERO
                    else:
                        u_price_d = p_lo_d
                        u_price_hi_d = max(ext_p_d, dex_p_hi_d)
                elif tn in stables and not _is_live_real_router(router) and (ext_p_d > _DEC_ZERO or dex_p_d > _DEC_ZERO):
                    u_price_d = ext_p_d if ext_p_d > _DEC_ZERO else dex_p_d
                    u_price_hi_d = max(ext_p_d, dex_p_hi_d) if (ext_p_d > _DEC_ZERO and dex_p_hi_d > _DEC_ZERO) else u_price_d
            elif block_pin <= 0:
                if tn in stables:
                    u_price_d = Decimal("1")
                elif tn in bluechips:
                    u_price_d = Decimal("85000") if dec == 8 else Decimal("3000")
                u_price_hi_d = u_price_d
            u_price_f = float(u_price_d)
            u_price_hi_f = float(u_price_hi_d)
            decimals_map[tn] = dec
            price_map[tn] = u_price_f
            if prices_dec_out is not None:
                prices_dec_out[tn] = u_price_d
            if upper_prices_out is not None:
                upper_prices_out[tn] = u_price_hi_f
            if upper_prices_dec_out is not None:
                upper_prices_dec_out[tn] = u_price_hi_d
            if router.store is not None and block_pin > 0:
                if u_price_hi_d > _DEC_ZERO:
                    router.store.put_price(f"TOKEN_MAX:{cid}:{tn}:{block_pin}", u_price_hi_f, "onchain_meta_max")
                meta_rows.append((
                    cid,
                    tn,
                    block_pin,
                    sym or "ERC20",
                    dec,
                    bool(is_erc20 or (tn in stables) or (tn in bluechips) or (tn == wnative)),
                    u_price_f,
                    100_000.0 if u_price_d > _DEC_ZERO else 0.0,
                    "onchain_meta",
                ))
        if router.store is not None and meta_rows:
            router.store.put_token_meta_batch(meta_rows)

    return decimals_map, price_map


@_with_decimal_prec_100
def build_backward_trust_closure(
    router: RPCRouter,
    chain: str,
    seed_addresses: List[str],
    block_pin: int,
    protocol_tvl_hint_usd: float = 0.0,
) -> TrustClosureResult:
    """
    다중 홉 연결 가치 도달 가능성 폐포(Connected Value Reachability Closure):
    - 외부 진입 컨트랙트 자체의 잔고가 $0이더라도 연결된 금고/풀/토큰 알로원스/동적 외부 CALL이 존재하면
      절대 E1에서 조기 종료(drop)하지 않고 E2 -> E3 -> Stage 4 Foundry 다중 금고 보존 법칙 검증으로 전달한다!
    - RPC 전면 장애 시 빈 바이트코드(안전)로 오판하지 않도록 예외를 상위로 전파하여 `미검증 차단` 처리한다.
    """
    c = _norm_chain(chain)
    btag = hex(block_pin) if block_pin > 0 else "latest"
    clean_seeds = sorted({nx for x in seed_addresses if (nx := _norm_addr(x))})
    if not clean_seeds:
        return TrustClosureResult(
            chain=c,
            block_pin=block_pin,
            seed_addresses=[],
            all_addresses=[],
            resolutions={},
            vault_exposures={},
            max_extractable_usd=0.0,
            min_gas_usd=0.01,
            early_exit_safe=True,
            early_exit_reason="E1_NO_VALID_SEED_ADDRESS",
        )

    resolutions = _resolve_proxy_and_delegates(
        router,
        c,
        clean_seeds,
        block_pin,
        raise_on_rpc_failure=(block_pin > 0),
    )
    expanded = _expand_address_graph_conceptually(router, c, clean_seeds, resolutions, block_pin, max_nodes=64, max_hops=2)
    new_addrs = [x for x in expanded if x not in resolutions]
    if new_addrs:
        resolutions.update(_resolve_proxy_and_delegates(router, c, new_addrs, block_pin))

    all_addrs = sorted(resolutions.keys())
    alias_set = NATIVE_ALIAS_TOKENS_BY_CHAIN.get(c, frozenset())
    stables = [x for x in CHAIN_STABLES.get(c, []) if _norm_addr(x) not in alias_set]
    bluechips = [x for x in CHAIN_BLUECHIPS.get(c, []) if _norm_addr(x) not in alias_set]
    wnative = WRAPPED_NATIVE_BY_CHAIN.get(c, "")
    if wnative and _norm_addr(wnative) not in alias_set and wnative not in stables:
        stables.insert(0, wnative)

    seed_erc20_cands: List[str] = []
    for s_a in clean_seeds:
        r_s = resolutions.get(s_a)
        if r_s is None:
            continue
        s_codes = _res_facet_codes_hex(r_s)
        if any(any(sel_k in str(chx).lower() for sel_k in ("70a08231", "18160ddd", "313ce567")) for chx in s_codes):
            seed_erc20_cands.append(s_a)

    clean_seed_set: Set[str] = set(clean_seeds)
    all_addr_set: Set[str] = set(all_addrs)
    candidate_tokens: List[str] = [
        t_a
        for t_a in dict.fromkeys([*seed_erc20_cands, *stables, *bluechips, *[a for a in all_addrs if a not in clean_seed_set]])
        if _norm_addr(t_a) not in alias_set
    ]
    cand_tok_set: Set[str] = set(candidate_tokens)
    static_tok_extras: List[str] = []
    for a_st in all_addrs:
        r_st = resolutions.get(a_st)
        if r_st is None:
            continue
        for chx_st in _res_facet_codes_hex(r_st):
            eb_st = _hex_to_bytes(chx_st)
            if eb_st:
                for p_st in _push20_constants(_disassemble(eb_st)):
                    np_st = _norm_addr(p_st)
                    if (
                        _is_non_precompile_addr(np_st)
                        and np_st not in all_addr_set
                        and np_st not in alias_set
                        and np_st != "0xffffffffffffffffffffffffffffffffffffffff"
                    ):
                        static_tok_extras.append(np_st)
    if _has_sourcify_corpus_files(SOURCIFY_PARQUET_DIR):
        cid_bt = CHAIN_IDS.get(c, 0)
        if cid_bt > 0:
            for s_v in clean_seeds[:4]:
                try:
                    sf_v = _query_local_sourcify_verified(cid_bt, s_v)
                    if isinstance(sf_v, dict) and isinstance(sf_v.get("sources"), dict):
                        for src_txt in sf_v["sources"].values():
                            for m_ad in _ANY_ADDR_RE.findall(str(src_txt or "")):
                                nm_ad = _norm_addr(m_ad)
                                if (
                                    _is_non_precompile_addr(nm_ad)
                                    and nm_ad not in all_addr_set
                                    and nm_ad not in alias_set
                                    and nm_ad != "0xffffffffffffffffffffffffffffffffffffffff"
                                ):
                                    static_tok_extras.append(nm_ad)
                except Exception:
                    pass
    for st_ex in dict.fromkeys(static_tok_extras):
        if len(candidate_tokens) >= 96:
            break
        _append_unique(candidate_tokens, cand_tok_set, st_ex)

    approval_owners: Set[str] = set(all_addrs)
    ext_approval_spenders: Set[str] = set()
    if block_pin > 100:
        try:
            is_live_rpc_bt = bool(type(router).call is RPCRouter.call and "call" not in router.__dict__)
            tok_lookback = 50_000 if is_live_rpc_bt else 3_000
            recent_from = max(1, block_pin - tok_lookback)
            log_tokens, log_owners = _harvest_token_logs_bisect(
                router,
                c,
                all_addrs,
                recent_from,
                block_pin,
                max_depth=(3 if is_live_rpc_bt else 2),
                out_spenders=ext_approval_spenders,
            )
            if recent_from > 2:
                dormant_span = 1_000_000 if is_live_rpc_bt else 500_000
                dormant_from = max(1, block_pin - dormant_span)
                if dormant_from < recent_from:
                    d_tokens, d_owners = _harvest_token_logs_bisect(
                        router,
                        c,
                        all_addrs,
                        dormant_from,
                        recent_from - 1,
                        max_depth=1,
                        out_spenders=ext_approval_spenders,
                    )
                    log_tokens |= d_tokens
                    log_owners |= d_owners
            _, inb_grantors_bt, inb_toks_bt = _harvest_inbound_trust_and_approvals(
                router, c, all_addrs, block_pin, is_live_rpc=is_live_rpc_bt
            )
            log_tokens |= inb_toks_bt
            log_owners |= inb_grantors_bt
            for lt in sorted(log_tokens):
                if _norm_addr(lt) not in alias_set:
                    _append_unique(candidate_tokens, cand_tok_set, lt)
            approval_owners |= log_owners
        except Exception:
            pass

    closure_truncated = bool(len(expanded) >= 64)

    bal_res = router.batch_call(
        c,
        [("eth_getBalance", [_checksum(a), btag]) for a in all_addrs],
        block_pin=block_pin,
        need_archive=True,
    )
    np_min_dec_raw, np_max_dec_raw = _estimate_native_price_interval_dec(c, router=router, block_pin=block_pin)
    np_min_dec = max(_DEC_ZERO, np_min_dec_raw)
    np_max_dec = max(_DEC_ZERO, np_max_dec_raw)
    native_price_min = float(np_min_dec)
    native_price_max = float(np_max_dec)
    native_price = native_price_min
    exposures: Dict[str, VaultExposure] = {a: VaultExposure(address=a) for a in all_addrs}
    native_dec_map: Dict[str, Decimal] = {}
    tok_dec_map: Dict[str, Dict[str, Decimal]] = {a: {} for a in all_addrs}
    allow_dec_map: Dict[str, Decimal] = {a: _DEC_ZERO for a in all_addrs}
    has_unpriced_native_exposure = False
    rpc_balance_incomplete = bool(block_pin > 0 and any(b is None for b in bal_res))
    wei_18_dec = Decimal(10) ** 18
    for a, bhex in zip(all_addrs, bal_res):
        try:
            w = int(str(bhex), 16) if isinstance(bhex, str) and bhex.startswith("0x") else 0
        except Exception:
            w = 0
        exposures[a].native_wei = w
        n_d = (Decimal(w) / wei_18_dec) * np_max_dec
        native_dec_map[a] = n_d
        exposures[a].native_usd = float(n_d)
        if w > 0 and np_max_dec <= _DEC_ZERO:
            has_unpriced_native_exposure = True

    price_max_map: Dict[str, float] = {}
    price_dec_map: Dict[str, Decimal] = {}
    price_max_dec_map: Dict[str, Decimal] = {}
    dec_map, price_map = _resolve_token_metadata_batch(
        router,
        c,
        candidate_tokens,
        block_pin,
        np_min_dec,
        upper_prices_out=price_max_map,
        native_price_max_usd=np_max_dec,
        prices_dec_out=price_dec_map,
        upper_prices_dec_out=price_max_dec_map,
    )
    bal_sel = bytes.fromhex(BALANCE_OF_SEL[2:])
    allow_sel = bytes.fromhex(ALLOWANCE_SEL[2:])

    mc_queries: List[Tuple[str, bytes]] = []
    mc_meta: List[Tuple[str, str, str]] = []
    for a in all_addrs:
        a_padded = abi_encode(["address"], [a])
        for tok in candidate_tokens:
            t_norm = _norm_addr(tok)
            if t_norm and t_norm != a:
                mc_queries.append((t_norm, bal_sel + a_padded))
                mc_meta.append(("bal", a, t_norm))

    # 연결된 금고(all_addrs 포함) 및 외부 오너가 프로토콜 컨트랙트(spender)에 부여한 allowance 전수 조사
    owner_list = sorted(approval_owners)
    for ow in owner_list:
        ow_padded = abi_encode(["address"], [ow])
        for tok in candidate_tokens:
            t_norm = _norm_addr(tok)
            if not t_norm:
                continue
            if ow not in all_addr_set:
                mc_queries.append((t_norm, bal_sel + ow_padded))
                mc_meta.append(("ow_bal", ow, t_norm))
            for spender in all_addrs:
                if spender == ow:
                    continue
                pair_padded = abi_encode(["address", "address"], [ow, spender])
                mc_queries.append((t_norm, allow_sel + pair_padded))
                mc_meta.append((f"allow:{spender}", ow, t_norm))

    ext_sp_list = sorted(s for s in ext_approval_spenders if s not in all_addr_set)[:24]
    for ext_sp in ext_sp_list:
        for v_addr in all_addrs:
            for tok in candidate_tokens:
                t_norm = _norm_addr(tok)
                if not t_norm:
                    continue
                pair_padded = abi_encode(["address", "address"], [v_addr, ext_sp])
                mc_queries.append((t_norm, allow_sel + pair_padded))
                mc_meta.append((f"ext_allow:{ext_sp}", v_addr, t_norm))

    owner_bals: Dict[Tuple[str, str], int] = {}
    pending_allows: List[Tuple[str, str, str, int]] = []
    pending_ext_allows: List[Tuple[str, str, str, int]] = []
    has_unpriced_token_exposure = has_unpriced_native_exposure

    def _tok_amount_hi_usd_dec(tn: str, amt: int) -> Tuple[Decimal, Decimal]:
        dec_t = dec_map.get(tn, 18)
        u_p_d = price_dec_map.get(tn, _to_dec(price_map.get(tn, 0)))
        u_p_hi_d = price_max_dec_map.get(tn, _to_dec(price_max_map.get(tn, u_p_d)))
        return (Decimal(amt) / (Decimal(10) ** dec_t)) * u_p_hi_d, u_p_d

    if mc_queries:
        mc_out: List[Tuple[bool, bytes]] = []
        for idx_mq in range(0, len(mc_queries), 128):
            mc_out.extend(router.multicall3(c, mc_queries[idx_mq : idx_mq + 128], block_pin=block_pin))
            if block_pin > 0 and getattr(router, "last_multicall_transport_failed", lambda: False)():
                rpc_balance_incomplete = True
        if block_pin > 0 and (len(mc_out) < len(mc_queries) or not any(ok for ok, _ in mc_out)):
            try:
                rebuilt_mc: List[Tuple[bool, bytes]] = list(mc_out)
                for fb_off in range(0, len(mc_queries), 64):
                    fb_slice = mc_queries[fb_off : fb_off + 64]
                    fb_calls = [
                        ("eth_call", [{"to": _checksum(t_a), "data": "0x" + bytes(cd).hex()}, btag])
                        for t_a, cd in fb_slice
                    ]
                    fb_res = router.batch_call(
                        c,
                        fb_calls,
                        block_pin=block_pin,
                        need_archive=True,
                        raise_on_all_failed=True,
                    )
                    if any(r_fb is None for r_fb in fb_res):
                        rpc_balance_incomplete = True
                    for rel_fb, r_fb in enumerate(fb_res):
                        idx_fb = fb_off + rel_fb
                        if idx_fb < len(rebuilt_mc) and isinstance(r_fb, str) and r_fb.startswith("0x") and len(r_fb) > 2:
                            rebuilt_mc[idx_fb] = (True, _hex_to_bytes(r_fb))
                mc_out = rebuilt_mc
            except Exception:
                rpc_balance_incomplete = True
        for (kind, actor, t_norm), (ok, rdata) in zip(mc_meta, mc_out):
            if not ok or len(rdata) < 32:
                continue
            raw_amt = int.from_bytes(rdata[:32], "big")
            if raw_amt <= 0:
                continue
            if kind == "bal":
                exposures[actor].token_balances[t_norm] = raw_amt
                t_d, u_price_d = _tok_amount_hi_usd_dec(t_norm, raw_amt)
                tok_dec_map[actor][t_norm] = t_d
                exposures[actor].token_usd[t_norm] = float(t_d)
                owner_bals[(actor, t_norm)] = raw_amt
                if u_price_d <= _DEC_ZERO:
                    has_unpriced_token_exposure = True
            elif kind == "ow_bal":
                owner_bals[(actor, t_norm)] = raw_amt
            elif kind.startswith("allow:"):
                spender = kind.split(":", 1)[1]
                pending_allows.append((spender, actor, t_norm, raw_amt))
            elif kind.startswith("ext_allow:"):
                ext_sp = kind.split(":", 1)[1]
                pending_ext_allows.append((ext_sp, actor, t_norm, raw_amt))

    owner_effective_raw: Dict[Tuple[str, str], int] = {}
    for a_k, exp_v in exposures.items():
        for t_k, amt_v in exp_v.token_balances.items():
            if amt_v > 0:
                owner_effective_raw[(a_k, t_k)] = max(owner_effective_raw.get((a_k, t_k), 0), amt_v)

    active_approved_owners: List[str] = []
    seen_active_owners: Set[str] = set()
    for spender, ow, t_norm, allow_amt in pending_allows:
        eff_amt = min(allow_amt, owner_bals.get((ow, t_norm), 0))
        if eff_amt > 0 and spender in exposures:
            al_d, u_price_d = _tok_amount_hi_usd_dec(t_norm, eff_amt)
            allow_dec_map[spender] = allow_dec_map.get(spender, _DEC_ZERO) + al_d
            exposures[spender].allowance_usd = float(allow_dec_map[spender])
            exposures[spender].allowance_usd_dec = format(allow_dec_map[spender], "f")
            owner_effective_raw[(ow, t_norm)] = max(owner_effective_raw.get((ow, t_norm), 0), eff_amt)
            if ow not in all_addr_set:
                _append_unique(active_approved_owners, seen_active_owners, ow)
            if u_price_d <= _DEC_ZERO:
                has_unpriced_token_exposure = True

    held_tok_raw: Dict[str, int] = {}
    for (_, t_k), raw_v in owner_effective_raw.items():
        if raw_v > 0:
            held_tok_raw[t_k] = held_tok_raw.get(t_k, 0) + raw_v

    total_onchain_dec = _DEC_ZERO
    native_total_dec = _DEC_ZERO
    native_total_hi_dec = _DEC_ZERO
    nat_scale_hi = (
        (np_max_dec / np_min_dec)
        if (np_min_dec > _DEC_ZERO and np_max_dec > np_min_dec)
        else Decimal("1")
    )
    for a, exp in exposures.items():
        if exp.native_wei > 0 and np_max_dec <= _DEC_ZERO:
            has_unpriced_token_exposure = True
        nat_a_d = native_dec_map.get(a, _DEC_ZERO)
        native_total_dec += nat_a_d
        native_total_hi_dec += nat_a_d * nat_scale_hi
        exp_tot_dec = (
            nat_a_d
            + sum(tok_dec_map.get(a, {}).values(), _DEC_ZERO)
            + allow_dec_map.get(a, _DEC_ZERO)
        )
        exp.total_usd = float(exp_tot_dec)
        exp.total_usd_dec = format(exp_tot_dec, "f")
        total_onchain_dec += exp_tot_dec

    # 아웃바운드 승인된 외부 스펜더 노출 기록(프로토콜 금고 보유분 중복 합산 없이 allowance_usd만 별도 노출)
    for ext_sp, ow_v, t_norm, allow_amt in pending_ext_allows:
        eff_amt = min(allow_amt, owner_bals.get((ow_v, t_norm), 0))
        if eff_amt > 0 and ext_sp not in all_addr_set:
            al_d, u_price_d = _tok_amount_hi_usd_dec(t_norm, eff_amt)
            if u_price_d <= _DEC_ZERO:
                has_unpriced_token_exposure = True
            if al_d > _DEC_ZERO:
                ext_exp = exposures.get(ext_sp)
                if ext_exp is None:
                    ext_exp = VaultExposure(address=ext_sp)
                    exposures[ext_sp] = ext_exp
                prev_ext_dec = _to_dec(ext_exp.allowance_usd_dec or ext_exp.allowance_usd)
                new_ext_dec = prev_ext_dec + al_d
                ext_exp.allowance_usd = float(new_ext_dec)
                ext_exp.allowance_usd_dec = format(new_ext_dec, "f")
                ext_exp.total_usd = float(new_ext_dec)
                ext_exp.total_usd_dec = format(new_ext_dec, "f")

    realizable_tokens_dec = _DEC_ZERO
    realizable_tokens_hi_dec = _DEC_ZERO
    verified_exit_pools: Dict[str, Dict[str, Any]] = {}
    stables_set_bt = {_norm_addr(x) for x in stables if _norm_addr(x)}
    all_tokens_dex_verified = bool(
        block_pin > 0 and held_tok_raw and not has_unpriced_token_exposure and not rpc_balance_incomplete
    )
    for t_norm, tot_raw in sorted(held_tok_raw.items()):
        dec_t = dec_map.get(t_norm, 18)
        if t_norm == wnative and np_max_dec > _DEC_ZERO:
            tok_real_d = (Decimal(tot_raw) / (Decimal(10) ** dec_t)) * np_max_dec
            realizable_tokens_dec += tok_real_d
            realizable_tokens_hi_dec += tok_real_d
            verified_exit_pools[t_norm] = {
                "pool": _checksum(wnative),
                "quote_token": "native",
                "dex_kind": "unwrap_native",
                "held_raw": str(tot_raw),
                "realizable_usd": round(float(tok_real_d), 4),
                "dex_depth_usd": round(float(tok_real_d), 4),
                "paused": False,
            }
            continue
        if block_pin <= 0:
            nom_d, _ = _tok_amount_hi_usd_dec(t_norm, tot_raw)
            realizable_tokens_dec += nom_d
            realizable_tokens_hi_dec += nom_d
            all_tokens_dex_verified = False
            continue
        try:
            dex_q = probe_dex_exit_liquidity(
                router,
                c,
                t_norm,
                tot_raw,
                dec_t,
                price_map.get(t_norm, 0.0),
                native_price,
                block_pin,
                quote_prices_usd=price_map,
            )
        except Exception:
            dex_q = {"exit_liquid": False, "realizable_usd": 0.0}
        if dex_q.get("paused"):
            verified_exit_pools[t_norm] = {
                "pool": "",
                "quote_token": "",
                "dex_kind": "paused_token",
                "held_raw": str(tot_raw),
                "realizable_usd": 0.0,
                "dex_depth_usd": 0.0,
                "paused": True,
            }
        elif dex_q.get("best_pool_address"):
            tok_real_d = _to_dec(dex_q.get("realizable_usd_dec") or dex_q.get("realizable_usd") or 0.0)
            realizable_tokens_dec += tok_real_d
            nom_hi_d, _ = _tok_amount_hi_usd_dec(t_norm, tot_raw)
            nom_lo_d = (Decimal(tot_raw) / (Decimal(10) ** dec_t)) * _to_dec(price_map.get(t_norm, 0.0))
            tok_real_hi_d = tok_real_d
            if nom_hi_d > nom_lo_d > _DEC_ZERO:
                tok_real_hi_d = max(tok_real_hi_d, min(nom_hi_d, tok_real_d * (nom_hi_d / nom_lo_d)))
            if nat_scale_hi > Decimal("1"):
                tok_real_hi_d = max(tok_real_hi_d, tok_real_d * nat_scale_hi)
            realizable_tokens_hi_dec += tok_real_hi_d
            exit_entry: Dict[str, Any] = {
                "pool": str(dex_q.get("best_pool_address") or ""),
                "quote_token": str(dex_q.get("best_quote_token") or ""),
                "dex_kind": str(dex_q.get("best_dex_kind") or ""),
                "v3_fee": int(dex_q.get("v3_fee") or 0),
                "curve_i": int(dex_q.get("curve_i") or 0),
                "curve_j": int(dex_q.get("curve_j") or 0),
                "curve_underlying": bool(dex_q.get("curve_underlying")),
                "solidly_stable": bool(dex_q.get("solidly_stable")),
                "held_raw": str(tot_raw),
                "realizable_usd": round(float(tok_real_d), 4),
                "dex_depth_usd": round(float(dex_q.get("dex_depth_usd") or 0.0), 4),
                "paused": False,
            }
            if dex_q.get("best_other_token"):
                exit_entry["lp_other_token"] = str(dex_q.get("best_other_token") or "")
            if dex_q.get("redeem_target"):
                exit_entry["redeem_target"] = str(dex_q.get("redeem_target") or "")
            if isinstance(dex_q.get("underlying_exit"), dict) and dex_q["underlying_exit"].get("pool"):
                exit_entry["underlying_exit"] = dict(dex_q["underlying_exit"])
            verified_exit_pools[t_norm] = exit_entry
        elif t_norm in stables_set_bt and dex_q.get("exit_liquid"):
            tok_real_d = _to_dec(dex_q.get("realizable_usd_dec") or dex_q.get("realizable_usd") or 0.0)
            realizable_tokens_dec += tok_real_d
            nom_hi_d, _ = _tok_amount_hi_usd_dec(t_norm, tot_raw)
            realizable_tokens_hi_dec += max(tok_real_d, nom_hi_d)
            verified_exit_pools[t_norm] = {
                "pool": "",
                "quote_token": _checksum(t_norm),
                "dex_kind": "stablecoin_cap",
                "held_raw": str(tot_raw),
                "realizable_usd": round(float(tok_real_d), 4),
                "dex_depth_usd": round(float(dex_q.get("dex_depth_usd") or 0.0), 4),
                "paused": False,
            }
        else:
            all_tokens_dex_verified = False

    realizable_extractable_dec = max(_DEC_ZERO, native_total_dec + realizable_tokens_dec)
    realizable_upper_dec = max(realizable_extractable_dec, native_total_hi_dec + realizable_tokens_hi_dec)
    realizable_extractable_usd = float(realizable_extractable_dec)
    realizable_extractable_dec_str = format(realizable_extractable_dec, "f")

    total_onchain_usd = float(total_onchain_dec)
    max_extractable_dec = max(total_onchain_dec, max(_DEC_ZERO, _to_dec(protocol_tvl_hint_usd)))
    max_extractable_usd = float(max_extractable_dec)
    gas_wei = fetch_gas_price_wei(router, c, block_pin) if block_pin > 0 else (2_000_000_000 if c == "ethereum" else 100_000_000)
    min_gas_dec = (Decimal(gas_wei * 21_000) / wei_18_dec) * max(_DEC_ZERO, _to_dec(native_price_min))
    min_gas_usd = float(min_gas_dec)
    total_onchain_dec_str = format(total_onchain_dec, "f")
    max_extractable_dec_str = format(max_extractable_dec, "f")
    min_gas_dec_str = format(min_gas_dec, "f")

    has_any_code = False
    has_dynamic_reachability = False
    has_view_selector_logic = False
    has_unresolved_delegation = False
    for r in resolutions.values():
        if r.unresolved_delegation:
            has_unresolved_delegation = True
        if r.proxy_kind == "eip7702":
            has_any_code = True
            has_dynamic_reachability = True
        for chx in _res_facet_codes_hex(r):
            eb = _hex_to_bytes(chx)
            if len(eb) > 0:
                has_any_code = True
                dis_eb = _disassemble(eb)
                if _has_dynamic_or_external_call_capability(dis_eb):
                    has_dynamic_reachability = True
                if any(nm == "RETURN" for _, nm, _ in dis_eb) and any(
                    nm == "PUSH4" and len(imm) == 4 and imm != b"\xff\xff\xff\xff" for _, nm, imm in dis_eb
                ):
                    has_view_selector_logic = True

    def _make_closure_result(
        early_safe: bool,
        early_reason: str,
        max_usd: float = max_extractable_usd,
        max_usd_dec_s: str = max_extractable_dec_str,
        dyn_reach: bool = False,
    ) -> TrustClosureResult:
        return TrustClosureResult(
            chain=c,
            block_pin=block_pin,
            seed_addresses=clean_seeds,
            all_addresses=all_addrs,
            resolutions=resolutions,
            vault_exposures=exposures,
            max_extractable_usd=max_usd,
            min_gas_usd=min_gas_usd,
            early_exit_safe=early_safe,
            early_exit_reason=early_reason,
            token_decimals=dec_map,
            token_prices_usd=price_map,
            has_dynamic_external_reachability=dyn_reach,
            approved_owners=active_approved_owners,
            max_extractable_usd_dec=max_usd_dec_s,
            min_gas_usd_dec=min_gas_dec_str,
            realizable_extractable_usd=realizable_extractable_usd,
            realizable_extractable_usd_dec=realizable_extractable_dec_str,
            verified_exit_pools=verified_exit_pools,
            has_unpriced_token_exposure=has_unpriced_token_exposure,
            rpc_balance_incomplete=rpc_balance_incomplete,
            closure_truncated=closure_truncated,
        )

    if (
        not has_any_code
        and not has_unresolved_delegation
        and total_onchain_dec < PROFIT_FLOOR_DEC
        and not has_unpriced_token_exposure
        and not rpc_balance_incomplete
    ):
        return _make_closure_result(
            True,
            "E1_ALL_TARGETS_EMPTY_CODE",
            max_usd=total_onchain_usd,
            max_usd_dec_s=total_onchain_dec_str,
        )

    v4_pool_mgr_set = {_norm_addr(m_a) for m_a in UNISWAP_V4_POOL_MANAGERS.get(c, ()) if _norm_addr(m_a)}
    has_v4_pool_mgr = bool(v4_pool_mgr_set and any(a in v4_pool_mgr_set for a in all_addrs))
    e1_below_nominal = (max_extractable_dec - min_gas_dec) < PROFIT_FLOOR_DEC
    e1_below_realizable = bool(
        all_tokens_dex_verified
        and not has_v4_pool_mgr
        and _to_dec(protocol_tvl_hint_usd) <= _DEC_ZERO
        and (realizable_upper_dec - min_gas_dec) < PROFIT_FLOOR_DEC
    )
    if (
        (e1_below_nominal or e1_below_realizable)
        and not has_dynamic_reachability
        and not has_unresolved_delegation
        and not has_unpriced_token_exposure
        and not rpc_balance_incomplete
        and not has_view_selector_logic
        and not closure_truncated
    ):
        e1_tag = (
            f"E1_PURE_STATIC_BELOW_MIN_USD({max_extractable_usd:.2f}<{MIN_PROFIT_USD})"
            if e1_below_nominal
            else f"E1_REALIZABLE_BELOW_MIN_USD({realizable_extractable_usd:.2f}<{MIN_PROFIT_USD})"
        )
        return _make_closure_result(True, e1_tag)

    return _make_closure_result(False, "", dyn_reach=has_dynamic_reachability)


# ═══════════════════════════════════════════════════════════════════════════
# §5. 개념 기반 바이트코드 CFG, E2(Value/State Sink), E3(Caller-Dominator),
#     4대 상태 채널 슬라이서 및 불연속 경계 솔버 (Discontinuity Solver)
# ═══════════════════════════════════════════════════════════════════════════

VALUE_SINK_SELECTORS: Set[str] = {
    "0xa9059cbb",  # transfer(address,uint256)
    "0x23b872dd",  # transferFrom(address,address,uint256)
    "0x095ea7b3",  # approve(address,uint256)
    "0x2e1a7d4d",  # withdraw(uint256)
    "0xb460af94",  # withdraw(uint256,address,address) - ERC4626
    "0xba087652",  # redeem(uint256,address,address) - ERC4626
    "0x852a12e3",  # redeem(uint256) - Compound
    "0xdb006a75",  # redeemUnderlying(uint256)
    "0xc5ebeaec",  # borrow(uint256)
    "0x40c10f19",  # mint(address,uint256)
    "0x6a627842",  # mint(address)
    "0x89afcb44",  # burn(address)
    "0x022c0d9f",  # swap(uint256,uint256,address,bytes) - UniV2
    "0x128acb08",  # swap(address,bool,int256,uint160,bytes) - UniV3
    "0xbc25cf77",  # skim(address)
    "0x490e6cbc",  # collect(...)
    "0xab9c4b5d",  # flashLoan(...)
    "0x5cffe9de",  # flashLoanSimple(...)
}


@dataclass
class ValueSinkScanResult:
    has_s1_native_call: bool = False
    has_s2_token_call: bool = False
    has_s3_delegatecall: bool = False
    has_s4_selfdestruct: bool = False
    has_s5_state_mutation: bool = False
    all_branches_revert: bool = False
    sink_pcs: List[int] = field(default_factory=list)
    sink_kinds: List[str] = field(default_factory=list)
    early_exit_safe: bool = False
    early_exit_reason: str = ""


def quick_scan_value_sinks(code: bytes, cancun_active: bool = True) -> ValueSinkScanResult:
    """
    E2 조기 종료: 1-패스 선형 스캔으로 물리적 Value/State Sink 존재 여부 및 전수 REVERT 판정.
    - S1(CALL), S2(Token/Vault CALL), S3(DELEGATECALL/CALLCODE), S4(SELFDESTRUCT - EIP-6780 이후에도 ETH 강제 전송 수행),
      S5(SSTORE/TSTORE/CREATE/CREATE2 - 영속·트랜지언트 상태 변조 및 컨트랙트 배포 포함).
    """
    if not code:
        return ValueSinkScanResult(
            all_branches_revert=True,
            early_exit_safe=False,
            early_exit_reason="E2_EMPTY_BYTECODE",
        )
    dis = _disassemble(code)
    if not dis:
        return ValueSinkScanResult(
            all_branches_revert=True,
            early_exit_safe=True,
            early_exit_reason="E2_EMPTY_DISASSEMBLY",
        )

    has_return_or_stop = any(nm in ("STOP", "RETURN", "SELFDESTRUCT") or nm.startswith("OP_") for _, nm, _ in dis)
    falloff_halts_normally = dis[-1][1] not in ("REVERT", "INVALID", "JUMP", "RETURN", "STOP", "SELFDESTRUCT")
    if not has_return_or_stop and not falloff_halts_normally:
        return ValueSinkScanResult(
            all_branches_revert=True,
            early_exit_safe=True,
            early_exit_reason="E2_ALL_BRANCHES_REVERT_OR_INVALID",
        )

    s1 = False
    s2 = False
    s3 = False
    s4 = False
    s5 = False
    sink_pcs: List[int] = []
    sink_kinds: Set[str] = set()

    pushed_sels: Set[str] = set()
    for _, nm, imm in dis:
        if nm == "PUSH4" and len(imm) == 4:
            pushed_sels.add("0x" + imm.hex())
        elif nm == "PUSH32" and len(imm) == 32 and imm[4:] == b"\x00" * 28:
            pushed_sels.add("0x" + imm[:4].hex())

    for idx, (pc, nm, _) in enumerate(dis):
        if nm == "CALL":
            window_back = dis[max(0, idx - 12) : idx]
            s1 = True
            sink_pcs.append(pc)
            sink_kinds.add("S1_NATIVE_OR_EXTERNAL_CALL")
            if pushed_sels & VALUE_SINK_SELECTORS or any(w[1] in ("MSTORE", "CALLDATACOPY", "MCOPY") for w in window_back):
                s2 = True
                sink_kinds.add("S2_TOKEN_OR_VAULT_CALL")
        elif nm in ("DELEGATECALL", "CALLCODE"):
            s3 = True
            sink_pcs.append(pc)
            sink_kinds.add("S3_DELEGATECALL")
        elif nm == "SELFDESTRUCT":
            s4 = True
            sink_pcs.append(pc)
            sink_kinds.add("S4_SELFDESTRUCT")
        elif nm in ("SSTORE", "TSTORE", "CREATE", "CREATE2"):
            s5 = True
            sink_pcs.append(pc)
            sink_kinds.add("S5_STATE_OR_CREATE_SINK")

    if not (s1 or s2 or s3 or s4 or s5):
        if any(nm.startswith("OP_") or nm in ("STATICCALL", "JUMP", "JUMPI") for _, nm, _ in dis):
            cfg_unmod = disassemble_and_build_cfg(code)
            root_reach: Set[int] = set()
            if 0 in cfg_unmod.blocks:
                q_r = [0]
                while q_r:
                    cur_pc = q_r.pop()
                    if cur_pc in root_reach or cur_pc not in cfg_unmod.blocks:
                        continue
                    root_reach.add(cur_pc)
                    for s_pc in cfg_unmod.blocks[cur_pc].succs:
                        if s_pc not in root_reach:
                            q_r.append(s_pc)
            has_reach_unmod = any(
                ep.reaches_unresolved_jump
                or any(
                    cfg_unmod.blocks[b_pc].has_unmodeled_op or cfg_unmod.blocks[b_pc].has_dynamic_staticcall
                    for b_pc in ep.reachable_blocks
                    if b_pc in cfg_unmod.blocks
                )
                for ep in cfg_unmod.entries.values()
            ) or any(
                cfg_unmod.blocks[b_pc].has_unresolved_jump
                or cfg_unmod.blocks[b_pc].has_unmodeled_op
                or cfg_unmod.blocks[b_pc].has_dynamic_staticcall
                for b_pc in root_reach
            )
            if has_reach_unmod:
                return ValueSinkScanResult(
                    has_s1_native_call=False,
                    has_s2_token_call=False,
                    has_s3_delegatecall=False,
                    has_s4_selfdestruct=False,
                    has_s5_state_mutation=True,
                    all_branches_revert=False,
                    sink_pcs=[
                        pc
                        for pc, nm, _ in dis
                        if nm.startswith("OP_") or nm in ("STATICCALL", "JUMP", "JUMPI")
                    ],
                    sink_kinds=["S5_REACHABLE_UNMODELED_OR_DYNAMIC_TARGET"],
                    early_exit_safe=False,
                    early_exit_reason="",
                )
        return ValueSinkScanResult(
            has_s1_native_call=False,
            has_s2_token_call=False,
            has_s3_delegatecall=False,
            has_s4_selfdestruct=False,
            has_s5_state_mutation=False,
            all_branches_revert=False,
            sink_pcs=[],
            sink_kinds=[],
            early_exit_safe=True,
            early_exit_reason="E2_ZERO_PHYSICAL_VALUE_SINKS",
        )

    return ValueSinkScanResult(
        has_s1_native_call=s1,
        has_s2_token_call=s2,
        has_s3_delegatecall=s3,
        has_s4_selfdestruct=s4,
        has_s5_state_mutation=s5,
        all_branches_revert=False,
        sink_pcs=sink_pcs,
        sink_kinds=sorted(sink_kinds),
        early_exit_safe=False,
        early_exit_reason="",
    )


@dataclass
class BasicBlock:
    start_pc: int
    end_pc: int
    insns: List[Tuple[int, str, bytes]] = field(default_factory=list)
    succs: List[int] = field(default_factory=list)
    preds: List[int] = field(default_factory=list)
    has_caller_eq: bool = False
    caller_gate_const: str = ""
    caller_gate_slot: Optional[int] = None
    caller_gate_shift: int = 0
    authorized_succ_pc: Optional[int] = None
    unauthorized_succ_pc: Optional[int] = None
    has_sstore: bool = False
    has_arbitrary_sstore: bool = False
    has_keccak_sstore: bool = False
    sstore_slots: List[int] = field(default_factory=list)
    has_sload: bool = False
    sload_slots: List[int] = field(default_factory=list)
    has_tstore: bool = False
    has_tload: bool = False
    has_value_sink: bool = False
    has_external_call: bool = False
    has_call_before_sstore: bool = False
    has_unresolved_jump: bool = False
    has_unmodeled_op: bool = False
    has_dynamic_staticcall: bool = False
    pushed_jumpdests: List[int] = field(default_factory=list)
    has_revert: bool = False
    has_return: bool = False


@dataclass
class EntryPointCFG:
    selector: str
    entry_pc: int
    reachable_blocks: Set[int] = field(default_factory=set)
    reaches_value_sink: bool = False
    reaches_sstore: bool = False
    reaches_arbitrary_sstore: bool = False
    reaches_keccak_sstore: bool = False
    reaches_unresolved_jump: bool = False
    reaches_dynamic_staticcall: bool = False
    written_slots: Set[int] = field(default_factory=set)
    read_slots: Set[int] = field(default_factory=set)
    caller_dominated: bool = False
    dominator_guard_addr: str = ""
    dominator_guard_slot: Optional[int] = None
    dominator_guard_shift: int = 0


@dataclass
class CFGModel:
    blocks: Dict[int, BasicBlock]
    entries: Dict[str, EntryPointCFG]
    disassembly: List[Tuple[int, str, bytes]]


_TERMINATORS = {"STOP", "RETURN", "REVERT", "INVALID", "SELFDESTRUCT", "JUMP", "JUMPI"}
_ADDR_MASK_160 = (1 << 160) - 1
_DEGENERATE_CALLER_ADDRS: FrozenSet[str] = frozenset({
    "0x0000000000000000000000000000000000000000",
    "0x000000000000000000000000000000000000cafe",
    "0x000000000000000000000000000000000000beef",
    "0x000000000000000000000000000000000000dead",
    "0x1000000000000000000000000000000000013370",
    "0x2000000000000000000000000000000000023370",
    "0x3000000000000000000000000000000000033370",
    "0x1804c8ab1f12e6bbf3894d4083f33e07309d1f38",
    "0x000000000000000000636f6e736f6c652e6c6f67",
    HEVM_ADDRESS_LOWER,
})
_PUBLIC_PERMISSIONLESS_CALLERS: FrozenSet[str] = frozenset({
    MULTICALL3_ADDR.lower(),
    "0x5ff137d4b0fdcd49dca30c7cf57e578a026d2789",
    "0x0000000071727de22e5e9d8baf0edac6f37da032",
    "0x4337084d9e255ff0702461cf8895ce9e3b5ff108",
    "0x000000000022d473030f116ddee9f6b43ac78ba3",
    "0x4e59b44847b379578588920ca78fbf26c0b4956c",
    "0xba5ed099633d3b313e4d5f7bdc1305d3c28ba5ed",
    "0x914d7fec6aac8cd542e72bca78b30650d45643d7",
    "0xa6b71e26c5e0845f74c812102ca7114b6a896ab2",
    "0x4e1dcf7ad4e460cfd30791ccc4f9c8a4f820ec67",
    "0x0000000000ffe8b47b3e2130213b802212439497",
    "0x3fab184622dc19b6109349b94811493bf2a45362",
})
_MNEMONIC_STACK_DELTA: Dict[str, Tuple[int, int]] = {
    nm: (pop_c, push_c) for _, (nm, pop_c, push_c, _) in OPCODE_SPEC.items()
}


def _const_sym_int(sym: str) -> Optional[int]:
    if sym.startswith("CONST20:"):
        try:
            return int(sym[8:])
        except ValueError:
            return None
    if sym.startswith("CONST:"):
        try:
            return int(sym[6:])
        except ValueError:
            return None
    return None


def _parse_caller_cond_sym(cond_sym: str) -> Optional[Tuple[str, str, Optional[int], int]]:
    """`CMP_EQ_CALLER|CONST|0x...` 또는 `CMP_NE_CALLER|SLOT|0|0` 스택 심볼에서 가드 메타데이터를 무손실 복원."""
    parts = cond_sym.split("|")
    if len(parts) < 3 or parts[0] not in ("CMP_EQ_CALLER", "CMP_NE_CALLER"):
        return None
    kind = parts[0]
    if parts[1] == "CONST" and len(parts) >= 3:
        return (kind, parts[2], None, 0)
    if parts[1] == "SLOT" and len(parts) >= 4:
        try:
            return (kind, "", int(parts[2]), int(parts[3]))
        except ValueError:
            return None
    return None


def _branch_unconditionally_reverts(blocks: Dict[int, BasicBlock], start_pc: Optional[int], max_steps: int = 16) -> bool:
    """주어진 분기 시작 블록으로부터 도달 가능한 모든 경로가 Sink/SSTORE/TSTORE/RETURN/UnresolvedJump 없이 REVERT/INVALID로 종료되는지 판정."""
    if start_pc is None or start_pc not in blocks:
        return False
    visited: Set[int] = set()
    queue: deque[int] = deque([start_pc])
    saw_terminal_revert = False
    while queue and len(visited) < max_steps:
        cur = queue.popleft()
        if cur in visited or cur not in blocks:
            continue
        visited.add(cur)
        bb = blocks[cur]
        if bb.has_value_sink or bb.has_sstore or bb.has_tstore or bb.has_return or bb.has_unresolved_jump:
            return False
        if bb.has_revert and not bb.succs:
            saw_terminal_revert = True
            continue
        if not bb.succs:
            return False
        for sc in bb.succs:
            if sc not in visited:
                queue.append(sc)
    return saw_terminal_revert and len(queue) == 0


def disassemble_and_build_cfg(code: bytes) -> CFGModel:
    """
    바이트코드로부터 BasicBlock CFG, 전 오피코드 정밀 심볼릭 스택 추적(PUSH0..PUSH32, DUP1..16/DUPN, SWAP1..16/SWAPN, EXCHANGE,
    SLOAD, SHR/DIV 패킹 슬롯, 160비트 완전 마스크 검증형 CALLER, 심볼 내장형 EQ/ISZERO, TSTORE/TLOAD),
    서브루틴 반환 JUMPDEST 연결, PUSH1..PUSH4 다중 블록 디스패처 및 분기 감응형 Caller-Dominator를 구축한다.
    """
    dis = _disassemble(code)
    if not dis:
        return CFGModel(blocks={}, entries={}, disassembly=[])

    boundaries: Set[int] = {dis[0][0]}
    pc_to_idx: Dict[int, int] = {pc: i for i, (pc, _, _) in enumerate(dis)}
    jumpdests: Set[int] = {pc for pc, nm, _ in dis if nm == "JUMPDEST"}
    boundaries |= jumpdests

    for i, (pc, nm, _) in enumerate(dis):
        if nm in _TERMINATORS and i + 1 < len(dis):
            boundaries.add(dis[i + 1][0])

    sorted_starts = sorted(boundaries)
    blocks: Dict[int, BasicBlock] = {}
    raw_caller_cond: Dict[int, Tuple[str, str, Optional[int], int, Optional[int], Optional[int]]] = {}
    block_jump_targets: Dict[int, Optional[int]] = {}
    block_fallthrough_pcs: Dict[int, Optional[int]] = {}
    block_jump_dst_sym: Dict[int, str] = {}

    for b_idx, start_pc in enumerate(sorted_starts):
        next_start = sorted_starts[b_idx + 1] if b_idx + 1 < len(sorted_starts) else (dis[-1][0] + 1)
        s_i = pc_to_idx[start_pc]
        b_insns: List[Tuple[int, str, bytes]] = []
        j = s_i
        while j < len(dis) and dis[j][0] < next_start:
            b_insns.append(dis[j])
            j += 1
        if not b_insns:
            continue
        bb = BasicBlock(start_pc=start_pc, end_pc=b_insns[-1][0], insns=b_insns)

        sym_stack: List[str] = []
        last_cond_sym: str = ""
        jump_target_pc: Optional[int] = None
        fallthrough_pc: Optional[int] = sorted_starts[b_idx + 1] if b_idx + 1 < len(sorted_starts) else None
        block_fallthrough_pcs[start_pc] = fallthrough_pc
        saw_call_in_block = False

        for _, op_nm, imm in b_insns:
            if op_nm == "PUSH0":
                sym_stack.append("CONST:0")
            elif op_nm.startswith("PUSH"):
                val = int.from_bytes(imm, "big") if imm else 0
                sym_stack.append(f"CONST20:{val}" if op_nm == "PUSH20" else f"CONST:{val}")
            elif op_nm == "CALLER":
                sym_stack.append("CALLER")
            elif op_nm == "ORIGIN":
                sym_stack.append("ORIGIN")
            elif op_nm == "ADDRESS":
                sym_stack.append("ADDRESS")
            elif op_nm == "DUPN" or op_nm.startswith("DUP"):
                d_n = (((imm[0] + 145) % 256) if imm else 1) if op_nm == "DUPN" else (int(op_nm[3:]) if op_nm[3:].isdigit() else 1)
                sym_stack.append(sym_stack[-d_n] if len(sym_stack) >= d_n else "UNK")
            elif op_nm == "SWAPN" or op_nm.startswith("SWAP"):
                s_n = (((imm[0] + 145) % 256) if imm else 1) if op_nm == "SWAPN" else (int(op_nm[4:]) if op_nm[4:].isdigit() else 1)
                if len(sym_stack) >= s_n + 1:
                    sym_stack[-1], sym_stack[-(s_n + 1)] = sym_stack[-(s_n + 1)], sym_stack[-1]
                elif sym_stack:
                    sym_stack[-1] = "UNK"
            elif op_nm == "EXCHANGE":
                if imm:
                    k_ex = imm[0] ^ 143
                    q_ex, r_ex = divmod(k_ex, 16)
                    n_idx, m_idx = (q_ex + 1, r_ex + 1) if q_ex < r_ex else (r_ex + 1, 29 - q_ex)
                    if len(sym_stack) >= m_idx + 1:
                        sym_stack[-(n_idx + 1)], sym_stack[-(m_idx + 1)] = sym_stack[-(m_idx + 1)], sym_stack[-(n_idx + 1)]
                    elif len(sym_stack) >= n_idx + 1:
                        sym_stack[-(n_idx + 1)] = "UNK"
            elif op_nm == "POP":
                if sym_stack:
                    sym_stack.pop()
            elif op_nm in ("KECCAK256", "SHA3"):
                for _ in range(min(len(sym_stack), 2)):
                    sym_stack.pop()
                sym_stack.append("KECCAK")
            elif op_nm == "SHL":
                sh_s = sym_stack.pop() if sym_stack else "UNK"
                val_s = sym_stack.pop() if sym_stack else "UNK"
                if _const_sym_int(sh_s) == 96 and (
                    val_s in ("CALLER", "ADDRESS") or val_s.startswith(("SLOAD:", "SLOAD_PACKED:", "CONST:", "CONST20:"))
                ):
                    sym_stack.append(f"SHL96:{val_s}")
                else:
                    sym_stack.append("ARITH")
            elif op_nm in ("SHR", "DIV"):
                top1 = sym_stack.pop() if sym_stack else "UNK"
                top2 = sym_stack.pop() if sym_stack else "UNK"
                c1 = _const_sym_int(top1)
                c2 = _const_sym_int(top2)
                if op_nm == "SHR" and c1 == 96 and top2.startswith("SHL96:"):
                    inner = top2[6:]
                    c_in = _const_sym_int(inner)
                    if inner in ("CALLER", "ADDRESS"):
                        sym_stack.append(inner)
                    elif inner.startswith("SLOAD:"):
                        s_id = int(inner.split(":")[1])
                        sym_stack.append(f"SLOAD_PACKED:{s_id}:0")
                    elif inner.startswith("SLOAD_PACKED:"):
                        sym_stack.append(inner)
                    elif c_in is not None:
                        sym_stack.append(f"CONST20:{c_in & _ADDR_MASK_160}")
                    else:
                        sym_stack.append("ARITH")
                elif op_nm == "SHR" and top2.startswith("SLOAD:") and c1 is not None and (c1 % 8) == 0 and c1 <= 96:
                    s_id = int(top2.split(":")[1])
                    sym_stack.append(f"SLOAD_PACKED:{s_id}:{c1 // 8}")
                elif (
                    op_nm == "DIV"
                    and top1.startswith("SLOAD:")
                    and c2 is not None
                    and c2 > 0
                    and (c2 & (c2 - 1)) == 0
                    and ((c2.bit_length() - 1) % 8) == 0
                    and (c2.bit_length() - 1) <= 96
                ):
                    s_id = int(top1.split(":")[1])
                    sym_stack.append(f"SLOAD_PACKED:{s_id}:{(c2.bit_length() - 1) // 8}")
                else:
                    sym_stack.append("ARITH")
            elif op_nm == "AND":
                a = sym_stack.pop() if sym_stack else "UNK"
                b = sym_stack.pop() if sym_stack else "UNK"
                ca = _const_sym_int(a)
                cb = _const_sym_int(b)
                if ca in (_ADDR_MASK_160, _UINT256_MAX):
                    if cb is not None:
                        sym_stack.append(f"CONST20:{cb & _ADDR_MASK_160}" if ca == _ADDR_MASK_160 else f"CONST:{cb}")
                    else:
                        sym_stack.append(b)
                elif cb in (_ADDR_MASK_160, _UINT256_MAX):
                    if ca is not None:
                        sym_stack.append(f"CONST20:{ca & _ADDR_MASK_160}" if cb == _ADDR_MASK_160 else f"CONST:{ca}")
                    else:
                        sym_stack.append(a)
                elif ca is not None and cb is not None:
                    sym_stack.append(f"CONST:{ca & cb}")
                else:
                    # 160비트 미만 부분 비트마스크(예: 0xff) 또는 동적 마스크는 CALLER 신원 증명을 훼손하므로 격하
                    sym_stack.append("MASKED_UNK")
            elif op_nm == "SLOAD":
                bb.has_sload = True
                sl = sym_stack.pop() if sym_stack else "UNK"
                c_sl = _const_sym_int(sl)
                if c_sl is not None:
                    bb.sload_slots.append(c_sl)
                    sym_stack.append(f"SLOAD:{c_sl}")
                else:
                    sym_stack.append("SLOAD_DYN")
            elif op_nm == "SSTORE":
                bb.has_sstore = True
                if saw_call_in_block:
                    bb.has_call_before_sstore = True
                sl = sym_stack.pop() if sym_stack else "UNK"
                _val = sym_stack.pop() if sym_stack else "UNK"
                c_sl = _const_sym_int(sl)
                if c_sl is not None:
                    bb.sstore_slots.append(c_sl)
                elif sl.startswith("KECCAK"):
                    bb.has_keccak_sstore = True
                else:
                    bb.has_arbitrary_sstore = True
            elif op_nm in ("EQ", "SUB", "XOR"):
                a = sym_stack.pop() if sym_stack else "UNK"
                b = sym_stack.pop() if sym_stack else "UNK"
                if a == "CALLER" or b == "CALLER":
                    other = b if a == "CALLER" else a
                    guard_suffix = ""
                    if other.startswith("CONST20:"):
                        c_val = int(other[8:])
                        if 0 <= c_val <= _ADDR_MASK_160:
                            guard_suffix = f"CONST|0x{c_val:040x}"
                    elif other.startswith("CONST:"):
                        c_val = int(other[6:])
                        if c_val == 0 or (0x1000 < c_val <= _ADDR_MASK_160 and c_val != 10**18):
                            guard_suffix = f"CONST|0x{c_val:040x}"
                    elif other.startswith("SLOAD_PACKED:"):
                        parts = other.split(":")
                        g_sl = int(parts[1])
                        g_sh = int(parts[2]) if len(parts) > 2 else 0
                        guard_suffix = f"SLOT|{g_sl}|{g_sh}"
                    elif other.startswith("SLOAD:"):
                        g_sl = int(other[6:])
                        guard_suffix = f"SLOT|{g_sl}|0"
                    elif other.startswith("TLOAD:"):
                        g_tsl = int(other[6:]) | (1 << 240)
                        guard_suffix = f"SLOT|{g_tsl}|0"
                    if guard_suffix:
                        prefix = "CMP_EQ_CALLER" if op_nm == "EQ" else "CMP_NE_CALLER"
                        sym_stack.append(f"{prefix}|{guard_suffix}")
                    else:
                        sym_stack.append("CMP_OTHER")
                else:
                    sym_stack.append("CMP_OTHER")
            elif op_nm == "ISZERO":
                x = sym_stack.pop() if sym_stack else "UNK"
                if x.startswith("CMP_EQ_CALLER|"):
                    sym_stack.append("CMP_NE_CALLER|" + x[len("CMP_EQ_CALLER|"):])
                elif x.startswith("CMP_NE_CALLER|"):
                    sym_stack.append("CMP_EQ_CALLER|" + x[len("CMP_NE_CALLER|"):])
                else:
                    sym_stack.append("ISZERO_OTHER")
            elif op_nm == "TSTORE":
                bb.has_tstore = True
                tsl = sym_stack.pop() if sym_stack else "UNK"
                _tval = sym_stack.pop() if sym_stack else "UNK"
                c_tsl = _const_sym_int(tsl)
                if c_tsl is not None:
                    bb.sstore_slots.append(c_tsl | (1 << 240))
                else:
                    bb.has_arbitrary_sstore = True
            elif op_nm == "TLOAD":
                bb.has_tload = True
                tsl = sym_stack.pop() if sym_stack else "UNK"
                c_tsl = _const_sym_int(tsl)
                if c_tsl is not None:
                    bb.sload_slots.append(c_tsl | (1 << 240))
                    sym_stack.append(f"TLOAD:{c_tsl}")
                else:
                    sym_stack.append("TLOAD_VAL")
            elif op_nm in ("CALL", "DELEGATECALL", "CALLCODE"):
                bb.has_value_sink = True
                bb.has_external_call = True
                if op_nm in ("DELEGATECALL", "CALLCODE"):
                    bb.has_sstore = True
                    bb.has_arbitrary_sstore = True
                saw_call_in_block = True
                for _ in range(min(len(sym_stack), 7 if op_nm != "DELEGATECALL" else 6)):
                    sym_stack.pop()
                sym_stack.append("CALL_RET")
            elif op_nm in ("CREATE", "CREATE2"):
                bb.has_value_sink = True
                bb.has_external_call = True
                saw_call_in_block = True
                for _ in range(min(len(sym_stack), 4 if op_nm == "CREATE2" else 3)):
                    sym_stack.pop()
                sym_stack.append("CREATE_RET")
            elif op_nm == "SELFDESTRUCT":
                bb.has_value_sink = True
                if sym_stack:
                    sym_stack.pop()
            elif op_nm == "STATICCALL":
                _sc_gas = sym_stack.pop() if sym_stack else "UNK"
                sc_addr = sym_stack.pop() if sym_stack else "UNK"
                c_sc = _const_sym_int(sc_addr)
                if sc_addr != "ADDRESS" and not (c_sc is not None and 1 <= c_sc <= 9):
                    bb.has_dynamic_staticcall = True
                for _ in range(min(len(sym_stack), 4)):
                    sym_stack.pop()
                sym_stack.append("STATICCALL_RET")
            elif op_nm in ("REVERT", "INVALID"):
                bb.has_revert = True
                for _ in range(min(len(sym_stack), 2 if op_nm == "REVERT" else 0)):
                    sym_stack.pop()
            elif op_nm in ("RETURN", "STOP"):
                bb.has_return = True
                for _ in range(min(len(sym_stack), 2 if op_nm == "RETURN" else 0)):
                    sym_stack.pop()
            elif op_nm == "JUMP":
                dst = sym_stack.pop() if sym_stack else "ENTRY_RET"
                for stk_s in sym_stack:
                    s_val = _const_sym_int(stk_s)
                    if s_val is not None and s_val in jumpdests and s_val not in bb.pushed_jumpdests:
                        bb.pushed_jumpdests.append(s_val)
                block_jump_dst_sym[start_pc] = dst
                t_pc = _const_sym_int(dst)
                if t_pc is not None:
                    if t_pc in jumpdests:
                        jump_target_pc = t_pc
                    else:
                        bb.has_unresolved_jump = True
                elif dst != "ENTRY_RET":
                    bb.has_unresolved_jump = True
            elif op_nm == "JUMPI":
                dst = sym_stack.pop() if sym_stack else "ENTRY_RET"
                cond = sym_stack.pop() if sym_stack else "UNK"
                last_cond_sym = cond
                t_pc = _const_sym_int(dst)
                if t_pc is not None and t_pc in jumpdests:
                    jump_target_pc = t_pc
                else:
                    bb.has_unresolved_jump = True
            elif op_nm.startswith("OP_"):
                bb.has_unmodeled_op = True
                bb.has_unresolved_jump = True
                sym_stack = ["UNK"] * len(sym_stack)
            else:
                pop_c, push_c = _MNEMONIC_STACK_DELTA.get(op_nm, (0, 0))
                for _ in range(min(len(sym_stack), pop_c)):
                    sym_stack.pop()
                for _ in range(push_c):
                    sym_stack.append("UNK")

        block_jump_targets[start_pc] = jump_target_pc
        last_nm = b_insns[-1][1]
        if last_nm == "JUMP":
            if jump_target_pc is not None:
                bb.succs.append(jump_target_pc)
        elif last_nm == "JUMPI":
            if jump_target_pc is not None:
                bb.succs.append(jump_target_pc)
            if fallthrough_pc is not None and fallthrough_pc not in bb.succs:
                bb.succs.append(fallthrough_pc)
            parsed_cond = _parse_caller_cond_sym(last_cond_sym)
            if parsed_cond is not None:
                c_kind, g_const, g_slot, g_shift = parsed_cond
                raw_caller_cond[start_pc] = (c_kind, g_const, g_slot, g_shift, jump_target_pc, fallthrough_pc)
        elif last_nm not in _TERMINATORS:
            if fallthrough_pc is not None:
                bb.succs.append(fallthrough_pc)

        blocks[start_pc] = bb

    # 서브루틴 호출 블록의 반환 JUMPDEST를 서브루틴 종료 블록(ENTRY_RET JUMP)의 후속 엣지로 전파
    subcall_edges: Set[Tuple[int, int]] = set()
    for caller_pc, caller_bb in blocks.items():
        j_tgt = block_jump_targets.get(caller_pc)
        if j_tgt is None or j_tgt not in blocks:
            continue
        ret_jds = [p_jd for p_jd in caller_bb.pushed_jumpdests if p_jd != j_tgt and p_jd in blocks]
        if not ret_jds:
            continue
        subcall_edges.add((caller_pc, j_tgt))
        for r_mid in ret_jds[1:]:
            mid_tgt = block_jump_targets.get(r_mid)
            if mid_tgt is not None and mid_tgt in blocks:
                subcall_edges.add((r_mid, mid_tgt))
        outer_ret = ret_jds[0]
        sub_vis: Set[int] = set()
        sub_q: deque[int] = deque([j_tgt])
        while sub_q and len(sub_vis) < 256:
            s_cur = sub_q.popleft()
            if s_cur in sub_vis or s_cur not in blocks:
                continue
            sub_vis.add(s_cur)
            s_bb = blocks[s_cur]
            if s_bb.insns and s_bb.insns[-1][1] == "JUMP" and block_jump_dst_sym.get(s_cur) == "ENTRY_RET":
                for r_jd in ret_jds:
                    if r_jd not in s_bb.succs:
                        s_bb.succs.append(r_jd)
            for s_nxt in s_bb.succs:
                if s_nxt not in sub_vis and s_nxt != outer_ret:
                    sub_q.append(s_nxt)
        if sub_q:
            caller_bb.has_unresolved_jump = True

    # 타깃이 해결되지 않은 모든 JUMP 블록(succs == [])을 Fail-Open으로 UnresolvedJump 처리
    for bb in blocks.values():
        if bb.insns and bb.insns[-1][1] == "JUMP" and not bb.succs:
            bb.has_unresolved_jump = True

    for start_pc, bb in blocks.items():
        for sc in bb.succs:
            if sc in blocks and start_pc not in blocks[sc].preds:
                blocks[sc].preds.append(start_pc)

    for b_pc, (cond_kind, g_const, g_slot, g_shift, j_pc, f_pc) in raw_caller_cond.items():
        bb = blocks[b_pc]
        if cond_kind == "CMP_EQ_CALLER":
            auth_pc, unauth_pc = j_pc, f_pc
        else:
            auth_pc, unauth_pc = f_pc, j_pc
        if auth_pc is not None and unauth_pc is not None and auth_pc != unauth_pc:
            if _branch_unconditionally_reverts(blocks, unauth_pc):
                bb.has_caller_eq = True
                bb.caller_gate_const = g_const
                bb.caller_gate_slot = g_slot
                bb.caller_gate_shift = g_shift
                bb.authorized_succ_pc = auth_pc
                bb.unauthorized_succ_pc = unauth_pc

    has_dispatcher_shift = any(
        nm in ("SHR", "DIV") and idx > 0 and dis[idx - 1][1].startswith("PUSH") and int.from_bytes(dis[idx - 1][2] or b"\x00", "big") in (0xE0, 1 << 224)
        for idx, (_, nm, _) in enumerate(dis)
    )
    entries: Dict[str, EntryPointCFG] = {}
    for start_pc, bb in blocks.items():
        b_insns = bb.insns
        if b_insns[-1][1] != "JUMPI":
            continue
        jt_pc = block_jump_targets.get(start_pc)
        ft_pc = block_fallthrough_pcs.get(start_pc)
        for k, (_, nm, imm) in enumerate(b_insns[:-1]):
            sel = ""
            if nm == "PUSH4" and len(imm) == 4:
                sel = "0x" + imm.hex()
            elif has_dispatcher_shift and nm in ("PUSH1", "PUSH2", "PUSH3") and 1 <= len(imm) <= 3:
                if any(w[1] in ("EQ", "SUB", "XOR") for w in b_insns[k + 1 : min(len(b_insns) - 1, k + 4)]):
                    sel = "0x" + imm.rjust(4, b"\x00").hex()
            if not sel or sel in ("0x00000000", "0xffffffff") or sel in entries:
                continue
            window = b_insns[k + 1 : min(len(b_insns), k + 8)]
            cmp_rel_idx = next((idx_w for idx_w, w in enumerate(window) if w[1] in ("EQ", "SUB", "XOR")), -1)
            if cmp_rel_idx < 0:
                continue
            pre_delta = sum(
                _MNEMONIC_STACK_DELTA.get(w[1], (0, 0))[1] - _MNEMONIC_STACK_DELTA.get(w[1], (0, 0))[0]
                for w in window[:cmp_rel_idx]
            )
            if pre_delta not in (0, 1):
                continue
            post_cmp_ops = [w[1] for w in b_insns[k + 2 + cmp_rel_idx : -1]]
            if not all(op_w == "ISZERO" or op_w.startswith(("PUSH", "DUP", "SWAP")) for op_w in post_cmp_ops):
                continue
            cmp_op = window[cmp_rel_idx][1]
            iszero_cnt = sum(1 for w in b_insns[k + 1 + cmp_rel_idx : -1] if w[1] == "ISZERO")
            jumps_on_match = (iszero_cnt % 2 == 0) if cmp_op == "EQ" else (iszero_cnt % 2 == 1)
            if jumps_on_match:
                tgt: Optional[int] = jt_pc if (jt_pc is not None and jt_pc in blocks) else None
                if tgt is None:
                    for w_idx in range(len(b_insns) - 2, k, -1):
                        if b_insns[w_idx][1].startswith("PUSH"):
                            cand_t = int.from_bytes(b_insns[w_idx][2], "big")
                            if cand_t in blocks:
                                tgt = cand_t
                                break
            else:
                tgt = ft_pc if (ft_pc is not None and ft_pc in blocks) else None
            if tgt is not None:
                entries[sel] = EntryPointCFG(selector=sel, entry_pc=tgt)

    if 0 in blocks:
        selector_entry_pcs = {ep.entry_pc for ep in entries.values()}
        fb_vis: Set[int] = set()
        fb_q: deque[int] = deque([0])
        fb_reaches_action = False
        while fb_q:
            cur = fb_q.popleft()
            if cur in fb_vis or cur not in blocks:
                continue
            if cur in selector_entry_pcs and cur != 0:
                continue
            fb_vis.add(cur)
            cbb0 = blocks[cur]
            if (
                cbb0.has_value_sink
                or cbb0.has_sstore
                or cbb0.has_tstore
                or cbb0.has_unresolved_jump
                or cbb0.has_unmodeled_op
                or cbb0.has_dynamic_staticcall
            ):
                fb_reaches_action = True
            for sc in cbb0.succs:
                if sc not in fb_vis and sc not in selector_entry_pcs:
                    fb_q.append(sc)
        if fb_reaches_action or not entries:
            entries["fallback"] = EntryPointCFG(selector="fallback", entry_pc=0)

    selector_entry_pcs = {ep.entry_pc for sel, ep in entries.items() if sel != "fallback"}
    for sel, ep in entries.items():
        visited: Set[int] = set()
        queue: deque[int] = deque([ep.entry_pc])
        while queue:
            cur = queue.popleft()
            if cur in visited or cur not in blocks:
                continue
            if sel == "fallback" and cur in selector_entry_pcs and cur != 0:
                continue
            visited.add(cur)
            cbb = blocks[cur]
            if cbb.has_value_sink:
                ep.reaches_value_sink = True
            if cbb.has_sstore or cbb.has_tstore:
                ep.reaches_sstore = True
                ep.written_slots.update(cbb.sstore_slots)
            if cbb.has_arbitrary_sstore:
                ep.reaches_arbitrary_sstore = True
            if cbb.has_keccak_sstore:
                ep.reaches_keccak_sstore = True
            if cbb.has_sload or cbb.has_tload:
                ep.read_slots.update(cbb.sload_slots)
            if cbb.has_unresolved_jump:
                ep.reaches_unresolved_jump = True
            if cbb.has_dynamic_staticcall:
                ep.reaches_dynamic_staticcall = True
            for sc in cbb.succs:
                if sc not in visited:
                    queue.append(sc)
        ep.reachable_blocks = visited

        # 서브루틴 호출(ret_jds 푸시) 없이 직접 도달하는 ENTRY_RET JUMP 블록은 해당 진입점에서 미해결 동적 점프로 취급
        vis_no_subcall: Set[int] = set()
        q_ns: deque[int] = deque([ep.entry_pc])
        while q_ns:
            c_ns = q_ns.popleft()
            if c_ns in vis_no_subcall or c_ns not in blocks:
                continue
            if sel == "fallback" and c_ns in selector_entry_pcs and c_ns != 0:
                continue
            vis_no_subcall.add(c_ns)
            for sc_ns in blocks[c_ns].succs:
                if (c_ns, sc_ns) in subcall_edges:
                    continue
                if sc_ns not in vis_no_subcall:
                    q_ns.append(sc_ns)
        unmatched_entry_ret_blocks = {
            b_pc
            for b_pc in vis_no_subcall
            if blocks[b_pc].insns and blocks[b_pc].insns[-1][1] == "JUMP" and block_jump_dst_sym.get(b_pc) == "ENTRY_RET"
        }
        if unmatched_entry_ret_blocks:
            ep.reaches_unresolved_jump = True

        # 합집합(`|`) 강제: SSTORE/Sink/동적STATICCALL 블록과 동적 미해결 점프(UnresolvedJump) 블록 모두 지배되어야만 닫힘 인정!
        sink_or_write_blocks = {
            b_pc
            for b_pc in visited
            if (
                blocks[b_pc].has_value_sink
                or blocks[b_pc].has_sstore
                or blocks[b_pc].has_tstore
                or blocks[b_pc].has_unresolved_jump
                or blocks[b_pc].has_dynamic_staticcall
            )
        } | unmatched_entry_ret_blocks
        pure_guards = [
            b_pc
            for b_pc in sorted(visited)
            if blocks[b_pc].has_caller_eq and b_pc not in sink_or_write_blocks and blocks[b_pc].authorized_succ_pc is not None
        ]
        if sink_or_write_blocks and pure_guards:
            for g_pc in pure_guards:
                g_bb = blocks[g_pc]
                blocked_edge = (g_pc, g_bb.authorized_succ_pc)
                vis_no_auth: Set[int] = set()
                q2: deque[int] = deque([ep.entry_pc])
                while q2:
                    c2 = q2.popleft()
                    if c2 in vis_no_auth or c2 not in blocks:
                        continue
                    if sel == "fallback" and c2 in selector_entry_pcs and c2 != 0:
                        continue
                    vis_no_auth.add(c2)
                    for sc in blocks[c2].succs:
                        if (c2, sc) == blocked_edge:
                            continue
                        if sc not in vis_no_auth:
                            q2.append(sc)
                if not (vis_no_auth & sink_or_write_blocks):
                    ep.caller_dominated = True
                    ep.dominator_guard_addr = g_bb.caller_gate_const
                    ep.dominator_guard_slot = g_bb.caller_gate_slot
                    ep.dominator_guard_shift = g_bb.caller_gate_shift
                    break

    return CFGModel(blocks=blocks, entries=entries, disassembly=dis)


@dataclass
class CallerDominatorProof:
    all_closed: bool
    open_selectors: List[str]
    closed_selectors: List[str]
    early_exit_safe: bool
    early_exit_reason: str


def prove_caller_dominator_closed(
    cfg: CFGModel,
    router: Optional[RPCRouter] = None,
    chain: str = "ethereum",
    target_addr: str = "",
    block_pin: int = 0,
    depth: int = 0,
    slot_collisions: Optional[Sequence[int]] = None,
    forbidden_callers: Optional[Set[str]] = None,
) -> CallerDominatorProof:
    """
    E3 조기 종료 (Caller-Dominator Theorem 3대 공리 검증, 전 구간 Fail-Open 무결성):
    1. 모든 Value Sink/SSTORE/TSTORE/UnresolvedJump 도달 진입점이 분기 감응형 CALLER == G 가드 지배자에 의해 통제됨
       (CALLER != G 분기는 반드시 무부작용 REVERT/INVALID로 종료)
    2. G가 퇴화 상수(0x0, address(this), ZERO_STATE_CALLER 후보군, 무권한 공용 싱글턴/라우터)가 아님 (32바이트 패딩 정규화 온체인 슬롯 실측)
    3. 비권한 진입점이 G의 슬롯을 덮어쓰지 못하며(프록시 슬롯 충돌, 매핑 Keccak 슬롯 및 임의 SSTORE 포함),
       G가 컨트랙트(멀티 패싯 프록시 포함)이면 재귀 검사 통과 (depth 한도 도달 또는 RPC 오류 시 Fail-Open 개방 처리)
    """
    if slot_collisions:
        open_all = sorted(cfg.entries.keys()) if cfg.entries else ["fallback"]
        return CallerDominatorProof(
            all_closed=False,
            open_selectors=open_all,
            closed_selectors=[],
            early_exit_safe=False,
            early_exit_reason="",
        )

    if not cfg.entries:
        return CallerDominatorProof(
            all_closed=True,
            open_selectors=[],
            closed_selectors=[],
            early_exit_safe=True,
            early_exit_reason="E3_NO_REACHABLE_ENTRIES",
        )

    unprotected_written_slots: Set[int] = set()
    has_unprotected_arbitrary_sstore = False
    has_unprotected_keccak_sstore = False
    open_sels_set: Set[str] = set()
    closed_sels_set: Set[str] = set()
    candidate_closed: Dict[str, Tuple[EntryPointCFG, Optional[int]]] = {}

    def _mark_entry_open(sel_k: str, ep_k: EntryPointCFG) -> None:
        nonlocal has_unprotected_arbitrary_sstore, has_unprotected_keccak_sstore
        open_sels_set.add(sel_k)
        if ep_k.reaches_sstore:
            unprotected_written_slots.update(ep_k.written_slots)
            if ep_k.reaches_arbitrary_sstore:
                has_unprotected_arbitrary_sstore = True
            if ep_k.reaches_keccak_sstore:
                has_unprotected_keccak_sstore = True

    t_norm = _norm_addr(target_addr)
    infra_fn = globals().get("_infra_addresses_for_chain")
    chain_infra = set(infra_fn(chain)) if callable(infra_fn) else set()
    forbid_set: Set[str] = (
        set(_DEGENERATE_CALLER_ADDRS)
        | set(_PUBLIC_PERMISSIONLESS_CALLERS)
        | set(_deterministic_caller_candidates(chain))
        | chain_infra
    )
    if forbidden_callers:
        forbid_set.update(nx for x in forbidden_callers if (nx := _norm_addr(x)))

    for sel, ep in sorted(cfg.entries.items()):
        if not (
            ep.reaches_value_sink
            or ep.reaches_sstore
            or ep.reaches_unresolved_jump
            or ep.reaches_dynamic_staticcall
        ):
            closed_sels_set.add(sel)
            continue
        if not ep.caller_dominated:
            _mark_entry_open(sel, ep)
            continue
        g_addr = _norm_addr(ep.dominator_guard_addr) if ep.dominator_guard_addr else ""
        g_slot = ep.dominator_guard_slot
        g_shift = ep.dominator_guard_shift
        if g_slot is not None and (
            g_slot in unprotected_written_slots
            or has_unprotected_arbitrary_sstore
            or ((g_slot & ~(1 << 240)) >= (1 << 64) and has_unprotected_keccak_sstore)
        ):
            _mark_entry_open(sel, ep)
            continue
        if not g_addr and g_slot is not None and (g_slot & (1 << 240)) != 0:
            _mark_entry_open(sel, ep)
            continue
        if not g_addr and g_slot is not None and router is not None and t_norm and block_pin > 0:
            try:
                sval = router.call(
                    chain,
                    "eth_getStorageAt",
                    [_checksum(t_norm), hex(g_slot), hex(block_pin)],
                    block_pin=block_pin,
                )
                if not isinstance(sval, str):
                    _mark_entry_open(sel, ep)
                    continue
                word_b = _hex_to_word32(sval)
                word_int = int.from_bytes(word_b, "big")
                addr_int = (word_int >> max(0, int(g_shift) * 8)) & _ADDR_MASK_160
                g_addr = f"0x{addr_int:040x}"
            except Exception:
                _mark_entry_open(sel, ep)
                continue
        if not g_addr or not _is_non_precompile_addr(g_addr) or g_addr in forbid_set or g_addr == t_norm:
            _mark_entry_open(sel, ep)
            continue
        if router is not None and block_pin > 0:
            try:
                g_res_map = _resolve_proxy_and_delegates(
                    router,
                    chain,
                    [g_addr],
                    block_pin,
                    raise_on_rpc_failure=True,
                )
                g_res = g_res_map.get(_norm_addr(g_addr))
                if g_res is None or g_res.slot_collisions or g_res.unresolved_delegation:
                    _mark_entry_open(sel, ep)
                    continue
                g_codes = [fb for gf_hex in _res_facet_codes_hex(g_res) if (fb := _hex_to_bytes(gf_hex))]
                sub_open = False
                if g_codes:
                    if depth >= 2:
                        sub_open = True
                    else:
                        sub_cfg = _merge_facet_cfgs([disassemble_and_build_cfg(gc) for gc in g_codes])
                        sub_proof = prove_caller_dominator_closed(
                            sub_cfg,
                            router=router,
                            chain=chain,
                            target_addr=g_addr,
                            block_pin=block_pin,
                            depth=depth + 1,
                            slot_collisions=g_res.slot_collisions,
                            forbidden_callers=(forbid_set | {t_norm}),
                        )
                        if not sub_proof.all_closed:
                            sub_open = True
                elif g_res.proxy_kind != "none":
                    sub_open = True
                else:
                    r_store = getattr(router, "store", None)
                    if r_store is not None:
                        try:
                            cur_cid = int(CHAIN_IDS.get(_norm_chain(chain), 0))
                            with r_store._read_conn() as rc:
                                row_cc = rc.execute(
                                    "SELECT 1 FROM contract_code WHERE address=? AND chain_id != ? AND raw_code_hex NOT IN ('', '0x') LIMIT 1",
                                    (_norm_addr(g_addr), cur_cid),
                                ).fetchone()
                                if row_cc is not None:
                                    sub_open = True
                        except Exception:
                            pass
                    if not sub_open:
                        try:
                            txc_raw = router.call(
                                chain,
                                "eth_getTransactionCount",
                                [_checksum(g_addr), hex(block_pin)],
                                block_pin=block_pin,
                            )
                            if (
                                not isinstance(txc_raw, str)
                                or not txc_raw.startswith("0x")
                                or len(txc_raw) <= 2
                                or int(txc_raw, 16) <= 0
                            ):
                                sub_open = True
                        except Exception:
                            sub_open = True
                if sub_open:
                    _mark_entry_open(sel, ep)
                    continue
            except Exception:
                _mark_entry_open(sel, ep)
                continue
        candidate_closed[sel] = (ep, g_slot)

    changed = True
    while changed:
        changed = False
        for sel, (ep, g_slot) in list(candidate_closed.items()):
            if g_slot is not None and (
                g_slot in unprotected_written_slots
                or has_unprotected_arbitrary_sstore
                or ((g_slot & ~(1 << 240)) >= (1 << 64) and has_unprotected_keccak_sstore)
            ):
                del candidate_closed[sel]
                _mark_entry_open(sel, ep)
                changed = True

    open_sels = sorted({s.split("@", 1)[0] for s in open_sels_set})
    closed_sels = sorted({s.split("@", 1)[0] for s in (closed_sels_set | set(candidate_closed.keys()))} - set(open_sels))
    all_closed = len(open_sels) == 0
    return CallerDominatorProof(
        all_closed=all_closed,
        open_selectors=open_sels,
        closed_selectors=closed_sels,
        early_exit_safe=all_closed,
        early_exit_reason="E3_CALLER_DOMINATOR_CLOSED" if all_closed else "",
    )


def _merge_facet_cfgs(cfgs: Sequence[CFGModel]) -> CFGModel:
    """
    동일 프록시(Diamond EIP-2535 또는 다중 구현체)에 속한 패싯들의 CFGModel을 단일 주소 공유 스토리지 공간으로 병합한다.
    패싯 간 스토리지 슬롯 쓰기-읽기 결합을 보존하여 교차 패싯 가드 슬롯 오염 탐지 및 인과 슬라이싱을 수행한다.
    """
    if not cfgs:
        return CFGModel(blocks={}, entries={}, disassembly=[])
    if len(cfgs) == 1:
        return cfgs[0]
    merged_blocks: Dict[int, BasicBlock] = {}
    merged_entries: Dict[str, EntryPointCFG] = {}
    merged_dis: List[Tuple[int, str, bytes]] = []
    for idx, c_model in enumerate(cfgs):
        off = idx * 0x100000
        for b_pc, bb in c_model.blocks.items():
            merged_blocks[b_pc + off] = BasicBlock(
                start_pc=bb.start_pc + off,
                end_pc=bb.end_pc + off,
                insns=[(pc + off, nm, imm) for pc, nm, imm in bb.insns],
                succs=[s + off for s in bb.succs],
                preds=[p + off for p in bb.preds],
                has_caller_eq=bb.has_caller_eq,
                caller_gate_const=bb.caller_gate_const,
                caller_gate_slot=bb.caller_gate_slot,
                caller_gate_shift=bb.caller_gate_shift,
                authorized_succ_pc=(bb.authorized_succ_pc + off) if bb.authorized_succ_pc is not None else None,
                unauthorized_succ_pc=(bb.unauthorized_succ_pc + off) if bb.unauthorized_succ_pc is not None else None,
                has_sstore=bb.has_sstore,
                has_arbitrary_sstore=bb.has_arbitrary_sstore,
                has_keccak_sstore=bb.has_keccak_sstore,
                sstore_slots=list(bb.sstore_slots),
                has_sload=bb.has_sload,
                sload_slots=list(bb.sload_slots),
                has_tstore=bb.has_tstore,
                has_tload=bb.has_tload,
                has_value_sink=bb.has_value_sink,
                has_external_call=bb.has_external_call,
                has_call_before_sstore=bb.has_call_before_sstore,
                has_unresolved_jump=bb.has_unresolved_jump,
                has_unmodeled_op=bb.has_unmodeled_op,
                has_dynamic_staticcall=bb.has_dynamic_staticcall,
                pushed_jumpdests=[jd + off for jd in bb.pushed_jumpdests],
                has_revert=bb.has_revert,
                has_return=bb.has_return,
            )
        for sel, ep in c_model.entries.items():
            shifted_ep = EntryPointCFG(
                selector=ep.selector,
                entry_pc=ep.entry_pc + off,
                reachable_blocks={r + off for r in ep.reachable_blocks},
                reaches_value_sink=ep.reaches_value_sink,
                reaches_sstore=ep.reaches_sstore,
                reaches_arbitrary_sstore=ep.reaches_arbitrary_sstore,
                reaches_keccak_sstore=ep.reaches_keccak_sstore,
                reaches_unresolved_jump=ep.reaches_unresolved_jump,
                reaches_dynamic_staticcall=ep.reaches_dynamic_staticcall,
                written_slots=set(ep.written_slots),
                read_slots=set(ep.read_slots),
                caller_dominated=ep.caller_dominated,
                dominator_guard_addr=ep.dominator_guard_addr,
                dominator_guard_slot=ep.dominator_guard_slot,
                dominator_guard_shift=ep.dominator_guard_shift,
            )
            if sel not in merged_entries:
                merged_entries[sel] = shifted_ep
            else:
                prev_ep = merged_entries[sel]
                prev_active = (
                    prev_ep.reaches_value_sink
                    or prev_ep.reaches_sstore
                    or prev_ep.reaches_unresolved_jump
                    or prev_ep.reaches_dynamic_staticcall
                )
                cur_active = (
                    shifted_ep.reaches_value_sink
                    or shifted_ep.reaches_sstore
                    or shifted_ep.reaches_unresolved_jump
                    or shifted_ep.reaches_dynamic_staticcall
                )
                if cur_active and not prev_active:
                    merged_entries[sel] = shifted_ep
                elif cur_active and prev_active:
                    prev_guard = (prev_ep.dominator_guard_addr, prev_ep.dominator_guard_slot, prev_ep.dominator_guard_shift)
                    cur_guard = (shifted_ep.dominator_guard_addr, shifted_ep.dominator_guard_slot, shifted_ep.dominator_guard_shift)
                    if not shifted_ep.caller_dominated:
                        prev_ep.caller_dominated = False
                    elif prev_ep.caller_dominated and prev_guard != cur_guard:
                        merged_entries[f"{sel}@f{idx}"] = EntryPointCFG(
                            selector=shifted_ep.selector,
                            entry_pc=shifted_ep.entry_pc,
                            reachable_blocks=set(shifted_ep.reachable_blocks),
                            reaches_value_sink=shifted_ep.reaches_value_sink,
                            reaches_sstore=shifted_ep.reaches_sstore,
                            reaches_arbitrary_sstore=shifted_ep.reaches_arbitrary_sstore,
                            reaches_keccak_sstore=shifted_ep.reaches_keccak_sstore,
                            reaches_unresolved_jump=shifted_ep.reaches_unresolved_jump,
                            reaches_dynamic_staticcall=shifted_ep.reaches_dynamic_staticcall,
                            written_slots=set(shifted_ep.written_slots),
                            read_slots=set(shifted_ep.read_slots),
                            caller_dominated=shifted_ep.caller_dominated,
                            dominator_guard_addr=shifted_ep.dominator_guard_addr,
                            dominator_guard_slot=shifted_ep.dominator_guard_slot,
                            dominator_guard_shift=shifted_ep.dominator_guard_shift,
                        )
                    prev_ep.reachable_blocks.update(shifted_ep.reachable_blocks)
                    prev_ep.reaches_value_sink = prev_ep.reaches_value_sink or shifted_ep.reaches_value_sink
                    prev_ep.reaches_sstore = prev_ep.reaches_sstore or shifted_ep.reaches_sstore
                    prev_ep.reaches_arbitrary_sstore = prev_ep.reaches_arbitrary_sstore or shifted_ep.reaches_arbitrary_sstore
                    prev_ep.reaches_keccak_sstore = prev_ep.reaches_keccak_sstore or shifted_ep.reaches_keccak_sstore
                    prev_ep.reaches_unresolved_jump = prev_ep.reaches_unresolved_jump or shifted_ep.reaches_unresolved_jump
                    prev_ep.reaches_dynamic_staticcall = prev_ep.reaches_dynamic_staticcall or shifted_ep.reaches_dynamic_staticcall
                    prev_ep.written_slots.update(shifted_ep.written_slots)
                    prev_ep.read_slots.update(shifted_ep.read_slots)
        merged_dis.extend((pc + off, nm, imm) for pc, nm, imm in c_model.disassembly)
    return CFGModel(blocks=merged_blocks, entries=merged_entries, disassembly=merged_dis)


def _build_res_merged_cfg(res: ProxyResolution) -> Optional[CFGModel]:
    facet_cfgs = [
        disassemble_and_build_cfg(fb)
        for f_chx in _res_facet_codes_hex(res)
        if (fb := _hex_to_bytes(f_chx))
    ]
    return _merge_facet_cfgs(facet_cfgs) if facet_cfgs else None


@dataclass
class CausalSlice:
    slice_id: str
    target_address: str
    channel: str  # CH_STORAGE | CH_TRANSIENT | CH_BALANCE | CH_MIDFRAME
    legs: List[str]  # selectors in execution order
    shared_slots: List[int] = field(default_factory=list)
    witness_candidates: List[int] = field(default_factory=list)
    repeat_counts: List[int] = field(default_factory=lambda: [1, 2])
    rationale: str = ""
    leg_targets: List[str] = field(default_factory=list)
    abi_inputs_by_sel: Dict[str, List[str]] = field(default_factory=dict)
    needs_agent_synthesis: bool = False
    undecided_reason: str = ""


def solve_discontinuity_boundaries(dis: List[Tuple[int, str, bytes]]) -> List[int]:
    """
    불연속 경계 솔버(Discontinuity Boundary Solver):
    - 디스패처 PUSH4 셀렉터 노이즈를 배제하고 실제 산술/비교/시프트 경계점(`bytecode_knots`)을 추출하여
      하네스 상위 6개 Witness 예산 안에 계약 고유 임계값과 표준 단위(`1e18`, `1e6`, `1`)가 함께 배치되도록 정렬한다.
    """
    core_units: List[int] = [
        10**18,
        10**6,
        1,
    ]
    secondary_units: List[int] = [
        100 * (10**18),
        1000 * (10**6),
        10**8,
        1000 * (10**18),
        100_000 * (10**6),
        10**18 - 1,
        10**18 + 1,
    ]
    u256_max = _UINT256_MAX
    div_knots: List[int] = []
    cmp_knots: List[int] = []
    n = len(dis)
    for idx, (pc, nm, imm) in enumerate(dis):
        if nm.startswith("PUSH") and 0 < len(imm) <= 32:
            val = int.from_bytes(imm, "big")
            if val == 0 or val >= u256_max:
                continue
            win_set = {dis[j][1] for j in range(idx + 1, min(n, idx + 5))}
            # 디스패처 PUSH4 <selector>; EQ 패턴 제외
            if nm == "PUSH4" and "EQ" in win_set and any(dis[j][1] == "JUMPI" for j in range(idx + 1, min(n, idx + 9))):
                continue
            if nm in ("PUSH1", "PUSH2") and pc < 512 and win_set <= {"JUMPI", "JUMP"}:
                continue
            if win_set & {"DIV", "SDIV", "MOD", "SMOD", "MULMOD", "ADDMOD"}:
                div_knots.extend([val, val + 1] + ([val - 1] if val > 1 else []))
            elif win_set & {"LT", "GT", "SLT", "SGT", "EQ", "SUB"}:
                if val < (1 << 128):
                    cmp_knots.extend([val, val + 1] + ([val - 1] if val > 0 else []))
            elif (win_set & {"SHL", "SHR", "SAR", "CLZ"}) and val < 256:
                cmp_knots.append(1 << val)
                if val > 0:
                    cmp_knots.append((1 << val) - 1)

    front_bc = list(dict.fromkeys([*div_knots[:6], *cmp_knots[:6]]))
    tail_knots: List[int] = [0, 2, math.isqrt(u256_max)]
    ordered: List[int] = []
    seen: Set[int] = set()
    interleaved_head = [
        10**18,
        *front_bc[:2],
        10**6,
        *front_bc[2:4],
        1,
        *front_bc[4:6],
    ]
    for k in [*interleaved_head, *core_units, *secondary_units, *div_knots, *cmp_knots, *tail_knots]:
        if 0 <= k <= u256_max and k not in seen:
            seen.add(k)
            ordered.append(k)
    return ordered[:28]


def _format_abi_param_type(inp: Dict[str, Any]) -> str:
    """중첩 tuple(components) 및 배열 접미사를 재귀적으로 표준 ABI 시그니처 타입 문자열로 변환."""
    t = str(inp.get("type") or "uint256").strip()
    if t.startswith("tuple"):
        comps = inp.get("components") or []
        comp_str = ",".join(_format_abi_param_type(c) for c in comps if isinstance(c, dict))
        suffix = t[5:]
        return f"({comp_str}){suffix}"
    return t


def _extract_abi_inputs_map(abi_list: Sequence[Any]) -> Dict[str, List[str]]:
    """검증된 ABI JSON에서 selector -> 입력 타입 리스트 매핑 생성 (재귀 중첩 tuple 완벽 지원)."""
    out: Dict[str, List[str]] = {}
    for item in abi_list or []:
        if not isinstance(item, dict) or item.get("type") != "function":
            continue
        name = str(item.get("name") or "").strip()
        if not name:
            continue
        inputs = item.get("inputs") or []
        in_types: List[str] = [_format_abi_param_type(inp) for inp in inputs if isinstance(inp, dict)]
        sig = f"{name}({','.join(in_types)})"
        out[_selector(sig).lower()] = in_types
    return out


def _abi_requires_agent_reasoning(in_types: Sequence[str]) -> bool:
    """기계적 원시 템플릿으로 포괄 불가능한 중첩 튜플/가변 바이트/고정·가변 길이 배열 페이로드 존재 여부."""
    for t in in_types:
        ts = t.strip()
        if ts in ("bytes", "string") or ts.startswith("(") or ts.endswith("]"):
            return True
    return False


def slice_four_channel_causal_chains(
    target_address: str,
    cfg: CFGModel,
    open_selectors: List[str],
    max_slices: int = 64,
    abi_list: Optional[Sequence[Any]] = None,
    peer_dep_targets: Optional[Sequence[Any]] = None,
) -> List[CausalSlice]:
    """
    4대 물리적 상태 채널(CH_STORAGE, CH_TRANSIENT, CH_BALANCE, CH_MIDFRAME) 인과 슬라이서:
    - 1-leg 전수 + 2-leg 대각쌍 + 자금우선 3·4-leg + 오라클/잔액 dep->consumer 순서쌍 + depth-2 콜백 프로브
    """
    t_norm = _norm_addr(target_address)
    witnesses = solve_discontinuity_boundaries(cfg.disassembly)
    abi_map = _extract_abi_inputs_map(abi_list or [])
    slices: List[CausalSlice] = []

    open_eps = [cfg.entries[s] for s in open_selectors if s in cfg.entries]
    if not open_eps and open_selectors:
        open_set = set(open_selectors)
        open_eps = [ep for k, ep in cfg.entries.items() if k.split("@", 1)[0] in open_set]
    if not open_eps and cfg.entries:
        open_eps = list(cfg.entries.values())[:8]

    writers = [ep for ep in open_eps if ep.reaches_sstore or ep.reaches_unresolved_jump]
    sinks = [
        ep
        for ep in open_eps
        if ep.reaches_value_sink or ep.reaches_sstore or ep.reaches_unresolved_jump or ep.reaches_dynamic_staticcall
    ]

    def _sel_abi_flags(sel_s: str, extra_complex: bool = False) -> Tuple[bool, List[str], bool]:
        sel_low = sel_s.lower()
        verified = bool(abi_map) and (sel_low in abi_map) and (sel_low != "fallback")
        in_types = abi_map.get(sel_low, [])
        is_complex = _abi_requires_agent_reasoning(in_types) or extra_complex or (not verified)
        return verified, in_types, is_complex

    for sk in sinks:
        dyn_sc_only = sk.reaches_dynamic_staticcall and not (sk.reaches_value_sink or sk.reaches_sstore)
        has_verified_sel, in_t, complex_abi = _sel_abi_flags(sk.selector, dyn_sc_only)
        slices.append(
            CausalSlice(
                slice_id=f"ch_storage_1leg_{t_norm[-6:]}_{sk.selector}",
                target_address=t_norm,
                channel="CH_MIDFRAME" if dyn_sc_only else "CH_STORAGE",
                legs=[sk.selector],
                shared_slots=sorted(sk.read_slots & sk.written_slots)[:8],
                witness_candidates=witnesses[:14],
                repeat_counts=[1, 2],
                rationale="Direct open entry reaching physical value, state, or dynamic staticcall sink",
                leg_targets=[t_norm],
                abi_inputs_by_sel={sk.selector: in_t} if has_verified_sel else {},
                needs_agent_synthesis=complex_abi,
                undecided_reason=(
                    "Dynamic STATICCALL view/verifier callback synthesis required"
                    if dyn_sc_only
                    else (
                        "Unverified selector or fallback calldata synthesis required"
                        if not has_verified_sel
                        else ("Complex struct/bytes calldata synthesis required" if complex_abi else "")
                    )
                ),
            )
        )
        if sk.reaches_sstore and sk.reaches_value_sink:
            slices.append(
                CausalSlice(
                    slice_id=f"ch_storage_self3leg_{t_norm[-6:]}_{sk.selector}",
                    target_address=t_norm,
                    channel="CH_STORAGE",
                    legs=[sk.selector, sk.selector, sk.selector],
                    shared_slots=sorted(sk.read_slots | sk.written_slots)[:8],
                    witness_candidates=witnesses[:10],
                    repeat_counts=[1, 2],
                    rationale="3-leg repeated state accumulation and extraction on coupled SSTORE+Sink entry",
                    leg_targets=[t_norm, t_norm, t_norm],
                    abi_inputs_by_sel={sk.selector: in_t} if has_verified_sel else {},
                    needs_agent_synthesis=complex_abi,
                    undecided_reason="Unverified selector or complex ABI in 3-leg accumulation" if complex_abi else "",
                )
            )

    for wr in writers:
        for sk in sinks:
            if wr.selector == sk.selector:
                continue
            shared = sorted(wr.written_slots & sk.read_slots)
            if shared or (not wr.written_slots and not sk.read_slots):
                sel_abi = {
                    s: abi_map[s.lower()]
                    for s in (wr.selector, sk.selector)
                    if s.lower() in abi_map and s.lower() != "fallback"
                }
                pair_verified = len(sel_abi) == 2
                complex_pair = (not pair_verified) or any(_abi_requires_agent_reasoning(v) for v in sel_abi.values())
                slices.append(
                    CausalSlice(
                        slice_id=f"ch_storage_2leg_{t_norm[-6:]}_{wr.selector}_{sk.selector}",
                        target_address=t_norm,
                        channel="CH_STORAGE",
                        legs=[wr.selector, sk.selector],
                        shared_slots=shared[:8],
                        witness_candidates=witnesses[:14],
                        repeat_counts=[1, 2, 5],
                        rationale="State writer SSTORE coupling into value sink SLOAD",
                        leg_targets=[t_norm, t_norm],
                        abi_inputs_by_sel=sel_abi,
                        needs_agent_synthesis=complex_pair,
                        undecided_reason="Multi-leg unverified or complex ABI state transition" if complex_pair else "",
                    )
                )
                slices.append(
                    CausalSlice(
                        slice_id=f"ch_storage_3leg_{t_norm[-6:]}_{wr.selector}_{sk.selector}_{wr.selector}",
                        target_address=t_norm,
                        channel="CH_STORAGE",
                        legs=[wr.selector, sk.selector, wr.selector],
                        shared_slots=shared[:8],
                        witness_candidates=witnesses[:10],
                        repeat_counts=[1, 2],
                        rationale="3-leg symmetric state transition and unwind sequence",
                        leg_targets=[t_norm, t_norm, t_norm],
                        abi_inputs_by_sel=sel_abi,
                        needs_agent_synthesis=complex_pair,
                        undecided_reason="3-leg unverified or complex ABI state transition" if complex_pair else "",
                    )
                )
                if len(writers) >= 2:
                    wr2 = next((w for w in writers if w.selector != wr.selector), wr)
                    sel_abi_4 = {
                        s: abi_map[s.lower()]
                        for s in (wr.selector, wr2.selector, sk.selector)
                        if s.lower() in abi_map and s.lower() != "fallback"
                    }
                    complex_4 = (len(sel_abi_4) < 3) or any(_abi_requires_agent_reasoning(v) for v in sel_abi_4.values())
                    slices.append(
                        CausalSlice(
                            slice_id=f"ch_storage_4leg_{t_norm[-6:]}_{wr.selector}_{wr2.selector}_{sk.selector}_{wr.selector}",
                            target_address=t_norm,
                            channel="CH_STORAGE",
                            legs=[wr.selector, wr2.selector, sk.selector, wr.selector],
                            shared_slots=shared[:8],
                            witness_candidates=witnesses[:8],
                            repeat_counts=[1, 2],
                            rationale="4-leg capital-prioritized setup-mutate-extract-unwind sequence",
                            leg_targets=[t_norm, t_norm, t_norm, t_norm],
                            abi_inputs_by_sel=sel_abi_4,
                            needs_agent_synthesis=complex_4,
                            undecided_reason="4-leg multi-state unverified or complex ABI boundary" if complex_4 else "",
                        )
                    )

    has_transient = any(bb.has_tstore or bb.has_tload for bb in cfg.blocks.values())
    if has_transient and sinks:
        for sk in sinks[:4]:
            has_verified_sel, in_t, complex_abi = _sel_abi_flags(sk.selector)
            slices.append(
                CausalSlice(
                    slice_id=f"ch_transient_{t_norm[-6:]}_{sk.selector}",
                    target_address=t_norm,
                    channel="CH_TRANSIENT",
                    legs=[sk.selector, sk.selector],
                    shared_slots=[],
                    witness_candidates=witnesses[:10],
                    repeat_counts=[1, 2],
                    rationale="Same-transaction transient storage (TSTORE/TLOAD) multi-call coupling",
                    leg_targets=[t_norm, t_norm],
                    abi_inputs_by_sel={sk.selector: in_t} if has_verified_sel else {},
                    needs_agent_synthesis=complex_abi,
                    undecided_reason="EIP-1153 transient storage unverified or complex ABI" if complex_abi else "",
                )
            )

    has_div = any(nm in ("DIV", "SDIV") for _, nm, _ in cfg.disassembly)
    has_ext_read = any(nm in ("STATICCALL", "SELFBALANCE", "BALANCE") for _, nm, _ in cfg.disassembly)
    if has_div and has_ext_read and sinks:
        for sk in sinks[:4]:
            has_verified_sel, in_t, complex_abi = _sel_abi_flags(sk.selector)
            slices.append(
                CausalSlice(
                    slice_id=f"ch_balance_skew_{t_norm[-6:]}_{sk.selector}",
                    target_address=t_norm,
                    channel="CH_BALANCE",
                    legs=[sk.selector],
                    shared_slots=sorted(sk.read_slots)[:4],
                    witness_candidates=witnesses[:14],
                    repeat_counts=[1, 2, 16],
                    rationale="External balance/reserve read coupled with integer division rounding boundary",
                    leg_targets=[t_norm],
                    abi_inputs_by_sel={sk.selector: in_t} if has_verified_sel else {},
                    needs_agent_synthesis=complex_abi,
                    undecided_reason="Spot reserve/exchange-rate dependency with unverified or complex ABI" if complex_abi else "",
                )
            )
            for dep_item in (peer_dep_targets or [])[:4]:
                if isinstance(dep_item, (tuple, list)) and len(dep_item) >= 2:
                    dep_addr, dep_sel = str(dep_item[0]), str(dep_item[1])
                    dep_abi_in = list(dep_item[2]) if len(dep_item) >= 3 and isinstance(dep_item[2], (list, tuple)) else []
                else:
                    dep_addr, dep_sel = str(dep_item), sk.selector
                    dep_abi_in = []
                dn = _norm_addr(dep_addr)
                if dn and dn != t_norm:
                    dep_abi_map: Dict[str, List[str]] = {}
                    if has_verified_sel:
                        dep_abi_map[sk.selector] = in_t
                    if dep_abi_in:
                        dep_abi_map[dep_sel] = dep_abi_in
                    slices.append(
                        CausalSlice(
                            slice_id=f"ch_balance_dep_{dn[-4:]}_{dep_sel}_{t_norm[-4:]}_{sk.selector}",
                            target_address=t_norm,
                            channel="CH_BALANCE",
                            legs=[dep_sel, sk.selector],
                            shared_slots=sorted(sk.read_slots)[:4],
                            witness_candidates=witnesses[:12],
                            repeat_counts=[1, 2],
                            rationale="Cross-contract oracle/balance dependency -> consumer ordered pair",
                            leg_targets=[dn, t_norm],
                            abi_inputs_by_sel=dep_abi_map,
                            needs_agent_synthesis=True,
                            undecided_reason="Cross-contract dep->consumer invariant coupling",
                        )
                    )

    # 4. CH_MIDFRAME: 상태 변경 외부 CALL(STATICCALL 제외)과 SSTORE/TSTORE가 결합된 진입점의 깊이-2 리엔트런시/콜백 프로브
    midframe_sels: List[str] = []
    for sk in sinks:
        has_ext_call_in_ep = False
        has_state_write_in_ep = sk.reaches_sstore
        for b_pc in sk.reachable_blocks:
            bb = cfg.blocks.get(b_pc)
            if not bb:
                continue
            if bb.has_external_call:
                has_ext_call_in_ep = True
            if bb.has_sstore or bb.has_tstore:
                has_state_write_in_ep = True
            if bb.has_call_before_sstore:
                midframe_sels.append(sk.selector)
                break
        else:
            if has_ext_call_in_ep and (has_state_write_in_ep or len(writers) > 0):
                midframe_sels.append(sk.selector)
    for msel in sorted(set(midframe_sels))[:4]:
        msel_low = msel.lower()
        has_verified_msel = bool(abi_map) and (msel_low in abi_map) and (msel_low != "fallback")
        in_t = abi_map.get(msel_low, [])
        complex_abi = (not has_verified_msel) or _abi_requires_agent_reasoning(in_t)
        slices.append(
            CausalSlice(
                slice_id=f"ch_midframe_{t_norm[-6:]}_{msel}",
                target_address=t_norm,
                channel="CH_MIDFRAME",
                legs=[msel],
                shared_slots=[],
                witness_candidates=witnesses[:10],
                repeat_counts=[1, 2],
                rationale="State-modifying external CALL coupled with state mutation (depth-2 callback window)",
                leg_targets=[t_norm],
                abi_inputs_by_sel={msel: in_t} if has_verified_msel else {},
                needs_agent_synthesis=complex_abi,
                undecided_reason="Mid-frame callback with unverified or complex ABI" if complex_abi else "",
            )
        )

    return slices[:max_slices]

# ═══════════════════════════════════════════════════════════════════════════
# §6. Foundry (tools/foundry/forge.exe) 직접 포크 하네스 및 치트코드 화이트리스트 검증기
# ═══════════════════════════════════════════════════════════════════════════

_VM_VAR_DECL_RE = re.compile(r"\bVm\s+(?:constant\s+|immutable\s+)?([A-Za-z_][A-Za-z0-9_]*)\b")
_VM_CAST_ASSIGN_RE = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*=\s*Vm\s*\(")
_VM_INLINE_CALL_RE = re.compile(r"\bVm\s*\([^)]*\)\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\s*\(")
_LOWLEVEL_HEVM_RE = re.compile(
    r"0x7109709[Ee][Cc]fa91a80626f[Ff]3989[Dd]68f67[Ff]5b1[Dd][Dd]12[Dd]\s*\.\s*(?:call|staticcall|delegatecall)"
)
_HEVM_HEX_RE = re.compile(r"0x7109709[Ee][Cc]fa91a80626f[Ff]3989[Dd]68f67[Ff]5b1[Dd][Dd]12[Dd]")
_HEVM_DERIVE_RE = re.compile(r"hevm\s+cheat\s+code", re.IGNORECASE)
_CONSOLE_HEX_RE = re.compile(r"0x000000000000000000636[Ff]6[Ee]736[Ff]6[Cc]652[Ee]6[Cc]6[Ff]67")


def _strip_solidity_comments_preserve_strings(src: str) -> str:
    """문자열 리터럴("...", '...') 내부의 //, /* 를 건드리지 않고 Solidity 주석만 정확히 제거한다."""
    out: List[str] = []
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        if ch in ('"', "'"):
            quote = ch
            out.append(ch)
            i += 1
            while i < n:
                c2 = src[i]
                out.append(c2)
                if c2 == "\\" and i + 1 < n:
                    out.append(src[i + 1])
                    i += 2
                    continue
                i += 1
                if c2 == quote:
                    break
        elif ch == "/" and i + 1 < n and src[i + 1] == "/":
            i += 2
            while i < n and src[i] != "\n":
                i += 1
        elif ch == "/" and i + 1 < n and src[i + 1] == "*":
            i += 2
            while i + 1 < n and not (src[i] == "*" and src[i + 1] == "/"):
                if src[i] == "\n":
                    out.append("\n")
                i += 1
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


FOUNDRY_DEFAULT_SENDER: str = "0x1804c8ab1f12e6bbf3894d4083f33e07309d1f38"
FOUNDRY_TEST_CONTRACT: str = "0x7fa9385be102ac3eac297483dd6233d62b3e1496"
CREATE2_DEPLOYER_ADDR: str = "0x4e59b44847b379578588920ca78fbf26c0b4956c"
FOUNDRY_CONSOLE_ADDR: str = "0x000000000000000000636f6e736f6c652e6c6f67"

_INLINE_FORK_CALLS: FrozenSet[str] = frozenset({"createSelectFork", "selectFork"})
_INLINE_FORK_SELECTORS: FrozenSet[str] = frozenset(
    _selector(sig).lower()
    for sig in (
        "createSelectFork(string,uint256)",
        "createSelectFork(string)",
        "createSelectFork(string,bytes32)",
        "selectFork(uint256)",
    )
)
_SINGLE_ARG_PRANK_SELECTORS: FrozenSet[str] = frozenset(
    _selector(sig).lower()
    for sig in ("prank(address)", "startPrank(address)")
)
_TWO_ARG_PRANK_SELECTORS: FrozenSet[str] = frozenset(
    _selector(sig).lower()
    for sig in ("prank(address,address)", "startPrank(address,address)")
)
_FORBIDDEN_VM_SELECTORS: FrozenSet[str] = frozenset(
    _selector(sig).lower()
    for sig in (
        "deal(address,uint256)",
        "etch(address,bytes)",
        "store(address,bytes32,bytes32)",
        "load(address,bytes32)",
        "roll(uint256)",
        "warp(uint256)",
        "fee(uint256)",
        "txGasPrice(uint256)",
        "coinbase(address)",
        "mockCall(address,bytes,bytes)",
        "mockCall(address,uint256,bytes,bytes)",
        "clearMockedCalls()",
        "ffi(string[])",
        "readFile(string)",
        "writeFile(string,string)",
        "envString(string)",
        "envUint(string)",
        "envBytes32(string)",
        "sign(uint256,bytes32)",
        "addr(uint256)",
        "hoax(address)",
        "hoax(address,uint256)",
        "startHoax(address)",
        "startHoax(address,uint256)",
        "transact(bytes32)",
        "revertToState(uint256)",
        "broadcast()",
        "broadcast(address)",
        "startBroadcast()",
        "startBroadcast(address)",
        "stopBroadcast()",
    )
)

_ASSEMBLY_KW_RE: re.Pattern[str] = re.compile(r"\bassembly\b")
_FORGE_CONFIG_RE: re.Pattern[str] = re.compile(r"forge-config\s*:", re.IGNORECASE)
_CONSOLE_DOT_RE: re.Pattern[str] = re.compile(r"\bconsole2?\s*\.")
_DEFAULT_SENDER_HEX_RE: re.Pattern[str] = re.compile(rf"{FOUNDRY_DEFAULT_SENDER}\b", re.IGNORECASE)
_TEST_CONTRACT_HEX_RE: re.Pattern[str] = re.compile(rf"{FOUNDRY_TEST_CONTRACT}\b", re.IGNORECASE)
_CREATE2_DEPLOYER_HEX_RE: re.Pattern[str] = re.compile(rf"{CREATE2_DEPLOYER_ADDR}\b", re.IGNORECASE)
_SOL_SETUP_FN_RE: re.Pattern[str] = re.compile(r"\bfunction\s+setUp\s*\(")
_SOL_IMPORT_STMT_RE: re.Pattern[str] = re.compile(r'(?:^|[;{}])\s*import\s+(?:["\']|[\w*{])', re.MULTILINE)
_SOL_CONTRACT_WITH_LIB_RE: re.Pattern[str] = re.compile(
    r"\b(abstract\s+contract|contract|library)\s+([A-Za-z_][A-Za-z0-9_]*)\b([^{]*)\{"
)
_SOL_CONTRACT_NO_LIB_RE: re.Pattern[str] = re.compile(
    r"\b(abstract\s+contract|contract)\s+([A-Za-z_][A-Za-z0-9_]*)\b([^{]*)\{"
)
_SOL_IS_CLAUSE_RE: re.Pattern[str] = re.compile(r"\bis\b(.*)$", re.DOTALL)
_SOL_IDENT_HEAD_RE: re.Pattern[str] = re.compile(r"\s*([A-Za-z_][A-Za-z0-9_]*)")
_SOL_TEST_FN_RE: re.Pattern[str] = re.compile(r"\bfunction\s+(test[A-Za-z0-9_]*)\s*\(")
_SOL_ADDR_THIS_RE: re.Pattern[str] = re.compile(r"\baddress\s*\(\s*this\s*\)")
_SOL_SELFBALANCE_RE: re.Pattern[str] = re.compile(r"\bselfbalance\s*\(")
_SOL_ASM_SELF_RE: re.Pattern[str] = re.compile(r"\b(?:address|selfbalance)\s*\(\s*\)")
_SOL_CALLBACK_FN_RE: re.Pattern[str] = re.compile(r"\b(?:receive|fallback)\s*\([^)]*\)[^{;]*\{")
_SOL_HEVM_VAR_LINE_RE: re.Pattern[str] = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*=\s*.*0x7109709", re.IGNORECASE)
_SOL_CONST_ADDR_DECL_RE: re.Pattern[str] = re.compile(
    r"\baddress\s+(?:(?:public|private|internal)\s+)*constant\s+(?:(?:public|private|internal)\s+)*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([^;]+);"
)
_SOL_FULL_HEX_ADDR_RE: re.Pattern[str] = re.compile(r"^0x[0-9a-fA-F]{1,40}$")
_SOL_BALANCED_CAST_RE: re.Pattern[str] = re.compile(r"^(?:payable|address|uint160)\s*\((.*)\)$", re.DOTALL)
_SOL_ASM_LOG_RE: re.Pattern[str] = re.compile(r"\blog[0-4]\s*\(")
_SOL_SIMPLE_IDENT_RE: re.Pattern[str] = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_SOL_CONSTRUCTOR_RE: re.Pattern[str] = re.compile(r"\bconstructor\s*\(")
_SOL_SINGLE_EQ_RE: re.Pattern[str] = re.compile(r"(?<![=!<>])=(?![=>])")
_SOL_CONSTANT_KW_RE: re.Pattern[str] = re.compile(r"\bconstant\b")
_SOL_QUOTED_STR_RE: re.Pattern[str] = re.compile(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'')
_SOL_NEW_KW_RE: re.Pattern[str] = re.compile(r"\bnew\b")
_SOL_MEMBER_ACCESS_RE: re.Pattern[str] = re.compile(r"[A-Za-z0-9_)\]]\s*\.\s*[A-Za-z_]")
_SOL_CONSERVATION_EVENT_EMIT_RE: re.Pattern[str] = re.compile(r"\b(?:event|emit)\s+Conservation(?:Gain|SupplyMint)\b")


def _unwrap_sol_addr_expr(expr: str) -> str:
    cur = (expr or "").strip()
    while cur:
        m = _SOL_BALANCED_CAST_RE.fullmatch(cur)
        if not m:
            break
        inner = m.group(1).strip()
        # Ensure outer cast closes on this expression's end (not `(a) + address(b)`).
        depth = 0
        in_str = ""
        esc = False
        balanced_single = True
        for ch in inner:
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == in_str:
                    in_str = ""
                continue
            if ch in ('"', "'"):
                in_str = ch
            elif ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth < 0:
                    balanced_single = False
                    break
        if not balanced_single or depth != 0:
            break
        cur = inner
    return cur


def _iter_sol_prank_calls(clean_src: str, vm_vars: Sequence[str]) -> List[Tuple[str, bool]]:
    """Extract balanced `(args_text, is_valid)` pairs for every `prank(...)` / `startPrank(...)` invocation."""
    var_pat = "|".join(re.escape(v) for v in vm_vars)
    head_re = re.compile(
        rf"(?:\b(?:{var_pat})|\b(?:Vm|IHevm|Hevm|StdCheats)\s*\([^)]*\))\s*\.\s*(?:prank|startPrank)\s*\("
    )
    out: List[Tuple[str, bool]] = []
    n = len(clean_src)
    for m in head_re.finditer(clean_src):
        pos = m.end()
        depth = 1
        in_str = ""
        esc = False
        i = pos
        closed = False
        while i < n:
            ch = clean_src[i]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == in_str:
                    in_str = ""
            else:
                if ch in ('"', "'"):
                    in_str = ch
                elif ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        out.append((clean_src[pos:i].strip(), True))
                        closed = True
                        break
            i += 1
        if not closed:
            out.append((clean_src[pos:].strip(), False))
    return out


def _extract_assembly_blocks(clean_src: str) -> List[str]:
    """중첩 중괄호({ ... })를 포함한 전체 Yul assembly 블록 본문을 정확히 추출한다."""
    blocks: List[str] = []
    for m in _ASSEMBLY_KW_RE.finditer(clean_src):
        brace_pos = clean_src.find("{", m.end())
        if brace_pos < 0:
            continue
        depth = 0
        j = brace_pos
        while j < len(clean_src):
            if clean_src[j] == "{":
                depth += 1
            elif clean_src[j] == "}":
                depth -= 1
                if depth == 0:
                    blocks.append(clean_src[brace_pos + 1 : j])
                    break
            j += 1
    return blocks


def _parse_solidity_contract_closures(
    src: str, include_library: bool = True
) -> Dict[str, Tuple[str, int, List[str]]]:
    """Solidity 소스에서 contract/abstract contract(/library) 선언 위치와 상속 베이스 폐포 본문 리스트를 O(1) deque BFS로 추출."""
    pat = _SOL_CONTRACT_WITH_LIB_RE if include_library else _SOL_CONTRACT_NO_LIB_RE
    raw_defs: Dict[str, Tuple[str, List[str], int, str]] = {}
    src_len = len(src)
    for cm in pat.finditer(src):
        c_kind = _WS_COLLAPSE_RE.sub(" ", cm.group(1).strip().lower())
        c_name = cm.group(2)
        inh_raw = cm.group(3) or ""
        bases: List[str] = []
        m_is = _SOL_IS_CLAUSE_RE.search(inh_raw)
        if m_is:
            for b_tok in m_is.group(1).split(","):
                b_id_m = _SOL_IDENT_HEAD_RE.match(b_tok)
                if b_id_m:
                    bases.append(b_id_m.group(1))
        b_pos = cm.end() - 1
        b_depth = 0
        b_idx = b_pos
        c_body = ""
        while b_idx < src_len:
            ch = src[b_idx]
            if ch == "{":
                b_depth += 1
            elif ch == "}":
                b_depth -= 1
                if b_depth == 0:
                    c_body = src[b_pos + 1 : b_idx]
                    break
            b_idx += 1
        if c_body:
            raw_defs[c_name] = (c_kind, bases, b_pos, c_body)

    closures: Dict[str, Tuple[str, int, List[str]]] = {}
    for c_name, (c_kind, bases, b_pos, c_body) in raw_defs.items():
        bodies = [c_body]
        seen: Set[str] = {c_name}
        q: deque[str] = deque(bases)
        while q:
            bn = q.popleft()
            if bn in seen or bn not in raw_defs:
                continue
            seen.add(bn)
            _, sub_bases, _, sub_body = raw_defs[bn]
            bodies.append(sub_body)
            q.extend(sub_bases)
        closures[c_name] = (c_kind, b_pos, bodies)
    return closures


@functools.lru_cache(maxsize=64)
def _compiled_vm_var_regexes(vm_key: Tuple[str, ...]) -> Tuple[re.Pattern[str], re.Pattern[str], re.Pattern[str]]:
    var_pat = "|".join(re.escape(v) for v in vm_key)
    return (
        re.compile(rf"\b(?:{var_pat})\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\s*\("),
        re.compile(
            rf"(?:\b(?:{var_pat})|\b(?:Vm|IHevm|Hevm|StdCheats)\s*\([^)]*\))\s*\.\s*(?:prank|startPrank)\s*\(([^;]*)\)"
        ),
        re.compile(rf"\b(?:{var_pat})\b"),
    )


def _top_level_sol_statements(body: str) -> List[str]:
    """컨트랙트 최상위(중괄호 깊이 0) 세미콜론 선언문만 추출한다."""
    stmts: List[str] = []
    buf: List[str] = []
    depth = 0
    in_str = ""
    esc = False
    for ch in body:
        if in_str:
            if depth == 0:
                buf.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == in_str:
                in_str = ""
            continue
        if ch in ('"', "'"):
            in_str = ch
            if depth == 0:
                buf.append(ch)
            continue
        if ch == "{":
            if depth == 0:
                buf.clear()
            depth += 1
            continue
        if ch == "}":
            if depth > 0:
                depth -= 1
            if depth == 0:
                buf.clear()
            continue
        if depth == 0:
            if ch == ";":
                s_txt = "".join(buf).strip()
                buf.clear()
                if s_txt:
                    stmts.append(s_txt)
            else:
                buf.append(ch)
    return stmts


def verify_cheatcode_allowlist(
    sol_source: str,
    compiled_bytecode: bytes = b"",
    allowed_caller: str = "",
    forbid_inline_fork: bool = False,
) -> Tuple[bool, List[str]]:
    """
    Default-Deny 치트코드 화이트리스트 검증기:
    오직 ALLOWED_VM_CALLS만 허용하며, 문자열 리터럴을 보존한 주석 제거 후 별칭 변수(Vm v = ...),
    인라인 캐스트(Vm(...).deal), Yul assembly 내 HEVM_ADDRESS 참조, 컴파일된 바이트코드 내 비허용 셀렉터를 전수 차단한다.
    """
    violations: List[str] = []
    if sol_source:
        if _FORGE_CONFIG_RE.search(sol_source):
            violations.append("disallowed_inline_forge_config")
        clean_src = _strip_solidity_comments_preserve_strings(sol_source)

        if _HEVM_DERIVE_RE.search(clean_src):
            violations.append("disallowed_hevm_derivation_string")
        if _CONSOLE_HEX_RE.search(clean_src) or _CONSOLE_DOT_RE.search(clean_src):
            violations.append("disallowed_console_address")
        if _DEFAULT_SENDER_HEX_RE.search(clean_src):
            violations.append("disallowed_default_sender_reference")
        if _TEST_CONTRACT_HEX_RE.search(clean_src):
            violations.append("disallowed_test_harness_address_reference")
        if _CREATE2_DEPLOYER_HEX_RE.search(clean_src):
            violations.append("disallowed_create2_deployer_reference")
        if _SOL_SETUP_FN_RE.search(clean_src):
            violations.append("disallowed_setup_prestate_mutation")
        if _SOL_IMPORT_STMT_RE.search(clean_src):
            violations.append("disallowed_external_import")

        for c_name_h, (c_kind_h, _, bodies_to_check) in _parse_solidity_contract_closures(
            clean_src, include_library=True
        ).items():
            is_harness_suite = (
                c_kind_h == "library"
                or c_name_h.startswith(("Verify_", "AgentVerify_"))
                or any(_SOL_TEST_FN_RE.search(b_txt) is not None for b_txt in bodies_to_check)
            )
            if is_harness_suite:
                for chk_body in bodies_to_check:
                    if _SOL_CONSTRUCTOR_RE.search(chk_body):
                        violations.append("disallowed_harness_constructor_prestate")
                    for stmt in _top_level_sol_statements(chk_body):
                        m_eq = _SOL_SINGLE_EQ_RE.search(stmt)
                        if not m_eq:
                            continue
                        lhs = stmt[: m_eq.start()]
                        rhs = stmt[m_eq.end() :]
                        if not _SOL_CONSTANT_KW_RE.search(lhs):
                            violations.append("disallowed_harness_state_initializer")
                            continue
                        rhs_no_str = _SOL_QUOTED_STR_RE.sub('""', rhs)
                        if (
                            _SOL_NEW_KW_RE.search(rhs_no_str)
                            or "{" in rhs_no_str
                            or _SOL_MEMBER_ACCESS_RE.search(rhs_no_str)
                        ):
                            violations.append("disallowed_harness_state_initializer")
                    if (
                        _SOL_ADDR_THIS_RE.search(chk_body)
                        or _SOL_SELFBALANCE_RE.search(chk_body)
                        or any(_SOL_ASM_SELF_RE.search(asm_h) for asm_h in _extract_assembly_blocks(chk_body))
                    ):
                        violations.append("disallowed_harness_self_reference")
                    if c_kind_h != "library" and _SOL_CALLBACK_FN_RE.search(chk_body):
                        violations.append("disallowed_harness_callback_entrypoint")

        vm_vars: Set[str] = {"vm", "cheats", "hevm"}
        for m in _VM_VAR_DECL_RE.finditer(clean_src):
            vm_vars.add(m.group(1))
        for m in _VM_CAST_ASSIGN_RE.finditer(clean_src):
            vm_vars.add(m.group(1))

        for line in clean_src.splitlines():
            if _HEVM_HEX_RE.search(line) and "Vm(" not in line:
                m_var = _SOL_HEVM_VAR_LINE_RE.search(line)
                if m_var:
                    vm_vars.add(m_var.group(1))

        call_re, _, vm_word_re = _compiled_vm_var_regexes(tuple(sorted(vm_vars)))
        for rx, check_lowlevel in ((call_re, True), (_VM_INLINE_CALL_RE, False)):
            for m in rx.finditer(clean_src):
                fn_name = m.group(1)
                if check_lowlevel and fn_name in ("call", "staticcall", "delegatecall", "callcode"):
                    violations.append(f"disallowed_lowlevel_vm_call:{fn_name}")
                elif forbid_inline_fork and fn_name in _INLINE_FORK_CALLS:
                    violations.append(f"disallowed_inline_fork:{fn_name}")
                elif fn_name not in ALLOWED_VM_CALLS:
                    violations.append(f"disallowed_vm_call:{fn_name}")

        if allowed_caller:
            norm_c0 = _norm_addr(allowed_caller)
            const_addrs: Dict[str, str] = {}
            for cm in _SOL_CONST_ADDR_DECL_RE.finditer(clean_src):
                c_ident = cm.group(1)
                c_rhs = _unwrap_sol_addr_expr(cm.group(2))
                if _SOL_FULL_HEX_ADDR_RE.fullmatch(c_rhs):
                    na_decl = f"0x{int(c_rhs, 16):040x}"
                    if c_ident in const_addrs and const_addrs[c_ident] != na_decl:
                        const_addrs[c_ident] = "__CONFLICT__"
                    else:
                        const_addrs[c_ident] = na_decl
                else:
                    const_addrs[c_ident] = "__NONCONST__"
            for arg_txt, closed_ok in _iter_sol_prank_calls(clean_src, sorted(vm_vars)):
                if not closed_ok:
                    violations.append("disallowed_malformed_prank_args")
                    continue
                try:
                    raw_args = _split_top_level_csv(arg_txt, open_chars="([", close_chars=")]", strict=True)
                except ABIError:
                    violations.append("disallowed_malformed_prank_args")
                    continue
                if not raw_args:
                    violations.append("disallowed_empty_prank_caller")
                elif forbid_inline_fork and len(raw_args) != 2:
                    violations.append("disallowed_single_arg_prank_missing_tx_origin")
                for arg_item in raw_args:
                    core_arg = _unwrap_sol_addr_expr(arg_item)
                    if _SOL_FULL_HEX_ADDR_RE.fullmatch(core_arg):
                        na = f"0x{int(core_arg, 16):040x}"
                        if norm_c0 and na != norm_c0:
                            violations.append(f"disallowed_prank_caller:{na}")
                    elif _SOL_SIMPLE_IDENT_RE.fullmatch(core_arg):
                        na_c = const_addrs.get(core_arg, "")
                        if not na_c or na_c.startswith("__"):
                            violations.append(f"disallowed_dynamic_prank_caller:{core_arg or 'expr'}")
                        elif norm_c0 and na_c != norm_c0:
                            violations.append(f"disallowed_prank_caller:{na_c}")
                    else:
                        violations.append(f"disallowed_dynamic_prank_caller:{(core_arg or arg_item)[:32] or 'expr'}")

        if _LOWLEVEL_HEVM_RE.search(clean_src):
            violations.append("disallowed_lowlevel_hevm_call")

        for asm_body in _extract_assembly_blocks(clean_src):
            if _HEVM_HEX_RE.search(asm_body) or vm_word_re.search(asm_body):
                violations.append("disallowed_assembly_hevm_access")
            if _SOL_ASM_LOG_RE.search(asm_body):
                violations.append("disallowed_assembly_raw_log")

    if compiled_bytecode:
        eff_allowed_sels = (
            (ALLOWED_VM_SELECTORS - _INLINE_FORK_SELECTORS - _SINGLE_ARG_PRANK_SELECTORS)
            if forbid_inline_fork
            else ALLOWED_VM_SELECTORS
        )
        eff_forbidden_sels = (
            (_FORBIDDEN_VM_SELECTORS | _INLINE_FORK_SELECTORS | _SINGLE_ARG_PRANK_SELECTORS)
            if forbid_inline_fork
            else _FORBIDDEN_VM_SELECTORS
        )
        dis = _disassemble(compiled_bytecode)
        hevm_bytes = bytes.fromhex(HEVM_ADDRESS_LOWER[2:])
        block_stop_ops = {"CALL", "STATICCALL", "DELEGATECALL", "CALLCODE", "RETURN", "REVERT", "STOP", "JUMP", "JUMPI", "JUMPDEST"}
        call_stop_ops = {"CALL", "STATICCALL", "DELEGATECALL", "CALLCODE", "RETURN", "REVERT", "STOP"}
        for idx, (_, nm, imm) in enumerate(dis):
            if nm == "PUSH20" and imm == hevm_bytes:
                start_i = idx
                while start_i > max(0, idx - 24):
                    if dis[start_i - 1][1] in block_stop_ops:
                        break
                    start_i -= 1
                end_i = idx + 1
                while end_i < min(len(dis), idx + 64):
                    if dis[end_i][1] in call_stop_ops:
                        end_i += 1
                        break
                    end_i += 1
                window = dis[start_i:end_i]
                has_call_op = any(w_nm in {"CALL", "STATICCALL", "DELEGATECALL", "CALLCODE"} for _, w_nm, _ in window[idx - start_i :])
                if not has_call_op:
                    continue
                cand_sels: List[str] = []
                abi_head_sels: List[str] = []
                for w_i, (_, w_nm, w_imm) in enumerate(window):
                    if w_nm == "PUSH4" and len(w_imm) == 4:
                        sel = "0x" + w_imm.hex().lower()
                        if sel == "0xffffffff":
                            continue
                        cand_sels.append(sel)
                        tail_ops = window[w_i + 1 : w_i + 5]
                        has_shl_e0 = any(
                            t_nm == "SHL" for _, t_nm, _ in tail_ops
                        ) and any(
                            t_nm == "PUSH1" and t_imm == b"\xe0" for _, t_nm, t_imm in tail_ops
                        )
                        has_mul_29 = any(
                            t_nm == "MUL" for _, t_nm, _ in tail_ops
                        ) and any(
                            t_nm == "PUSH29" and t_imm == (b"\x01" + b"\x00" * 28) for _, t_nm, t_imm in tail_ops
                        )
                        if has_shl_e0 or has_mul_29:
                            abi_head_sels.append(sel)
                    elif w_nm == "PUSH32" and len(w_imm) == 32 and w_imm[4:] == b"\x00" * 28:
                        sel = "0x" + w_imm[:4].hex().lower()
                        if sel in ("0x00000000", "0xffffffff"):
                            continue
                        cand_sels.append(sel)
                        abi_head_sels.append(sel)
                if not cand_sels:
                    violations.append("disallowed_untyped_bytecode_hevm_call")
                else:
                    bad_sels: List[str] = []
                    bad_sel_set: Set[str] = set()
                    for s in cand_sels:
                        if s in eff_forbidden_sels:
                            _append_unique(bad_sels, bad_sel_set, s)
                    if abi_head_sels:
                        for s in abi_head_sels:
                            if s not in eff_allowed_sels:
                                _append_unique(bad_sels, bad_sel_set, s)
                    elif not any(s in eff_allowed_sels for s in cand_sels):
                        for s in cand_sels:
                            _append_unique(bad_sels, bad_sel_set, s)
                    for bs in bad_sels:
                        violations.append(f"disallowed_bytecode_vm_selector:{bs}")

    return len(violations) == 0, sorted(set(violations))


def _scan_compiled_out_dir_allowlist(
    out_dir: Path,
    target_sol_name: str,
    forbid_inline_fork: bool = False,
) -> Tuple[bool, List[str]]:
    """forge 컴파일 산출물(out/<target_sol_name>/*.json)의 바이트코드 치트코드 화이트리스트 및 EIP-170/EIP-3860 크기 한도 검증."""
    sol_out = out_dir / target_sol_name
    if not sol_out.is_dir():
        return True, []
    all_violations: List[str] = []
    is_harness_exempt = ("Verify_", "AgentVerify_", "Vm", "IERC20")
    forbidden_init_ops = frozenset({
        "CALL", "DELEGATECALL", "CALLCODE", "CREATE", "CREATE2",
        "SELFDESTRUCT", "SSTORE", "TSTORE",
    })
    for jf in sol_out.glob("*.json"):
        try:
            doc = json.loads(jf.read_text(encoding="utf-8", errors="replace"))
            dep_obj = doc.get("deployedBytecode")
            dep_hex = dep_obj.get("object", "") if isinstance(dep_obj, dict) else ""
            dep_bytes = _hex_to_bytes(dep_hex) if isinstance(dep_hex, str) and len(dep_hex) > 4 else b""
            abi_list = doc.get("abi")
            has_test_abi = isinstance(abi_list, list) and any(
                isinstance(item, dict)
                and item.get("type") == "function"
                and (
                    str(item.get("name", "")).startswith(("test", "invariant"))
                    or str(item.get("name", "")) == "setUp"
                )
                for item in abi_list
            )
            is_harness_contract = jf.stem.startswith(("Verify_", "AgentVerify_")) or has_test_abi
            for key in ("deployedBytecode", "bytecode"):
                b_obj = doc.get(key)
                raw_hex = b_obj.get("object", "") if isinstance(b_obj, dict) else ""
                if isinstance(raw_hex, str) and len(raw_hex) > 4:
                    b_bytes = _hex_to_bytes(raw_hex)
                    if not jf.stem.startswith(is_harness_exempt):
                        if key == "deployedBytecode" and len(b_bytes) > 24_576:
                            all_violations.append(f"eip170_runtime_size_exceeded:{jf.stem}:{len(b_bytes)}")
                        elif key == "bytecode" and len(b_bytes) > 49_152:
                            all_violations.append(f"eip3860_initcode_size_exceeded:{jf.stem}:{len(b_bytes)}")
                    if key == "bytecode" and is_harness_contract and len(b_bytes) > len(dep_bytes):
                        init_bytes = b_bytes[: len(b_bytes) - len(dep_bytes)] if dep_bytes else b_bytes
                        if any(nm in forbidden_init_ops for _, nm, _ in _disassemble(init_bytes)):
                            all_violations.append(f"disallowed_harness_initcode_side_effect:{jf.stem}")
                    ok, v_list = verify_cheatcode_allowlist(
                        "",
                        compiled_bytecode=b_bytes,
                        forbid_inline_fork=forbid_inline_fork,
                    )
                    if not ok:
                        all_violations.extend(v_list)
        except Exception:
            continue
    return len(all_violations) == 0, sorted(set(all_violations))


def _deterministic_caller_candidates(
    chain: str,
    exclude_addrs: Optional[Sequence[str]] = None,
) -> List[str]:
    """체인별 고엔트로피 결정론적 무상태 호출자(c_0) 후보군 산출 (프로토콜 폐포·인프라·degenerate 주소와의 충돌 원천 배제)."""
    c = _norm_chain(chain)
    cid = CHAIN_IDS.get(c, 1)
    excl = {nx for x in (exclude_addrs or []) if (nx := _norm_addr(x))}
    excl |= _DEGENERATE_CALLER_ADDRS
    excl |= _PUBLIC_PERMISSIONLESS_CALLERS
    excl.add("0x7fa9385be102ac3eac297483dd6233d62b3e1496")
    excl |= _infra_addresses_for_chain(c)
    out: List[str] = []
    seed_domain = _keccak256(f"EVM_ZERO_STATE_ENTROPY_V2:{c}:{cid}:0x9e3779b97f4a7c15f39cc0605cedc834".encode("utf-8"))
    for idx in range(32):
        r1 = _keccak256(seed_domain + idx.to_bytes(8, "big") + cid.to_bytes(8, "big"))
        digest = _keccak256(r1 + seed_domain)
        cand = "0x" + digest[12:32].hex().lower()
        if cand not in excl and int(cand, 16) > 0x10000:
            out.append(cand)
    if not out:
        out.append("0x1000000000000000000000000000000000013370")
    return out


def select_zero_state_caller(
    router: RPCRouter,
    chain: str,
    block_pin: int,
    exclude_addrs: Optional[Sequence[str]] = None,
    check_tokens: Optional[Sequence[str]] = None,
) -> str:
    """감사 기준 블록(block_pin)에서 balance==0, nonce==0, code=='0x', 그리고 주요 ERC-20 잔고==0 조건을 만족하는 무상태 호출자 선택."""
    c = _norm_chain(chain)
    btag = hex(block_pin) if block_pin > 0 else "latest"
    candidates = _deterministic_caller_candidates(c, exclude_addrs=exclude_addrs)
    if block_pin <= 0:
        return candidates[0]
    toks_to_check = list(dict.fromkeys(nt for t in (check_tokens or []) if (nt := _norm_addr(t))))
    for cand in candidates:
        try:
            cs_cand = _checksum(cand)
            res = router.batch_call(
                c,
                [
                    ("eth_getBalance", [cs_cand, btag]),
                    ("eth_getTransactionCount", [cs_cand, btag]),
                    ("eth_getCode", [cs_cand, btag]),
                ],
                block_pin=block_pin,
                need_archive=True,
            )
            if (
                len(res) == 3
                and all(isinstance(res[i], str) and str(res[i]).startswith("0x") for i in range(3))
                and len(str(res[0])) > 2
                and len(str(res[1])) > 2
            ):
                bal = int(str(res[0]), 16)
                nonce = int(str(res[1]), 16)
                code = _hex_to_bytes(res[2])
                if bal == 0 and nonce == 0 and len(code) == 0:
                    if toks_to_check:
                        cand_padded = bytes(12) + bytes.fromhex(cand[2:])
                        subcalls = [(tk, bytes.fromhex("70a08231") + cand_padded) for tk in toks_to_check]
                        has_tok_bal = False
                        for off_tk in range(0, len(subcalls), 64):
                            chunk_sc = subcalls[off_tk : off_tk + 64]
                            mc_res = router.multicall3(c, chunk_sc, block_pin)
                            if mc_res is not None and len(mc_res) == len(chunk_sc):
                                if any(
                                    ok_b and len(ret_b) >= 32 and int.from_bytes(ret_b[:32], "big") > 0
                                    for ok_b, ret_b in mc_res
                                ):
                                    has_tok_bal = True
                                    break
                        if has_tok_bal:
                            continue
                    return cand
        except Exception:
            continue
    return candidates[0]


_OSAKA_EVM_CHAINS: FrozenSet[str] = frozenset({"ethereum"})
_PRAGUE_EVM_CHAINS: FrozenSet[str] = frozenset({
    "optimism", "base", "unichain", "ink", "worldchain", "mode", "zora", "soneium",
    "swellchain", "lisk", "fraxtal", "bob", "bsc", "opbnb", "gnosis", "arbitrum",
    "berachain", "sonic", "polygon",
})


def _target_foundry_evm_version(rpc_endpoints: Dict[str, str], explicit_evm_version: str = "") -> str:
    """대상 체인 활성 런타임 하드포크 사양(Osaka/Fusaka · Prague/Pectra · Cancun)에 정합하는 Foundry EVM 타겟 산출."""
    exp = explicit_evm_version.strip().lower()
    if exp in ("osaka", "prague", "cancun", "shanghai", "paris"):
        return exp
    chains = {_norm_chain(k) for k in (rpc_endpoints or {}).keys() if str(k).strip()}
    if not chains or chains <= _OSAKA_EVM_CHAINS:
        return "osaka"
    if chains <= (_OSAKA_EVM_CHAINS | _PRAGUE_EVM_CHAINS):
        return "prague"
    return "cancun"


def ensure_clean_forge_workspace(
    rpc_endpoints: Dict[str, str],
    slug: str = "_shared",
    offline: bool = False,
    evm_version: str = "",
) -> Path:
    """
    프로토콜별 격리 Foundry 워크스페이스(audit_artifacts/<slug>/forge) 초기화 및 foundry.toml 작성:
    - 로컬 `tools/foundry/solc.exe` 고정(`auto_detect_solc = false`)으로 외부 컴파일러 다운로드 원천 차단
    - 대상 체인 활성 하드포크(`osaka`/`prague`/`cancun`) 설정(`forge`가 `solc 0.8.28` 상한 `prague`로 자동 컴파일 후 활성 런타임으로 실행)
    - `no_storage_caching = true`, `cache_path = "cache"`, `out = "out"`으로 OS 홈 디렉토리(`~/.foundry`) 오염 차단
    """
    clean_s = _norm_slug(slug) or "_shared"
    ws = ARTIFACT_ROOT / clean_s / "forge"
    (ws / "src").mkdir(parents=True, exist_ok=True)
    (ws / "test").mkdir(parents=True, exist_ok=True)
    (ws / "cache").mkdir(parents=True, exist_ok=True)
    (ws / "out").mkdir(parents=True, exist_ok=True)

    eff_evm_ver = _target_foundry_evm_version(rpc_endpoints, explicit_evm_version=evm_version)
    lines = [
        "[profile.default]",
        'src = "src"',
        'test = "test"',
        'out = "out"',
        'cache_path = "cache"',
        'libs = ["lib"]',
        f'evm_version = "{eff_evm_ver}"',
        "optimizer = true",
        "optimizer_runs = 200",
        "via_ir = false",
        "no_storage_caching = true",
        "fs_permissions = []",
    ]
    if SOLC_BIN.is_file():
        lines.append(f'solc = "{SOLC_BIN.resolve().as_posix()}"')
        lines.append("auto_detect_solc = false")
    else:
        lines.append("auto_detect_solc = true")
    lines.append("offline = true")
    lines.extend(["", "[rpc_endpoints]"])
    for ch_name, url in sorted(rpc_endpoints.items()):
        if url:
            safe_url = url.replace('"', "")
            lines.append(f'{ch_name} = "{safe_url}"')
    (ws / "foundry.toml").write_text("\n".join(lines) + "\n", encoding="utf-8")
    _write_json_atomic(ws / "_isolated_env.json", _isolated_subproc_env(ws))
    return ws


def _render_leg_invocation_solidity(
    target_expr: str,
    sel_hex: str,
    witness: Union[int, str],
    caller_expr: str,
    abi_types: Sequence[str],
    var_prefix: str,
) -> str:
    """
    단일 leg에 대해 ABI 시그니처 또는 다중 표준 인자 템플릿 생성.
    - solc 0.8.28 'Stack too deep'을 원천 방지하기 위해 블록 스코프(`{ bool _ok; ... }`)와 단일 로컬 변수만 사용한다.
    """
    if sel_hex == "fallback" or not sel_hex.startswith("0x") or len(sel_hex) != 10:
        return f'            {{ (bool _ok, ) = {target_expr}.call(""); _ok; }}'
    sc = sel_hex[2:]
    if abi_types and not _abi_requires_agent_reasoning(abi_types):
        args_list: List[str] = []
        for t in abi_types:
            ts = t.strip()
            if ts == "address":
                args_list.append(caller_expr)
            elif ts == "bool":
                args_list.append("true")
            elif ts.startswith("uint"):
                args_list.append(f"uint256({witness})")
            elif ts.startswith("int"):
                args_list.append(f"int256(uint256({witness}))")
            elif ts.startswith("bytes"):
                args_list.append("bytes32(0)")
            else:
                args_list.append(f"uint256({witness})")
        arg_str = ", ".join(args_list)
        return (
            f"            {{ (bool _ok, ) = {target_expr}.call("
            f'abi.encodeWithSelector(bytes4(hex"{sc}"), {arg_str})); _ok; }}'
        )
    return "\n".join(
        [
            "            {",
            f'                (bool _ok, ) = {target_expr}.call(hex"{sc}");',
            f'                if (!_ok) {{ (_ok, ) = {target_expr}.call(abi.encodeWithSelector(bytes4(hex"{sc}"), uint256({witness}))); }}',
            f'                if (!_ok) {{ (_ok, ) = {target_expr}.call(abi.encodeWithSelector(bytes4(hex"{sc}"), {caller_expr}, uint256({witness}))); }}',
            f'                if (!_ok) {{ (_ok, ) = {target_expr}.call(abi.encodeWithSelector(bytes4(hex"{sc}"), uint256({witness}), {caller_expr}, {caller_expr})); }}',
            "            }",
        ]
    )


_SOLIDITY_SPDX_AND_VM_HEADER: str = """// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface Vm {
    function prank(address msgSender) external;
    function prank(address msgSender, address txOrigin) external;
    function startPrank(address msgSender) external;
    function startPrank(address msgSender, address txOrigin) external;
    function stopPrank() external;
    function assume(bool condition) external pure;
    function recordLogs() external;
}"""


_NON_IDENT_CHAR_RE: re.Pattern[str] = re.compile(r"[^A-Za-z0-9_]")


def _safe_solidity_ident(slug: str) -> str:
    return _NON_IDENT_CHAR_RE.sub("_", slug) or "Protocol"


_SUPPORTED_HARNESS_DEX_KINDS: FrozenSet[str] = frozenset(
    {"v2", "solidly_v", "solidly_s", "v3", "algebra", "curve"}
)
_SUPPORTED_HARNESS_UNWIND_KINDS: FrozenSet[str] = frozenset({"lp_token"})
_SUPPORTED_HARNESS_REDEEM_KINDS: FrozenSet[str] = frozenset(
    {"redeem_erc4626", "redeem_atoken", "redeem_ctoken"}
)


def _harness_benchmark_set(chain: str) -> Set[str]:
    """
    `judge_conservation_accounting` 라이브 모드 기준과 동일하게
    네이티브/Wrapped Native/체인 스테이블만 벤치마크 자산으로 분류한다.
    (CHAIN_BLUECHIPS는 DEX 자동 청산 대상에 포함하여 라이브 미확정 차단 사각지대를 제거.)
    """
    norm_c = _norm_chain(chain)
    bset: Set[str] = set(NATIVE_ALIAS_TOKENS_BY_CHAIN.get(norm_c, frozenset()))
    bset.add("0x0000000000000000000000000000000000000000")
    wn_addr = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(norm_c, ""))
    if wn_addr:
        bset.add(wn_addr)
    bset.update(_norm_chain_stables_set(norm_c))
    return bset


def _make_dex_route_step(
    tk_n: str,
    quote_n: str,
    pool_n: str,
    entry: Dict[str, Any],
    slot_by_addr: Dict[str, int],
) -> Optional[Dict[str, Any]]:
    dex_kind = str(entry.get("dex_kind") or "").strip().lower()
    if (
        not tk_n
        or not quote_n
        or not pool_n
        or pool_n == quote_n
        or quote_n == tk_n
        or tk_n not in slot_by_addr
        or quote_n not in slot_by_addr
        or dex_kind not in _SUPPORTED_HARNESS_DEX_KINDS
    ):
        return None
    ci = int(entry.get("curve_i") or 0)
    cj = int(entry.get("curve_j") or 0)
    if dex_kind == "curve" and (ci == cj or not (0 <= ci < 8 and 0 <= cj < 8)):
        return None
    return {
        "token": _checksum(tk_n),
        "token_slot": slot_by_addr[tk_n],
        "pool": _checksum(pool_n),
        "quote": _checksum(quote_n),
        "quote_slot": slot_by_addr[quote_n],
        "dex_kind": dex_kind,
        "curve_i": ci,
        "curve_j": cj,
        "curve_underlying": bool(entry.get("curve_underlying")),
        "v3_fee": int(entry.get("v3_fee") or 0),
        "solidly_stable": bool(entry.get("solidly_stable")),
    }


def _build_harness_liquidation_routes(
    norm_c: str,
    tok_list: Sequence[str],
    exit_routes: Optional[Dict[str, Dict[str, Any]]],
    max_routes: int = 6,
) -> List[Dict[str, Any]]:
    """
    모니터링 대상 토큰(`tok_list`) 중 라이브 정산 벤치마크(WNATIVE/체인 스테이블)가 아닌
    블루칩·장기·LP·영수증 토큰에 대해 검증된 온체인 DEX 스왑, LP 소각 언와인드, 또는 ERC-4626/Aave/Compound 상환 경로를 추출한다.
    출력 토큰이 `tok_list`에 포함된 경로만 선택하여 사후 회계 차액 검증 정합성을 보장한다.
    """
    if not exit_routes or not tok_list:
        return []
    slot_by_addr: Dict[str, int] = {_norm_addr(tk): idx + 1 for idx, tk in enumerate(tok_list) if _norm_addr(tk)}
    benchmark_set = _harness_benchmark_set(norm_c)

    sorted_items: List[Tuple[float, str, Dict[str, Any]]] = []
    for raw_k, raw_v in exit_routes.items():
        tk_n = _norm_addr(raw_k)
        if not tk_n or not isinstance(raw_v, dict) or bool(raw_v.get("paused")):
            continue
        if tk_n in benchmark_set or tk_n not in slot_by_addr:
            continue
        sorted_items.append((float(raw_v.get("realizable_usd") or 0.0), tk_n, raw_v))
    sorted_items.sort(key=lambda item: (-item[0], item[1]))

    routes: List[Dict[str, Any]] = []
    for _, tk_n, entry in sorted_items:
        dex_kind = str(entry.get("dex_kind") or "").strip().lower()
        pool = _norm_addr(entry.get("pool") or "")
        quote = _norm_addr(entry.get("quote_token") or "")
        if not pool or not quote or quote not in slot_by_addr or quote == tk_n:
            continue
        if dex_kind in _SUPPORTED_HARNESS_DEX_KINDS:
            step_r = _make_dex_route_step(tk_n, quote, pool, entry, slot_by_addr)
            if step_r is not None:
                if quote not in benchmark_set:
                    q_exit = exit_routes.get(quote)
                    if isinstance(q_exit, dict) and not bool(q_exit.get("paused")):
                        qe_pool = _norm_addr(q_exit.get("pool") or "")
                        qe_quote = _norm_addr(q_exit.get("quote_token") or "")
                        qe_step = _make_dex_route_step(quote, qe_quote, qe_pool, q_exit, slot_by_addr)
                        if qe_step is not None and qe_quote in benchmark_set:
                            step_r["hop2"] = qe_step
                routes.append(step_r)
        elif dex_kind in _SUPPORTED_HARNESS_UNWIND_KINDS:
            if pool == quote:
                continue
            lp_rec: Dict[str, Any] = {
                "token": _checksum(tk_n),
                "token_slot": slot_by_addr[tk_n],
                "pool": _checksum(pool),
                "quote": _checksum(quote),
                "quote_slot": slot_by_addr[quote],
                "dex_kind": "lp_token",
            }
            if quote not in benchmark_set:
                q_exit = exit_routes.get(quote)
                if isinstance(q_exit, dict) and not bool(q_exit.get("paused")):
                    qe_pool = _norm_addr(q_exit.get("pool") or "")
                    qe_quote = _norm_addr(q_exit.get("quote_token") or "")
                    qe_step = _make_dex_route_step(quote, qe_quote, qe_pool, q_exit, slot_by_addr)
                    if qe_step is not None and qe_quote in benchmark_set:
                        lp_rec["quote_exit"] = qe_step
            lp_other = _norm_addr(entry.get("lp_other_token") or entry.get("other_token") or "")
            if lp_other and lp_other not in (tk_n, quote):
                lp_rec["other"] = _checksum(lp_other)
                lp_rec["other_slot"] = slot_by_addr.get(lp_other, 0)
                lp_rec["other_is_benchmark"] = lp_other in benchmark_set
                if lp_other not in benchmark_set:
                    other_exit = exit_routes.get(lp_other)
                    if isinstance(other_exit, dict) and not bool(other_exit.get("paused")):
                        oe_pool = _norm_addr(other_exit.get("pool") or "")
                        oe_quote = _norm_addr(other_exit.get("quote_token") or "")
                        oe_step = _make_dex_route_step(lp_other, oe_quote, oe_pool, other_exit, slot_by_addr)
                        if oe_step is not None and oe_quote in benchmark_set:
                            lp_rec["other_exit"] = oe_step
            routes.append(lp_rec)
        elif dex_kind in _SUPPORTED_HARNESS_REDEEM_KINDS:
            redeem_target = _norm_addr(entry.get("redeem_target") or ("" if dex_kind == "redeem_atoken" else tk_n))
            if dex_kind == "redeem_atoken" and (not redeem_target or redeem_target == tk_n):
                continue
            if not redeem_target:
                continue
            route_rec: Dict[str, Any] = {
                "token": _checksum(tk_n),
                "token_slot": slot_by_addr[tk_n],
                "pool": _checksum(redeem_target),
                "quote": _checksum(quote),
                "quote_slot": slot_by_addr[quote],
                "dex_kind": dex_kind,
            }
            und = entry.get("underlying_exit")
            if isinstance(und, dict) and quote not in benchmark_set:
                u_pool = _norm_addr(und.get("pool") or "")
                u_quote = _norm_addr(und.get("quote_token") or "")
                u_kind = str(und.get("dex_kind") or "").strip().lower()
                u_ci = int(und.get("curve_i") or 0)
                u_cj = int(und.get("curve_j") or 0)
                u_crv_ok = u_kind != "curve" or (u_ci != u_cj and 0 <= u_ci < 8 and 0 <= u_cj < 8)
                if (
                    u_pool
                    and u_quote
                    and u_pool != u_quote
                    and u_quote != quote
                    and u_quote in slot_by_addr
                    and u_kind in _SUPPORTED_HARNESS_DEX_KINDS
                    and u_crv_ok
                ):
                    route_rec["hop2"] = {
                        "token": _checksum(quote),
                        "token_slot": slot_by_addr[quote],
                        "pool": _checksum(u_pool),
                        "quote": _checksum(u_quote),
                        "quote_slot": slot_by_addr[u_quote],
                        "dex_kind": u_kind,
                        "curve_i": u_ci,
                        "curve_j": u_cj,
                        "curve_underlying": bool(und.get("curve_underlying")),
                    }
            routes.append(route_rec)
        if len(routes) >= max_routes:
            break
    return routes


def _routes_need_dex_liquidator(routes: Sequence[Dict[str, Any]]) -> bool:
    need_kinds = _SUPPORTED_HARNESS_DEX_KINDS | _SUPPORTED_HARNESS_UNWIND_KINDS
    for r in routes:
        if r.get("dex_kind") in need_kinds:
            return True
        if isinstance(r.get("hop2"), dict) and r["hop2"].get("dex_kind") in need_kinds:
            return True
    return False


