def _native_unit_symbol(chain: str) -> str:
    c = _norm_chain(chain)
    if c in _NATIVE_UNIT_SYMBOLS:
        return _NATIVE_UNIT_SYMBOLS[c]
    if c in _BTC_NATIVE_CHAINS or c in ("rsk", "bsquared", "bevm", "ailayer", "btr"):
        return "BTC"
    return "ETH"


EIP7825_TX_GAS_CAP: int = 16_777_216

_ROLLUP_L1_FEE_CHAINS: FrozenSet[str] = frozenset({
    "optimism", "base", "mode", "zora", "blast", "fraxtal", "lisk", "worldchain",
    "ink", "unichain", "soneium", "swellchain", "bob", "arbitrum", "scroll",
    "mantle", "manta", "kroma", "opbnb", "cyber", "redstone", "shape",
    "superseed", "polynomial", "mint", "orderly", "lyra", "ancient8", "boba",
})


def _estimate_rollup_l1_fee_wei(
    router: Optional[RPCRouter],
    chain: str,
    block_pin: int,
    calldata_len: int = 256,
) -> int:
    """롤업 체인의 기준 블록(block_pin) 온체인 L1 데이터 수수료(wei) 실측 조회 (실RPC 실패 시 -1 fail-open)."""
    c = _norm_chain(chain)
    if c not in _ROLLUP_L1_FEE_CHAINS or block_pin <= 0:
        return 0
    if router is not None:
        btag = hex(int(block_pin))
        if c == "arbitrum":
            try:
                raw = router.call(
                    c,
                    "eth_call",
                    [{"to": "0x000000000000000000000000000000000000006C", "data": "0x41b247a8"}, btag],
                    block_pin=block_pin,
                    need_archive=True,
                )
                rb = _hex_to_bytes(raw) if isinstance(raw, str) else b""
                if len(rb) >= 64:
                    per_l2_tx = int.from_bytes(rb[0:32], "big")
                    per_byte_wei = int.from_bytes(rb[32:64], "big")
                    if per_l2_tx + per_byte_wei > 0:
                        return max(21_000 * 100_000, per_l2_tx + per_byte_wei * max(calldata_len, 128))
            except Exception:
                pass
        else:
            try:
                pay_len = min(max(int(calldata_len), 64), 16384)
                if pay_len <= 55:
                    rlp_data = bytes([0x80 + pay_len]) + (b"\x01" * pay_len)
                elif pay_len <= 255:
                    rlp_data = b"\xb8" + bytes([pay_len]) + (b"\x01" * pay_len)
                else:
                    rlp_data = b"\xb9" + pay_len.to_bytes(2, "big") + (b"\x01" * pay_len)
                tx_body = (
                    b"\x01\x80\x84\x3b\x9a\xca\x00\x84\x3b\x9a\xca\x00\x82\x52\x08"
                    + (b"\x94" + b"\x11" * 20)
                    + b"\x80"
                    + rlp_data
                    + b"\xc0\x80\x80\x80"
                )
                if len(tx_body) <= 255:
                    dummy_tx = b"\x02\xf8" + bytes([len(tx_body)]) + tx_body
                else:
                    dummy_tx = b"\x02\xf9" + len(tx_body).to_bytes(2, "big") + tx_body
                cdata = encode_calldata("0x49948e0e", ["bytes"], [dummy_tx])
                oracle_to = (
                    "0x5300000000000000000000000000000000000002"
                    if c == "scroll"
                    else "0x420000000000000000000000000000000000000F"
                )
                raw = router.call(
                    c,
                    "eth_call",
                    [{"to": oracle_to, "data": cdata}, btag],
                    block_pin=block_pin,
                    need_archive=True,
                )
                rb = _hex_to_bytes(raw) if isinstance(raw, str) else b""
                if len(rb) >= 32:
                    fee_w = int.from_bytes(rb[:32], "big")
                    if fee_w > 0:
                        return fee_w
            except Exception:
                pass
    return -1 if _is_live_real_router(router) else 0


def _verify_wnative_backing(
    router: Optional[RPCRouter],
    chain: str,
    wnative_addr: str,
    block_pin: int,
    required_wei: int = 1,
    wnative_decimals: int = 18,
) -> bool:
    """WNATIVE 컨트랙트의 온체인 네이티브 담보 건전성(eth_getBalance >= max(required_wei, totalSupply_wei))을 기준 블록에서 검증."""
    if block_pin <= 0:
        return True
    if router is None:
        return False
    wn = _norm_addr(wnative_addr)
    if not wn:
        return True
    c = _norm_chain(chain)
    if wn in NATIVE_ALIAS_TOKENS_BY_CHAIN.get(c, frozenset()):
        return True
    btag = hex(int(block_pin))
    try:
        cs_wn = _checksum(wn)
        res = router.batch_call(
            c,
            [
                ("eth_getBalance", [cs_wn, btag]),
                ("eth_call", [{"to": cs_wn, "data": "0x18160ddd"}, btag]),
            ],
            block_pin=block_pin,
            need_archive=True,
        )
        if not res or len(res) < 2 or res[0] is None or res[1] is None:
            return False
        bal_wei = int(str(res[0]), 16) if str(res[0]).startswith("0x") else int(res[0] or 0)
        if bal_wei < max(1, int(required_wei)):
            return False
        ts_bytes = _hex_to_bytes(res[1]) if isinstance(res[1], str) else b""
        if len(ts_bytes) < 32:
            return False
        total_supply = int.from_bytes(ts_bytes[:32], "big")
        w_dec = int(wnative_decimals) if 0 <= int(wnative_decimals) <= 77 else 18
        if total_supply > 0:
            if w_dec < 18:
                if bal_wei < total_supply * (10 ** (18 - w_dec)):
                    return False
            elif w_dec > 18:
                if bal_wei * (10 ** (w_dec - 18)) < total_supply:
                    return False
            elif bal_wei < total_supply:
                return False
        return True
    except Exception:
        return False


@dataclass
class ConservationVerdict:
    verdict: str  # _format_profit_verdict(net_krw) | VERDICT_SAFE | VERDICT_BLOCKED
    gross_usd: float
    gas_usd: float
    flash_fee_usd: float
    net_usd: float
    net_krw: int
    fx_rate_krw: float
    fx_source: str
    corroborated: bool
    mutex_only_rejected: bool
    reason: str
    swap_fee_usd: float = 0.0
    slippage_usd: float = 0.0
    gross_profit_native: str = "0.000000000000000000"
    net_profit_native: str = "0.000000000000000000"
    profit_native_unit: str = "ETH"
    costs: Dict[str, str] = field(default_factory=dict)
    net_usd_exact: str = "0"


def _domain_deltas(
    caller_before: Dict[str, int],
    caller_after: Dict[str, int],
    vault_before: Dict[str, int],
    vault_after: Dict[str, int],
    chain: str = "ethereum",
    decimals_map: Optional[Dict[str, int]] = None,
) -> Tuple[Dict[str, int], Dict[str, int], Dict[str, int]]:
    """
    네이티브와 공식 WNATIVE를 단일 등가 클래스('native', 18-dec wei 기준 정규화)로 통합하여
    1:1 래핑/언래핑에 의한 허위 보존 이득을 0으로 상계하고,
    듀얼 원장 네이티브 별칭 토큰(Celo/Polygon/Metis/zkSync)의 이중 합산을 원천 차단한다.
    """
    c = _norm_chain(chain)
    wnative = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
    alias_set = NATIVE_ALIAS_TOKENS_BY_CHAIN.get(c, frozenset())
    native_keys = {"native", "ETH", "0x0000000000000000000000000000000000000000"}
    w_dec_raw = int((decimals_map or {}).get(wnative, 18)) if wnative else 18
    w_dec = w_dec_raw if 0 <= w_dec_raw <= 77 else 18

    def _agg_snapshot(snap: Dict[str, int]) -> Dict[str, int]:
        has_explicit_native = any(k in native_keys or _norm_addr(k) == "0x0000000000000000000000000000000000000000" for k in snap)
        agg: Dict[str, int] = {}
        for k, v in snap.items():
            nk = _norm_addr(k)
            raw_v = int(v or 0)
            if nk in alias_set:
                if has_explicit_native:
                    continue
                ck = "native"
            elif wnative and nk == wnative:
                ck = "native"
                if w_dec < 18:
                    raw_v = raw_v * (10 ** (18 - w_dec))
                elif w_dec > 18:
                    raw_v = raw_v // (10 ** (w_dec - 18))
            elif k in native_keys or nk == "0x0000000000000000000000000000000000000000":
                ck = "native"
            else:
                ck = nk or k
            agg[ck] = agg.get(ck, 0) + raw_v
        return agg

    cb_agg = _agg_snapshot(caller_before)
    ca_agg = _agg_snapshot(caller_after)
    vb_agg = _agg_snapshot(vault_before)
    va_agg = _agg_snapshot(vault_after)

    caller_gains: Dict[str, int] = {}
    vault_losses: Dict[str, int] = {}
    caller_losses: Dict[str, int] = {}
    all_assets = set(cb_agg.keys()) | set(ca_agg.keys()) | set(vb_agg.keys()) | set(va_agg.keys())
    for asset in sorted(all_assets):
        cb = cb_agg.get(asset, 0)
        ca = ca_agg.get(asset, 0)
        vb = vb_agg.get(asset, 0)
        va = va_agg.get(asset, 0)
        if ca > cb:
            caller_gains[asset] = ca - cb
        elif cb > ca:
            caller_losses[asset] = cb - ca
        if vb > va:
            vault_losses[asset] = vb - va
    if wnative and w_dec > 18:
        sub_scale = 10 ** (w_dec - 18)

        def _exact_native_units(snap: Dict[str, int]) -> int:
            has_exp = any(k in native_keys or _norm_addr(k) == "0x0000000000000000000000000000000000000000" for k in snap)
            tot_u = 0
            for k_s, v_s in snap.items():
                nk_s = _norm_addr(k_s)
                rv_s = int(v_s or 0)
                if nk_s in alias_set:
                    if has_exp:
                        continue
                    tot_u += rv_s * sub_scale
                elif nk_s == wnative:
                    tot_u += rv_s
                elif k_s in native_keys or nk_s == "0x0000000000000000000000000000000000000000":
                    tot_u += rv_s * sub_scale
            return tot_u

        if _exact_native_units(caller_before) > _exact_native_units(caller_after):
            caller_gains.pop("native", None)
            caller_losses["native"] = max(1, caller_losses.get("native", 0))
    return caller_gains, vault_losses, caller_losses


def _corroborate_caller_profit(
    caller_gains: Dict[str, int],
    vault_losses: Dict[str, int],
    storage_Slot_flips: Optional[List[Tuple[int, int, int]]] = None,
) -> Tuple[bool, bool]:
    """가치 보존 법칙(Conservation of Value) 교차 검증 및 ReentrancyGuard(1<->2) 뮤텍스 오탐 필터."""
    if not caller_gains:
        if storage_Slot_flips:
            only_mutex = all((old_v in (1, 2) and new_v in (1, 2)) for _, old_v, new_v in storage_Slot_flips)
            if only_mutex:
                return False, True
        return False, False

    for asset, gain_amt in caller_gains.items():
        loss_amt = vault_losses.get(asset, 0)
        if gain_amt > 0 and loss_amt > 0:
            return True, False
    return False, False


def _is_head_fresh_against_tip(router: Optional[Any], chain: str, block_pin: int, tip_block: int) -> bool:
    """감사/재실행 기준 블록이 최신 헤드 대비 `<= 5블록` 또는 고속 L2 `<= 12초` 이내 신선도(+ 라이브 시 벽시계 지연 방어)를 충족하는지 판정."""
    if block_pin <= 0 or tip_block < block_pin:
        return False
    is_live_r = _is_live_real_router(router)
    ts_tip = 0
    if is_live_r:
        ts_tip = _fetch_block_timestamp(router, chain, tip_block, need_archive=False, timeout=4.0)
        if ts_tip <= 0 or (time.time() - ts_tip) > 300.0:
            return False
    if (tip_block - block_pin) <= MAX_AUDIT_BLOCK_LAG:
        return True
    if ts_tip <= 0:
        ts_tip = _fetch_block_timestamp(router, chain, tip_block, need_archive=False, timeout=4.0)
    if ts_tip <= 0:
        return False
    ts_pin = _fetch_block_timestamp(router, chain, block_pin, need_archive=False, timeout=4.0)
    return bool(ts_pin > 0 and 0 <= (ts_tip - ts_pin) <= 12)


@_with_decimal_prec_100
def _extract_dex_exit_components(
    dex_q: Dict[str, Any],
    fallback_nom_dec: Decimal = _DEC_ZERO,
) -> Optional[Tuple[Decimal, Decimal, Decimal, Decimal, Decimal, Decimal]]:
    """DEX 청산 호가 딕셔너리에서 (pre_swap_usd, fee_usd, slippage_usd, fee_bps, slip_bps, eff_unit_price) 정밀 추출."""
    realizable_dec = max(
        _DEC_ZERO,
        _to_dec(dex_q["realizable_usd_dec"] if "realizable_usd_dec" in dex_q else dex_q.get("realizable_usd", 0.0)),
    )
    if not dex_q.get("exit_liquid", False) or realizable_dec <= _DEC_ZERO:
        return None
    fee_b_dec = max(_DEC_ZERO, _to_dec(dex_q.get("swap_fee_bps", 30)))
    slip_b_dec = max(_DEC_ZERO, _to_dec(dex_q.get("slippage_bps", 0)))
    eff_u_p_dec = _to_dec(
        dex_q["effective_unit_price_dec"]
        if "effective_unit_price_dec" in dex_q
        else dex_q.get("effective_unit_price", 0.0)
    )
    nom_dec = _to_dec(dex_q["nominal_usd_dec"] if "nominal_usd_dec" in dex_q else dex_q.get("nominal_usd", 0.0))
    if nom_dec <= _DEC_ZERO:
        nom_dec = fallback_nom_dec if fallback_nom_dec > _DEC_ZERO else realizable_dec
    depth_dec = _to_dec(dex_q["dex_depth_usd_dec"] if "dex_depth_usd_dec" in dex_q else dex_q.get("dex_depth_usd", 0.0))
    pre_swap_dec = max(
        realizable_dec,
        min(nom_dec, max(realizable_dec, depth_dec * Decimal("2"))) if depth_dec > _DEC_ZERO else nom_dec,
    )
    tot_fric_dec = max(_DEC_ZERO, pre_swap_dec - realizable_dec)
    fee_dec = min(tot_fric_dec, pre_swap_dec * (fee_b_dec / Decimal("10000")))
    slip_dec = max(_DEC_ZERO, tot_fric_dec - fee_dec)
    return pre_swap_dec, fee_dec, slip_dec, fee_b_dec, slip_b_dec, eff_u_p_dec


@_with_decimal_prec_100
def judge_conservation_accounting(
    store: Optional[SQLiteStore],
    chain: str,
    caller_before: Dict[str, int],
    caller_after: Dict[str, int],
    vault_before: Dict[str, int],
    vault_after: Dict[str, int],
    gas_used: int = 150_000,
    gas_price_wei: int = 2_000_000_000,
    flash_principal_usd: float = 0.0,
    flash_fee_bps: float = 0.0,
    storage_slot_flips: Optional[List[Tuple[int, int, int]]] = None,
    decimals_map: Optional[Dict[str, int]] = None,
    prices_map: Optional[Dict[str, float]] = None,
    router: Optional[RPCRouter] = None,
    block_pin: int = 0,
    live_head_block: int = 0,
    allow_offline_fixture: bool = False,
    supply_minted_assets: Optional[Set[str]] = None,
    calldata_len: int = 0,
    flash_fee_already_in_balances: bool = False,
    session_id: str = "",
) -> ConservationVerdict:
    """
    실물 회수 가치 보존 방정식 판정기:
    - 네이티브+WNATIVE 등가 클래스 통합(온체인 담보 건전성 검증 포함) 및 호출자 음수 잔고 변화 차단/차감
    - 10진 고정밀(`Decimal`, `prec=100`) 연산으로 미반올림 순이익 `>= $100.00 USD` 판정 및 원 단위 절사(`ROUND_DOWN`) 정수 산출
    - 블록 지연(`live_head_block - block_pin > 5`), 환율 미확정, 단가/유동성 미확정 시 허위 `"안전"`이 아닌 `"미검증 차단"` 반환
    """
    c = _norm_chain(chain)
    unit_sym = _native_unit_symbol(c)
    offline_mode = bool(allow_offline_fixture or store is None or block_pin <= 0)
    eff_sid = str(session_id or getattr(router, "session_id", "") or "").strip().lower()
    fx_krw_dec, fx_src = _fetch_usd_krw_rate_dec(
        store, allow_offline_fixture=offline_mode, router=router, session_id=eff_sid
    )
    fx_krw = float(fx_krw_dec)

    def _blocked_zero(
        reason_str: str, *, corroborated_flag: bool = False, fx_override: Optional[float] = None
    ) -> ConservationVerdict:
        return ConservationVerdict(
            verdict=VERDICT_BLOCKED,
            gross_usd=0.0,
            gas_usd=0.0,
            flash_fee_usd=0.0,
            net_usd=0.0,
            net_krw=0,
            fx_rate_krw=fx_krw if fx_override is None else fx_override,
            fx_source=fx_src,
            corroborated=corroborated_flag,
            mutex_only_rejected=False,
            reason=reason_str,
            profit_native_unit=unit_sym,
        )

    if live_head_block > 0 and block_pin > 0 and not _is_head_fresh_against_tip(router, c, block_pin, live_head_block):
        return _blocked_zero(f"AUDIT_BLOCK_LAG_EXCEEDED({live_head_block - block_pin}>{MAX_AUDIT_BLOCK_LAG})")

    if fx_krw_dec <= _DEC_ZERO:
        return _blocked_zero("FX_RATE_UNAVAILABLE", fx_override=0.0)

    caller_gains, vault_losses, caller_losses = _domain_deltas(
        caller_before, caller_after, vault_before, vault_after, chain=c, decimals_map=decimals_map
    )
    corroborated, mutex_rejected = _corroborate_caller_profit(caller_gains, vault_losses, storage_slot_flips)

    wnative_c = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c, ""))
    explicit_np_d = _to_dec((prices_map or {}).get("native") or (prices_map or {}).get(wnative_c) or 0)
    if explicit_np_d > _DEC_ZERO and (offline_mode or router is not None):
        np_min_raw_d = explicit_np_d
        np_hi_cand_d = _to_dec((prices_map or {}).get("native_max") or 0)
        if np_hi_cand_d <= _DEC_ZERO and store is not None:
            for np_k in (
                (f"native_usd_max:{c}:{int(block_pin)}" if block_pin > 0 else f"native_usd_max:{c}"),
                f"native_usd_max:{c}",
                f"native_max:{c}",
            ):
                np_hit = store.get_price(np_k, max_age_sec=1800.0)
                if np_hit is not None and _to_dec(np_hit[0]) > _DEC_ZERO:
                    np_hi_cand_d = _to_dec(np_hit[0])
                    break
        if np_hi_cand_d <= _DEC_ZERO and not offline_mode and router is not None:
            _, est_hi_d = _estimate_native_price_interval_dec(
                c, router=router, block_pin=block_pin, allow_offline_fixture=False
            )
            if est_hi_d > _DEC_ZERO:
                np_hi_cand_d = est_hi_d
        np_max_raw_d = max(np_min_raw_d, np_hi_cand_d) if np_hi_cand_d > _DEC_ZERO else np_min_raw_d
    else:
        np_min_raw_d, np_max_raw_d = _estimate_native_price_interval_dec(
            c, router=router, block_pin=block_pin, allow_offline_fixture=offline_mode
        )

    cd_bytes = max(0, int(calldata_len))
    eip7623_floor_gas = (21_000 + 40 * cd_bytes) if cd_bytes > 0 else 21_000
    eff_gas_units = max(int(gas_used), eip7623_floor_gas)

    def _safe_reject(reason_str: str, mutex_rej: bool = False) -> ConservationVerdict:
        eff_np_d = max(_DEC_ZERO, np_max_raw_d)
        gas_nat_d = Decimal(max(eff_gas_units, 21_000) * max(int(gas_price_wei), 100_000)) / (Decimal(10) ** 18)
        gas_usd_d = gas_nat_d * eff_np_d
        flash_fee_d = (
            _DEC_ZERO
            if flash_fee_already_in_balances
            else max(_DEC_ZERO, _to_dec(flash_principal_usd) * (_to_dec(flash_fee_bps) / Decimal("10000")))
        )
        return ConservationVerdict(
            verdict=VERDICT_SAFE,
            gross_usd=0.0,
            gas_usd=float(gas_usd_d.quantize(Decimal("0.000001"), rounding=ROUND_HALF_EVEN)),
            flash_fee_usd=float(flash_fee_d.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN)),
            net_usd=0.0,
            net_krw=0,
            fx_rate_krw=fx_krw,
            fx_source=fx_src,
            corroborated=False,
            mutex_only_rejected=mutex_rej,
            reason=reason_str,
            profit_native_unit=unit_sym,
            net_usd_exact="0",
        )

    if eff_gas_units > EIP7825_TX_GAS_CAP:
        return _safe_reject(f"EIP7825_TX_GAS_CAP_EXCEEDED({eff_gas_units}>{EIP7825_TX_GAS_CAP})")

    if caller_losses:
        return _safe_reject("CALLER_NEGATIVE_ASSET_DELTA_REJECTED")

    if not corroborated:
        return _safe_reject("MUTEX_FLIP_REJECTED" if mutex_rejected else "NO_CORROBORATED_CONSERVATION_GAIN", mutex_rej=mutex_rejected)

    if (np_min_raw_d <= _DEC_ZERO or router is None) and not offline_mode:
        return _blocked_zero("NATIVE_PRICE_UNCONFIRMED_FAIL_OPEN", corroborated_flag=True)
    np_min_dec = max(Decimal("1e-12"), np_min_raw_d)
    np_max_dec = max(np_min_dec, np_max_raw_d)
    native_price_min = float(np_min_dec)

    if not offline_mode and wnative_c:
        w_dec_chk = int((decimals_map or {}).get(wnative_c, 18))
        w_dec_chk = w_dec_chk if 0 <= w_dec_chk <= 77 else 18
        wnative_gain_raw = sum(
            int(v or 0) - int(caller_before.get(k, 0) or 0)
            for k, v in caller_after.items()
            if _norm_addr(k) == wnative_c and int(v or 0) > int(caller_before.get(k, 0) or 0)
        )
        wnative_vloss_raw = sum(
            int(v or 0) - int(vault_after.get(k, 0) or 0)
            for k, v in vault_before.items()
            if _norm_addr(k) == wnative_c and int(v or 0) > int(vault_after.get(k, 0) or 0)
        )
        wnative_exposure_raw = max(wnative_gain_raw, wnative_vloss_raw)
        if wnative_exposure_raw > 0:
            w_sub_scale = 10 ** (w_dec_chk - 18) if w_dec_chk > 18 else 1
            req_wei = (
                wnative_exposure_raw * (10 ** (18 - w_dec_chk))
                if w_dec_chk < 18
                else (((wnative_exposure_raw + w_sub_scale - 1) // w_sub_scale) if w_dec_chk > 18 else wnative_exposure_raw)
            )
            chk_blocks = [block_pin]
            if live_head_block > block_pin:
                chk_blocks.append(live_head_block)
            for chk_b in chk_blocks:
                if not _verify_wnative_backing(
                    router, c, wnative_c, chk_b, required_wei=max(1, req_wei), wnative_decimals=w_dec_chk
                ):
                    return _blocked_zero("WNATIVE_RESERVE_UNCONFIRMED_FAIL_OPEN", corroborated_flag=True)

    l2_exec_wei = max(eff_gas_units, 21_000) * max(int(gas_price_wei), 100_000)
    l1_fee_wei = (
        _estimate_rollup_l1_fee_wei(router, c, block_pin, calldata_len=max(cd_bytes, 256))
        if (c in _ROLLUP_L1_FEE_CHAINS and block_pin > 0)
        else 0
    )
    if l1_fee_wei < 0:
        return _blocked_zero("ROLLUP_L1_FEE_UNCONFIRMED_FAIL_OPEN", corroborated_flag=True)
    np_dec = np_min_dec
    wei_scale_dec = Decimal(10**18)
    gas_native_dec = Decimal(l2_exec_wei + int(l1_fee_wei)) / wei_scale_dec
    gas_usd_dec = gas_native_dec * np_max_dec
    flash_fee_usd_dec = (
        _DEC_ZERO
        if flash_fee_already_in_balances
        else max(
            _DEC_ZERO,
            _to_dec(flash_principal_usd) * (_to_dec(flash_fee_bps) / Decimal("10000")),
        )
    )

    gross_usd_dec = _DEC_ZERO
    swap_fee_usd_dec = _DEC_ZERO
    slippage_usd_dec = _DEC_ZERO
    dec_lookup = decimals_map or {}
    price_lookup = prices_map or {}
    wnative = wnative_c
    stables_norm = _norm_chain_stables_set(c)
    minted_norm = {_norm_addr(x) or str(x) for x in (supply_minted_assets or set()) if x}
    has_unconfirmed_gain_valuation = False

    for asset, gain_amt in sorted(caller_gains.items()):
        conserved_amt = min(gain_amt, vault_losses.get(asset, 0))
        if conserved_amt <= 0:
            continue
        norm_a = _norm_addr(asset)
        is_supply_mint = bool(minted_norm and ((norm_a and norm_a in minted_norm) or str(asset) in minted_norm))
        if asset in ("native", "ETH", "0x0000000000000000000000000000000000000000") or (wnative and norm_a == wnative):
            is_wnative_mint = bool(wnative and wnative in minted_norm)
            if is_supply_mint or is_wnative_mint:
                if router is not None and block_pin > 0 and wnative:
                    w_dec = max(0, min(77, int(dec_lookup.get(wnative, 18))))
                    w_probe_amt = (
                        (int(conserved_amt) * (10 ** w_dec)) // (10 ** 18)
                        if (asset in ("native", "ETH", "0x0000000000000000000000000000000000000000") and w_dec != 18)
                        else int(conserved_amt)
                    )
                    dex_w = probe_dex_exit_liquidity(
                        router,
                        c,
                        wnative,
                        w_probe_amt,
                        w_dec,
                        native_price_min,
                        native_price_min,
                        block_pin,
                        quote_prices_usd=price_lookup,
                        unbacked_supply_mint=True,
                    )
                    w_comp = _extract_dex_exit_components(dex_w)
                    if w_comp is None:
                        has_unconfirmed_gain_valuation = True
                        continue
                    w_pre_dec, w_fee_dec, w_slip_dec, _, _, _ = w_comp
                    gross_usd_dec += w_pre_dec
                    swap_fee_usd_dec += w_fee_dec
                    slippage_usd_dec += w_slip_dec
                    continue
                has_unconfirmed_gain_valuation = True
                continue
            gross_usd_dec += (Decimal(int(conserved_amt)) / wei_scale_dec) * np_min_dec
        else:
            p_usd_d = _to_dec(price_lookup.get(norm_a, 0))
            if p_usd_d <= _DEC_ZERO:
                p_usd_d, _ = _fetch_token_price_usd_dec(
                    store, c, norm_a or asset, router=router, block_pin=block_pin, allow_offline_fixture=offline_mode
                )
            if p_usd_d <= _DEC_ZERO and offline_mode and norm_a in stables_norm:
                p_usd_d = Decimal("1")
            dec = dec_lookup.get(norm_a, 6 if (norm_a in stables_norm and conserved_amt < 10**15) else 18)
            is_benchmark_asset = bool(norm_a in stables_norm or (wnative and norm_a == wnative))
            if not offline_mode and not is_benchmark_asset:
                has_unconfirmed_gain_valuation = True
                continue
            unit_qty_dec = Decimal(int(conserved_amt)) / (Decimal(10) ** int(dec))
            if router is not None and block_pin > 0:
                dex_info = probe_dex_exit_liquidity(
                    router,
                    c,
                    norm_a or asset,
                    conserved_amt,
                    dec,
                    float(max(p_usd_d, _DEC_ZERO)),
                    native_price_min,
                    block_pin,
                    quote_prices_usd=price_lookup,
                    unbacked_supply_mint=is_supply_mint,
                )
                fallback_nom = unit_qty_dec * p_usd_d if p_usd_d > _DEC_ZERO else _DEC_ZERO
                d_comp = _extract_dex_exit_components(dex_info, fallback_nom_dec=fallback_nom)
                if d_comp is None:
                    has_unconfirmed_gain_valuation = True
                    continue
                pre_swap_dec, fee_dec, slip_dec, fee_b_dec, slip_b_dec, eff_u_p_dec = d_comp
                if fee_b_dec == _DEC_ZERO and slip_b_dec == _DEC_ZERO and eff_u_p_dec > _DEC_ZERO and not is_supply_mint:
                    gross_usd_dec += unit_qty_dec * eff_u_p_dec
                    continue
                gross_usd_dec += pre_swap_dec
                swap_fee_usd_dec += fee_dec
                slippage_usd_dec += slip_dec
            elif p_usd_d > _DEC_ZERO and not is_supply_mint:
                gross_usd_dec += unit_qty_dec * p_usd_d
            else:
                has_unconfirmed_gain_valuation = True

    gross_usd_q = float(gross_usd_dec.quantize(Decimal("0.01"), rounding=ROUND_DOWN))
    gas_usd_q = float(gas_usd_dec.quantize(Decimal("0.000001"), rounding=ROUND_HALF_EVEN))
    flash_fee_usd_q = float(flash_fee_usd_dec.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN))
    swap_fee_usd_q = float(swap_fee_usd_dec.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN))
    slippage_usd_q = float(slippage_usd_dec.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN))
    flash_fee_native_dec = flash_fee_usd_dec / np_dec
    gross_native_dec = gross_usd_dec / np_dec
    swap_fee_native_dec = swap_fee_usd_dec / np_dec
    slippage_native_dec = slippage_usd_dec / np_dec
    net_usd_dec = gross_usd_dec - gas_usd_dec - flash_fee_usd_dec - swap_fee_usd_dec - slippage_usd_dec
    net_usd_q = float(
        net_usd_dec.quantize(Decimal("0.01"), rounding=ROUND_DOWN if net_usd_dec >= _DEC_ZERO else ROUND_HALF_EVEN)
    )
    net_native_dec = max(_DEC_ZERO, net_usd_dec / np_dec)
    gross_native_str = _fmt_dec18(gross_native_dec)
    costs_dict = {
        "gas_native": _fmt_dec18(gas_native_dec),
        "flash_loan_fee_native": _fmt_dec18(flash_fee_native_dec),
        "swap_fees_native": _fmt_dec18(swap_fee_native_dec),
        "slippage_native": _fmt_dec18(slippage_native_dec),
    }

    if net_usd_dec >= PROFIT_FLOOR_DEC:
        net_krw = int((net_usd_dec * fx_krw_dec).to_integral_value(rounding=ROUND_DOWN))
        if net_krw > 0:
            return ConservationVerdict(
                verdict=_format_profit_verdict(net_krw),
                gross_usd=gross_usd_q,
                gas_usd=gas_usd_q,
                flash_fee_usd=flash_fee_usd_q,
                net_usd=net_usd_q,
                net_krw=net_krw,
                fx_rate_krw=fx_krw,
                fx_source=fx_src,
                corroborated=True,
                mutex_only_rejected=False,
                reason=f"PROVEN_NET_PROFIT_{net_krw}_KRW",
                swap_fee_usd=swap_fee_usd_q,
                slippage_usd=slippage_usd_q,
                gross_profit_native=gross_native_str,
                net_profit_native=_fmt_dec18(net_native_dec),
                profit_native_unit=unit_sym,
                costs=costs_dict,
                net_usd_exact=format(net_usd_dec, "f"),
            )

    def _non_profit_tail(verdict_tok: str, eff_net_usd: float, reason_txt: str) -> ConservationVerdict:
        return ConservationVerdict(
            verdict=verdict_tok,
            gross_usd=gross_usd_q,
            gas_usd=gas_usd_q,
            flash_fee_usd=flash_fee_usd_q,
            net_usd=eff_net_usd,
            net_krw=0,
            fx_rate_krw=fx_krw,
            fx_source=fx_src,
            corroborated=True,
            mutex_only_rejected=False,
            reason=reason_txt,
            swap_fee_usd=swap_fee_usd_q,
            slippage_usd=slippage_usd_q,
            gross_profit_native=gross_native_str,
            net_profit_native="0.000000000000000000",
            profit_native_unit=unit_sym,
            costs=costs_dict,
            net_usd_exact=format(net_usd_dec, "f") if verdict_tok == VERDICT_SAFE else "0",
        )

    if has_unconfirmed_gain_valuation and not offline_mode:
        return _non_profit_tail(VERDICT_BLOCKED, 0.0, "TOKEN_PRICE_OR_LIQUIDITY_UNCONFIRMED_FAIL_OPEN")

    return _non_profit_tail(
        VERDICT_SAFE,
        net_usd_q,
        f"BELOW_MIN_PROFIT_THRESHOLD({net_usd_q:.2f}<{MIN_PROFIT_USD})",
    )


def _render_agent_poc_skeleton(
    slug: str,
    cid: int,
    chain: str,
    block_pin: int,
    caller: str,
    target_addr: str,
    *,
    token_addrs: Optional[Sequence[str]] = None,
    vault_addresses: Optional[Sequence[str]] = None,
    exit_routes: Optional[Dict[str, Dict[str, Any]]] = None,
) -> str:
    """
    에이전트 위임 시 즉시 컴파일 가능한 가치보존·청산 통합 검증 테스트 스켈레톤 생성:
    - `TOK_*` / `VAULT_*`, `_takeSnap`, `_tryLiquidateGains`, `_bridgeLiquidatedGain`, `_assertConservationLiq` 사전 배선.
    - 인라인 createSelectFork 제거로 `--offline --fork-block-number` 캐시 재사용 최신 헤드 리플레이 정합성 보장.
    - 멀티 파일 동일 워크스페이스 컴파일 충돌 방지를 위해 헬퍼 컨트랙트 이름을 `LiquidatorHelper_Agent_<slug>_<cid>`로 격리.
    """
    safe_contract = _safe_solidity_ident(slug)
    cid_i = max(1, int(cid))
    ctx = _prepare_conservation_harness_context(
        slug,
        chain,
        caller,
        target_addr,
        token_addrs or (),
        vault_addresses=vault_addresses,
        exit_routes=exit_routes,
        helper_suffix=f"Agent_{safe_contract}_{cid_i}",
    )
    asset_count = int(ctx["asset_count"])
    if ctx["liq_routes"]:
        post_liq_block = (
            f"        (uint256[{asset_count}] memory liqCredit, uint256[{asset_count}] memory liqDebited) = _tryLiquidateGains(snapBefore, snapMid);"
        )
    else:
        post_liq_block = (
            f"        uint256[{asset_count}] memory liqCredit;\n"
            f"        uint256[{asset_count}] memory liqDebited;"
        )

    test_fn_body = f"""
    function test_candidate_{cid_i}() public {{
        ConservationSnap memory snapBefore = _takeSnap(ZERO_STATE_CALLER);
        uint256 gasStart = gasleft();
        vm.startPrank(ZERO_STATE_CALLER, ZERO_STATE_CALLER);
        // Implement dynamic on-chain state verification against TARGET
        vm.stopPrank();
        uint256 gasUsed = gasStart > gasleft() ? (gasStart - gasleft()) : 21000;
        ConservationSnap memory snapMid = _takeSnap(ZERO_STATE_CALLER);
        uint256 liqGasStart = gasleft();
{post_liq_block}
        // Optional: if an exploit yields custom/LP tokens not auto-liquidated above, swap remaining stolen gains
        // under vm.startPrank(ZERO_STATE_CALLER, ZERO_STATE_CALLER) and call:
        // _bridgeLiquidatedGain(snapBefore, snapMid, liqCredit, liqDebited, tokSlot, quoteSlot, spentAmt, boughtAmt);
        {{
            uint256 liqGasUsed = liqGasStart > gasleft() ? (liqGasStart - gasleft()) : 0;
            for (uint256 li = 0; li < {asset_count}; li++) {{
                if (liqDebited[li] > 0) {{ gasUsed += liqGasUsed; break; }}
            }}
        }}
        ConservationSnap memory snapAfter = _takeSnap(ZERO_STATE_CALLER);
        _assertConservationLiq({cid_i}, snapBefore, snapAfter, liqCredit, liqDebited, gasUsed);
    }}"""
    return _render_conservation_contract_body(
        ctx,
        f"AgentVerify_{safe_contract}_{cid_i}",
        "ZERO_STATE_CALLER",
        include_bridge_helper=True,
        caller_const_decl=True,
        include_slot_comments=True,
        extra_members=test_fn_body,
    )


def _wrap_self_isolated_cmd(env_json_path: Path, args_tail: str) -> str:
    """동봉 격리 명령줄 단독 실행 시에도 작업 디렉터리와 12개 환경변수가 audit_artifacts 하위 격리 경로로 자동 고정되도록 래핑."""
    return (
        f'{_PY_CLI_TOK} -B -X utf8 -c '
        '"import json,pathlib,subprocess,sys; '
        "p=pathlib.Path(sys.argv[1]); "
        "sys.exit(subprocess.run(sys.argv[2:], cwd=str(p.parent), env=json.loads(p.read_text('utf-8')), stdin=subprocess.DEVNULL).returncode)\" "
        f'"{env_json_path}" {args_tail}'
    )


def _resolve_request_rpc_and_cast_suffix(
    router: Optional[RPCRouter],
    chain: str,
    block_pin: int,
) -> Tuple[str, str, str]:
    c = _norm_chain(chain)
    rpc_u = ""
    if router is not None and int(block_pin) > 0:
        cands = router.candidate_urls(c, need_archive=True, for_forge=True)
        rpc_u = cands[0] if cands else ""
    eff_rpc_u = rpc_u or "http://127.0.0.1:8545"
    cast_blk_suffix = f" --block {int(block_pin)}" if int(block_pin) > 0 else ""
    return c, eff_rpc_u, cast_blk_suffix


def _resolve_slug_artifact_dir(slug: str, root_dir: Optional[Path] = None) -> Tuple[str, Path]:
    norm_s = _norm_slug(slug)
    eff_root = root_dir if root_dir is not None else ARTIFACT_ROOT
    return norm_s, eff_root / norm_s


def _sanitize_rel_source_path(raw_name: str, fallback_idx: int) -> Path:
    parts = [
        p
        for p in str(raw_name or "").replace("\\", "/").split("/")
        if p and p not in (".", "..") and ":" not in p
    ]
    if not parts:
        parts = [f"Contract_{fallback_idx}.sol"]
    return Path(*parts)


def _export_bundle_sources(
    pdir: Path,
    slug: str,
    verified_sources: Dict[str, Dict[str, Any]],
    incident_sources: Optional[Dict[str, Any]] = None,
) -> List[str]:
    """검증 컨트랙트·연결 금고·유사 Mode B 원본 소스 및 ABI를 audit_artifacts/<slug>/sources/에 완비 저장."""
    src_root = pdir / "sources"
    out_rels: List[str] = []
    seen_rels: Set[str] = set()

    def _dump_entry(sub_tag: str, sinfo: Dict[str, Any]) -> None:
        dest_dir = src_root / sub_tag
        dest_dir.mkdir(parents=True, exist_ok=True)
        smap = sinfo.get("sources")
        if isinstance(smap, dict):
            for idx_f, (fn, content) in enumerate(smap.items(), 1):
                rel_p = _sanitize_rel_source_path(str(fn), idx_f)
                out_f = dest_dir / rel_p
                out_f.parent.mkdir(parents=True, exist_ok=True)
                out_f.write_text(str(content or ""), encoding="utf-8")
                rel_str = f"audit_artifacts/{slug}/sources/{sub_tag}/{rel_p.as_posix()}"
                if rel_str not in seen_rels:
                    seen_rels.add(rel_str)
                    out_rels.append(rel_str)
        abi_val = sinfo.get("abi")
        if isinstance(abi_val, list) and abi_val:
            abi_f = dest_dir / "abi.json"
            _write_json_atomic(abi_f, abi_val)
            rel_abi = f"audit_artifacts/{slug}/sources/{sub_tag}/abi.json"
            if rel_abi not in seen_rels:
                seen_rels.add(rel_abi)
                out_rels.append(rel_abi)

    if isinstance(incident_sources, dict) and incident_sources.get("sources"):
        _dump_entry("_incident_seed", incident_sources)
    for addr_k, sinfo in verified_sources.items():
        if not isinstance(sinfo, dict):
            continue
        sub_tag = _norm_slug(str(addr_k)[:18]) or "target"
        _dump_entry(sub_tag, sinfo)
    return out_rels[:64]


def _summarize_closure_for_poc(
    closure: Optional[TrustClosureResult],
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    if closure is None:
        return [], {}
    seed_set = set(closure.seed_addresses)
    vaults: List[Dict[str, Any]] = []
    for addr, exp in sorted(
        closure.vault_exposures.items(),
        key=lambda kv: (-_ve_total_dec(kv[1]), kv[0]),
    ):
        pr = closure.resolutions.get(addr)
        pk = pr.proxy_kind if pr else "none"
        if (
            addr not in seed_set
            and _ve_total_dec(exp) <= _DEC_ZERO
            and exp.native_wei <= 0
            and not exp.token_balances
            and _ve_allow_dec(exp) <= _DEC_ZERO
        ):
            continue
        vaults.append({
            "address": _checksum(addr),
            "native_usd": round(float(exp.native_usd), 4),
            "token_usd": { _checksum(t): round(float(v), 4) for t, v in exp.token_usd.items() },
            "token_balances_raw": { _checksum(t): str(raw) for t, raw in exp.token_balances.items() },
            "allowance_usd": round(float(exp.allowance_usd), 4),
            "total_usd": round(float(exp.total_usd), 4),
            "proxy_kind": pk,
            "impls": [_checksum(ix) for ix in (pr.impl_addresses if pr else ())],
        })
        if len(vaults) >= 32:
            break
    exit_summary: Dict[str, Any] = {
        "max_extractable_usd": round(float(closure.max_extractable_usd), 4),
        "realizable_extractable_usd": round(float(closure.realizable_extractable_usd), 4),
        "pools": dict(closure.verified_exit_pools),
    }
    return vaults, exit_summary


def emit_poc_requests_for_slug(
    slug: str,
    chain: str,
    block_pin: int,
    caller: str,
    slices: Sequence[CausalSlice],
    verified_sources: Dict[str, Dict[str, Any]],
    principle_summary: str = "",
    force_all: bool = False,
    router: Optional[RPCRouter] = None,
    mechanical_cap: Optional[int] = None,
    session_id: str = "",
    closure: Optional[TrustClosureResult] = None,
    incident_sources: Optional[Dict[str, Any]] = None,
    compact_single_bundle: bool = False,
) -> List[Path]:
    """
    비기계적 의미 추론 경계 후보들에 대해 자가 기술(Self-Describing) 규격의
    `audit_artifacts/<slug>/poc_requests/poc_request_{cid}.json`, 전체 검증 소스·ABI(`sources/`),
    연결 금고 잔액·실매도 가능 DEX 풀 정보 및 컴파일 가능한 초기 스켈레톤을 생성한다.
    """
    slug, pdir = _resolve_slug_artifact_dir(slug)
    req_dir = pdir / "poc_requests"
    req_dir.mkdir(parents=True, exist_ok=True)
    (pdir / "verdicts").mkdir(parents=True, exist_ok=True)
    c, eff_rpc_u, cast_blk_suffix = _resolve_request_rpc_and_cast_suffix(router, chain, block_pin)
    ws = ensure_clean_forge_workspace({c: eff_rpc_u}, slug=slug, offline=(block_pin <= 0))
    flash_opts = list(FLASH_PROVIDERS.get(c, [])) + [{"provider": "no-flash", "vault": "0x0000000000000000000000000000000000000000", "fee_bps": 0}]
    fork_cli_suffix = f' --fork-url "{eff_rpc_u}" --fork-block-number {int(block_pin)}' if block_pin > 0 else ""
    ws_env_hint = _isolated_subproc_env(ws)
    ws_env_json = ws / "_isolated_env.json"
    _write_json_atomic(ws_env_json, ws_env_hint)
    sid_clean = str(session_id or "").strip().lower()
    resume_cmd = f"{CLI_INVOKE_PREFIX} run {sid_clean}" if sid_clean else f"{CLI_INVOKE_PREFIX} run"
    exported_source_rels = _export_bundle_sources(pdir, slug, verified_sources, incident_sources=incident_sources)
    connected_vaults, exit_pool_summary = _summarize_closure_for_poc(closure)
    base_vaults: List[str] = [str(v["address"]) for v in connected_vaults if v.get("address")]
    if closure is not None:
        skel_tokens = _prioritize_closure_monitored_tokens(c, closure, limit=12)
        skel_exit_routes = dict(closure.verified_exit_pools) if closure.verified_exit_pools else None
    else:
        wn_c = WRAPPED_NATIVE_BY_CHAIN.get(c, "")
        skel_tokens = ([wn_c] if wn_c else []) + list(CHAIN_STABLES.get(c, [])[:4])
        skel_exit_routes = None
    skel_note = (
        "Accounting, gas, USD/KRW rate, and final profit numbers are sealed exclusively by the engine from ConservationGain events. "
        "The pre-generated test skeleton pre-wires TOK_*/VAULT_*, _takeSnap, _tryLiquidateGains (auto-liquidating DEX/ERC4626/aToken/cToken/LP/bluechip gains after snapMid), "
        "_bridgeLiquidatedGain (for custom unrouted post-snapMid swaps), and _assertConservationLiq."
    )
    skel_event_hint = (
        "event ConservationGain(uint256 sliceIdx, address asset, uint256 callerGain, uint256 vaultLoss, uint256 gasUsed) "
        "- emitted automatically by _assertConservationLiq; leave stolen tokens on ZERO_STATE_CALLER before snapMid "
        "or liquidate custom unrouted tokens after _tryLiquidateGains and call _bridgeLiquidatedGain."
    )
    source_inc_meta: Optional[Dict[str, Any]] = None
    if isinstance(incident_sources, dict) and incident_sources:
        source_inc_meta = {
            "case_slug": str(incident_sources.get("case_slug") or ""),
            "similarity": float(incident_sources.get("similarity") or 0.0),
            "principle_summary": str(incident_sources.get("principle_summary") or ""),
        }

    written: List[Path] = []
    raw_agent_slices = (
        list(slices)
        if force_all
        else [
            s
            for idx_s, s in enumerate(slices)
            if s.needs_agent_synthesis or (mechanical_cap is not None and idx_s >= mechanical_cap)
        ]
    )
    dedup_agent_slices: List[CausalSlice] = []
    seen_agent_keys: Set[Tuple[str, Tuple[str, ...], str]] = set()
    for sl_cand in raw_agent_slices:
        ak = (_norm_addr(sl_cand.target_address), tuple(sl_cand.legs), str(sl_cand.channel))
        if ak not in seen_agent_keys:
            seen_agent_keys.add(ak)
            dedup_agent_slices.append(sl_cand)
    agent_slices = dedup_agent_slices

    if compact_single_bundle and len(agent_slices) >= 1:
        primary_sl = agent_slices[0]
        src_info = verified_sources.get(primary_sl.target_address) or next(iter(verified_sources.values()), {})
        src_files = src_info.get("sources") or {}
        snippet_list: List[str] = [f"// {fn}\n" + str(content)[:1200] for fn, content in list(src_files.items())[:3]]
        rel_sol = f"audit_artifacts/{slug}/forge/test/test_1.t.sol"
        rel_verdict = f"audit_artifacts/{slug}/verdicts/verdict_1.json"
        rel_req = f"audit_artifacts/{slug}/poc_requests/poc_request_1.json"
        bundle_vaults = [
            x
            for s_i in agent_slices
            for x in ([s_i.target_address] + list(s_i.leg_targets or []))
            if _norm_addr(x)
        ] + base_vaults
        sol_disk_path = ws / "test" / "test_1.t.sol"
        if not sol_disk_path.exists():
            sol_disk_path.write_text(
                _render_agent_poc_skeleton(
                    slug,
                    1,
                    c,
                    block_pin,
                    caller,
                    primary_sl.target_address,
                    token_addrs=skel_tokens,
                    vault_addresses=bundle_vaults,
                    exit_routes=skel_exit_routes,
                ),
                encoding="utf-8",
            )
        cs_target = _checksum(primary_sl.target_address)
        all_leg_targets = list(
            dict.fromkeys(
                _checksum(x)
                for s_i in agent_slices
                for x in (s_i.leg_targets or [s_i.target_address])
                if _norm_addr(x)
            )
        )
        all_witnesses = list(
            dict.fromkeys(str(w) for s_i in agent_slices for w in s_i.witness_candidates)
        )[:24]
        req_payload: Dict[str, Any] = {
            "schema_version": ARTIFACT_SCHEMA_VERSION,
            "candidate_id": 1,
            "session_id": sid_clean,
            "slug": slug,
            "chain": c,
            "audit_block": block_pin,
            "zero_state_caller": _checksum(caller),
            "target_address": cs_target,
            "leg_targets": all_leg_targets or [cs_target],
            "legs": primary_sl.legs,
            "undecided_reason": primary_sl.undecided_reason or primary_sl.rationale,
            "state_channels": list(dict.fromkeys(str(s_i.channel) for s_i in agent_slices)),
            "discontinuity_seeds": all_witnesses,
            "candidate_slices": [
                {
                    "candidate_id": idx_c,
                    "target_address": _checksum(s_i.target_address),
                    "leg_targets": [_checksum(x) for x in (s_i.leg_targets or [s_i.target_address]) if _norm_addr(x)],
                    "legs": list(s_i.legs),
                    "channel": str(s_i.channel),
                    "undecided_reason": s_i.undecided_reason or s_i.rationale,
                    "witness_candidates": [str(w) for w in s_i.witness_candidates[:8]],
                }
                for idx_c, s_i in enumerate(agent_slices, start=1)
            ],
            "connected_vaults": connected_vaults,
            "verified_exit_pools": exit_pool_summary,
            "flash_loan_options": flash_opts,
            "principle_summary": principle_summary,
            "editable_files": [rel_sol, rel_verdict],
            "readable_files": [rel_req, rel_sol, *exported_source_rels],
            "isolated_commands": {
                "preverify_forge_test": _wrap_self_isolated_cmd(
                    ws_env_json,
                    f'"{FORGE_BIN}" test --offline --no-storage-caching --root "{ws}" --match-path "test/test_1.t.sol"{fork_cli_suffix} -vvv',
                ),
                "readonly_cast_call_template": _wrap_self_isolated_cmd(
                    ws_env_json,
                    f'"{CAST_BIN}" call --rpc-url "{eff_rpc_u}"{cast_blk_suffix} {cs_target} 0x18160ddd',
                ),
                "resume_engine": resume_cmd,
                "isolated_env_hint": dict(ws_env_hint),
            },
            "submission_schema": {
                "verdict_file": rel_verdict,
                "note": skel_note,
                "allowed_status_values": ["PROVEN_BY_FORGE", VERDICT_SAFE, VERDICT_BLOCKED],
                "example_verdict_json": {
                    "candidate_id": 1,
                    "verdict": VERDICT_SAFE,
                    "notes": "Verified on-chain invariant holds across all reachable state transitions",
                    "remediation_exhausted": {k: True for k in REMEDIATION_KEYS},
                },
            },
            "optional_conservation_event": skel_event_hint,
            "relevant_source_slices": snippet_list,
        }
        if source_inc_meta:
            req_payload["source_incident"] = source_inc_meta
        rpath = req_dir / "poc_request_1.json"
        _write_json_atomic(rpath, req_payload)
        for old_rf in req_dir.glob("poc_request_*.json"):
            if old_rf.name != "poc_request_1.json":
                try:
                    old_rf.unlink()
                except Exception:
                    pass
        return [rpath]

    for cid, sl in enumerate(agent_slices, start=1):
        src_info = verified_sources.get(sl.target_address) or next(iter(verified_sources.values()), {})
        src_files = src_info.get("sources") or {}
        snippet_list = []
        for fn, content in list(src_files.items())[:2]:
            snippet_list.append(f"// {fn}\n" + str(content)[:1200])
        rel_sol = f"audit_artifacts/{slug}/forge/test/test_{cid}.t.sol"
        rel_verdict = f"audit_artifacts/{slug}/verdicts/verdict_{cid}.json"
        rel_req = f"audit_artifacts/{slug}/poc_requests/poc_request_{cid}.json"
        sl_vaults = [
            x
            for x in ([sl.target_address] + list(sl.leg_targets or []))
            if _norm_addr(x)
        ] + base_vaults
        sol_disk_path = ws / "test" / f"test_{cid}.t.sol"
        if not sol_disk_path.exists():
            sol_disk_path.write_text(
                _render_agent_poc_skeleton(
                    slug,
                    cid,
                    c,
                    block_pin,
                    caller,
                    sl.target_address,
                    token_addrs=skel_tokens,
                    vault_addresses=sl_vaults,
                    exit_routes=skel_exit_routes,
                ),
                encoding="utf-8",
            )
        cs_target = _checksum(sl.target_address)
        req_payload = {
            "schema_version": ARTIFACT_SCHEMA_VERSION,
            "candidate_id": cid,
            "session_id": sid_clean,
            "slug": slug,
            "chain": c,
            "audit_block": block_pin,
            "zero_state_caller": _checksum(caller),
            "target_address": cs_target,
            "leg_targets": [_checksum(x) for x in (sl.leg_targets or [sl.target_address]) if _norm_addr(x)],
            "legs": sl.legs,
            "undecided_reason": sl.undecided_reason or sl.rationale,
            "state_channels": [sl.channel],
            "discontinuity_seeds": [str(w) for w in sl.witness_candidates],
            "connected_vaults": connected_vaults,
            "verified_exit_pools": exit_pool_summary,
            "flash_loan_options": flash_opts,
            "principle_summary": principle_summary,
            "editable_files": [rel_sol, rel_verdict],
            "readable_files": [rel_req, rel_sol, *exported_source_rels],
            "isolated_commands": {
                "preverify_forge_test": _wrap_self_isolated_cmd(
                    ws_env_json,
                    f'"{FORGE_BIN}" test --offline --no-storage-caching --root "{ws}" --match-path "test/test_{cid}.t.sol"{fork_cli_suffix} -vvv',
                ),
                "readonly_cast_call_template": _wrap_self_isolated_cmd(
                    ws_env_json,
                    f'"{CAST_BIN}" call --rpc-url "{eff_rpc_u}"{cast_blk_suffix} {cs_target} 0x18160ddd',
                ),
                "resume_engine": resume_cmd,
                "isolated_env_hint": dict(ws_env_hint),
            },
            "submission_schema": {
                "verdict_file": rel_verdict,
                "note": skel_note,
                "allowed_status_values": ["PROVEN_BY_FORGE", VERDICT_SAFE, VERDICT_BLOCKED],
                "example_verdict_json": {
                    "candidate_id": cid,
                    "verdict": VERDICT_SAFE,
                    "notes": "Verified on-chain invariant holds across all reachable state transitions",
                    "remediation_exhausted": {k: True for k in REMEDIATION_KEYS},
                },
            },
            "optional_conservation_event": skel_event_hint,
            "relevant_source_slices": snippet_list,
        }
        if source_inc_meta:
            req_payload["source_incident"] = source_inc_meta
        rpath = req_dir / f"poc_request_{cid}.json"
        _write_json_atomic(rpath, req_payload)
        written.append(rpath)
    return written


def _serialize_closure(c: TrustClosureResult) -> Dict[str, Any]:
    return dataclasses.asdict(c)


def _deserialize_closure(d: Dict[str, Any]) -> TrustClosureResult:
    res_map: Dict[str, ProxyResolution] = {}
    for k, v in (d.get("resolutions") or {}).items():
        if isinstance(v, dict):
            res_map[str(k)] = ProxyResolution(
                address=str(v.get("address") or k),
                proxy_kind=str(v.get("proxy_kind") or "none"),
                impl_addresses=list(v.get("impl_addresses") or []),
                admin_address=str(v.get("admin_address") or ""),
                raw_code_hex=str(v.get("raw_code_hex") or "0x"),
                effective_code_hex=str(v.get("effective_code_hex") or "0x"),
                skeleton_hash=str(v.get("skeleton_hash") or ""),
                slot_collisions=[int(x) for x in (v.get("slot_collisions") or [])],
                impl_codes_hex={str(ik): str(iv) for ik, iv in (v.get("impl_codes_hex") or {}).items()},
                unresolved_delegation=bool(v.get("unresolved_delegation", False)),
            )
    exp_map: Dict[str, VaultExposure] = {}
    for k, v in (d.get("vault_exposures") or {}).items():
        if isinstance(v, dict):
            exp_map[str(k)] = VaultExposure(
                address=str(v.get("address") or k),
                native_wei=int(v.get("native_wei") or 0),
                native_usd=float(v.get("native_usd") or 0.0),
                token_balances={str(tk): int(tv) for tk, tv in (v.get("token_balances") or {}).items()},
                token_usd={str(tk): float(tv) for tk, tv in (v.get("token_usd") or {}).items()},
                allowance_usd=float(v.get("allowance_usd") or 0.0),
                total_usd=float(v.get("total_usd") or 0.0),
                allowance_usd_dec=str(
                    v["allowance_usd_dec"]
                    if v.get("allowance_usd_dec") not in (None, "")
                    else format(_to_dec(v.get("allowance_usd") or 0.0), "f")
                ),
                total_usd_dec=str(
                    v["total_usd_dec"]
                    if v.get("total_usd_dec") not in (None, "")
                    else format(_to_dec(v.get("total_usd") or 0.0), "f")
                ),
            )
    return TrustClosureResult(
        chain=str(d.get("chain") or "ethereum"),
        block_pin=int(d.get("block_pin") or 0),
        seed_addresses=list(d.get("seed_addresses") or []),
        all_addresses=list(d.get("all_addresses") or []),
        resolutions=res_map,
        vault_exposures=exp_map,
        max_extractable_usd=float(d.get("max_extractable_usd") or 0.0),
        min_gas_usd=float(d.get("min_gas_usd") or 0.01),
        early_exit_safe=bool(d.get("early_exit_safe", False)),
        early_exit_reason=str(d.get("early_exit_reason") or ""),
        token_decimals={str(tk): int(tv) for tk, tv in (d.get("token_decimals") or {}).items()},
        token_prices_usd={str(tk): float(tv) for tk, tv in (d.get("token_prices_usd") or {}).items()},
        has_dynamic_external_reachability=bool(d.get("has_dynamic_external_reachability", False)),
        approved_owners=[str(x) for x in (d.get("approved_owners") or []) if _norm_addr(x)],
        max_extractable_usd_dec=str(
            d["max_extractable_usd_dec"]
            if d.get("max_extractable_usd_dec") not in (None, "")
            else format(_to_dec(d.get("max_extractable_usd") or 0.0), "f")
        ),
        min_gas_usd_dec=str(
            d["min_gas_usd_dec"]
            if d.get("min_gas_usd_dec") not in (None, "")
            else format(_to_dec(d.get("min_gas_usd") or 0.01, Decimal("0.01")), "f")
        ),
        realizable_extractable_usd=float(
            d.get("realizable_extractable_usd")
            if d.get("realizable_extractable_usd") is not None
            else (d.get("max_extractable_usd") or 0.0)
        ),
        realizable_extractable_usd_dec=str(
            d["realizable_extractable_usd_dec"]
            if d.get("realizable_extractable_usd_dec") not in (None, "")
            else format(
                _to_dec(
                    d.get("realizable_extractable_usd")
                    if d.get("realizable_extractable_usd") is not None
                    else (d.get("max_extractable_usd") or 0.0)
                ),
                "f",
            )
        ),
        verified_exit_pools={
            str(pk): dict(pv)
            for pk, pv in (d.get("verified_exit_pools") or {}).items()
            if isinstance(pv, dict)
        },
        has_unpriced_token_exposure=bool(d.get("has_unpriced_token_exposure", False)),
        rpc_balance_incomplete=bool(d.get("rpc_balance_incomplete", False)),
        closure_truncated=bool(d.get("closure_truncated", False)),
    )


def emit_address_discovery_request(
    slug: str,
    chain: str,
    block_pin: int,
    tvl_usd: float,
    meta_hint: Optional[Dict[str, Any]] = None,
    router: Optional[RPCRouter] = None,
    session_id: str = "",
    mode: str = "A",
    principle_summary: str = "",
) -> Path:
    """
    기계적 주소 수집이 비어 있을 때 에이전트에게 자가 기술(Self-Describing) 규격의 4단계 우선순위 주소 탐색을 요청하는
    `audit_artifacts/<slug>/address_request.json` 생성.
    """
    slug, pdir = _resolve_slug_artifact_dir(slug)
    pdir.mkdir(parents=True, exist_ok=True)
    c, eff_rpc_u, cast_blk_suffix = _resolve_request_rpc_and_cast_suffix(router, chain, block_pin)
    cand_probe_addr = _checksum(WRAPPED_NATIVE_BY_CHAIN.get(c) or "0x0000000000000000000000000000000000000001")
    base_slug = _strip_chain_suffix_slug(slug)
    rel_out = f"audit_artifacts/{slug}/discovered_addresses.json"
    rel_req = f"audit_artifacts/{slug}/address_request.json"
    cast_env_dir = pdir / "_cast_env"
    cast_env_dir.mkdir(parents=True, exist_ok=True)
    (cast_env_dir / "foundry.toml").write_text("[profile.default]\nno_storage_caching = true\noffline = true\n", encoding="utf-8")
    cast_env_hint = _isolated_subproc_env(cast_env_dir)
    _write_json_atomic(cast_env_dir / "_isolated_env.json", cast_env_hint)
    sid_clean = str(session_id or "").strip().lower()
    resume_cmd = f"{CLI_INVOKE_PREFIX} run {sid_clean}" if sid_clean else f"{CLI_INVOKE_PREFIX} run"
    req_doc = {
        "schema_version": ARTIFACT_SCHEMA_VERSION,
        "session_id": sid_clean,
        "mode": str(mode or "A"),
        "slug": slug,
        "base_slug": base_slug,
        "chain": c,
        "audit_block": int(block_pin),
        "tvl_usd": float(tvl_usd),
        "principle_summary": str(principle_summary or "")[:2000],
        "known_metadata": meta_hint or {},
        "editable_files": [rel_out],
        "readable_files": [rel_req],
        "isolated_commands": {
            "verify_code_template": _wrap_self_isolated_cmd(
                cast_env_dir / "_isolated_env.json",
                f'"{CAST_BIN}" code --rpc-url "{eff_rpc_u}"{cast_blk_suffix} {cand_probe_addr}',
            ),
            "resume_engine": resume_cmd,
            "isolated_env_hint": cast_env_hint,
        },
        "priority_order": [
            "1_official_docs",
            "2_gitbook",
            "3_github",
            "4_defillama_adapter",
        ],
        "recommended_web_queries": [
            f'"{base_slug}" "{c}" official docs deployed contract addresses',
            f'site:gitbook.io "{base_slug}" "{c}" contract addresses',
            f'site:github.com "{base_slug}" deployments "{c}" 0x',
            f'site:github.com/DefiLlama/DefiLlama-Adapters "{base_slug}"',
        ],
        "output_file": rel_out,
        "output_schema_example": {
            "official_docs": ["0x..."],
            "gitbook": ["0x..."],
            "github": ["0x..."],
            "defillama_adapter": ["0x..."],
            "confirmed_no_contracts": False,
            "no_onchain_contracts": False,
            "pure_offchain_proven": False,
            "offchain_evidence": "",
        },
    }
    apath = pdir / "address_request.json"
    _write_json_atomic(apath, req_doc)
    return apath


def write_protocol_artifacts(
    slug: str,
    result_payload: Dict[str, Any],
    forge_payload: Optional[Dict[str, Any]] = None,
    trace_payload: Optional[Dict[str, Any]] = None,
    poc_request_payload: Optional[Dict[str, Any]] = None,
    root_dir: Optional[Path] = None,
) -> Path:
    """audit_artifacts/<slug>/ 산출물 원자적 기록, 결론 확정 시 작업 내용 즉시 삭제(방식 A) 및 pins.json SHA-256 해시 봉인."""
    slug, pdir = _resolve_slug_artifact_dir(slug, root_dir)
    pdir.mkdir(parents=True, exist_ok=True)
    verdicts_dir = pdir / "verdicts"
    verdicts_dir.mkdir(parents=True, exist_ok=True)

    payload_copy = dict(result_payload)
    payload_copy["slug"] = slug

    raw_verdict = str(payload_copy.get("verdict") or "")
    net_krw_int = int(payload_copy.get("net_krw") or 0)
    if raw_verdict == VERDICT_PROFIT and net_krw_int > 0:
        raw_verdict = _format_profit_verdict(net_krw_int)
        payload_copy["verdict"] = raw_verdict
    verdict_val = raw_verdict

    is_terminal_sealed = _is_valid_verdict(verdict_val, allow_template=False) and not bool(payload_copy.get("needs_agent", False))
    is_profit_sealed = is_terminal_sealed and _is_profit_verdict(verdict_val, allow_template=False)

    if not is_terminal_sealed or is_profit_sealed:
        if forge_payload is not None:
            _write_json_atomic(pdir / "forge_output.json", forge_payload)
        if trace_payload is not None:
            _write_json_atomic(pdir / "execution_trace_summary.json", trace_payload)
    if not is_terminal_sealed and poc_request_payload is not None:
        req_dir = pdir / "poc_requests"
        req_dir.mkdir(parents=True, exist_ok=True)
        cid = int(poc_request_payload.get("candidate_id") or 1)
        _write_json_atomic(req_dir / f"poc_request_{cid}.json", poc_request_payload)

    if is_terminal_sealed:
        if is_profit_sealed:
            for sub_rm in ("sources", "_cast_env", "poc_requests"):
                shutil.rmtree(pdir / sub_rm, ignore_errors=True)
            forge_ws = pdir / "forge"
            if forge_ws.is_dir():
                for f_sub in ("out", "cache", "broadcast", "_subproc_tmp", "_subproc_home"):
                    shutil.rmtree(forge_ws / f_sub, ignore_errors=True)
            for transient_fn in ("checkpoint.json", "address_request.json", "discovered_addresses.json"):
                try:
                    (pdir / transient_fn).unlink(missing_ok=True)
                except OSError:
                    pass
            for cand_fo in pdir.glob("forge_output_*.json"):
                try:
                    cand_fo.unlink()
                except OSError:
                    pass
            if not any(verdicts_dir.glob("verdict_*.json")):
                v1_doc_p: Dict[str, Any] = {
                    "candidate_id": 1,
                    "verdict": verdict_val,
                    "audit_block": int(payload_copy.get("audit_block") or 0),
                    "notes": str(payload_copy.get("reason") or "Mechanical engine determination"),
                    "gross_profit_native": str(payload_copy.get("gross_profit_native") or "0.000000000000000000"),
                    "costs": payload_copy.get("costs") or {},
                    "net_profit_native": str(payload_copy.get("net_profit_native") or "0.000000000000000000"),
                    "profit_native_unit": str(payload_copy.get("profit_native_unit") or "ETH"),
                    "net_profit_usd": float(payload_copy.get("net_usd") or 0.0),
                    "net_profit_krw": int(payload_copy.get("net_krw") or 0),
                }
                _write_json_atomic(verdicts_dir / "verdict_1.json", v1_doc_p)
        else:
            for child in list(pdir.iterdir()):
                if child == verdicts_dir:
                    continue
                if child.is_dir():
                    shutil.rmtree(child, ignore_errors=True)
                elif child.name not in ("result.json", "pins.json"):
                    try:
                        child.unlink()
                    except OSError:
                        pass
            for old_vf in list(verdicts_dir.iterdir()):
                if old_vf.name != "verdict_1.json":
                    if old_vf.is_dir():
                        shutil.rmtree(old_vf, ignore_errors=True)
                    else:
                        try:
                            old_vf.unlink()
                        except OSError:
                            pass
            v1_doc: Dict[str, Any] = {
                "candidate_id": 1,
                "verdict": verdict_val,
                "audit_block": int(payload_copy.get("audit_block") or 0),
                "notes": str(payload_copy.get("reason") or "Mechanical engine determination"),
            }
            if verdict_val == VERDICT_BLOCKED:
                v1_doc["remediation_exhausted"] = payload_copy.get("remediation_exhausted") or {
                    k: True for k in REMEDIATION_KEYS
                }
                v1_doc["blocker_reason"] = str(payload_copy.get("reason") or "BLOCKED")
            _write_json_atomic(verdicts_dir / "verdict_1.json", v1_doc)

    res_path = pdir / "result.json"
    _write_json_atomic(res_path, payload_copy)

    file_hashes: Dict[str, str] = {}
    for fn in ("result.json", "forge_output.json", "execution_trace_summary.json"):
        fp = pdir / fn
        if fp.exists():
            file_hashes[fn] = _sha256_file(fp)
    for vf in sorted(verdicts_dir.glob("verdict_*.json")):
        file_hashes[f"verdicts/{vf.name}"] = _sha256_file(vf)

    pins_data = {
        "schema_version": ARTIFACT_SCHEMA_VERSION,
        "slug": slug,
        "chain": payload_copy.get("chain", ""),
        "audit_block": int(payload_copy.get("audit_block") or 0),
        "verdict": verdict_val,
        "net_usd": float(payload_copy.get("net_usd") or 0.0),
        "net_krw": int(payload_copy.get("net_krw") or 0),
        "sealed_at": int(time.time()),
        "file_sha256": file_hashes,
    }
    _write_json_atomic(pdir / "pins.json", pins_data)
    return pdir


@_with_decimal_prec_100
def _verify_protocol_pins_loaded(
    slug: str, root_dir: Optional[Path] = None
) -> Tuple[bool, str, Optional[Dict[str, Any]], Optional[Dict[str, Any]]]:
    """pins.json SHA-256·필드 교차 정합성 검증 및 파싱된 (result.json, forge_output.json) 문서 반환."""
    slug, pdir = _resolve_slug_artifact_dir(slug, root_dir)
    pins_file = pdir / "pins.json"
    res_file = pdir / "result.json"
    if not pins_file.exists() or not res_file.exists():
        return False, "MISSING_PINS_OR_RESULT", None, None
    try:
        pins = json.loads(pins_file.read_text(encoding="utf-8"))
        res = json.loads(res_file.read_text(encoding="utf-8"))
    except Exception as exc:
        return False, f"JSON_PARSE_ERROR:{exc}", None, None

    if bool(res.get("needs_agent", False)):
        return False, "PENDING_AGENT_INTERVENTION", res, None

    verdict = str(res.get("verdict") or "")
    if not _is_valid_verdict(verdict, allow_template=False):
        return False, f"INVALID_VERDICT:{verdict}", res, None

    fhashes = pins.get("file_sha256", {})
    if not isinstance(fhashes, dict) or "result.json" not in fhashes:
        return False, "RESULT_HASH_MISSING_IN_PINS", res, None
    if not any(str(k).startswith("verdicts/verdict_") for k in fhashes.keys()):
        return False, "VERDICT_HASH_MISSING_IN_PINS", res, None
    tsum_doc: Any = {}
    if _is_profit_verdict(verdict, allow_template=False) and (pdir / "execution_trace_summary.json").is_file():
        if "execution_trace_summary.json" not in fhashes:
            return False, "TRACE_SUMMARY_HASH_MISSING_IN_PINS", res, None
        tsum_doc = _read_json(pdir / "execution_trace_summary.json", default={})
        if not isinstance(tsum_doc, dict) or not bool(tsum_doc.get("target_called_in_trace")) or bool(tsum_doc.get("disallowed_cheatcode_in_trace")):
            return False, "TRACE_SUMMARY_INVALID_FOR_PROFIT", res, None

    for fn, expected_hash in fhashes.items():
        fp = pdir / fn
        if not fp.exists():
            return False, f"REFERENCED_FILE_MISSING:{fn}", res, None
        actual_hash = _sha256_file(fp)
        if actual_hash != expected_hash:
            return False, f"SHA256_MISMATCH:{fn}", res, None

    if str(pins.get("verdict") or "") != verdict:
        return False, "PINS_VERDICT_MISMATCH", res, None
    if int(pins.get("audit_block") or 0) != int(res.get("audit_block") or 0):
        return False, "PINS_AUDIT_BLOCK_MISMATCH", res, None
    if abs(_to_dec(pins.get("net_usd")) - _to_dec(res.get("net_usd"))) > Decimal("0.01"):
        return False, "PINS_NET_USD_MISMATCH", res, None
    if int(pins.get("net_krw") or 0) != int(res.get("net_krw") or 0):
        return False, "PINS_NET_KRW_MISMATCH", res, None

    fdoc: Optional[Dict[str, Any]] = None
    if _is_profit_verdict(verdict, allow_template=False):
        net_krw_val = int(res.get("net_krw") or 0)
        if net_krw_val <= 0 or _to_dec(res.get("net_usd_exact") or res.get("net_usd", 0.0)) < PROFIT_FLOOR_DEC:
            return False, "PROFIT_VERDICT_MISSING_POSITIVE_KRW", res, None
        if verdict != _format_profit_verdict(net_krw_val):
            return False, "PROFIT_VERDICT_STRING_KRW_MISMATCH", res, None
        forge_file = pdir / "forge_output.json"
        if not forge_file.exists():
            return False, "PROFIT_VERDICT_MISSING_FORGE_OUTPUT", res, None
        try:
            raw_fdoc = json.loads(forge_file.read_text(encoding="utf-8"))
            fdoc = raw_fdoc if isinstance(raw_fdoc, dict) else {}
            gains_list = fdoc.get("conservation_gains") or []
            if not (isinstance(gains_list, list) and len(gains_list) > 0):
                return False, "PROFIT_VERDICT_MISSING_VERIFIED_PROOF", res, fdoc
            f_tr = fdoc.get("trace_summary") if isinstance(fdoc.get("trace_summary"), dict) else {}
            eff_tr = tsum_doc if (isinstance(tsum_doc, dict) and tsum_doc) else f_tr
            if (
                not isinstance(eff_tr, dict)
                or not eff_tr
                or not bool(eff_tr.get("target_called_in_trace"))
                or bool(eff_tr.get("disallowed_cheatcode_in_trace"))
                or bool(f_tr.get("disallowed_cheatcode_in_trace"))
                or (bool(f_tr) and not bool(f_tr.get("target_called_in_trace")))
            ):
                return False, "TRACE_SUMMARY_INVALID_FOR_PROFIT", res, fdoc
        except Exception:
            return False, "PROFIT_VERDICT_INVALID_FORGE_JSON", res, None

    elif verdict == VERDICT_SAFE:
        if not str(res.get("reason") or res.get("early_exit") or "").strip():
            return False, "SAFE_VERDICT_MISSING_PROOF_REASON", res, fdoc
    elif verdict == VERDICT_BLOCKED:
        rem_map = res.get("remediation_exhausted")
        if (
            not str(res.get("reason") or "").strip()
            or not isinstance(rem_map, dict)
            or not all(bool(rem_map.get(k)) for k in REMEDIATION_KEYS)
        ):
            return False, "BLOCKED_VERDICT_INCOMPLETE_REMEDIATION", res, fdoc

    return True, "OK", res, fdoc


def verify_protocol_pins(slug: str, root_dir: Optional[Path] = None) -> Tuple[bool, str]:
    """pins.json에 기록된 SHA-256 해시, 필드 교차 정합성, 3분류 판정, 5대 해소 수단(REMEDIATION_KEYS), verdict_{cid}.json 및 forge_output.json 정합성 검증."""
    ok, reason, _, _ = _verify_protocol_pins_loaded(slug, root_dir)
    return ok, reason


def _sync_sealed_receipts_for_batch(store: SQLiteStore, batch_items: Sequence[Tuple[Any, ...]]) -> None:
    """큐 적재 배치 중 디스크에 이미 유효한 봉인 영수증(pins.json)이 존재하는 항목은 즉시 done 처리하여 재배정을 차단."""
    if not batch_items or not ARTIFACT_ROOT.is_dir():
        return
    for ns in dict.fromkeys(s for it in batch_items if (s := _norm_slug(str(it[0])))):
        if not (ARTIFACT_ROOT / ns / "pins.json").is_file():
            continue
        ok_s, _, res_s, _ = _verify_protocol_pins_loaded(ns, root_dir=ARTIFACT_ROOT)
        if ok_s and isinstance(res_s, dict):
            store.complete_queue_item(ns, str(res_s.get("verdict") or ""), float(res_s.get("net_krw") or 0.0))


def _store_cache_dir(store: SQLiteStore) -> Path:
    p = store.db_path.parent
    return p if p.name == "_cache" else (p / "_cache")


_CURSOR_PHASE_ORDER: Dict[str, int] = {
    "seed_harvest": 0,
    "exact_hash": 1,
    "sig_slices": 2,
    "code_slices": 3,
    "exhausted": 4,
}


def _export_relay_state(store: SQLiteStore, artifact_root: Optional[Path] = None) -> None:
    """PC방 이동 이어달리기용 경량 진행도 스냅샷(audit_artifacts/_relay_state.json) 원자적 저장."""
    if store._is_memory:
        return
    eff_root = artifact_root if artifact_root is not None else ARTIFACT_ROOT
    try:
        with store._read_conn() as rc:
            done_rows = rc.execute(
                "SELECT slug, priority, mode, chain, tvl_usd, sort_rank, addresses_json, principle_summary, verdict, net_krw "
                "FROM audit_queue WHERE status='done' ORDER BY slug ASC"
            ).fetchall()
            dyn_rows = rc.execute(
                "SELECT q.slug, q.priority, q.mode, q.chain, q.tvl_usd, q.sort_rank, q.addresses_json, q.principle_summary, "
                "COALESCE(m.meta_json, '{}') AS meta_json "
                "FROM audit_queue q LEFT JOIN proto_meta m ON q.slug = m.slug "
                "WHERE q.status != 'done' AND ("
                "q.slug LIKE 'modeb-match-%' "
                "OR q.slug LIKE 'modeb-clone-%' "
                "OR COALESCE(m.meta_json, '') LIKE '%mode_b_zero_seed_recovered%' "
                "OR COALESCE(m.meta_json, '') LIKE '%agent_addresses_recovered%'"
                ") ORDER BY q.slug ASC"
            ).fetchall()
            pv_rows = rc.execute(
                "SELECT chain_id, vault_addr, slug, net_krw, fully_exhausted FROM proven_vaults ORDER BY chain_id ASC, vault_addr ASC"
            ).fetchall()
        cur_raw = store.get_engine_meta("mode_b_sourcify_cursor_v1", "")
        cur_doc: Dict[str, Any] = {}
        if cur_raw:
            try:
                parsed_c = json.loads(cur_raw)
                if isinstance(parsed_c, dict):
                    cur_doc = dict(parsed_c)
                    cur_doc["sig_inflight"] = {}
                    cur_doc["code_inflight"] = {}
            except Exception:
                cur_doc = {}
        if not done_rows and not dyn_rows and not pv_rows and not cur_doc:
            return
        relay_doc: Dict[str, Any] = {
            "schema_version": 1,
            "mode_b_sourcify_cursor_v1": cur_doc,
            "done_items": [
                {
                    "slug": str(r["slug"]),
                    "priority": int(r["priority"]),
                    "mode": str(r["mode"] or "A"),
                    "chain": str(r["chain"]),
                    "tvl_usd": float(r["tvl_usd"] or 0.0),
                    "sort_rank": float(r["sort_rank"] or 0.0),
                    "addresses": json.loads(r["addresses_json"] or "[]"),
                    "principle_summary": str(r["principle_summary"] or ""),
                    "verdict": str(r["verdict"] or ""),
                    "net_krw": float(r["net_krw"] or 0.0),
                }
                for r in done_rows
            ],
            "pending_dynamic_items": [
                {
                    "slug": str(r["slug"]),
                    "priority": int(r["priority"]),
                    "mode": str(r["mode"] or "B"),
                    "chain": str(r["chain"]),
                    "tvl_usd": float(r["tvl_usd"] or 0.0),
                    "sort_rank": float(r["sort_rank"] or 0.0),
                    "addresses": json.loads(r["addresses_json"] or "[]"),
                    "principle_summary": str(r["principle_summary"] or ""),
                    "meta": json.loads(r["meta_json"] or "{}"),
                }
                for r in dyn_rows
            ],
            "proven_vaults": [
                {
                    "chain_id": int(r["chain_id"]),
                    "vault_addr": str(r["vault_addr"]),
                    "slug": str(r["slug"]),
                    "net_krw": float(r["net_krw"] or 0.0),
                    "fully_exhausted": bool(r["fully_exhausted"]),
                }
                for r in pv_rows
            ],
        }
        _write_json_atomic(eff_root / "_relay_state.json", relay_doc)
    except Exception:
        pass


def _import_relay_state(
    store: SQLiteStore,
    artifact_root: Optional[Path] = None,
    *,
    prune_unsealed_orphans: bool = False,
) -> int:
    """새 PC방에서 _relay_state.json 및 봉인 영수증(pins.json)을 읽어 완료 타겟·커서·검증 금고를 SQLite로 자동 복원."""
    eff_root = artifact_root if artifact_root is not None else ARTIFACT_ROOT
    if not eff_root.is_dir():
        return 0
    restored = 0
    done_now = store.list_done_slugs()
    relay_path = eff_root / "_relay_state.json"
    relay_doc = _read_json(relay_path, default=None) if relay_path.is_file() else None

    if isinstance(relay_doc, dict):
        dyn_list = relay_doc.get("pending_dynamic_items")
        if isinstance(dyn_list, list) and dyn_list:
            dyn_batch: List[Tuple[Any, ...]] = []
            dyn_meta: List[Tuple[str, Dict[str, Any]]] = []
            recovered_addr_slugs: List[str] = []
            for di in dyn_list:
                if not isinstance(di, dict):
                    continue
                ds = _norm_slug(str(di.get("slug") or ""))
                if not ds:
                    continue
                di_addrs = list(di.get("addresses") or ())
                di_meta = dict(di["meta"]) if isinstance(di.get("meta"), dict) else {}
                dyn_batch.append(
                    (
                        ds,
                        int(di.get("priority") or 1),
                        str(di.get("chain") or "ethereum"),
                        float(di.get("tvl_usd") or 0.0),
                        di_addrs,
                        str(di.get("mode") or "B"),
                        str(di.get("principle_summary") or ""),
                        float(di.get("sort_rank") or 0.0),
                    )
                )
                if di_meta:
                    dyn_meta.append((ds, di_meta))
                    if di_addrs and (di_meta.get("mode_b_zero_seed_recovered") or di_meta.get("agent_addresses_recovered")):
                        recovered_addr_slugs.append(ds)
            if dyn_meta:
                store.put_proto_meta_batch(dyn_meta)
            if dyn_batch:
                store.upsert_queue_items_batch(dyn_batch)
            if recovered_addr_slugs:
                now_rec = time.time()
                with store._write_tx():
                    for rs in recovered_addr_slugs:
                        store._conn.execute(
                            "UPDATE audit_queue SET claim_boot_id='RECOVERED', updated_at=? WHERE slug=? AND status='pending'",
                            (now_rec, rs),
                        )

        done_list = relay_doc.get("done_items")
        if isinstance(done_list, list) and done_list:
            missing_done_batch: List[Tuple[Any, ...]] = []
            verified_to_complete: List[Tuple[str, str, float]] = []
            for item_d in done_list:
                if not isinstance(item_d, dict):
                    continue
                ds = _norm_slug(str(item_d.get("slug") or ""))
                if not ds or ds in done_now or not (eff_root / ds / "pins.json").is_file():
                    continue
                ok_p, _, res_p, _ = _verify_protocol_pins_loaded(ds, root_dir=eff_root)
                if not ok_p or not isinstance(res_p, dict):
                    continue
                missing_done_batch.append(
                    (
                        ds,
                        int(item_d.get("priority") or (1 if str(item_d.get("mode") or "") == "B" else 2)),
                        str(item_d.get("chain") or res_p.get("chain") or "ethereum"),
                        float(item_d.get("tvl_usd") or 0.0),
                        list(item_d.get("addresses") or ()),
                        str(item_d.get("mode") or ("B" if ds.startswith(("modeb-", "case-")) else "A")),
                        str(item_d.get("principle_summary") or ""),
                        float(item_d.get("sort_rank") or 0.0),
                    )
                )
                verified_to_complete.append((ds, str(res_p.get("verdict") or ""), float(res_p.get("net_krw") or 0.0)))
            if missing_done_batch:
                store.upsert_queue_items_batch(missing_done_batch)
            for ds, v_s, krw_f in verified_to_complete:
                store.complete_queue_item(ds, v_s, krw_f)
                done_now.add(ds)
                restored += 1

        rel_cur = relay_doc.get("mode_b_sourcify_cursor_v1")
        if isinstance(rel_cur, dict) and rel_cur.get("phase"):
            loc_raw = store.get_engine_meta("mode_b_sourcify_cursor_v1", "")
            loc_cur: Dict[str, Any] = {}
            if loc_raw:
                try:
                    lp = json.loads(loc_raw)
                    if isinstance(lp, dict):
                        loc_cur = lp
                except Exception:
                    loc_cur = {}
            if not loc_cur:
                merged_cur = dict(rel_cur)
                merged_cur["sig_done_ranges"] = _merge_idx_ranges(rel_cur.get("sig_done_ranges") or [])
                merged_cur["code_done_ranges"] = _merge_idx_ranges(rel_cur.get("code_done_ranges") or [])
                merged_cur["sig_inflight"] = {}
                merged_cur["code_inflight"] = {}
            else:
                merged_cur = dict(loc_cur)
                l_ph = str(loc_cur.get("phase") or "seed_harvest")
                r_ph = str(rel_cur.get("phase") or "seed_harvest")
                if _CURSOR_PHASE_ORDER.get(r_ph, 0) > _CURSOR_PHASE_ORDER.get(l_ph, 0):
                    merged_cur["phase"] = r_ph
                for max_k in ("seed_cursor", "hash_offset", "sig_file_idx", "code_file_idx", "matched_count", "enqueued_count"):
                    merged_cur[max_k] = max(int(loc_cur.get(max_k) or 0), int(rel_cur.get(max_k) or 0))
                merged_cur["sidecar_done"] = bool(loc_cur.get("sidecar_done") or rel_cur.get("sidecar_done"))
                merged_cur["sig_done_ranges"] = _merge_idx_ranges(
                    list(loc_cur.get("sig_done_ranges") or []) + list(rel_cur.get("sig_done_ranges") or [])
                )
                merged_cur["code_done_ranges"] = _merge_idx_ranges(
                    list(loc_cur.get("code_done_ranges") or []) + list(rel_cur.get("code_done_ranges") or [])
                )
            store.put_engine_meta("mode_b_sourcify_cursor_v1", json.dumps(merged_cur, ensure_ascii=False))

        pv_list = relay_doc.get("proven_vaults")
        if isinstance(pv_list, list) and pv_list:
            now_pv = time.time()
            with store._write_tx():
                for pv in pv_list:
                    if not isinstance(pv, dict):
                        continue
                    v_addr = _norm_addr(str(pv.get("vault_addr") or ""))
                    cid_pv = int(pv.get("chain_id") or 0)
                    if cid_pv > 0 and v_addr:
                        store._conn.execute(
                            "INSERT OR REPLACE INTO proven_vaults(chain_id, vault_addr, slug, net_krw, fully_exhausted, proven_at) VALUES(?,?,?,?,?,?)",
                            (
                                cid_pv,
                                v_addr,
                                _norm_slug(str(pv.get("slug") or "")),
                                float(pv.get("net_krw") or 0.0),
                                1 if bool(pv.get("fully_exhausted", True)) else 0,
                                now_pv,
                            ),
                        )

    # _relay_state.json 외에 디스크에 직접 존재하는 봉인 영수증(pins.json)도 누락 없이 복원하고,
    # run 재개 시에는 핀·요청서·체크포인트 없이 반쪽만 남은 미완결 폴더를 정리하여 데드락을 예방한다.
    disk_batch: List[Tuple[Any, ...]] = []
    disk_complete: List[Tuple[str, str, float]] = []
    for d_ent in list(eff_root.iterdir()):
        if not d_ent.is_dir() or d_ent.name.startswith("_"):
            continue
        ns_d = _norm_slug(d_ent.name)
        if not ns_d or ns_d in done_now:
            continue
        if (d_ent / "pins.json").is_file():
            ok_d, _, res_d, _ = _verify_protocol_pins_loaded(ns_d, root_dir=eff_root)
            if ok_d and isinstance(res_d, dict):
                eff_m = "B" if ns_d.startswith(("modeb-", "case-")) else "A"
                disk_batch.append((ns_d, 1 if eff_m == "B" else 2, str(res_d.get("chain") or "ethereum"), 0.0, [], eff_m, "", 0.0))
                disk_complete.append((ns_d, str(res_d.get("verdict") or ""), float(res_d.get("net_krw") or 0.0)))
            continue
        if prune_unsealed_orphans:
            q_st_d = store.get_queue_status(ns_d)
            req_sub = d_ent / "poc_requests"
            has_live_work = (
                (d_ent / "checkpoint.json").is_file()
                or (d_ent / "address_request.json").is_file()
                or (d_ent / "poc_request.json").is_file()
                or (req_sub.is_dir() and any(req_sub.glob("poc_request_*.json")))
            )
            if q_st_d in ("", "pending") and not has_live_work:
                can_prune = False
                with _try_slug_lock(d_ent) as acq_orp:
                    can_prune = bool(acq_orp and not (d_ent / "pins.json").is_file())
                if can_prune:
                    shutil.rmtree(d_ent, ignore_errors=True)
    if disk_batch:
        store.upsert_queue_items_batch(disk_batch)
    for ns_d, v_d, krw_d in disk_complete:
        store.complete_queue_item(ns_d, v_d, krw_d)
        restored += 1
    return restored


# ═══════════════════════════════════════════════════════════════════════════
# §8. 통합 파이프라인 오케스트레이터 및 무인자 3-CLI (run / done / selftest)
# ═══════════════════════════════════════════════════════════════════════════


def _score_clean_against_seed_variant(
    seed_entry: Dict[str, Any],
    cand_clean: bytes,
    cand_masked: bytes,
    c_grams: Set[bytes],
    cm_grams: Set[bytes],
) -> float:
    s_clean: bytes = seed_entry["clean_bytes"]
    s_masked: bytes = seed_entry["masked_bytes"]
    if cand_clean == s_clean:
        return 1.0
    ratio = float(min(len(s_clean), len(cand_clean))) / float(max(len(s_clean), len(cand_clean)))
    if ratio < MIN_SIZE_RATIO:
        return 0.0
    if cand_masked and s_masked and cand_masked == s_masked:
        return 0.995
    s_grams: Set[bytes] = seed_entry["clean_grams"]
    sm_grams: Set[bytes] = seed_entry["masked_grams"]
    raw_sc = (float(len(s_grams & c_grams)) / float(len(s_grams))) if s_grams and c_grams else 0.0
    msk_sc = (float(len(sm_grams & cm_grams)) / float(len(sm_grams))) if sm_grams and cm_grams else 0.0
    return max(raw_sc, msk_sc)


def _merge_len_intervals(bounds: Sequence[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if not bounds:
        return []
    ordered = sorted((max(64, int(lo)), max(64, int(hi))) for lo, hi in bounds)
    merged: List[Tuple[int, int]] = [ordered[0]]
    for lo, hi in ordered[1:]:
        p_lo, p_hi = merged[-1]
        if lo <= p_hi + 64:
            merged[-1] = (p_lo, max(p_hi, hi))
        else:
            merged.append((lo, hi))
    return merged


_BALLPARK_NATIVE_USD_BY_CHAIN: Dict[str, float] = {
    "bsc": 600.0,
    "opbnb": 600.0,
    "avalanche": 25.0,
    "polygon": 0.4,
    "fantom": 0.5,
    "sonic": 0.5,
    "gnosis": 1.0,
    "celo": 0.6,
    "mantle": 0.8,
    "cronos": 0.1,
    "kaia": 0.15,
    "sei": 0.3,
    "berachain": 4.0,
    "hyperevm": 20.0,
    "monad": 1.0,
}


def _clone_fund_rank_boost(hint_usd: float) -> float:
    """보유 자금 추정치(USD)에 기반한 단조 증가형 Priority-1 랭크 가산점 계산."""
    if hint_usd <= 0.0 or not math.isfinite(hint_usd):
        return 0.0
    return float(min(500_000.0, hint_usd) + math.log1p(hint_usd))


def _probe_clone_liquid_balance_hints(
    router: Optional[RPCRouter],
    chain_addrs: Sequence[Tuple[str, str]],
) -> Dict[Tuple[str, str], float]:
    """
    Mode B 클론 후보들의 온체인 네이티브/WNATIVE/주요 스테이블코인 잔고 규모(USD 근사치)를
    체인당 최대 2회 배치 RPC(eth_getBalance + Multicall3.balanceOf)로 스냅샷하여 자금 보유 클론 우선 정렬에 활용.
    """
    if router is None or not chain_addrs:
        return {}
    is_mock = (
        type(router).call is not RPCRouter.call
        or "call" in router.__dict__
        or type(router).batch_call is not RPCRouter.batch_call
        or "batch_call" in router.__dict__
    )
    if getattr(socket.getaddrinfo, "__name__", "") == "_guarded_getaddrinfo" and not is_mock:
        return {}
    by_chain: Dict[str, List[str]] = {}
    for ch, ad in chain_addrs:
        c_nm = _norm_chain(ch)
        na = _norm_addr(ad)
        if not c_nm or not na:
            continue
        lst = by_chain.setdefault(c_nm, [])
        if na not in lst and len(lst) < 192:
            lst.append(na)
    bal_sel = bytes.fromhex(BALANCE_OF_SEL[2:])
    dec_sel = bytes.fromhex(_selector("decimals()")[2:])
    out: Dict[Tuple[str, str], float] = {}
    for c_nm, addrs in by_chain.items():
        try:
            wn = _norm_addr(WRAPPED_NATIVE_BY_CHAIN.get(c_nm) or "")
            stables = [
                na for s in (CHAIN_STABLES.get(c_nm) or ())[:4]
                if (na := _norm_addr(s)) and na != wn
            ]
            native_usd_unit_d = (
                Decimal("2500")
                if c_nm in NATIVE_ETH_CHAINS
                else _to_dec(_BALLPARK_NATIVE_USD_BY_CHAIN.get(c_nm, 1))
            )
            toks = ([wn] if wn else []) + stables
            dec_map: Dict[str, int] = {wn: 18} if wn else {}
            for chunk_off in range(0, len(addrs), 48):
                chunk_addrs = addrs[chunk_off : chunk_off + 48]
                native_calls = [("eth_getBalance", [_checksum(a), "latest"]) for a in chunk_addrs]
                native_res = router.batch_call(c_nm, native_calls, block_pin=0, timeout=6.0)
                for a, raw_bal in zip(chunk_addrs, native_res):
                    if isinstance(raw_bal, str) and raw_bal.startswith("0x"):
                        wei = _hex_to_int(raw_bal)
                        if wei > 0:
                            nat_est_d = (Decimal(wei) / (Decimal(10) ** 18)) * native_usd_unit_d
                            out[(c_nm, a)] = float(_to_dec(out.get((c_nm, a), 0)) + nat_est_d)
                if not toks:
                    continue
                need_dec = (chunk_off == 0) and bool(stables)
                mc_calls: List[Tuple[str, bytes]] = [(st, dec_sel) for st in stables] if need_dec else []
                for a in chunk_addrs:
                    pad_a = abi_encode(["address"], [_checksum(a)])
                    for tok in toks:
                        mc_calls.append((tok, bal_sel + pad_a))
                mc_res = router.multicall3(c_nm, mc_calls, block_pin=0, chunk_size=120)
                if len(mc_res) != len(mc_calls):
                    continue
                idx = 0
                if need_dec:
                    for st in stables:
                        ok_d, raw_d = mc_res[idx]
                        idx += 1
                        if ok_d and len(raw_d) >= 32:
                            dv = int.from_bytes(raw_d[:32], "big")
                            dec_map[st] = dv if 0 <= dv <= 24 else (18 if c_nm == "bsc" else 6)
                        else:
                            dec_map[st] = 18 if c_nm == "bsc" else 6
                for a in chunk_addrs:
                    for tok in toks:
                        ok_b, raw_b = mc_res[idx]
                        idx += 1
                        if not ok_b or len(raw_b) < 32:
                            continue
                        amt_raw = int.from_bytes(raw_b[:32], "big")
                        if amt_raw <= 0:
                            continue
                        dec_t = dec_map.get(tok, 18)
                        human_amt_d = Decimal(amt_raw) / (Decimal(10) ** dec_t)
                        usd_est_d = human_amt_d * (native_usd_unit_d if tok == wn else Decimal("1"))
                        if usd_est_d > _DEC_ZERO:
                            out[(c_nm, a)] = float(_to_dec(out.get((c_nm, a), 0)) + usd_est_d)
        except Exception:
            continue
    return out


def _collect_impl_proxies_for_chains(
    store: SQLiteStore,
    impl_addrs_by_chain: Dict[str, Sequence[str]],
) -> Tuple[Dict[Tuple[str, str], Set[str]], List[Tuple[str, str]]]:
    """
    체인별 구현체 주소 목록에 연결된 모든 프록시를 수집한다:
    - SQLite(`store.find_proxies_by_impl`)
    - 고속 클론 테이블(`_find_fast_clone_proxies_by_impl`)
    - 로컬 Sourcify V2 Parquet(`search_sourcify_v2_proxies_for_impls`)
    """
    proxies_by_impl: Dict[Tuple[str, str], Set[str]] = {}
    proxy_pairs: List[Tuple[str, str]] = []
    proxy_pair_seen: Set[Tuple[str, str]] = set()

    def _record(c_n: str, ni: str, p_addr: str) -> None:
        if not c_n or not ni or not p_addr or p_addr == ni:
            return
        proxies_by_impl.setdefault((c_n, ni), set()).add(p_addr)
        pk = (c_n, p_addr)
        if pk not in proxy_pair_seen:
            proxy_pair_seen.add(pk)
            proxy_pairs.append(pk)

    for raw_c, raw_impls in impl_addrs_by_chain.items():
        c_p = _norm_chain(str(raw_c))
        uniq_impls = list(dict.fromkeys(_norm_addr(str(a)) for a in raw_impls if _norm_addr(str(a))))
        if not c_p or not uniq_impls:
            continue
        impl_set_c = set(uniq_impls)
        sole_impl = uniq_impls[0] if len(uniq_impls) == 1 else ""
        cid_p = CHAIN_IDS.get(c_p, 0)

        for prow in store.find_proxies_by_impl(uniq_impls, chain_id=(cid_p or None)):
            p_addr = _norm_addr(str(prow.get("address") or ""))
            p_cid = int(prow.get("chain_id") or cid_p or 0)
            p_chain = _norm_chain(CHAIN_BY_ID.get(p_cid, c_p) if p_cid else c_p)
            if not p_addr or p_chain != c_p:
                continue
            for imp_a in (prow.get("impl_addrs") or []):
                ni = _norm_addr(str(imp_a))
                if ni in impl_set_c:
                    _record(c_p, ni, p_addr)

        try:
            fast_rows = _find_fast_clone_proxies_by_impl(
                uniq_impls,
                chain_id=(cid_p or None),
                limit=min(128, max(32, len(uniq_impls) * 4)),
            )
        except Exception:
            fast_rows = []
        for frow in fast_rows:
            p_addr = _norm_addr(str(frow.get("proxy_address") or frow.get("address") or ""))
            ni = _norm_addr(str(frow.get("impl_address") or ""))
            p_chain = _norm_chain(str(frow.get("chain") or c_p))
            if p_chain == c_p and p_addr:
                if ni in impl_set_c:
                    _record(c_p, ni, p_addr)
                elif not ni and sole_impl:
                    _record(c_p, sole_impl, p_addr)

        if cid_p > 0:
            try:
                pq_rows = search_sourcify_v2_proxies_for_impls(
                    uniq_impls,
                    chain_id=cid_p,
                    limit=min(128, max(32, len(uniq_impls) * 4)),
                )
            except Exception:
                pq_rows = []
            for srow in pq_rows:
                p_addr = _norm_addr(str(srow.get("proxy_address") or srow.get("address") or ""))
                ni = _norm_addr(str(srow.get("impl_address") or ""))
                p_cid = int(srow.get("chain_id") or cid_p or 0)
                p_chain = _norm_chain(str(srow.get("chain") or (CHAIN_BY_ID.get(p_cid, c_p) if p_cid else c_p)))
                if p_chain == c_p and p_addr:
                    if ni in impl_set_c:
                        _record(c_p, ni, p_addr)
                    elif not ni and sole_impl:
                        _record(c_p, sole_impl, p_addr)

    return proxies_by_impl, proxy_pairs


def _enqueue_mode_b_sourcify_matches(
    store: SQLiteStore,
    raw_matches: Sequence[Dict[str, Any]],
    router: Optional[RPCRouter] = None,
) -> int:
    """Mode B 297개 원천 사건 대비 Sourcify 매치 클론을 Priority=1 최우선으로 큐에 등록(자금 보유 클론·프록시 잔고 합산 우선 정렬)."""
    if not raw_matches:
        return 0
    cand_slugs: List[str] = []
    prepared: List[Tuple[str, Dict[str, Any]]] = []
    for m in raw_matches:
        c_slug = _norm_chain(str(m.get("chain") or ""))
        addr = _norm_addr(str(m.get("address") or ""))
        case_idx = int(m.get("case_idx", 0))
        if not c_slug or not addr:
            continue
        mslug = _norm_slug(f"modeb-match-{c_slug}-{case_idx:03d}-{addr[2:8]}{addr[-6:]}")
        cand_slugs.append(mslug)
        prepared.append((mslug, m))
    if not prepared:
        return 0
    existing = store.list_existing_slugs(cand_slugs)
    probe_pairs: List[Tuple[str, str]] = [
        (_norm_chain(str(m["chain"])), _norm_addr(str(m["address"])))
        for mslug, m in prepared
        if mslug not in existing
    ]
    probe_set: Set[Tuple[str, str]] = set(probe_pairs)
    proxies_by_impl: Dict[Tuple[str, str], Set[str]] = {}
    if probe_pairs:
        pending_by_chain: Dict[str, List[str]] = {}
        for c_p, a_p in probe_pairs:
            pending_by_chain.setdefault(c_p, []).append(a_p)
        proxies_by_impl, coll_proxy_pairs = _collect_impl_proxies_for_chains(store, pending_by_chain)
        for pk in coll_proxy_pairs:
            if pk not in probe_set:
                probe_set.add(pk)
                probe_pairs.append(pk)
    bal_hints = _probe_clone_liquid_balance_hints(router, probe_pairs) if router is not None and probe_pairs else {}
    batch_items: List[Tuple[str, int, str, float, Sequence[str], str, str, float]] = []
    meta_items: List[Tuple[str, Dict[str, Any]]] = []
    seen_slugs: Set[str] = set(existing)
    for mslug, m in prepared:
        if mslug in seen_slugs:
            continue
        seen_slugs.add(mslug)
        c_slug = _norm_chain(str(m["chain"]))
        addr = _norm_addr(str(m["address"]))
        score = float(m.get("score") or 0.0)
        assoc_proxies = sorted(proxies_by_impl.get((c_slug, addr), ()))
        hint_usd = float(bal_hints.get((c_slug, addr), 0.0)) + sum(
            float(bal_hints.get((c_slug, pa), 0.0)) for pa in assoc_proxies
        )
        s_rank = float(1_000_000.0 + score * 1000.0 + _clone_fund_rank_boost(hint_usd))
        batch_items.append(
            (mslug, 1, c_slug, MIN_TVL_USD, [addr], "B", str(m.get("principle") or ""), s_rank)
        )
        m_meta: Dict[str, Any] = {
            "mode_b_source_slug": str(m.get("seed_slug") or ""),
            "mode_b_source_addrs": list(m.get("seed_addrs") or []),
            "mode_b_source_chain": str(m.get("seed_chain") or c_slug),
            "mode_b_similarity": round(score, 4),
            "mode_b_seed_hashes": list(m.get("seed_hashes") or []),
            "mode_b_match_type": str(m.get("match_type") or "sourcify_cursor"),
            "matched_from": "sourcify_cursor",
        }
        if assoc_proxies:
            m_meta["mode_b_proxy_addrs"] = assoc_proxies[:32]
        if hint_usd > 0.0:
            m_meta["mode_b_hint_usd"] = round(hint_usd, 2)
        meta_items.append((mslug, m_meta))
    if not batch_items:
        return 0
    if meta_items:
        store.put_proto_meta_batch(meta_items)
    inserted_cnt = store.upsert_queue_items_batch(batch_items)
    _sync_sealed_receipts_for_batch(store, batch_items)
    return inserted_cnt


def _has_sourcify_corpus_files(p_root: Path) -> bool:
    if not p_root.is_dir():
        return False
    try:
        return (
            next(p_root.glob("*/*.parquet"), None) is not None
            or next(p_root.glob("*.parquet"), None) is not None
            or next(p_root.glob("*.jsonl"), None) is not None
            or next(p_root.glob("*/*.jsonl"), None) is not None
        )
    except OSError:
        return False


def _merge_idx_ranges(ranges: Sequence[Sequence[int]]) -> List[List[int]]:
    valid = sorted(
        ([int(r[0]), int(r[1])] for r in ranges if isinstance(r, (list, tuple)) and len(r) == 2 and int(r[1]) > int(r[0]) >= 0),
        key=lambda x: (x[0], x[1]),
    )
    if not valid:
        return []
    merged: List[List[int]] = [valid[0]]
    for lo, hi in valid[1:]:
        if lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])
    return merged


def _claim_next_slice_range(
    done_ranges: List[List[int]],
    inflight_map: Dict[str, float],
    total_cnt: int,
    step: int,
    now_ts: float,
    lease_sec: float = 60.0,
) -> Optional[Tuple[int, int]]:
    if total_cnt <= 0:
        return None
    expired_keys = [k for k, exp_v in list(inflight_map.items()) if float(exp_v or 0.0) <= now_ts]
    for ek in expired_keys:
        inflight_map.pop(ek, None)
    inf_ranges: List[List[int]] = []
    for k in inflight_map:
        parts = str(k).split(":", 1)
        if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
            inf_ranges.append([int(parts[0]), int(parts[1])])
    blocked = _merge_idx_ranges([*done_ranges, *inf_ranges])
    if not blocked:
        pos, next_lo = 0, total_cnt
    elif blocked[0][0] > 0:
        pos, next_lo = 0, blocked[0][0]
    else:
        pos = blocked[0][1]
        next_lo = blocked[1][0] if len(blocked) > 1 else total_cnt
    if pos >= total_cnt:
        return None
    end_pos = min(total_cnt, next_lo, pos + max(1, int(step)))
    if end_pos <= pos:
        return None
    inflight_map[f"{pos}:{end_pos}"] = now_ts + float(lease_sec)
    return pos, end_pos


def _get_mode_b_sourcify_cursor_phase(
    store: SQLiteStore,
    parquet_root: Optional[Path] = None,
) -> str:
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR
    if not _has_sourcify_corpus_files(p_root):
        return "exhausted"
    if not store.list_mode_b_primary_items():
        return "exhausted"
    raw_c = store.get_engine_meta("mode_b_sourcify_cursor_v1")
    if raw_c:
        try:
            doc_c = json.loads(raw_c)
            if isinstance(doc_c, dict) and doc_c.get("phase"):
                return str(doc_c["phase"])
        except Exception:
            pass
    return "seed_harvest"


def _advance_mode_b_sourcify_cursor(
    router: Optional[RPCRouter],
    store: SQLiteStore,
    parquet_root: Optional[Path] = None,
    max_wall_sec: float = 4.5,
    batch_code_files: int = 6,
) -> Dict[str, Any]:
    """
    컨트랙트.md(Mode B 297개 사건) × 로컬 Sourcify v2(129 GiB Parquet + 사이드카) 다중 세션 병렬 샤딩 파티션 커서:
    - engine_meta('mode_b_sourcify_cursor_v1') 상태를 따라 seed_harvest -> exact_hash -> sig_slices -> code_slices -> exhausted 순으로 재개 가능 전진.
    - sig_slices / code_slices는 슬라이스 구간 임대(sig_inflight/code_inflight) + 병합 완료 구간(sig_done_ranges/code_done_ranges)으로
      5개 동시 세션이 겹치지 않는 Parquet 파일 배치를 병렬 스캔하며, 타임아웃/크래시 시 해당 구간만 자동 회수 재시도(Fail-Open)한다.
    """
    t0 = time.monotonic()
    p_root = parquet_root if parquet_root is not None else SOURCIFY_PARQUET_DIR

    @contextlib.contextmanager
    def _cursor_meta_lock() -> Iterator[None]:
        if not store._is_memory:
            lpath = _store_cache_dir(store) / "_modeb_cursor_meta.lock"
            lpath.parent.mkdir(parents=True, exist_ok=True)
            with _exclusive_file_lock(lpath):
                yield
        else:
            with store._lock:
                yield

    @contextlib.contextmanager
    def _serial_phase_try_lock() -> Iterator[bool]:
        if not store._is_memory:
            spath = _store_cache_dir(store) / "_modeb_serial"
            spath.parent.mkdir(parents=True, exist_ok=True)
            with _try_slug_lock(spath) as acq_s:
                yield acq_s
        else:
            yield True

    def _load_cursor_dict() -> Dict[str, Any]:
        cur_raw_l = store.get_engine_meta("mode_b_sourcify_cursor_v1")
        cur_d: Dict[str, Any] = {}
        if cur_raw_l:
            try:
                ld = json.loads(cur_raw_l)
                if isinstance(ld, dict):
                    cur_d = ld
            except Exception:
                cur_d = {}
        cur_d.setdefault("phase", "seed_harvest")
        cur_d.setdefault("seed_cursor", 0)
        cur_d.setdefault("hash_offset", 0)
        cur_d.setdefault("sig_file_idx", 0)
        cur_d.setdefault("sig_step", 12)
        cur_d.setdefault("code_file_idx", 0)
        cur_d.setdefault("code_step", max(1, int(batch_code_files)))
        cur_d.setdefault("sidecar_done", False)
        cur_d.setdefault("matched_count", 0)
        cur_d.setdefault("enqueued_count", 0)
        s_done = _merge_idx_ranges(cur_d.get("sig_done_ranges") or ([] if int(cur_d["sig_file_idx"]) <= 0 else [[0, int(cur_d["sig_file_idx"])]]))
        c_done = _merge_idx_ranges(cur_d.get("code_done_ranges") or ([] if int(cur_d["code_file_idx"]) <= 0 else [[0, int(cur_d["code_file_idx"])]]))
        cur_d["sig_done_ranges"] = s_done
        cur_d["code_done_ranges"] = c_done
        cur_d["sig_inflight"] = dict(cur_d.get("sig_inflight") or {}) if isinstance(cur_d.get("sig_inflight"), dict) else {}
        cur_d["code_inflight"] = dict(cur_d.get("code_inflight") or {}) if isinstance(cur_d.get("code_inflight"), dict) else {}
        return cur_d

    def _save_cursor_dict(cur_d: Dict[str, Any]) -> None:
        try:
            store.put_engine_meta("mode_b_sourcify_cursor_v1", json.dumps(cur_d, ensure_ascii=False))
        except Exception:
            pass

    with _cursor_meta_lock():
        cursor = _load_cursor_dict()

    if cursor["phase"] == "exhausted":
        return {"phase": "exhausted", "enqueued": 0, "matched": 0, "timed_out": False}

    def _save_cursor() -> None:
        _save_cursor_dict(cursor)

    if not _has_sourcify_corpus_files(p_root):
        return {"phase": "exhausted", "enqueued": 0, "matched": 0, "timed_out": False}

    def _load_seed_variants() -> List[Dict[str, Any]]:
        if not store._is_memory:
            cand_paths = [_store_cache_dir(store) / "mode_b_seed_index_v1.json"]
            if _store_cache_dir(store).resolve() == CACHE_DIR.resolve():
                cand_paths.append(ARTIFACT_ROOT / "_relay_seed_index.json")
            for cpath in cand_paths:
                if cpath.is_file():
                    try:
                        d = json.loads(cpath.read_text(encoding="utf-8"))
                        if isinstance(d, dict) and isinstance(d.get("variants"), list):
                            return list(d["variants"])
                    except Exception:
                        pass
        raw_m = store.get_engine_meta("mode_b_seed_index_v1")
        if raw_m:
            try:
                d2 = json.loads(raw_m)
                if isinstance(d2, dict) and isinstance(d2.get("variants"), list):
                    return list(d2["variants"])
            except Exception:
                pass
        return []

    def _save_seed_variants(variants_list: List[Dict[str, Any]]) -> None:
        payload = {"variants": variants_list}
        if not store._is_memory:
            cdir_s = _store_cache_dir(store)
            _write_json_atomic(cdir_s / "mode_b_seed_index_v1.json", payload)
            if cdir_s.resolve() == CACHE_DIR.resolve():
                _write_json_atomic(ARTIFACT_ROOT / "_relay_seed_index.json", payload)
        else:
            store.put_engine_meta("mode_b_seed_index_v1", json.dumps(payload, ensure_ascii=True))

    modeb_items = store.list_mode_b_primary_items()
    if not modeb_items:
        return {"phase": cursor["phase"], "enqueued": 0, "matched": 0, "timed_out": False}

    seed_variants = _load_seed_variants()
    if not seed_variants and cursor["phase"] in ("exact_hash", "sig_slices", "code_slices"):
        with _cursor_meta_lock():
            cursor["phase"] = "seed_harvest"
            cursor["seed_cursor"] = 0
            _save_cursor()
    seed_addr_keys: Set[Tuple[int, str]] = {
        (CHAIN_IDS.get(_norm_chain(it["chain"]), 0), na)
        for it in modeb_items
        for a in (it.get("addresses") or ())
        if (na := _norm_addr(a))
    }

    enqueued_now = 0
    matched_now = 0
    timed_out_flag = False

    def _collect_variant_from_bytes(
        case_idx: int,
        it: Dict[str, Any],
        addr: str,
        raw_b: bytes,
    ) -> Optional[Dict[str, Any]]:
        clean_b = _strip_cbor_bytes(raw_b)
        if len(clean_b) < 64:
            return None
        sels: Set[str] = set()
        dis_sb = _disassemble(clean_b)
        for idx_d, (_, nm, imm) in enumerate(dis_sb):
            if nm == "PUSH4" and len(imm) == 4 and imm not in (b"\x00\x00\x00\x00", b"\xff\xff\xff\xff"):
                sh_l = imm.hex().lower()
                if sh_l not in _COMMON_BOILERPLATE_SELECTORS and any(
                    dis_sb[j][1] in ("EQ", "SUB", "GT", "LT")
                    for j in range(idx_d + 1, min(len(dis_sb), idx_d + 4))
                ):
                    sels.add(sh_l)
        if not sels:
            for _, nm, imm in dis_sb:
                if nm == "PUSH4" and len(imm) == 4 and imm not in (b"\x00\x00\x00\x00", b"\xff\xff\xff\xff"):
                    sh_l = imm.hex().lower()
                    if sh_l not in _COMMON_BOILERPLATE_SELECTORS:
                        sels.add(sh_l)
        hashes = sorted(
            {
                hashlib.sha256(raw_b).hexdigest().lower(),
                _keccak256(raw_b).hex().lower(),
                hashlib.sha256(clean_b).hexdigest().lower(),
                _keccak256(clean_b).hex().lower(),
            }
        )
        return {
            "case_idx": case_idx,
            "slug": str(it["slug"]),
            "chain": _norm_chain(it["chain"]),
            "addr": addr,
            "addrs": list(it.get("addresses") or ()),
            "principle": str(it.get("principle_summary") or "")[:400],
            "clean_hex": clean_b.hex(),
            "len_clean": len(clean_b),
            "hashes": hashes,
            "disp_sels": sorted(sels)[:12],
        }

    # Phase 1: Mode B 원천 시드 바이트코드 증분 수집 (로컬 Sourcify 우선 + 프록시 언래핑 + 과거 구현체/파괴전 복원)
    if cursor["phase"] == "seed_harvest":
        with _serial_phase_try_lock() as acq_s:
            if acq_s:
                sc_idx = int(cursor["seed_cursor"])
                seen_var_keys: Set[Tuple[str, str]] = {
                    (
                        str(v["slug"]),
                        hashlib.sha256(str(v.get("clean_hex") or "").encode("ascii")).hexdigest()[:32],
                    )
                    for v in seed_variants
                }

                def _add_seed_var(c_i: int, it_v: Dict[str, Any], ad_v: str, code_b_v: bytes) -> bool:
                    var = _collect_variant_from_bytes(c_i, it_v, ad_v, code_b_v)
                    if not var:
                        return False
                    vk = (
                        str(var["slug"]),
                        hashlib.sha256(str(var["clean_hex"]).encode("ascii")).hexdigest()[:32],
                    )
                    if vk in seen_var_keys:
                        return False
                    seen_var_keys.add(vk)
                    seed_variants.append(var)
                    return True

                while sc_idx < len(modeb_items) and (time.monotonic() - t0) < max_wall_sec:
                    chunk = modeb_items[sc_idx : sc_idx + 12]
                    by_chain: Dict[str, List[str]] = {}
                    for it in chunk:
                        cid_c = CHAIN_IDS.get(_norm_chain(it["chain"]), 0)
                        if cid_c > 0:
                            for a in (it.get("addresses") or ()):
                                na = _norm_addr(a)
                                if na:
                                    by_chain.setdefault(_norm_chain(it["chain"]), []).append(na)
                    local_codes_by_ca: Dict[Tuple[str, str], bytes] = {}
                    for c_nm, addr_grp in by_chain.items():
                        cid_c = CHAIN_IDS.get(c_nm, 0)
                        if cid_c <= 0:
                            continue
                        try:
                            hints = _query_local_sourcify_deployment_hints(cid_c, addr_grp, parquet_root=p_root)
                            for oa, ob in (hints.get("original_bytecodes") or {}).items():
                                if isinstance(ob, (bytes, bytearray)) and len(ob) >= 64:
                                    local_codes_by_ca[(c_nm, _norm_addr(oa))] = bytes(ob)
                        except Exception:
                            pass
                    for rel_i, it in enumerate(chunk):
                        if rel_i > 0 and (time.monotonic() - t0) >= max_wall_sec:
                            break
                        case_idx = sc_idx
                        c_nm = _norm_chain(it["chain"])
                        addrs = [_norm_addr(a) for a in (it.get("addresses") or ()) if _norm_addr(a)]
                        missing_rpc: List[str] = []
                        proxy_local_addrs: Set[str] = set()
                        for ad in addrs:
                            cb = local_codes_by_ca.get((c_nm, ad))
                            if cb:
                                _add_seed_var(case_idx, it, ad, cb)
                                if router is not None and _is_delegatecall_or_thin_proxy(cb):
                                    proxy_local_addrs.add(ad)
                                    missing_rpc.append(ad)
                            elif router is not None:
                                missing_rpc.append(ad)
                        item_rpc_incomplete = False
                        if missing_rpc and router is not None:
                            if (time.monotonic() - t0) >= max_wall_sec:
                                item_rpc_incomplete = True
                            else:
                                try:
                                    p_meta = store.get_proto_meta(it["slug"])
                                    blks: List[int] = []
                                    for raw_b in (p_meta.get("block_numbers") or ()):
                                        try:
                                            b_i = int(raw_b)
                                        except (TypeError, ValueError):
                                            b_i = 0
                                        if b_i > 1:
                                            blks.append(b_i)
                                    blk_h = (min(blks) - 1) if blks else 0
                                    eff_hi = blk_h
                                    if eff_hi <= 1:
                                        try:
                                            _, qh = router.get_quorum_head_block(c_nm)
                                            eff_hi = int(qh or 0)
                                        except Exception:
                                            eff_hi = 0
                                    hint_cap = max(eff_hi, max(blks) if blks else 0)
                                    hint_blocks = _extract_mode_b_hint_blocks(router, c_nm, p_meta, hint_cap)
                                    if hint_blocks:
                                        eff_hi = max(eff_hi, max(hint_blocks))
                                        if blk_h <= 0:
                                            blk_h = hint_blocks[0]
                                    target_addrs = list(dict.fromkeys(missing_rpc[:16]))
                                    res_map = _resolve_proxy_and_delegates(
                                        router, c_nm, target_addrs, blk_h, raise_on_rpc_failure=True
                                    )
                                    for ad_m in target_addrs:
                                        if (time.monotonic() - t0) >= max_wall_sec:
                                            item_rpc_incomplete = True
                                            break
                                        pr_m = res_map.get(ad_m)
                                        got_for_ad = False
                                        raw_is_proxy = ad_m in proxy_local_addrs
                                        if pr_m is not None:
                                            for chx in _res_facet_codes_hex(pr_m):
                                                rb = _hex_to_bytes(chx)
                                                if rb and len(rb) >= 64:
                                                    got_for_ad = True
                                                    _add_seed_var(case_idx, it, ad_m, rb)
                                            raw_b_m = _hex_to_bytes(pr_m.raw_code_hex)
                                            if pr_m.proxy_kind != "none" or (
                                                bool(raw_b_m)
                                                and any(
                                                    nm == "DELEGATECALL"
                                                    for _, nm, _ in _disassemble(_strip_cbor_bytes(raw_b_m))
                                                )
                                            ):
                                                raw_is_proxy = True
                                        if eff_hi > 1 and (raw_is_proxy or not got_for_ad):
                                            if raw_is_proxy:
                                                for hist_rb in _recover_historical_proxy_impl_bytecodes(
                                                    router, c_nm, ad_m, eff_hi, hint_blocks=hint_blocks
                                                ):
                                                    if hist_rb and len(hist_rb) >= 64:
                                                        got_for_ad = True
                                                        _add_seed_var(case_idx, it, ad_m, hist_rb)
                                            if not got_for_ad:
                                                hist_bisect = _recover_historical_bytecode_bisect(
                                                    router, c_nm, ad_m, eff_hi, hint_blocks=hint_blocks
                                                )
                                                rb_bisect = _hex_to_bytes(hist_bisect)
                                                if rb_bisect and len(rb_bisect) >= 64:
                                                    _add_seed_var(case_idx, it, ad_m, rb_bisect)
                                except Exception:
                                    item_rpc_incomplete = True
                        if item_rpc_incomplete:
                            break
                        sc_idx += 1
                _save_seed_variants(seed_variants)
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
                    cursor["seed_cursor"] = sc_idx
                    if sc_idx >= len(modeb_items):
                        cursor["phase"] = "exact_hash" if seed_variants else "exhausted"
                    _save_cursor()
            else:
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
        if cursor["phase"] in ("seed_harvest", "exhausted") or (time.monotonic() - t0) >= max_wall_sec:
            return {"phase": cursor["phase"], "enqueued": 0, "matched": 0, "timed_out": False}
        if not seed_variants:
            seed_variants = _load_seed_variants()

    if not seed_variants:
        with _cursor_meta_lock():
            cursor = _load_cursor_dict()
            cursor["phase"] = "exhausted"
            _save_cursor()
        return {"phase": "exhausted", "enqueued": 0, "matched": 0, "timed_out": False}

    f_counts, c_types, d_cols, ct_cols, chain_filter, addr_proj = _unpack_sourcify_base_schema(p_root, None)
    has_base_parquet = int(f_counts.get("contract_deployments", 0)) > 0 and int(f_counts.get("contracts", 0)) > 0
    vc_cols = c_types.get("verified_contracts") or {}
    ccs_sig_cols = c_types.get("compiled_contracts_signatures") or {}
    cd_cols = c_types.get("code") or {}
    rch_type = ct_cols.get("runtime_code_hash", "")
    usable_cid_list = ", ".join(str(cid) for cid in sorted(CHAIN_BY_ID.keys()) if _usable_chain(CHAIN_BY_ID[cid]))

    # Phase 2: Exact runtime_code_hash 일치 스캔 (36+60 메타 Parquet 초고속 조인)
    if cursor["phase"] == "exact_hash":
        with _serial_phase_try_lock() as acq_e:
            if acq_e:
                if has_base_parquet and DUCKDB_BIN.is_file():
                    hash_to_variants: Dict[str, List[Dict[str, Any]]] = {}
                    for v in seed_variants:
                        for h in v.get("hashes") or ():
                            hash_to_variants.setdefault(h, []).append(v)
                    all_hashes = sorted(hash_to_variants.keys())
                    h_off = int(cursor["hash_offset"])
                    while h_off < len(all_hashes) and (time.monotonic() - t0) < max_wall_sec:
                        h_chunk = all_hashes[h_off : h_off + 300]
                        if "BLOB" in rch_type:
                            rch_pred = f"ct.runtime_code_hash IN ({', '.join(f'unhex({_sql_quote_str(h)})' for h in h_chunk)})"
                            rch_sel = "lower(hex(ct.runtime_code_hash)) AS rch_hex"
                        else:
                            rch_pred = (
                                "lower(CASE WHEN typeof(ct.runtime_code_hash) = 'BLOB' THEN hex(ct.runtime_code_hash) "
                                f"ELSE replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', '') END) IN ({', '.join(_sql_quote_str(h) for h in h_chunk)})"
                            )
                            rch_sel = "lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', '')) AS rch_hex"
                        rows = _run_duckdb_cli_json(
                            f"""
                            SELECT
                                CAST(d.chain_id AS BIGINT) AS cid,
                                {addr_proj} AS addr_hex,
                                {rch_sel}
                            FROM contracts ct
                            JOIN contract_deployments d ON d.contract_id = ct.id
                            WHERE {rch_pred}
                              {chain_filter}
                            """,
                            parquet_root=p_root,
                            timeout_sec=max(5.0, max_wall_sec * 3.0),
                        )
                        if rows is None:
                            timed_out_flag = True
                            with _cursor_meta_lock():
                                cursor = _load_cursor_dict()
                                cursor["hash_offset"] = h_off
                                cursor["matched_count"] = int(cursor["matched_count"]) + matched_now
                                cursor["enqueued_count"] = int(cursor["enqueued_count"]) + enqueued_now
                                _save_cursor()
                            return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": True}
                        batch_m: List[Dict[str, Any]] = []
                        for er in rows:
                            parsed_er = _parse_usable_sourcify_row(er)
                            rch_k = str(er.get("rch_hex") or "").lower()
                            if parsed_er is None or (parsed_er[0], parsed_er[2]) in seed_addr_keys:
                                continue
                            cid_v, c_slug, addr_n = parsed_er
                            v_hits = hash_to_variants.get(rch_k)
                            if not v_hits:
                                continue
                            v0 = v_hits[0]
                            matched_now += 1
                            batch_m.append(
                                {
                                    "case_idx": v0["case_idx"],
                                    "seed_slug": v0["slug"],
                                    "seed_addrs": v0["addrs"],
                                    "seed_chain": v0["chain"],
                                    "seed_hashes": v0["hashes"],
                                    "principle": v0["principle"],
                                    "chain": c_slug,
                                    "address": addr_n,
                                    "score": 1.0,
                                    "match_type": "exact_hash",
                                }
                            )
                        enqueued_now += _enqueue_mode_b_sourcify_matches(store, batch_m, router=router)
                        h_off += len(h_chunk)
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()
                        cursor["hash_offset"] = h_off
                        if h_off >= len(all_hashes):
                            cursor["phase"] = "sig_slices"
                        cursor["matched_count"] = int(cursor["matched_count"]) + matched_now
                        cursor["enqueued_count"] = int(cursor["enqueued_count"]) + enqueued_now
                        _save_cursor()
                else:
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()
                        cursor["phase"] = "code_slices"
                        _save_cursor()
            else:
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
        if cursor["phase"] in ("exact_hash", "exhausted") or (time.monotonic() - t0) >= max_wall_sec:
            return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": False}

    # 사전 계산된 메모리 인덱스 구축 (sig_slices / code_slices 공용)
    precomp_variants: List[Dict[str, Any]] = []
    for v in seed_variants:
        c_bytes = _hex_to_bytes(v.get("clean_hex") or "")
        if len(c_bytes) < 64:
            continue
        m_bytes = _normalize_bytecode_immediates(c_bytes)
        precomp_variants.append(
            {
                **v,
                "clean_bytes": c_bytes,
                "masked_bytes": m_bytes,
                "clean_grams": _extract_grams_clean(c_bytes),
                "masked_grams": _extract_grams_clean(m_bytes),
                "disp_set": set(v.get("disp_sels") or ()),
            }
        )

    # Phase 3: 함수 시그니처 파티션 병렬 샤딩 슬라이스 (compiled_contracts_signatures/*.parquet)
    if cursor["phase"] == "sig_slices":
        has_sig_tables = all(
            int(f_counts.get(tbl, 0)) > 0
            for tbl in ("signatures", "compiled_contracts_signatures", "verified_contracts")
        )
        ccs_files = sorted((p_root / "compiled_contracts_signatures").glob("*.parquet"))
        sel_to_v_idxs: Dict[str, List[int]] = {}
        for idx_v, pv in enumerate(precomp_variants):
            for sh in sorted(pv["disp_set"])[:6]:
                sel_to_v_idxs.setdefault(sh, []).append(idx_v)
        chosen_sels = sorted(sel_to_v_idxs.keys())
        if has_base_parquet and has_sig_tables and ccs_files and chosen_sels and DUCKDB_BIN.is_file():
            vc_comp_col = _sf_col(vc_cols, "compilation_id", "compiled_contract_id")
            vc_dep_col = _sf_col(vc_cols, "deployment_id", "contract_deployment_id")
            ccs_sig_comp_col = _sf_col(ccs_sig_cols, "compilation_id", "compiled_contract_id")
            rch_hex_proj = (
                "lower(hex(ct.runtime_code_hash))"
                if "BLOB" in rch_type
                else "lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', ''))"
            )
            sel_blob_in = ", ".join(f"unhex({_sql_quote_str(sh)})" for sh in chosen_sels)
            min_sels_sql = 1 if len(chosen_sels) == 1 or any(len(pv["disp_set"]) == 1 for pv in precomp_variants) else 2
            while (time.monotonic() - t0) < max_wall_sec:
                claimed_sig: Optional[Tuple[int, int]] = None
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
                    if cursor["phase"] == "sig_slices":
                        s_done = _merge_idx_ranges(cursor.get("sig_done_ranges") or ())
                        s_inf = dict(cursor.get("sig_inflight") or {})
                        sig_step = max(1, int(cursor.get("sig_step") or 12))
                        claimed_sig = _claim_next_slice_range(
                            s_done,
                            s_inf,
                            len(ccs_files),
                            sig_step,
                            time.time(),
                            lease_sec=max(45.0, max_wall_sec * 6.0),
                        )
                        cursor["sig_done_ranges"] = s_done
                        cursor["sig_inflight"] = s_inf
                        if claimed_sig is None and len(s_done) == 1 and s_done[0] == [0, len(ccs_files)] and not s_inf:
                            cursor["phase"] = "code_slices"
                        _save_cursor()
                if claimed_sig is None:
                    break
                ccs_slice = ccs_files[claimed_sig[0] : claimed_sig[1]]
                sig_rows = _run_duckdb_cli_json(
                    f"""
                    WITH matched_comps AS (
                        SELECT
                            ccs.{ccs_sig_comp_col} AS comp_id_val,
                            COUNT(DISTINCT s.signature_hash_4) AS m_cnt,
                            string_agg(DISTINCT lower(hex(s.signature_hash_4)), ',') AS m_sels
                        FROM signatures s
                        JOIN compiled_contracts_signatures ccs ON ccs.signature_hash_32 = s.signature_hash_32
                        WHERE s.signature_hash_4 IN ({sel_blob_in})
                          AND ccs.signature_type = 'function'
                        GROUP BY ccs.{ccs_sig_comp_col}
                        HAVING COUNT(DISTINCT s.signature_hash_4) >= {min_sels_sql}
                    )
                    SELECT
                        CAST(d.chain_id AS BIGINT) AS cid,
                        {addr_proj} AS addr_hex,
                        {rch_hex_proj} AS rch_hex,
                        mc.m_sels AS m_sels
                    FROM matched_comps mc
                    JOIN verified_contracts vc ON vc.{vc_comp_col} = mc.comp_id_val
                    JOIN contract_deployments d ON vc.{vc_dep_col} = d.id
                    JOIN contracts ct ON d.contract_id = ct.id
                    WHERE 1=1 {chain_filter}
                    """,
                    parquet_root=p_root,
                    timeout_sec=max(5.0, max_wall_sec * 3.0),
                    table_files={"compiled_contracts_signatures": ccs_slice},
                )
                if sig_rows is None:
                    timed_out_flag = True
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()
                        s_inf = dict(cursor.get("sig_inflight") or {})
                        s_inf.pop(f"{claimed_sig[0]}:{claimed_sig[1]}", None)
                        cursor["sig_inflight"] = s_inf
                        cursor["sig_step"] = max(1, (claimed_sig[1] - claimed_sig[0]) // 2)
                        _save_cursor()
                    return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": True}
                cand_hits: List[Tuple[int, str, str, str, Dict[str, Any], float]] = []
                needed_rchs: Set[str] = set()
                for sr in sig_rows:
                    parsed_sr = _parse_usable_sourcify_row(sr)
                    rch_k = str(sr.get("rch_hex") or "").lower()
                    if parsed_sr is None or (parsed_sr[0], parsed_sr[2]) in seed_addr_keys:
                        continue
                    cid_v, c_slug, addr_n = parsed_sr
                    hit_sels = {x.strip().lower() for x in str(sr.get("m_sels") or "").split(",") if x.strip()}
                    best_pv: Optional[Dict[str, Any]] = None
                    best_sc = 0.0
                    cand_v_idxs: Set[int] = set()
                    for hs in hit_sels:
                        for iv in sel_to_v_idxs.get(hs, ()):
                            cand_v_idxs.add(iv)
                    for iv in cand_v_idxs:
                        pv = precomp_variants[iv]
                        if not pv["disp_set"]:
                            continue
                        inter = len(hit_sels & pv["disp_set"])
                        req_cnt = 1 if len(pv["disp_set"]) == 1 else max(2, int(len(pv["disp_set"]) * 0.4))
                        if inter >= req_cnt:
                            sc_s = min(0.99, float(inter) / float(max(1, len(pv["disp_set"]))))
                            if sc_s > best_sc:
                                best_sc = sc_s
                                best_pv = pv
                    if best_pv is not None:
                        cand_hits.append((cid_v, c_slug, addr_n, rch_k, best_pv, best_sc))
                        if _HEX64_RE.fullmatch(rch_k):
                            needed_rchs.add(rch_k)
                code_by_hash: Dict[str, bytes] = {}
                if needed_rchs and int(f_counts.get("code", 0)) > 0:
                    cd_ch_blob = "BLOB" in cd_cols.get("code_hash", "")
                    r_list = sorted(needed_rchs)[:128]
                    for r_off in range(0, len(r_list), 64):
                        rch_chunk = r_list[r_off : r_off + 64]
                        u_q = [
                            (
                                f"SELECT {_sql_quote_str(h)} AS ch_hex, lower(hex(cd.code)) AS c_hex "
                                f"FROM code cd WHERE cd.code_hash = unhex({_sql_quote_str(h)}) AND cd.code IS NOT NULL"
                            )
                            if cd_ch_blob
                            else (
                                f"SELECT {_sql_quote_str(h)} AS ch_hex, lower(hex(cd.code)) AS c_hex "
                                f"FROM code cd WHERE lower(CASE WHEN typeof(cd.code_hash) = 'BLOB' THEN hex(cd.code_hash) ELSE replace(CAST(cd.code_hash AS VARCHAR), '0x', '') END) = {_sql_quote_str(h)} AND cd.code IS NOT NULL"
                            )
                            for h in rch_chunk
                        ]
                        c_rows = _run_duckdb_cli_json(" UNION ALL ".join(u_q), parquet_root=p_root, timeout_sec=15.0)
                        for cr in c_rows or []:
                            ch_v = str(cr.get("ch_hex") or "").lower()
                            chex_v = str(cr.get("c_hex") or "")
                            if ch_v and chex_v:
                                try:
                                    code_by_hash[ch_v] = bytes.fromhex(chex_v)
                                except Exception:
                                    pass
                batch_sig_m: List[Dict[str, Any]] = []
                for cid_v, c_slug, addr_n, rch_k, pv, sel_sc in cand_hits:
                    fin_score = sel_sc
                    m_type = "selector_containment"
                    if rch_k in code_by_hash:
                        cb = code_by_hash[rch_k]
                        c_clean = _strip_cbor_bytes(cb)
                        if not c_clean:
                            continue
                        c_masked = _normalize_bytecode_immediates(c_clean)
                        fin_score = _score_clean_against_seed_variant(
                            pv, c_clean, c_masked, _extract_grams_clean(c_clean), _extract_grams_clean(c_masked)
                        )
                        if fin_score < CONTAINMENT_MIN:
                            continue
                        m_type = "exact" if fin_score >= 0.99 else "ngram"
                    elif sel_sc < CONTAINMENT_MIN:
                        continue
                    matched_now += 1
                    batch_sig_m.append(
                        {
                            "case_idx": pv["case_idx"],
                            "seed_slug": pv["slug"],
                            "seed_addrs": pv["addrs"],
                            "seed_chain": pv["chain"],
                            "seed_hashes": pv["hashes"],
                            "principle": pv["principle"],
                            "chain": c_slug,
                            "address": addr_n,
                            "score": fin_score,
                            "match_type": m_type,
                        }
                    )
                enq_s = _enqueue_mode_b_sourcify_matches(store, batch_sig_m, router=router)
                enqueued_now += enq_s
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
                    s_inf = dict(cursor.get("sig_inflight") or {})
                    s_inf.pop(f"{claimed_sig[0]}:{claimed_sig[1]}", None)
                    s_done = _merge_idx_ranges([*(cursor.get("sig_done_ranges") or ()), [claimed_sig[0], claimed_sig[1]]])
                    cursor["sig_done_ranges"] = s_done
                    cursor["sig_inflight"] = s_inf
                    cursor["sig_file_idx"] = s_done[0][1] if (s_done and s_done[0][0] == 0) else 0
                    cursor["matched_count"] = int(cursor["matched_count"]) + len(batch_sig_m)
                    cursor["enqueued_count"] = int(cursor["enqueued_count"]) + enq_s
                    if cursor["phase"] == "sig_slices" and len(s_done) == 1 and s_done[0] == [0, len(ccs_files)] and not s_inf:
                        cursor["phase"] = "code_slices"
                    _save_cursor()
        else:
            with _cursor_meta_lock():
                cursor = _load_cursor_dict()
                if cursor["phase"] == "sig_slices":
                    cursor["phase"] = "code_slices"
                    _save_cursor()
        if cursor["phase"] != "code_slices" or (time.monotonic() - t0) >= max_wall_sec:
            return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": False}

    # Phase 4: code/*.parquet 병렬 샤딩 + JSONL 사이드카 전수 멀티그램/마스크드 유사도 스캔
    if cursor["phase"] == "code_slices":
        def _score_cand_bytes_against_all(cb: bytes) -> Tuple[Optional[Dict[str, Any]], float]:
            c_clean = _strip_cbor_bytes(cb)
            if len(c_clean) < 64:
                return None, 0.0
            c_masked = _normalize_bytecode_immediates(c_clean)
            c_grams = _extract_grams_clean(c_clean)
            cm_grams = _extract_grams_clean(c_masked)
            best_pv: Optional[Dict[str, Any]] = None
            best_sc = 0.0
            n_cl = len(c_clean)
            for pv in precomp_variants:
                s_len = int(pv["len_clean"])
                if float(min(n_cl, s_len)) / float(max(n_cl, s_len)) < MIN_SIZE_RATIO:
                    continue
                sc = _score_clean_against_seed_variant(pv, c_clean, c_masked, c_grams, cm_grams)
                if sc > best_sc:
                    best_sc = sc
                    best_pv = pv
                if best_sc >= 1.0:
                    break
            return best_pv, best_sc

        if not bool(cursor.get("sidecar_done")):
            with _serial_phase_try_lock() as acq_sc:
                if acq_sc:
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()
                        need_sc = not bool(cursor.get("sidecar_done"))
                    if need_sc:
                        sidecar_m: List[Dict[str, Any]] = []
                        for sc_cid, sc_item in _iter_sourcify_sidecar_items(p_root):
                            c_slug = CHAIN_BY_ID.get(sc_cid, "")
                            addr_n = _norm_addr(sc_item.get("address"))
                            if not (c_slug and _usable_chain(c_slug) and addr_n) or (sc_cid, addr_n) in seed_addr_keys:
                                continue
                            chex = str(sc_item.get("runtime_code_hex") or sc_item.get("code_hex") or "").replace("0x", "").strip()
                            if not chex:
                                continue
                            try:
                                cb = bytes.fromhex(chex)
                            except Exception:
                                continue
                            bpv, bsc = _score_cand_bytes_against_all(cb)
                            if bpv is not None and bsc >= CONTAINMENT_MIN:
                                matched_now += 1
                                sidecar_m.append(
                                    {
                                        "case_idx": bpv["case_idx"],
                                        "seed_slug": bpv["slug"],
                                        "seed_addrs": bpv["addrs"],
                                        "seed_chain": bpv["chain"],
                                        "seed_hashes": bpv["hashes"],
                                        "principle": bpv["principle"],
                                        "chain": c_slug,
                                        "address": addr_n,
                                        "score": bsc,
                                        "match_type": "exact" if bsc >= 0.99 else "ngram",
                                    }
                                )
                        enq_sc = _enqueue_mode_b_sourcify_matches(store, sidecar_m, router=router)
                        enqueued_now += enq_sc
                        with _cursor_meta_lock():
                            cursor = _load_cursor_dict()
                            cursor["sidecar_done"] = True
                            cursor["matched_count"] = int(cursor["matched_count"]) + len(sidecar_m)
                            cursor["enqueued_count"] = int(cursor["enqueued_count"]) + enq_sc
                            _save_cursor()
                else:
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()

        code_files = sorted((p_root / "code").glob("*.parquet"))
        if has_base_parquet and code_files and DUCKDB_BIN.is_file():
            len_intervals = _merge_len_intervals(
                [
                    (max(64, int(pv["len_clean"] * MIN_SIZE_RATIO)), int(pv["len_clean"] / max(0.05, MIN_SIZE_RATIO)) + 256)
                    for pv in precomp_variants
                ]
            )
            len_sql = (
                " OR ".join(f"(octet_length(cd.code) BETWEEN {int(lo)} AND {int(hi)})" for lo, hi in len_intervals)
                if "BLOB" in cd_cols.get("code", "BLOB") and len_intervals
                else "octet_length(cd.code) >= 64" if "BLOB" in cd_cols.get("code", "BLOB") else "length(cd.code) >= 128"
            )
            join_ch_cond = (
                "ct.runtime_code_hash = cd.code_hash"
                if "BLOB" in rch_type and "BLOB" in cd_cols.get("code_hash", "")
                else "lower(replace(CAST(ct.runtime_code_hash AS VARCHAR), '0x', '')) = lower(replace(CAST(cd.code_hash AS VARCHAR), '0x', ''))"
            )
            code_hex_expr = (
                "lower(hex(cd.code))"
                if "BLOB" in cd_cols.get("code", "BLOB")
                else "lower(replace(CAST(cd.code AS VARCHAR), '0x', ''))"
            )
            while (time.monotonic() - t0) < max_wall_sec:
                claimed_code: Optional[Tuple[int, int]] = None
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
                    if cursor["phase"] == "code_slices":
                        c_done = _merge_idx_ranges(cursor.get("code_done_ranges") or ())
                        c_inf = dict(cursor.get("code_inflight") or {})
                        code_step = max(1, int(cursor.get("code_step") or batch_code_files))
                        claimed_code = _claim_next_slice_range(
                            c_done,
                            c_inf,
                            len(code_files),
                            code_step,
                            time.time(),
                            lease_sec=max(45.0, max_wall_sec * 6.0),
                        )
                        cursor["code_done_ranges"] = c_done
                        cursor["code_inflight"] = c_inf
                        if (
                            claimed_code is None
                            and len(c_done) == 1
                            and c_done[0] == [0, len(code_files)]
                            and not c_inf
                            and bool(cursor.get("sidecar_done"))
                        ):
                            cursor["phase"] = "exhausted"
                        _save_cursor()
                if claimed_code is None:
                    break
                c_slice = code_files[claimed_code[0] : claimed_code[1]]
                c_rows = _run_duckdb_cli_json(
                    f"""
                    SELECT
                        CAST(d.chain_id AS BIGINT) AS cid,
                        {addr_proj} AS addr_hex,
                        lower(hex(cd.code_hash)) AS ch_hex,
                        {code_hex_expr} AS code_hex
                    FROM code cd
                    JOIN contracts ct ON {join_ch_cond}
                    JOIN contract_deployments d ON d.contract_id = ct.id
                    WHERE ({len_sql})
                      AND CAST(d.chain_id AS BIGINT) IN ({usable_cid_list})
                      {chain_filter}
                    """,
                    parquet_root=p_root,
                    timeout_sec=max(5.0, max_wall_sec * 3.0),
                    table_files={"code": c_slice},
                )
                if c_rows is None:
                    timed_out_flag = True
                    with _cursor_meta_lock():
                        cursor = _load_cursor_dict()
                        c_inf = dict(cursor.get("code_inflight") or {})
                        c_inf.pop(f"{claimed_code[0]}:{claimed_code[1]}", None)
                        cursor["code_inflight"] = c_inf
                        cursor["code_step"] = max(1, (claimed_code[1] - claimed_code[0]) // 2)
                        _save_cursor()
                    return {"phase": cursor["phase"], "enqueued": enqueued_now, "matched": matched_now, "timed_out": True}
                hash_score_cache: Dict[str, Tuple[Optional[Dict[str, Any]], float]] = {}
                batch_code_m: List[Dict[str, Any]] = []
                for cr in c_rows:
                    cid_v = int(cr.get("cid") or 0)
                    c_slug = CHAIN_BY_ID.get(cid_v, "")
                    addr_s = str(cr.get("addr_hex") or "")
                    addr_n = _norm_addr(addr_s if addr_s.startswith("0x") else ("0x" + addr_s))
                    if not (c_slug and _usable_chain(c_slug) and addr_n) or (cid_v, addr_n) in seed_addr_keys:
                        continue
                    chk = str(cr.get("ch_hex") or "").lower()
                    if chk not in hash_score_cache:
                        try:
                            cb = bytes.fromhex(str(cr.get("code_hex") or ""))
                            hash_score_cache[chk] = _score_cand_bytes_against_all(cb)
                        except Exception:
                            hash_score_cache[chk] = (None, 0.0)
                    bpv, bsc = hash_score_cache[chk]
                    if bpv is not None and bsc >= CONTAINMENT_MIN:
                        matched_now += 1
                        batch_code_m.append(
                            {
                                "case_idx": bpv["case_idx"],
                                "seed_slug": bpv["slug"],
                                "seed_addrs": bpv["addrs"],
                                "seed_chain": bpv["chain"],
                                "seed_hashes": bpv["hashes"],
                                "principle": bpv["principle"],
                                "chain": c_slug,
                                "address": addr_n,
                                "score": bsc,
                                "match_type": "exact" if bsc >= 0.99 else "ngram",
                            }
                        )
                enq_c = _enqueue_mode_b_sourcify_matches(store, batch_code_m, router=router)
                enqueued_now += enq_c
                with _cursor_meta_lock():
                    cursor = _load_cursor_dict()
                    c_inf = dict(cursor.get("code_inflight") or {})
                    c_inf.pop(f"{claimed_code[0]}:{claimed_code[1]}", None)
                    c_done = _merge_idx_ranges([*(cursor.get("code_done_ranges") or ()), [claimed_code[0], claimed_code[1]]])
                    cursor["code_done_ranges"] = c_done
                    cursor["code_inflight"] = c_inf
                    cursor["code_file_idx"] = c_done[0][1] if (c_done and c_done[0][0] == 0) else 0
                    cursor["matched_count"] = int(cursor["matched_count"]) + len(batch_code_m)
                    cursor["enqueued_count"] = int(cursor["enqueued_count"]) + enq_c
                    if (
                        cursor["phase"] == "code_slices"
                        and len(c_done) == 1
                        and c_done[0] == [0, len(code_files)]
                        and not c_inf
                        and bool(cursor.get("sidecar_done"))
                    ):
                        cursor["phase"] = "exhausted"
                    _save_cursor()
        else:
            with _cursor_meta_lock():
                cursor = _load_cursor_dict()
                if cursor["phase"] == "code_slices" and bool(cursor.get("sidecar_done")):
                    cursor["phase"] = "exhausted"
                    _save_cursor()

    return {
        "phase": cursor["phase"],
        "enqueued": enqueued_now,
        "matched": matched_now,
        "timed_out": timed_out_flag,
    }


def _collect_mode_a_seed_items() -> Tuple[
    List[Tuple[str, int, str, float, Sequence[str], str, str]],
    List[Tuple[str, Dict[str, Any]]],
    bool,
]:
    """Mode A(Priority 2: _queue.json 캐시 또는 DeFiLlama 스팟 EVM TVL >= $100k 전수) 시드 목록 수집(무락 HTTP I/O 가능)."""
    batch_items: List[Tuple[str, int, str, float, Sequence[str], str, str]] = []
    meta_items: List[Tuple[str, Dict[str, Any]]] = []

    _NON_SPOT_TVL_KEYS = {
        "borrowed",
        "staking",
        "vesting",
        "doublecounted",
        "govtokens",
    }
    _NON_SPOT_TVL_SUFFIXES = (
        "-borrowed",
        "-staking",
        "-vesting",
        "-doublecounted",
        "-govtokens",
    )

    min_tvl_dec = _to_dec(MIN_TVL_USD)

    def _extract_tvl_dec(val_raw: Any) -> Decimal:
        if isinstance(val_raw, (int, float, Decimal)) and not isinstance(val_raw, bool):
            d_v = _to_dec(val_raw)
            return d_v if d_v.is_finite() and d_v > _DEC_ZERO else _DEC_ZERO
        if isinstance(val_raw, str):
            d_s = _to_dec(val_raw.strip())
            return d_s if d_s.is_finite() and d_s > _DEC_ZERO else _DEC_ZERO
        if isinstance(val_raw, list) and val_raw:
            last_el = val_raw[-1]
            if isinstance(last_el, dict):
                return _extract_tvl_dec(
                    last_el.get("totalLiquidityUSD") if last_el.get("totalLiquidityUSD") is not None else last_el.get("tvl")
                )
            return _extract_tvl_dec(last_el)
        if isinstance(val_raw, dict):
            for k_tvl in ("tvl", "totalLiquidityUSD", "tvl_usd"):
                if k_tvl in val_raw and val_raw.get(k_tvl) is not None:
                    return _extract_tvl_dec(val_raw.get(k_tvl))
        return _DEC_ZERO

    # 1. 기존 audit_artifacts/_queue.json에 캐시된 시드가 있으면 우선 병합
    legacy_q = QUEUE_FILE_PATH
    if legacy_q.exists():
        try:
            qdata = _read_json(legacy_q, default={})
            items = qdata if isinstance(qdata, list) else qdata.get("items", qdata.get("queue", []))
            if isinstance(items, list):
                for it in items:
                    if not isinstance(it, dict):
                        continue
                    try:
                        slug = _norm_slug(it.get("slug") or it.get("name") or "")
                        chain = _norm_chain(str(it.get("chain") or "ethereum"))
                        tvl_d = _extract_tvl_dec(it.get("tvl_usd") if it.get("tvl_usd") is not None else it.get("tvl"))
                        addrs = it.get("addresses") or it.get("contracts") or []
                        if isinstance(addrs, str):
                            addrs = [na] if (na := _norm_addr(addrs)) else []
                        elif isinstance(addrs, list):
                            addrs = [na for x in addrs if (na := _norm_addr(str(x)))]
                        if slug and tvl_d >= min_tvl_dec and chain in CHAIN_IDS:
                            batch_items.append((slug, 2, chain, float(tvl_d), addrs, "A", ""))
                            meta_dict = {
                                "url": str(it.get("url") or ""),
                                "docs": str(it.get("docs") or ""),
                                "gitbook": str(it.get("gitbook") or ""),
                                "github": it.get("github") if isinstance(it.get("github"), list) else ([str(it["github"])] if it.get("github") else []),
                                "module": str(it.get("module") or ""),
                            }
                            if any(meta_dict.values()):
                                meta_items.append((slug, meta_dict))
                    except Exception:
                        continue
        except Exception:
            pass

    # 2. 실시간 DeFiLlama /protocols API 페치 시도 (Mode A: Priority 2, CEX/Chain만 제외, 스팟 EVM TVL >= $100k 전수 포함)
    if not batch_items:
        try:
            plist = _http_get_json_with_fallback(None, "https://api.llama.fi/protocols", timeout=15.0)
            if isinstance(plist, list):
                for p in plist:
                    if not isinstance(p, dict):
                        continue
                    try:
                        cat = str(p.get("category") or "").strip()
                        has_explicit_contracts = bool(
                            _norm_addr(str(p.get("address") or "").split(":", 1)[-1])
                            or (isinstance(p.get("addresses"), dict) and p.get("addresses"))
                            or (isinstance(p.get("contracts"), dict) and p.get("contracts"))
                        )
                        if cat == "CEX" or (cat == "Chain" and not has_explicit_contracts):
                            continue
                        slug = _norm_slug(p.get("slug") or p.get("name") or "")
                        if not slug:
                            continue

                        raw_addr = str(p.get("address") or "")
                        chain_str = str(p.get("chain") or "ethereum")
                        if ":" in raw_addr:
                            ch_part, ad_part = raw_addr.split(":", 1)
                            chain_str = ch_part
                            raw_addr = ad_part
                        c_norm = _norm_chain(chain_str)
                        a_norm = _norm_addr(raw_addr)
                        seed_list = [a_norm] if a_norm else []

                        ch_tvls = p.get("chainTvls")
                        spot_evm_by_chain: Dict[str, Decimal] = {}
                        has_explicit_spot_tvls = False
                        if isinstance(ch_tvls, dict):
                            for ch_k, ch_v in ch_tvls.items():
                                k_str = str(ch_k).strip()
                                k_low = k_str.lower()
                                if k_low in _NON_SPOT_TVL_KEYS or k_low.endswith(_NON_SPOT_TVL_SUFFIXES):
                                    continue
                                has_explicit_spot_tvls = True
                                sub_c = _norm_chain(k_str)
                                sub_val_d = _extract_tvl_dec(ch_v)
                                if sub_c in CHAIN_IDS and sub_val_d > _DEC_ZERO:
                                    spot_evm_by_chain[sub_c] = spot_evm_by_chain.get(sub_c, _DEC_ZERO) + sub_val_d

                        raw_total_tvl_d = _extract_tvl_dec(p.get("tvl"))
                        raw_chains = p.get("chains")
                        fb_evm: List[str] = (
                            list(dict.fromkeys(nc for cx in raw_chains if _usable_chain(nc := _norm_chain(str(cx)))))
                            if isinstance(raw_chains, list)
                            else []
                        )
                        if not spot_evm_by_chain and c_norm not in CHAIN_IDS:
                            if fb_evm:
                                c_norm = fb_evm[0]
                            elif has_explicit_contracts:
                                c_norm = "ethereum"
                        total_spot_evm_tvl_d = (
                            sum(spot_evm_by_chain.values(), _DEC_ZERO)
                            if spot_evm_by_chain
                            else (_DEC_ZERO if has_explicit_spot_tvls else (raw_total_tvl_d if c_norm in CHAIN_IDS else _DEC_ZERO))
                        )
                        if total_spot_evm_tvl_d < min_tvl_dec:
                            continue

                        gh_raw = p.get("github")
                        gh_list = [str(g).strip() for g in gh_raw if str(g).strip()] if isinstance(gh_raw, list) else ([str(gh_raw).strip()] if gh_raw else [])
                        p_meta = {
                            "url": str(p.get("url") or "").strip(),
                            "github": gh_list,
                            "module": str(p.get("module") or "").strip(),
                            "address": str(p.get("address") or "").strip(),
                        }
                        has_p_meta = any(p_meta.values())
                        if has_p_meta:
                            meta_items.append((slug, p_meta))

                        # 멀티체인 배포(spot_evm_by_chain) 중 스팟 TVL >= $100(MIN_PROFIT_USD) 체인 전수 큐 등록 (부속 체인 누락 차단)
                        addr_map_raw = p.get("addresses") if isinstance(p.get("addresses"), dict) else (
                            p.get("contracts") if isinstance(p.get("contracts"), dict) else {}
                        )
                        norm_addr_map: Dict[str, List[str]] = {}
                        for ak, av in addr_map_raw.items():
                            nak = _norm_chain(str(ak))
                            if not nak:
                                continue
                            if isinstance(av, str):
                                na = _norm_addr(av.split(":", 1)[-1])
                                if na:
                                    norm_addr_map.setdefault(nak, []).append(na)
                            elif isinstance(av, list):
                                for x in av:
                                    na = _norm_addr(str(x).split(":", 1)[-1])
                                    if na:
                                        norm_addr_map.setdefault(nak, []).append(na)

                        def _append_mode_a_subchain(sub_c: str, use_root_slug: bool, eff_tvl_d: Decimal) -> None:
                            sub_slug = slug if use_root_slug else _norm_slug(f"{slug}-{sub_c}")
                            sub_seeds = list(
                                dict.fromkeys(
                                    [*seed_list, *norm_addr_map.get(sub_c, [])]
                                    if (sub_c == c_norm and seed_list)
                                    else norm_addr_map.get(sub_c, [])
                                )
                            )
                            batch_items.append((sub_slug, 2, sub_c, float(eff_tvl_d), sub_seeds, "A", ""))
                            if sub_slug != slug and has_p_meta:
                                meta_items.append((sub_slug, dict(p_meta)))

                        eligible_evm_chains = [
                            (sc, st_d)
                            for sc, st_d in spot_evm_by_chain.items()
                            if sc in CHAIN_IDS and st_d >= PROFIT_FLOOR_DEC
                        ]
                        if eligible_evm_chains:
                            ordered_evm_chains: List[Tuple[str, Decimal]] = []
                            if c_norm in CHAIN_IDS and spot_evm_by_chain.get(c_norm, _DEC_ZERO) >= PROFIT_FLOOR_DEC:
                                ordered_evm_chains.append((c_norm, spot_evm_by_chain[c_norm]))
                            for sc, st_d in sorted(eligible_evm_chains, key=lambda x: (-x[1], x[0])):
                                if (sc != c_norm or not ordered_evm_chains) and all(prev_c != sc for prev_c, _ in ordered_evm_chains):
                                    ordered_evm_chains.append((sc, st_d))
                            for idx_c, (sub_c, sub_tvl_d) in enumerate(ordered_evm_chains):
                                use_root = idx_c == 0 and (sub_c == c_norm or c_norm not in spot_evm_by_chain)
                                eff_tvl_d = max(sub_tvl_d, total_spot_evm_tvl_d) if (idx_c == 0 and len(ordered_evm_chains) == 1) else sub_tvl_d
                                _append_mode_a_subchain(sub_c, use_root, eff_tvl_d)
                        elif c_norm in CHAIN_IDS:
                            for idx_fb, sub_c in enumerate(dict.fromkeys([c_norm, *fb_evm])):
                                _append_mode_a_subchain(sub_c, idx_fb == 0, total_spot_evm_tvl_d)
                    except Exception:
                        continue
        except Exception:
            pass

    any_mode_a_seeded = any(len(it) >= 6 and it[5] == "A" for it in batch_items)
    return batch_items, meta_items, any_mode_a_seeded


def _ensure_mode_a_seeded(store: SQLiteStore) -> int:
    """
    지연된 Mode A(DeFiLlama HTTP) 시드 적재를 파일 락 밖에서 선행 페치한 뒤,
    락 내부에서는 mode_a_seed_pending 재확인 및 SQLite 배치 커밋만 원자적으로 수행.
    """
    if store.get_engine_meta("mode_a_seed_pending", "0") != "1":
        return 0
    a_items, a_meta, any_mode_a = _collect_mode_a_seed_items()
    with _exclusive_file_lock(LOCK_FILE_PATH):
        if store.get_engine_meta("mode_a_seed_pending", "0") != "1":
            return 0
        if a_meta:
            store.put_proto_meta_batch(a_meta)
        inserted = store.upsert_queue_items_batch(a_items) if a_items else 0
        if a_items:
            _sync_sealed_receipts_for_batch(store, a_items)
        if any_mode_a:
            store.put_engine_meta("mode_a_seed_ok", "1")
            store.put_engine_meta("mode_a_seed_pending", "0")
        else:
            store.put_engine_meta("mode_a_seed_ok", "0")
            # Keep mode_a_seed_pending="1" so transient HTTP failures retry on the next run instead of permanently dropping Mode A.
        return inserted


def _seed_queue_from_existing_or_live(store: SQLiteStore, defer_mode_a: bool = False) -> int:
    """Mode B(Priority 1: 컨트랙트.md 전 사건 헤더 무손실 분할 및 유사 컨트랙트 탐색 최우선) 및 Mode A(Priority 2: 지연 적재 지원) 일괄 큐 적재."""
    counts = store.queue_counts()
    if sum(counts.values()) > 0:
        return sum(counts.values())

    batch_items: List[Tuple[Any, ...]] = []
    meta_items: List[Tuple[str, Dict[str, Any]]] = []

    if defer_mode_a:
        store.put_engine_meta("mode_a_seed_pending", "1")
    else:
        a_items, a_meta, any_mode_a_seeded = _collect_mode_a_seed_items()
        batch_items.extend(a_items)
        meta_items.extend(a_meta)
        store.put_engine_meta("mode_a_seed_ok", "1" if any_mode_a_seeded else "0")
        store.put_engine_meta("mode_a_seed_pending", "0")

    # 3. Mode B (Priority 1): 컨트랙트.md 역사적 사례 전수 파싱 (전수 무손실 분할 + 0-시드 EVM 사례 주소 탐색 큐잉 + 분할 봉인)
    c_part = _parse_corpus_md_partition()
    evm_cases: List[HistoricalCaseSeed] = list(c_part.get("evm_cases") or [])
    pure_non_evm_cases: List[HistoricalCaseSeed] = list(c_part.get("pure_non_evm_cases") or [])
    total_headers = int(c_part.get("total_headers") or 0)
    store.put_engine_meta("corpus_md_total_headers", str(total_headers))
    store.put_engine_meta("corpus_md_evm_cases", str(len(evm_cases)))
    store.put_engine_meta("corpus_md_pure_non_evm_cases", str(len(pure_non_evm_cases)))

    seen_modeb_chain_addrs: Set[Tuple[str, Tuple[str, ...]]] = set()
    sig_to_primary_slug: Dict[Tuple[str, Tuple[str, ...]], str] = {}
    evm_case_slug_map: Dict[str, List[str]] = {}
    for idx, hc in enumerate(evm_cases):
        seeded_any = False
        case_slugs: List[str] = []
        default_hc_chain = hc.chains[0] if (hc.chains and hc.chains[0] in CHAIN_IDS) else "ethereum"
        case_candidates: List[Tuple[str, List[str]]] = []
        for ch_name, addr_list in hc.seed_addresses.items():
            c_norm = _norm_chain(ch_name)
            if c_norm not in CHAIN_IDS:
                c_norm = default_hc_chain
            addrs = list(dict.fromkeys(nx for x in addr_list if (nx := _norm_addr(x))))
            if not addrs:
                continue
            case_candidates.append((c_norm, addrs))
        for c_idx, (c_norm, addrs) in enumerate(case_candidates):
            sig_key = (c_norm, tuple(addrs))
            if sig_key in seen_modeb_chain_addrs and (seeded_any or c_idx < len(case_candidates) - 1):
                if sig_key in sig_to_primary_slug:
                    case_slugs.append(sig_to_primary_slug[sig_key])
                continue
            if sig_key in sig_to_primary_slug:
                seeded_any = True
                case_slugs.append(sig_to_primary_slug[sig_key])
                continue
            seen_modeb_chain_addrs.add(sig_key)
            seeded_any = True
            h_slug = _norm_slug(f"modeb-{c_norm}-{idx:03d}-{addrs[0][2:8]}{addrs[0][-6:]}")
            sig_to_primary_slug[sig_key] = h_slug
            case_slugs.append(h_slug)
            s_rank = float(len(addrs) * 1000 + max(0, 500 - idx))
            batch_items.append((h_slug, 1, c_norm, MIN_TVL_USD, addrs, "B", hc.principle_summary, s_rank))
            if hc.tx_hashes or hc.block_numbers:
                s_meta: Dict[str, Any] = {"title": hc.title}
                if hc.tx_hashes:
                    s_meta["tx_hashes"] = list(hc.tx_hashes)
                if hc.block_numbers:
                    s_meta["block_numbers"] = list(hc.block_numbers)
                meta_items.append((h_slug, s_meta))
        if not seeded_any:
            c_norm = default_hc_chain
            title_slug = _norm_slug(hc.title)[:24] or f"case-{idx:03d}"
            h_slug = _norm_slug(f"modeb-{c_norm}-{idx:03d}-{title_slug}")
            case_slugs.append(h_slug)
            s_rank = float((100 if hc.tx_hashes else 0) + max(0, 500 - idx))
            batch_items.append((h_slug, 1, c_norm, MIN_TVL_USD, [], "B", hc.principle_summary, s_rank))
            z_meta: Dict[str, Any] = {"title": hc.title, "mode_b_zero_seed": True}
            if hc.tx_hashes:
                z_meta["tx_hashes"] = list(hc.tx_hashes)
            if hc.block_numbers:
                z_meta["block_numbers"] = list(hc.block_numbers)
            meta_items.append((h_slug, z_meta))
        evm_case_slug_map[str(idx)] = list(dict.fromkeys(case_slugs))

    pure_non_evm_evidence = [{"case_idx": i, "chains": list(nc.chains)} for i, nc in enumerate(pure_non_evm_cases)]
    store.put_engine_meta(
        "corpus_md_partition_seal",
        json.dumps(
            {
                "evm_case_slug_map": evm_case_slug_map,
                "pure_non_evm_evidence": pure_non_evm_evidence,
            },
            ensure_ascii=False,
        ),
    )

    if meta_items:
        store.put_proto_meta_batch(meta_items)
    inserted_cnt = store.upsert_queue_items_batch(batch_items)
    _sync_sealed_receipts_for_batch(store, batch_items)
    return inserted_cnt


_GITBOOK_URL_RE: re.Pattern[str] = re.compile(r"https?://[a-zA-Z0-9_.-]+\.gitbook\.io(?:/[^\s\"'<>)]*)?", re.IGNORECASE)
_GITHUB_REPO_RE: re.Pattern[str] = re.compile(r"https?://github\.com/([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+)", re.IGNORECASE)
_DOCS_LINK_RE: re.Pattern[str] = re.compile(
    r"https?://(?:docs\.[a-zA-Z0-9_.-]+|[a-zA-Z0-9_.-]+/(?:docs|contracts|deployments))(?:/[^\s\"'<>)]*)?",
    re.IGNORECASE,
)


def _default_fetch_text(url: str, timeout: float = 4.0) -> str:
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "DefiAuditEngine/1.0",
            "Accept": "text/html,application/json,text/plain,*/*",
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read(262_144).decode("utf-8", errors="replace")


def _extract_agent_discovered_addresses(disc_path: Path) -> Tuple[List[str], bool]:
    """
    에이전트가 웹 검색 쿼리(1순위: 공식 Docs -> 2순위: GitBook -> 3순위: GitHub -> 4순위: DeFiLlama Adapter)로
    수집하여 기록한 `audit_artifacts/<slug>/discovered_addresses.json`에서 우선순위 순서대로 주소를 추출.
    반환값: (ordered_addresses, confirmed_no_onchain_contracts)
    """
    if not disc_path.is_file():
        return [], False
    doc = _read_json(disc_path, default=None)
    if doc is None:
        return [], False
    ordered: List[str] = []
    seen_ordered: Set[str] = set()

    def _add_raw_addrs(items: Sequence[Any]) -> None:
        for x in items:
            na = _norm_addr(str(x))
            if na and int(na, 16) > 0:
                _append_unique(ordered, seen_ordered, na)

    if isinstance(doc, list):
        _add_raw_addrs(doc)
        return ordered, (len(ordered) == 0)
    if isinstance(doc, dict):
        if (
            bool(doc.get("no_onchain_contracts", False))
            or bool(doc.get("confirmed_no_contracts", False))
            or bool(doc.get("pure_offchain_proven", False))
        ):
            return [], True
        for stage_key in (
            "official_docs",
            "docs",
            "gitbook",
            "github",
            "defillama_adapter",
            "defillama",
            "addresses",
            "contracts",
        ):
            val = doc.get(stage_key)
            if isinstance(val, list):
                _add_raw_addrs(val)
            elif isinstance(val, str):
                for na in _extract_addresses_from_text(val):
                    if int(na, 16) > 0:
                        _append_unique(ordered, seen_ordered, na)
        return ordered, False
    return [], False


_SUBDOMAIN_PREFIX_RE: re.Pattern[str] = re.compile(r"^(?:app|www|dapp|portal)\.")


def _filter_onchain_contract_addrs(
    router: Optional[RPCRouter],
    chain: str,
    addrs: Sequence[str],
    block_pin: int,
) -> Tuple[List[str], bool]:
    """`block_pin > 0`일 때 `eth_getCode` 배치 조회로 실제 컨트랙트 바이트코드가 존재하는 주소만 선별 반환한다."""
    c = _norm_chain(chain)
    clean_addrs: List[str] = []
    seen_c: Set[str] = set()
    for raw_a in addrs:
        na = _norm_addr(str(raw_a))
        if na and _is_non_precompile_addr(na) and na not in seen_c:
            seen_c.add(na)
            clean_addrs.append(na)
    if not clean_addrs or int(block_pin) <= 0 or router is None:
        return clean_addrs, False
    btag = hex(int(block_pin))
    try:
        code_res: List[Any] = []
        for off_ca in range(0, len(clean_addrs), 64):
            chunk_ca = clean_addrs[off_ca : off_ca + 64]
            code_res.extend(
                router.batch_call(
                    c,
                    [("eth_getCode", [_checksum(a), btag]) for a in chunk_ca],
                    block_pin=block_pin,
                    need_archive=True,
                    raise_on_all_failed=True,
                )
            )
        verified_onchain = [
            a
            for a, rhex in zip(clean_addrs, code_res)
            if isinstance(rhex, str) and rhex.startswith("0x") and len(rhex) > 2
        ]
        return verified_onchain, True
    except Exception:
        return clean_addrs, False


def _resolve_protocol_addresses(
    router: RPCRouter,
    slug: str,
    chain: str,
    initial_addrs: Sequence[str],
    store: Optional[SQLiteStore] = None,
    block_pin: int = 0,
    fetch_text_fn: Optional[Callable[[str], str]] = None,
) -> List[str]:
    """
    에이전트 웹 검색 연동 + 4단계 우선순위 컨트랙트 주소 수집기 (온체인 eth_getCode 검증 포함):
      0순위: 에이전트가 웹 검색 쿼리로 수집한 `audit_artifacts/<slug>/discovered_addresses.json`
      1순위: 공식 Docs (Official Docs: 웹 검색 쿼리 & docs.<domain>, <url>/docs, <url>/contracts, llms.txt)
      2순위: GitBook (웹 검색 쿼리 & *.gitbook.io/llms.txt, /contracts, /deployed-contracts)
      3순위: GitHub (공식 GitHub repo의 deployments.json, addresses.json, contracts.json, README.md)
      4순위: DeFiLlama Adapter (DefiLlama-Adapters/projects/<module> + api.llama.fi/protocol/<slug> + initial_addrs)
    """
    slug = _norm_slug(slug)
    c = _norm_chain(chain)
    st = store or router.store
    base_slug = _strip_chain_suffix_slug(slug)
    fetcher = fetch_text_fn or _default_fetch_text

    # 0순위: 에이전트가 웹 검색 쿼리로 작성한 discovered_addresses.json 확인
    disc_file = ARTIFACT_ROOT / slug / "discovered_addresses.json"
    agent_addrs, agent_confirmed_none = _extract_agent_discovered_addresses(disc_file)
    if agent_confirmed_none:
        return []
    if agent_addrs and fetch_text_fn is None:
        cand_agent = [a for a in agent_addrs if _is_non_precompile_addr(a)][:12]
        if block_pin <= 0:
            return cand_agent
        onchain_agent, _ = _filter_onchain_contract_addrs(router, c, cand_agent, block_pin)
        if onchain_agent:
            return onchain_agent

    meta: Dict[str, Any] = st.get_proto_meta(slug) if st is not None else {}
    if not meta and st is not None and base_slug != slug:
        meta = st.get_proto_meta(base_slug)
    cache_key = f"resolved_addrs_{c}"
    if fetch_text_fn is None and isinstance(meta.get(cache_key), list) and meta[cache_key]:
        cached_list = [nx for x in meta[cache_key] if (nx := _norm_addr(x))]
        if cached_list:
            return cached_list

    llama_detail_text = ""
    if not meta.get("url") and not meta.get("github") and not meta.get("module"):
        for cand_slug in dict.fromkeys((base_slug, slug)):
            try:
                raw_llama = fetcher(f"https://api.llama.fi/protocol/{urllib.parse.quote(cand_slug)}")
                if raw_llama:
                    llama_detail_text = raw_llama
                    try:
                        pdoc = json.loads(raw_llama)
                        if isinstance(pdoc, dict):
                            gh_v = pdoc.get("github")
                            gh_l = [str(g).strip() for g in gh_v if str(g).strip()] if isinstance(gh_v, list) else ([str(gh_v).strip()] if gh_v else [])
                            meta = {
                                **meta,
                                "url": str(pdoc.get("url") or meta.get("url") or "").strip(),
                                "github": gh_l or meta.get("github") or [],
                                "module": str(pdoc.get("module") or meta.get("module") or "").strip(),
                                "address": str(pdoc.get("address") or meta.get("address") or "").strip(),
                            }
                    except Exception:
                        pass
                    break
            except Exception:
                continue

    def _harvest_from_urls(urls: Sequence[str], max_urls: int = 4, max_addrs: int = 16) -> Tuple[List[str], List[str]]:
        addrs_found: List[str] = []
        seen_found: Set[str] = set()
        texts_collected: List[str] = []
        for u in list(dict.fromkeys(filter(None, urls)))[:max_urls]:
            try:
                txt = fetcher(u)
            except Exception:
                continue
            if not txt:
                continue
            texts_collected.append(txt)
            for ad in _extract_addresses_from_text(txt):
                if _is_non_precompile_addr(ad):
                    _append_unique(addrs_found, seen_found, ad)
                    if len(addrs_found) >= max_addrs:
                        break
            if len(addrs_found) >= max_addrs:
                break
        return addrs_found, texts_collected

    # ── 1순위: 공식 Docs (Official Docs + 웹 검색 쿼리 폴백) ──
    stage1_urls: List[str] = []
    explicit_docs = str(meta.get("docs") or "").strip()
    if explicit_docs:
        stage1_urls.append(explicit_docs)
    official_url = str(meta.get("url") or "").strip().rstrip("/")
    if official_url.startswith(("http://", "https://")):
        parsed_u = urllib.parse.urlparse(official_url)
        host = parsed_u.netloc.lower()
        root_domain = _SUBDOMAIN_PREFIX_RE.sub("", host)
        if root_domain and "." in root_domain:
            stage1_urls.extend(
                [
                    f"https://docs.{root_domain}/llms.txt",
                    f"https://docs.{root_domain}/contracts",
                    f"https://docs.{root_domain}",
                    f"{official_url}/docs",
                    f"{official_url}/contracts",
                ]
            )
        else:
            stage1_urls.extend([f"{official_url}/docs", f"{official_url}/contracts"])
    if not stage1_urls:
        q_docs = urllib.parse.quote_plus(f"{base_slug} {c} official docs deployed contract addresses")
        stage1_urls.append(f"https://html.duckduckgo.com/html/?q={q_docs}")
    stage1_addrs, stage1_texts = _harvest_from_urls(stage1_urls, max_urls=4)

    # Stage 1 본문에서 발견된 GitBook / GitHub 링크 추출
    discovered_gitbooks: List[str] = []
    seen_gitbooks: Set[str] = set()
    discovered_gh_repos: List[str] = []
    seen_gh_repos: Set[str] = set()

    def _harvest_gh_repos(txt_s: str) -> None:
        for gh_m in _GITHUB_REPO_RE.findall(txt_s):
            clean_repo = gh_m.strip("/").replace(".git", "")
            if clean_repo and not clean_repo.lower().startswith("defillama/"):
                _append_unique(discovered_gh_repos, seen_gh_repos, clean_repo)

    for txt in [*stage1_texts, llama_detail_text]:
        if not txt:
            continue
        for gb_m in _GITBOOK_URL_RE.findall(txt):
            _append_unique(discovered_gitbooks, seen_gitbooks, gb_m.rstrip("/"))
        _harvest_gh_repos(txt)
        for doc_m in _DOCS_LINK_RE.findall(txt):
            if "gitbook.io" in doc_m.lower():
                _append_unique(discovered_gitbooks, seen_gitbooks, doc_m.rstrip("/"))

    # ── 2순위: GitBook ──
    stage2_urls: List[str] = []
    if meta.get("gitbook"):
        stage2_urls.append(str(meta["gitbook"]).strip().rstrip("/"))
    for gb_base in [*discovered_gitbooks[:2], f"https://{base_slug}.gitbook.io"]:
        gb_root = _GITBOOK_SUFFIX_RE.sub("", gb_base.rstrip("/"))
        stage2_urls.extend([f"{gb_root}/llms.txt", f"{gb_root}/contracts", gb_base])
    stage2_addrs, stage2_texts = _harvest_from_urls(stage2_urls, max_urls=4)

    for txt in stage2_texts:
        _harvest_gh_repos(txt)

    # ── 3순위: GitHub (공식 리포지토리 배포 주소록 & 문서) ──
    stage3_urls: List[str] = []
    raw_gh_list = meta.get("github") if isinstance(meta.get("github"), list) else []
    gh_candidates: List[str] = []
    for g_entry in [*raw_gh_list, *discovered_gh_repos]:
        g_clean = _GITHUB_PREFIX_RE.sub("", str(g_entry).strip()).strip("/").replace(".git", "")
        if not g_clean:
            continue
        if "/" in g_clean:
            gh_candidates.append(g_clean)
        else:
            gh_candidates.append(f"{g_clean}/{base_slug}")
            gh_candidates.append(f"{g_clean}/contracts")
    for repo_slug in list(dict.fromkeys(gh_candidates))[:3]:
        for br in ("main", "master"):
            for fname in ("deployments.json", "addresses.json", "contracts.json", "README.md"):
                stage3_urls.append(f"https://raw.githubusercontent.com/{repo_slug}/{br}/{fname}")
    stage3_addrs, _ = _harvest_from_urls(stage3_urls, max_urls=4)

    # ── 4순위: DeFiLlama Adapter & 프로토콜 API & 초기 시드 주소 ──
    stage4_urls: List[str] = []
    mod_path = str(meta.get("module") or "").strip().lstrip("/")
    if mod_path:
        stage4_urls.append(f"https://raw.githubusercontent.com/DefiLlama/DefiLlama-Adapters/main/projects/{mod_path}")
    stage4_urls.append(f"https://raw.githubusercontent.com/DefiLlama/DefiLlama-Adapters/main/projects/{base_slug}/index.js")
    if not llama_detail_text:
        stage4_urls.append(f"https://api.llama.fi/protocol/{urllib.parse.quote(base_slug)}")
    stage4_addrs, _ = _harvest_from_urls(stage4_urls, max_urls=3)
    seen_stage4: Set[str] = set(stage4_addrs)
    if llama_detail_text:
        for ad in _extract_addresses_from_text(llama_detail_text):
            if _is_non_precompile_addr(ad):
                _append_unique(stage4_addrs, seen_stage4, ad)
    for init_a in initial_addrs:
        na = _norm_addr(init_a)
        if na and int(na, 16) > 0:
            _append_unique(stage4_addrs, seen_stage4, na)

    # 0순위(Agent Web Search) -> 1순위(Official Docs) -> 2순위(GitBook) -> 3순위(GitHub) -> 4순위(DeFiLlama Adapter) 순서 엄격 보존 병합
    ordered_candidates: List[str] = list(
        dict.fromkeys([*agent_addrs, *stage1_addrs, *stage2_addrs, *stage3_addrs, *stage4_addrs])
    )
    seen_ordered_cands: Set[str] = set(ordered_candidates)
    if not ordered_candidates and block_pin > 0:
        tx_list = [
            str(th).strip().lower()
            for th in (meta.get("tx_hashes") or [])
            if isinstance(th, str) and _ANY_TX_HASH_RE.match(str(th).strip())
        ]
        if tx_list:
            try:
                rcpt_res: List[Any] = []
                for off_tx in range(0, len(tx_list), 32):
                    chunk_tx = tx_list[off_tx : off_tx + 32]
                    rcpt_res.extend(
                        router.batch_call(
                            c,
                            [("eth_getTransactionReceipt", [th]) for th in chunk_tx],
                            block_pin=0,
                            need_archive=True,
                        )
                    )
                infra_set = _infra_addresses_for_chain(c)
                for rcpt in rcpt_res:
                    if not isinstance(rcpt, dict):
                        continue
                    sender_a = _norm_addr(rcpt.get("from"))
                    for cand_raw in (
                        rcpt.get("to"),
                        rcpt.get("contractAddress"),
                        *(lg.get("address") for lg in (rcpt.get("logs") or []) if isinstance(lg, dict)),
                    ):
                        ca = _norm_addr(cand_raw)
                        if ca and _is_non_precompile_addr(ca) and ca != sender_a and ca not in infra_set:
                            _append_unique(ordered_candidates, seen_ordered_cands, ca)
            except Exception:
                pass
    if not ordered_candidates:
        return []

    # 온체인 eth_getCode 검증: block_pin > 0일 때 실제 컨트랙트 바이트코드가 존재하는 주소만 반환하며,
    # 전수 EOA("0x")로 판명되면 빈 리스트([])를 반환하여 에이전트 address_request.json으로 위임한다.
    if block_pin > 0:
        final_addrs, _ = _filter_onchain_contract_addrs(router, c, ordered_candidates, block_pin)
    else:
        final_addrs = ordered_candidates

    if st is not None and fetch_text_fn is None and final_addrs:
        meta[cache_key] = list(final_addrs)
        st.put_proto_meta_batch([(slug, meta)])
    return list(final_addrs)


_GITBOOK_SUFFIX_RE: re.Pattern[str] = re.compile(r"/(?:contracts|docs|llms\.txt).*$")
_GITHUB_PREFIX_RE: re.Pattern[str] = re.compile(r"^https?://github\.com/")
_TEST_CID_FILE_RE: re.Pattern[str] = re.compile(r"^test_(\d+)\.t\.sol$")
_POC_REQ_CID_FILE_RE: re.Pattern[str] = re.compile(r"^poc_request_(\d+)\.json$")
_VERDICT_CID_FILE_RE: re.Pattern[str] = re.compile(r"^verdict_(\d+)\.json$")
_SOL_CALL_INTERACTION_RE: re.Pattern[str] = re.compile(r"\.\s*(?:call|staticcall)\s*[\({]")
_SELFTEST_ORPHAN_NS_RE: re.Pattern[str] = re.compile(r"_selftest_ns_(\d+)(?:_\d+)?")


@contextlib.contextmanager
def _try_slug_lock(slug_dir: Path) -> Iterator[bool]:
    """병렬 터미널 세션 간 동일 슬러그 디렉토리 중복 실행 방지용 비차단(Non-blocking) 파일 락."""
    slug_dir.mkdir(parents=True, exist_ok=True)
    lock_file = slug_dir / ".slug.lock"
    try:
        with _exclusive_file_lock(lock_file, timeout_sec=0.2):
            yield True
    except TimeoutError:
        yield False


