                {"slug": cmp_prof_slug, "chain": "ethereum", "audit_block": 20_000_000, "verdict": _format_profit_verdict(280_000), "net_usd": 200.0, "net_krw": 280_000, "fx_rate_krw": 1400.0, "fx_source": "fixture:t40", "reason": "verified"},
